// Discord-бот PANDAMIA: модерация голосовых каналов (права владельцев, мут/глухота,
// тег 🔑), бан-таймаут за выход с сервера, музыка и мост между серверами (pipe).
// Всё, что зависит от конкретного сервера, -- в config.json (шаблоны: config.example.json --
// со всеми пояснениями и значениями, config.minimal.json -- минимум: токен и id сервера).
// node >= 22 (портативный: ./node-v24.21.0-win-x64/node.exe)
// discord.js v14:
//   npm install discord.js @keyv/sqlite keyv
// CHANGELOG v2.65 (место в начатых треках и понятная стрелка у перепрыгивания):
//   * У ТРЕКОВ, КОТОРЫЕ НАЧИНАЛИ ИГРАТЬ, НО НЕ ДОИГРАНЫ, в /queue видно `02:44/03:14`
//     (просьба владельца). Позиция берётся из track.seek (её кладут /leave и срочный
//     переход) либо из m.seekSec у ждущего продолжения трека. У обычных треков -- как
//     раньше, просто длина.
//   * ИКОНКА ПЕРЕПРЫГИВАНИЯ -- АРКА-СТРЕЛКА «⤴» вместо «⏭»: тем же «⏭» помечено
//     «Пропустить», и две одинаковые стрелки в соседних рядах путали.
// CHANGELOG v2.64 (живое сообщение /queue -- раз в полминуты по умолчанию):
//   * MUSIC.queue_live_ms по умолчанию 30000 (было 60000) -- просьба владельца: чаще
//     видеть живые счётчики. Это ~120 правок в час против допустимых Discord ~3600.
//   * Про hosts-файл (вопрос владельца про YouTube) -- разбор в README: помогает только
//     при чисто DNS-блоке, требует ещё *.googlevideo.com, и при IP/DPI-блоке только сбивает
//     нашу проверку «DIRECT: есть».
// CHANGELOG v2.63 (срочный переход трогает ровно два трека):
//   * УТОЧНЕНИЕ ВЛАДЕЛЬЦА: «трогались только два трека» -- выбранный становится текущим,
//     а играющий -- СЛЕДУЮЩИМ, и всё. Раньше «то, что стояло до цели», уезжало в конец,
//     и порядок ломался без нужды. Теперь остальная очередь стоит как стояла.
// CHANGELOG v2.62 (/jump доступен DJ, кнопка «Перепрыгнуть», предзагрузка с повторами):
//   * /JUMP РАЗРЕШЁН ОБЫЧНОМУ DJ (просьба владельца: «полезная очень»), но по правилу
//     «своё/чужое», как /skip, /move и перемотка: цель должна быть его; «обрезать» --
//     только если всё убираемое тоже его; срочно перебить ЧУЖОЙ играющий трек нельзя
//     (иначе прыжок обошёл бы запрет на пропуск чужого). Проверка внутри jumpGuard,
//     поэтому слэш и кнопки не разъедутся.
//   * КНОПКА «⏭ Перепрыгнуть» В РЯДУ ДЕЙСТВИЙ (перед «▶ Войти»): окно ввода номера ->
//     подтверждение варианта. Пятая кнопка в ряду -- ровно лимит Discord.
//   * «▶ Войти» СТАЛ НЕЙТРАЛЬНЫМ: зелёный в боте -- «подтверждаю/ок», а вход в канал --
//     обычное перемещение (владелец: «почему ещё войти зелёным?»).
//   * ПРЕДЗАГРУЗКА ПРОБУЕТ НЕСКОЛЬКО РАЗ (PRELOAD_TRIES = 3 с паузой 5 с). Живой случай:
//     YouTube ответил '403 Forbidden' на скачивание следующего трека -- одна попытка, и
//     заготовки нет; когда очередь дошла, тот же трек открылся сразу. Одна сетевая заминка
//     не повод играть без заготовки; ошибку самого видео по-прежнему не повторяем.
// CHANGELOG v2.61 (/jump: прерванный трек -- следующим; автор ссылкой; видно самообновление):
//   * /JUMP: ПРЕРВАННЫЙ ТРЕК ИДЁТ СЛЕДУЮЩИМ (просьба владельца: «старый перекидывает В
//     КОНЕЦ, хотя я говорил НАОБОРОТ в начало очереди»). Срочный переход: цель играет
//     сразу, а прерванный встаёт сразу за ней -- заиграет следующим, с того же места
//     (с v2.63 остальная очередь при этом НЕ двигается).
//   * ВТОРОЙ ВАРИАНТ ТЕПЕРЬ СПРАШИВАЕТСЯ: не указал `mode` в команде -- бот отвечает
//     двумя кнопками («⏭ Срочный переход» / «✂ Обрезать до трека»), а не молча прыгает.
//     Логика одна -- jumpMusic, поэтому слэш-команда и кнопки не разъедутся.
//   * АВТОР В ОЧЕРЕДИ -- ССЫЛКОЙ НА ПРОФИЛЬ (упоминание), а не голым ником: по нику
//     нельзя ни написать, ни открыть профиль. Пингов нет: сообщение /queue и все его
//     правки идут с allowedMentions: { parse: [] }. У треков старой базы id нет -- там
//     остаётся ник.
//   * САМООБНОВЛЕНИЕ /queue СТАЛО ВИДИМЫМ. У прямого эфира не менялось НИЧЕГО (у него
//     нет позиции), и сообщение казалось мёртвым -- теперь у эфира есть `🔴 в эфире
//     MM:SS`. При старте -- строка, включено ли самообновление и как часто; первая
//     самоправка пишется в лог одной строкой (дальше молча -- 60 строк в час это спам).
// CHANGELOG v2.60 (прокси может быть несколько -- обрыв одного не тушит музыку):
//   * ВОПРОС ВЛАДЕЛЬЦА: «нет разве публичных прокси, которые бы всегда работали, не
//     скрывая IP, а только выступая как DNS?» Короткий ответ -- НЕТ: SOCKS/HTTP прокси
//     ВСЕГДА несёт твой трафик через чужую машину (даже если не прячет адрес), то есть
//     чужой открытый прокси -- это чужие логи, общая перегрузка и быстрые лимиты от
//     YouTube. Роль «только DNS» умеет играть socks5h (имя резолвит ПРОКСИ) -- но это
//     уже свой прокси, и он может икнуть. Честный ответ -- иметь ВТОРОЙ СВОЙ.
//   * ПОЭТОМУ MUSIC.proxy ТЕПЕРЬ ПРИНИМАЕТ СПИСОК: адреса через запятую (или массив).
//     Бот пробует их ПО ПОРЯДКУ, а «икнувший» пропускает минуту -- работу подхватывает
//     следующий. Больше трёх адресов не берём (это уже путаница); сколько взято -- видно
//     в стартовой строке.
//   * «ИКНУВШИЙ» ПРОКСИ -- НЕ «МЁРТВЫЙ НАСМЕРТЬ»: раньше был один общий флаг
//     proxyStreamDead, и один обрыв глушил сразу ВСЕ прокси. Теперь состояние своё у
//     КАЖДОГО адреса (proxyBadUntil на 60 с): обрыв потока или сетевой сбой в yt-dlp
//     помечает ИМЕННО тот адрес, а остальные продолжают работать.
//   * ТО ЖЕ И У OEmbed-ПРОВЕРКИ ОЧЕРЕДИ и у DIRECT: маршруты (ytRoutes) теперь не
//     строки 'proxy'/'DIRECT', а { proxy: <адрес> }, поэтому и скачивание на диск, и
//     поток, и проверка берут адрес ИЗ МАРШРУТА, а не из «главного» прокси.
//   * Настройка необязательна: одна строка в MUSIC.proxy работает ровно как раньше.
// CHANGELOG v2.55 («🔄 Обновить» в очереди и живой лог ещё и в файле):
//   * КНОПКА «🔄 Обновить» -- в РЯДУ ЛИСТАНИЯ, МЕЖДУ «◀ Влево» и «Вправо ▶» (просьба
//     владельца: «список обновляется только когда я по нему перемещаюсь»). Discord
//     перерисовывает сообщение только по нажатию, поэтому текст (что играет, сколько
//     ждать, кто сколько поставил) застывал на моменте вызова /queue. Теперь это одна
//     кнопка: та же страница, собранная заново из ЖИВОЙ очереди. Ряд стал РОВНО из пяти
//     кнопок (больше Discord не принимает), поэтому она встала именно сюда, а не
//     отдельным рядом. Правила те же, что у листания (перерисовывает тот, кто открыл).
//     Очередь пуста, а играть есть что -- кнопка тоже есть (ряд из одной кнопки).
//   * ЖИВОЙ ЛОГ ПИШЕТСЯ ЕЩЁ И В ФАЙЛ: logs/panda-ГГГГ-ММ.log -- ФАЙЛ НА МЕСЯЦ (это и
//     есть ротация), те же строки с теми же метками времени, что в консоли. Пишется
//     синхронно, поэтому файл актуален в любой момент: его можно открыть и прочитать
//     даже когда окно консоли уже прокрутилось. Пишет ЗЕРКАЛ сразу после config.json
//     (стартовые [db]/[music] в файле тоже есть), а обёртка со штампом его дополняет.
//       - папка -- ключ log_dir (по умолчанию "logs"), путь может быть любым;
//       - сколько месячных файлов держать -- ключ log_keep_months (0 -- не удалять
//         ничего; число -- при смене месяца старое уходит, и в логе видно, сколько);
//       - logs/ и любые *.log уже в .gitignore: в репозиторий лог не попадёт;
//       - файл не открылся (права, диск) -- ОДНА строка в консоль, бот работает дальше.
//     СЕРВИСНЫЕ КОМАНДЫ (node . dump/files/privacy/backup/restore/unkey/...) в файл не
//     пишут вообще: если у команды есть ЛЮБОЙ аргумент -- это сервис, а не бот (`node .`
//     запускается без аргументов), а в dump лежит содержимое базы, в unkey -- открытый
//     текст. У них и вывод остался прежним -- без меток времени.
// CHANGELOG v2.54 (история добавлений -- своя команда /history, а не строка в /queue):
//   * СТРОКИ «Последние добавления» В /queue БОЛЬШЕ НЕТ (просьба владельца). И дело не
//     только в месте: та строка строилась ИЗ ОЧЕРЕДИ, поэтому и показывала всего четыре
//     пачки, и теряла всё доигранное и убранное, и не говорила, что именно поставили --
//     «33 трека (№1, 2, 3 и ещё 30)» без единого названия.
//   * ЗАМЕНА -- КОМАНДА /history (для всех, как /queue): кто, когда и что поставил.
//     Один заход /play = одна запись, и в ней видно вид добавленного: трек, ПРЯМОЙ ЭФИР
//     или целый ПЛЕЙЛИСТ со составом (первые три названия и «и ещё N»), плюс счётчик
//     эфиров внутри пачки. Смотреть может каждый; команда есть и в /help.
//   * ИСТОРИЯ ЖИВЁТ ОТДЕЛЬНО ОТ ОЧЕРЕДИ (запись musicState/history), поэтому:
//       - её НЕ стирают /clear и /stop (очередь -- своё, история добавлений -- своё);
//       - доигранное, пропущенное и убранное из очереди в ней остаётся;
//       - она переживает перезапуск, а при старте в лог уходит строка, сколько пачек
//         поднято из базы;
//       - ПЕРВЫЙ ЗАПУСК НЕ ОТКРЫВАЕТСЯ ПУСТЫМ: если записи ещё нет, а в очереди есть
//         треки с метками добавления (addAt), бот ОДИН РАЗ переносит эти пачки в
//         историю и пишет об этом в лог -- очередь при этом не меняется.
//   * СКОЛЬКО ПОМНИТЬ -- КЛЮЧ MUSIC.history_len (по умолчанию 25, максимум 200;
//     0 -- выключить, /history так и скажет). Мусор в ключе не проходит молча: в
//     [config]-аудите строка с объяснением (иначе вышло бы 0 и история молча пропала).
//   * ОЧЕРЕДЬ СТАЛА КОРОЧЕ и от этого не пострадала: из бюджета страницы убрана длина
//     ушедшей строки, поэтому на страницу по-прежнему влезают все треки (проверяется
//     стендом на 200 длинных треках с эфирами и ⚠). Функция queueAddsText удалена -- её
//     текст есть в истории git (v2.35–v2.53), а поле addAt у треков осталось (по нему
//     переносятся старые пачки и его же видно в `node . dump`).
// CHANGELOG v2.53 (чужой трек нельзя ни перемотать, ни пропустить; подсказка /queue спрятана):
//   * ПРОПУСК ПОПАЛ ПОД ТО ЖЕ ПРАВИЛО, ЧТО ПЕРЕМОТКА (v2.50): свой трек пропускает
//     его автор, любой -- админы и модеры. Пропустить чужую песню -- не «перемотать»,
//     а выбросить её из эфира совсем, и раньше это делал любой DJ. Проверка -- внутри
//     queueSkip, поэтому кнопка «⏭ Пропустить» и /skip подчиняются ей одинаково.
//     Трек без автора (из старой базы) -- ничей: его пропускает тот, кому он играет.
//   * ПОДСКАЗКА ПОД /queue СЕЙЧАС НЕ ПОКАЗЫВАЕТСЯ -- просьба владельца («выглядит очень
//     ненужным, во всяком случае на данный момент»). Текст СОХРАНЁН целиком и включается
//     одним переключателем QUEUE_HINT_SHOW = true в коде (ни ключа в конфиге, ни второй
//     ветки сборки нет: бюджет страницы считается по тому же queueHintText (), поэтому
//     список просто получает освободившееся место).
// CHANGELOG v2.52 (прокси отвалился -- музыка не встаёт на мёртвом локальном DNS):
//   * РЕАЛЬНЫЙ СЛУЧАЙ ВЛАДЕЛЬЦА: прокси на миг отвалился, бот «честно» ушёл на DIRECT,
//     а youtube.com на этой машине ЛОКАЛЬНО НЕ РЕЗОЛВИТСЯ -- именно поэтому весь
//     YouTube и ходит через прокси (по той же причине в proxyForAgent схема поднимается
//     до socks5h: имя резолвит прокси). Итог: вместо музыки в логе была невнятная
//     «Unable to download API page ... Read timed out», а причина не читалась.
//   * ТЕПЕРЬ БОТ ЗНАЕТ, ЕСТЬ ЛИ ЗАПАСНОЙ ПУТЬ: при старте одна строка ('запасной путь
//     DIRECT: НЕ работает -- youtube.com локально не резолвится...'), а решения о
//     маршруте принимает один ytRoutes (): если имя локально не резолвится, DIRECT даже
//     не рассматривается и прокси остаётся рабочим маршрутом -- включая случай, когда
//     прокси «икнул» (v2.60). Если имя резолвится, DIRECT остаётся запасным путём, как раньше.
//   * 3-СЕКУНДНАЯ ПРОВЕРКА ПРОКСИ КЭШИРУЕТСЯ (30 с для живой / 60 с для молчащей).
//     Раньше она выполнялась перед КАЖДЫМ запуском yt-dlp -- метаданные, скачивание
//     на диск и поток, то есть до трёх раз на трек: при молчащем прокси это лишние
//     секунды на каждой песне.
//   * Кэширование IP вместо DNS сознательно НЕ делаем: yt-dlp резолвит имена сам, а
//     подсунуть ему готовый IP для HTTPS без правки самого yt-dlp нельзя.
// CHANGELOG v2.50 (перемотать чужой трек нельзя -- ни командой, ни кнопками):
//   * ЖИВОЙ СЛУЧАЙ ОТ ВЛАДЕЛЬЦА: «Почему я могу другим человеком (хоть и DJ) прыгать
//     по таймкодам МОЕГО трека?» Действительно мог: роль DJ проверялась, а АВТОРСТВО
//     самого трека -- нет. Правило «своё/чужое» (v2.31, v2.32) жило только в очереди
//     и в удалении, а внутренняя навигация -- перемотка ±30 с, окно «⏱ На таймкод…» и
//     /seek -- оставалась открыта всем DJ: чужой трек можно было утащить к концу или в
//     начало прямо посреди чужого сета (и преспокойно слушать его заново).
//   * ТЕПЕРЬ СВОЙ ТРЕК ПЕРЕМАТЫВАЕТ ЕГО АВТОР, А ЛЮБОЙ -- АДМИНЫ И МОДЕРЫ (staff).
//     Проверка стоит ВНУТРИ seekMusic, у самого общего места: через неё проходят все
//     три пути, поэтому разъехаться (как разъезжались подсказка и список) они не могут.
//     Трек БЕЗ АВТОРА -- из старой базы, он ничей: его перематывает тот, кому он
//     сейчас играет (как и раньше), иначе модернизация базы молча сломала бы кнопки.
//   * ОТКАЗ -- тот же понятный текст, что у перестановки и удаления («только свои
//     записи: этот трек добавил ...»), поэтому ничего нового объяснять не надо.
//     Кнопки перемотки остаются видны всем DJ (в общем сообщении ещё нельзя показать
//     разное разным людям): правило объявляется в ответе на нажатие, как и у меню автора.
// CHANGELOG v2.43 (проверка очереди только ПРЕДУПРЕЖДАЕТ, её итог виден в /queue):
//   * ЗАРАНЕЕ НИЧЕГО НЕ УДАЛЯЕТСЯ. Приговор «видео недоступно» зависит от НАШЕГО IP и
//     прокси: владелец меняет прокси, видео закрыто по региону СЕЙЧАС -- а когда до
//     трека дойдёт очередь, оно уже отдаётся. Поэтому проверка заранее только ПОМЕЧАЕТ
//     трек (⚠ в /queue) и говорит автору в его канал, а убирается трек ровно по факту:
//     не запустился при воспроизведении -- тогда и уходит из очереди с настоящей причиной.
//   * ИТОГ ВИДЕН ПРЯМО В /queue: сколько просмотрено (и когда), сколько сейчас «под
//     вопросом», сколько убрано при воспроизведении и когда следующий проход.
// CHANGELOG v2.41 (очередь проверяется заранее -- проблемы видно до эфира):
//   * О ПРОБЛЕМЕ С ТРЕКОМ УЗНАЮТ ДО ЭФИРА, А НЕ В ЕГО МОМЕНТ. Раньше единственным местом,
//     где выяснялось «видео больше нет», была предзагрузка: человек ждал свою песню,
//     чтобы услышать, что её не будет. Теперь бот сам прочёсывает очередь от начала
//     (MUSIC.queue_check, по умолчанию включено) и предупреждает заранее, а автору
//     говорит в ТОТ канал, откуда трек добавили (v2.39), одним сообщением на канал.
//   * ЛИМИТЫ YOUTUBE -- ГЛАВНАЯ ЗАБОТА ВЛАДЕЛЬЦА, И ОНА УЧТЕНА:
//       - сначала дешёвый публичный oEmbed (крошечный запрос, без скачивания и без плеера),
//         и ТОЛЬКО при его отказе запускается yt-dlp -- подтвердить приговор тем же
//         инструментом, который бы играл трек (значит без ложных срабатываний на видео,
//         которые просто нельзя встроить);
//       - ПЕРЕДНИЙ КРАЙ (3 трека) спрашивают сразу у yt-dlp: о том, что видео закрыто
//         для этого IP по региону, oEmbed не знает -- отвечает «есть», хотя бот его не
//         сыграет (живой случай: тот самый DJ-сет «Video unavailable»). Это один запуск
//         на трек -- как раз перед тем, как его поставят в эфир;
//       - на машинах, где youtube.com не резолвится локально (весь YouTube ходят через
//         VPN), запрос идёт через прокси со схемой socks5h (DNS резолвит прокси) -- без
//         этого проверка вообще не уходила бы (найдено живым прогоном);
//       - за проход не больше MUSIC.queue_check_depth треков (по умолчанию 20) и с паузой
//         MUSIC.queue_check_gap_ms (по умолчанию 5 с) -- меньше, чем один запуск yt-dlp
//         на каждый сыгранный трек, который бот делает и без этой проверки;
//       - тот же адрес за сессию проверяется ОДИН раз;
//       - прямые эфиры не проверяются; сеть/«подтвердите, что вы не робот»/возраст --
//         НЕ приговор: трек остаётся в очереди, а перепроверим не раньше чем через полчаса.
//   * В ЛОГЕ И В КОНФИГЕ ЭТО ВИДНО: строка при старте ('проверка очереди заранее:
//     ВКЛЮЧЕНА -- смотрю 20 треков от начала, пауза 5 с'), строка на каждый найденный
//     подозрительный трек ('проверка очереди: похоже, видео недоступно (...) -- оставляю
//     в очереди и проверю при воспроизведении'), сообщение в канал автора и два
//     предупреждения в [config]-аудите
//     (слишком большая глубина; слишком маленькая пауза).
// CHANGELOG v2.40 (приветствие ведёт в публичный канал, а не в закрытую «архивную»):
//   * ССЫЛКА ДЛЯ НОВИЧКА -- ОТДЕЛЬНАЯ НАСТРОЙКА. `welcome_channel` -- служебный: в нём
//     лежит сообщение с текстом правил, и часто он ЗАКРЫТ. Текст в ЛС доезжал, а на
//     ссылку человек получал «нет доступа». Ключ `welcome_public_channel` (и
//     необязательный `welcome_public_message`) уводит ссылку и название канала в
//     публичный канал -- например «о сервере», куда обычно идут приглашения. Пусто --
//     поведение прежнее.
// CHANGELOG v2.39 (проблема трека -- в канал его автора, проигранное не копится, конфиг целиком):
//   * ОШИБКА ТРЕКА УХОДИТ В КАНАЛ, ОТКУДА ЕГО ДОБАВИЛИ. Раньше любое «видео больше нет»
//     и «не удалось воспроизвести» писалось в ОДИН канал -- тот, откуда шла последняя
//     команда (мог быть чужим для автора трека). Теперь у каждого трека помнится свой
//     канал добавления (track.addIn из /play), и туда же уходит причина: автор вернётся
//     в свою комнату и сразу увидит, что его трек убран и почему, а не будет думать,
//     что забыл его поставить. Канала нет -- падаем на прежний путь (как раньше).
//   * ДИСК ПОМНИТ ТОЛЬКО ТО, ЧТО ЗВУЧИТ СЕЙЧАС. Скачанные файлы больше не копятся до
//     лимита: после каждого перехода на диске остаются ровно играющий трек и предзагрузка,
//     всё проигранное удаляется сразу (`кэш: убрал N файлов (M МБ)`). Прежнее поведение
//     (файлы живут до MUSIC.cache_max_mb) включается ключом `cache_keep_played: true`.
//     Файл, который Windows ещё не отдал (его читает только что убитый ffmpeg), уберётся
//     повторной попыткой -- но только если трек к тому моменту не понадобился снова.
//   * БОЕВОЙ КОНФИГ = ПРИМЕР: в config.json недоставало ключей MUSIC.cache* (работали
//     значения по умолчанию, а самого ключа не было видно). Теперь списки ключей совпадают.
// CHANGELOG v2.38 (кнопки переноса, короткая инструкция, кэш в отчётах, запреты ботам):
//   * ПЕРЕНОС ТРЕКА -- ТОЛЬКО ПЕРЕНОС. Список треков под /queue переключает сообщение
//     в режим переноса: остаются ровно две строки кнопок (убрать / в начало / в конец /
//     на позицию и выше / ниже / вернуться). Раньше на экране оставались ещё листание,
//     перемотка, вход/выход и чистка -- владелец: «слишком много кнопок».
//     «✖ Вернуться» возвращает обычные кнопки очереди; трек после каждого переноса
//     остаётся выбранным, поэтому двигать его можно подряд (и после окна «на позицию»).
//   * ИНСТРУКЦИЯ ПЕРЕПИСАНА ПОД ОБЫЧНОГО ЧЕЛОВЕКА И ВЛЕЗАЕТ В ОДИН EMBED (было ~5900
//     символов и два сообщения): как слушать музыку, что такое 🔑, что бот делает сам
//     (муты по каналам, таймаут за выход, возврат ролей, приветствие) и что посмотреть
//     про себя. Команды админов/модеров/DJ и разбор интерфейса очереди из текста убраны
//     -- они видны в списке слэш-команд в Discord (и подробно описаны в README).
//   * БОТАМ ЗАПРЕТ CONNECT НЕ ПИШЕТСЯ ВООБЩЕ (раньше -- только своему боту): право
//     ЗАЙТИ в комнату -- не «память о глухоте», и терять доступ туда, куда бота зовут,
//     он не должен. Мут/глухота ботов по каналу помнятся как раньше (запрет Speak).
//   * `node . cache` -- что скачано в кэш музыки, сколько занимает и что можно удалить
//     (`--clear` стереть всё, `--prune` применить лимит); `node . files` теперь
//     показывает у music_cache объём, а не только число файлов.
// CHANGELOG v2.37 (кэш аудио на диске -- YouTube больше не участвует в проигрывании):
//   * ТРЕК ЖИВЁТ ФАЙЛОМ. Раньше звук шёл потоком прямо из yt-dlp в Discord, то есть
//     YouTube участвовал в проигрывании каждую секунду: его сбои (403, Broken pipe,
//     оборванный сет) слышали слушатели, а перемотка и продолжение после перезапуска
//     каждый раз заново просили звук у YouTube.
//   * ГИБРИД (так выбрал владелец): короткий трек (до MUSIC.cache_full_max_min минут)
//     скачивается ЦЕЛИКОМ и играет файлом -- перемотка мгновенная и точная, YouTube не
//     нужен; предзагрузка следующего трека -- это его скачивание, то есть паузы между
//     песнями нет. Длинный сет и прямой эфир играют сразу потоком, но тот же звук
//     ПИШЕТСЯ на диск: доиграл до конца -- файл готов, и со следующего раза трек идёт
//     с диска (у прямого эфира позиции нет -- его не кэшируем).
//   * МЕСТО ОГРАНИЧЕНО: MUSIC.cache_max_mb (по умолчанию 4096 МБ), при переполнении
//     уходят самые старые файлы (играющий и уже готовый следующий -- не трогаются).
//     Недописанные хвосты после перезапуска убираются сами. Папка (MUSIC.cache_dir,
//     по умолчанию music_cache рядом с ботом) удаляется в любой момент -- бот скачает
//     заново; в базе про кэш ничего нет. Выключить совсем: MUSIC.cache = false.
//   * В ЛОГЕ ЭТО ВИДНО: 'кэш аудио: ВКЛЮЧЁН -- <папка>', 'качаю на диск: X',
//     'сохранил на диск: X (N МБ)', 'играю: X (с диска)', 'кэш переполнен -- убрал ...'.
//     Кэш не может «сломать» музыку: не скачалось / папка недоступна -- играем потоком,
//     как раньше (в лог идёт причина).
// CHANGELOG v2.36 (переход вместо чистки, авторские блоки, перестановка без счёта кликов):
//   * /JUMP -- ЭТО ПЕРЕХОД, А НЕ ЧИСТКА. Раньше «прыжок» молча выбрасывал всё до
//     выбранного трека (и в хелпе так и было написано -- владелец: «а выбрасывать или
//     нет, они сами решат»). Теперь выбранный трек играет сразу, а пройденное и
//     прерванный играющий (ВМЕСТЕ С МЕСТОМ В ТРЕКЕ) уезжают в конец очереди.
//     Ничего не теряется: убрать ненужное -- /remove, /clear, /clear author. Права
//     прежние: админы и модеры (прыжок перебивает то, что играет).
//   * АВТОРСКИЕ БЛОКИ: треки одного автора в очереди не чередуются. Пачка из /play
//     встаёт в конец блока СВОЕГО автора (нет его треков -- в конец очереди): очередь
//     читается блоками, /push и перестановка не рвут чужие плейлисты, а чередование --
//     осознанное действие staff (/move, /jump).
//   * ПЕРЕСТАНОВКА БЕЗ СЧЁТА КЛИКОВ: у выбранного трека вместо «⬆/⬇» теперь ещ‘ «⏫ В
//     начало», «⏬ В конец» и «#️⃣ На позицию…» (точный номер -- окном ввода Discord).
//     Ради второй строки кнопок список треков на время выбора прячется (рядов у Discord
//     не больше пяти), а выбранный номер виден в самом сообщении.
//   * БОТ НЕ УХОДИТ ОТ СЛУШАТЕЛЕЙ: за автором трека он переезжает только если в его
//     комнате не осталось НИКОГО другого (или если автор сам позвал /join). А /play,
//     когда бот играет в другой комнате, СПРАШИВАЕТ у позвавшего -- переехать к нему
//     или остаться там, где слушают (без ответа ничего не меняется).
//   * МУТ/ГЛУХОТА БОТОВ помнятся по каналу так же, как у людей (запрет Speak/Connect
//     на этом канале); исключение -- СВОЙ бот: его запрет Connect просто запер бы его
//     в комнате, поэтому ему ограничения не пишем. В общий канал ботов НЕ переносим.
//   * ПЕРЕМОТКА, КОТОРАЯ НЕ ВЫШЛА, БОЛЬШЕ НЕ НАЧИНАЕТ ТРЕК С НАЧАЛА: если источник не
//     умеет навигацию, бот сообщает об этом и продолжает с того же места, где играло
//     (с начала -- только при восстановлении после перезапуска, когда играть нечего).
//   * ИНСТРУКЦИЯ ПЕРЕПИСАНА: продолжения строк склеены (Discord сам переносит по ширине),
//     поэтому текст больше не выглядит обрывками; описания /jump и кнопок приведены
//     к тому, что бот делает на самом деле.
// CHANGELOG v2.35 (перемотка кнопками, история добавлений, живучесть продолжения с места):
//   * ПРОДОЛЖЕНИЕ С МЕСТА БОЛЬШЕ НЕ СЪЕДАЕТ ТРЕК. Измерено живым опытом на настоящем
//     DJ-сете (тот самый случай из лога владельца -- возобновлённый сет замолкал
//     через пару секунд): `--download-sections` на таких источниках отдаёт НОЛЬ байт
//     и падает через 30-45 секунд ('ERROR: ffmpeg exited with code 4294967274'), а
//     старая проверка ждала всего 1.5 с и принимала пустышку за рабочий поток.
//     Теперь: сдвиг до 2 минут делается сразу СВОИМ ffmpeg (звук -- через ~5-6 с),
//     большой сдвиг -- сначала секцией, но с проверкой, что поток реально отдал
//     данные (не отдал за 8 с -- сразу ffmpeg), и адрес, на котором секция не сработала,
//     больше не пробуется до конца работы бота.
//   * ВИДЕО, КОТОРОГО БОЛЬШЕ НЕТ (удалено/закрыто), БОЛЬШЕ НЕ ТЕРЯЕТСЯ МОЛЧА. И раньше
//     это была обычная ошибка: трек пропадал только после четырёх неудачных попыток
//     yt-dlp, а в логе оставалась голая причина без контекста. Теперь: предзагрузка,
//     упавшая с 'Video unavailable', помечает трек и говорит об этом в лог сразу, а
//     когда очередь до него доходит -- он убирается СРАЗУ (без четырёх попыток) с
//     понятной строкой в логе и сообщением в канал; остальные треки не трогаются, а
//     если в очереди только такие -- это как пустая очередь.
//     Проверки «не бот» и возрастные ограничения -- НЕ этот случай (зависят от IP).
//   * ПРОВЕРЕНО ЖИВЫМ ЗАПУСКОМ (19.09.2026, бот на реальном сервере): возобновление
//     того самого длинного сета прошло через два шага -- 'секция с 22:41 ничего не
//     отдала за 8 с -- беру тот же трек через ffmpeg' -- и играло дальше без единого
//     обрыва (раньше в этом месте лог через пару секунд уходил на следующий трек).
//     Тогда же живьём сработала пометка удалённого видео:
//     'видео больше нет на YouTube (Boris Brejcha WE2 | Tomorrowland 2024) -- уберу из
//     очереди, когда дойдёт'.
//   * [FIX] ПРЕДОХРАНИТЕЛЬ ОТ БЕСКОНЕЧНОГО КРУГА: если трек не заиграл, playNext звал
//     себя же без ограничений -- при сбое, который не связан с одним треком, бот
//     вычерпывал память и падал (поймано стендом: 'out of memory'). Теперь после
//     десяти неудач подряд честно останавливается и говорит об этом в лог.
//   * [v2.35] КНОПКИ ПЕРЕМОТКИ ±30 с под /queue: «◀ 30 с» / «30 с ▶» -- та же
//     функция, что у /seek. У прямого эфира позиции нет, поэтому там кнопки погашены.
//   * [v2.35] ИСТОРИЯ ДОБАВЛЕНИЙ в /queue: «🕘 Последние добавления: 20:08 Фантазёр --
//     3 трека (№1, 2, 3)». Метка времени пишется каждому треку при добавлении (/play),
//     один заход = одна «пачка», номера -- текущие места в очереди (тем же номерам
//     подчиняются /remove и кнопки). Видно свежие вставки в чужом длинном плейлисте.
//     В историю добавлений входит ТОЛЬКО текущая очередь: доигранное уже не помнится.
//   * РЯДЫ ПОД /queue ПЕРЕСОБРАНЫ ПОД ЖЁСТКИЙ ЛИМИТ DISCORD (5). Два меню с ОДНИМИ И
//     ТЕМИ ЖЕ номерами («убрать трек» и «двигать трек») заменены одним списком, а
//     действия -- «🗑 Убрать / ⬆ Выше / ⬇ Ниже / ✖ Готово» -- появляются после выбора
//     трека. Освободившийся ряд заняла перемотка. Старые сообщения (q:rm / q:mv) при
//     этом понимаются по-прежнему.
// CHANGELOG v2.34 (старт без слушателей и честный счёт людей в канале):
//   * ПОСЛЕ ПЕРЕЗАПУСКА БОТ ЗАХОДИТ И МОЛЧИТ, ЕСЛИ ЛЮДЕЙ НЕТ. Раньше он входил в
//     канал и СРАЗУ начинал играть («подключился -> возобновляю очередь -> играю»),
//     а пауза «нет слушателей» ставилась только после первого трека: то есть yt-dlp
//     уже качал музыку в пустую комнату. Теперь слушатели проверяются ДО старта:
//     очередь и МЕСТО В ТРЕКЕ остаются как были, а игра начинается с того же места,
//     как только кто-то зайдёт в канал (или по /join).
//   * СЛУШАТЕЛЕЙ СЧИТАЕМ ПО ФАКТУ (humansInChannelChecked): у чужого бота, зашедшего
//     в канал до нас, discord.js может не приложить member к голосовому состоянию, и
//     такой бот считался ЖИВЫМ слушателем -- это второй источник «играем в пустоту».
//     Теперь неизвестное состояние спрашивается у Discord (REST); не ответил --
//     считаем человеком (лучше заиграть живому слушателю, чем молчать).
//   * startRestored -- вторая линия обороны: проверка слушателей стоит прямо перед
//     playNext, а не только у вызывающих, поэтому любой путь восстановления (в том
//     числе будущий) не сможет заиграть в пустоту.
//   * [FIX] ЖДУЩАЯ ОЧЕРЕДЬ БЕЗ «ТЕКУЩЕГО» ТЕПЕРЬ ТОЖЕ СТАРТУЕТ. Ветка «человек зашёл --
//     начинаю сохранённую очередь» требовала, чтобы сохранился ждущий трек: если
//     состояние записалось между треками (m.current пуст), очередь ждала вечно --
//     комната полна, а бот молчит. Теперь достаточно самой очереди.
//   * ПРОФИЛЬ ГОВОРИТ ПРАВДУ: пока очередь ждёт слушателя, видно '⏸ «Канал» — жду
//     слушателя', а не '🎧 «Канал»', как будто музыка просто идёт.
// CHANGELOG v2.33 (автор у каждого трека, права на очередь, /seek, node . help):
//   * АВТОР ВИДЕН У КАЖДОГО ТРЕКА. В v2.31 ник у подряд идущих треков одного
//     человека писался один раз (экономили место) -- при листании длинного плейлиста
//     это читалось как «трек ничей»: одно «👤 Фантазёр» и пять строк без хозяина.
//     Теперь имя есть в каждой строке (длинный ник подрезается, названия треков при
//     нехватке места укорачиваются -- треки не выбрасываем и автора не прячем).
//   * /move У DJ -- ТОЛЬКО СВОИ И ТОЛЬКО НА СВОИ ЖЕ МЕСТА: цель перестановки должна
//     быть занята его треком (среди своих мест порядок какой угодно). Раньше DJ мог
//     выдвинуть свою песню вперёд чужого плейлиста -- обещали мы другого.
//   * /jump -- ТОЛЬКО ADM/MOD (решение владельца): это ПЕРЕХОД (v2.36), а не чистка --
//     выбранный трек играет сразу, а пройденное уезжает в конец очереди (ничего не
//     выбрасывается); у DJ в очереди всегда есть свои, поэтому перебивать чужую
//     музыку может только staff. Раньше тут было «выбрасывает всё до номера»,
//     а у DJ в очереди всегда есть свои треки -- так он и включал бы себе музыку без
//     конца, стирая чужое. DJ остаются /skip, /push по своим и свои места в очереди.
//   * НОВАЯ /seek <время>: перейти внутри ТЕКУЩЕГО трека (90, 1:30, 1:02:03).
//     Технически -- тот же путь, что у продолжения с места: трек возвращается первым
//     в очередь с отметкой секунды (--download-sections, а если источник так не умеет --
//     своим ffmpeg). ПРЯМОЙ ЭФИР: позиции у него нет и быть не может, поэтому переход
//     для эфира -- это переход к тому, что идёт СЕЙЧАС (свежий поток с живого края).
//     Кнопки у seek нет сознательно: редкая и «острая» операция.
//   * `node . help` -- список консольных команд (раньше его печатала только ошибка про
//     опечатку, и help отвечал «Неизвестная команда»). Список один на оба случая и
//     начинается с самого `node .`; `node . unkey` в него не попал сознательно.
//   * config.minimal.json -- РЕАЛЬНО минимальный: TOKEN и сервер с одним "allow": true
//     (без allow бот сервер не обслуживает). Всё остальное -- значения по умолчанию,
//     их в файле нет: раньше там лежали десятки ключей «на всякий случай».
// CHANGELOG v2.32 (вход/выход из очереди, поднять автора, читаемая вёрстка, fixauthors):
//   * «ВЫХОД» (ОТ /leave) -- МЯГКИЙ: человек просто ОТКЛАДЫВАЕТ СВОИ ТРЕКИ (как
//     пауза, только до его возвращения), а бот продолжает играть для остальных и
//     даже переезжает к следующему автору, если тот в другом канале. Место в
//     отложенном треке НЕ теряется (уезжает вместе с треком: track.seek) и
//     восстанавливается, когда до него снова дойдёт. Из канала бот выходит только
//     когда играть больше нечего (тогда -- как раньше: очередь и место в базе).
//     раньше /leave сразу обрывал чужую музыку на середине.
//   * ВХОД/ВЫХОД И В КНОПКАХ: «▶ Войти» (`/join`) и «⏏ Выйти» (`/leave`), плюс
//     «🧹⏏ Очистка/Выход» -- это /stop (/clear + /leave) одной кнопкой. Логика входа
//     одна на кнопку и команду (joinMusicChannel), вход и выход из кнопки видны
//     только нажавшему -- иначе каждое нажатие добавляло бы сообщение в чат.
//   * МЕНЮ АВТОРА: выбрать автора -- и в подтверждении видно, что с ним можно
//     (⬆ поднять наверх / 🗑 убрать). Список авторов показывается ВСЕМ, а права
//     проверяются при действии: нет прав -- бот говорит ПРИЧИНУ. `/push` теперь
//     доступен и обычному DJ, но только по СВОИМ трекам (раньше -- только staff).
//   * ВЁРСТКА /queue: номера в косых кавычках (`12`), а не «12.» -- Discord считал
//     это markdown-списком и сам переформатировал строки (первый пункт «уезжал» от
//     остальных); блоки (Сейчас / Очередь / По авторам / До конца) разделены линиями.
//   * `node . fixauthors <id> [имя] [--dry]` -- проставить автора трекам, у которых его
//     нет (у них обычный DJ ничего не может). При старте, если такие треки есть, бот
//     сам говорит об этом и даёт готовую команду.
//   * ЛИСТАНИЕ НЕ ЛОМАЕТ ОЧЕРЕДЬ (найдено живым запуском): в customId кнопок был
//     только НОМЕР страницы, поэтому на первой странице «В начало» и «Влево» давали
//     один и тот же id (как «Вправо» с «В конец» на последней) -- Discord отвечал
//     COMPONENT_CUSTOM_ID_DUPLICATED и отбивал ВСЁ сообщение /queue (в лог падал
//     uncaughtException). Теперь в id есть и сама кнопка: q:p:first / q:p:prev /
//     q:n:next / q:n:last. Старый вид «q:p:12» из уже отправленных сообщений тоже
//     понимается, и стенд проверяет уникальность id на размерах от 1 до 200 треков.
//   * ИНСТРУКЦИЯ БОЛЬШЕ НЕ МОЖЕТ "ПРОПАСТЬ": лимит Discord -- 6000 символов СУММОЙ
//     по всем embed'ам ОДНОГО сообщения (в одном описании -- 4096). Инструкция
//     подошла к 6000 вплотную, поэтому теперь она сначала режется на СООБЩЕНИЯ
//     (helpMessages), а потом каждое -- на embed'ы: переросла -- уйдёт двумя
//     сообщениями, а не отклонится целиком («бот запустился, а инструкции нет»).
// CHANGELOG v2.31 (очередь: DJ распоряжается только СВОИМ, листание, меню автора):
//   * СВОЁ / ЧУЖОЕ. Обычный DJ убирает, переставляет и чистит ТОЛЬКО свои записи --
//     в меню под /queue ему попадают только они, а чужая чистка (`/clear author:@другой`)
//     отбивается. Админы и модеры могут всё, включая всю очередь. Автор есть у каждого
//     нового трека (byId/byName), у треков из старых баз его нет -- такой показан как
//     «без автора» и считается НИЧЬИМ (обычный DJ его не трогает, staff может).
//   * /clear И /stop -- ВЫБОР И ПОДТВЕРЖДЕНИЕ. Обе команды (и кнопки «Очистить»/«Стоп»)
//     сначала спрашивают и говорят, что именно уйдёт (сколько из очереди, какой
//     играющий); staff выбирает «только мои» или «всю очередь», DJ -- только свои.
//     `/stop` со «своими» НЕ выходит из канала, если остаётся чужая музыка (глушить её
//     было бы свинством) -- а при пустой очереди выходит, как раньше.
//   * ЛИСТАНИЕ: «⏮ В начало / ◀ Влево / Вправо ▶ / В конец ⏭» -- шаг равен размеру
//     страницы, крайние кнопки гаснут на первой и последней странице.
//   * МЕНЮ «🗑 Удалить треки автора» вместо кнопки «🧹 Чужие»: выбираешь автора --
//     спрашиваем подтверждение (со списком и остатком). DJ видит в меню только себя
//     (даже когда своих треков нет -- в подтверждении так и сказано), staff -- всех,
//     включая ничьи треки из старых баз. Рядов компонентов не больше пяти (лимит Discord).
//   * /jump у DJ -- только если всё пропускаемое тоже его (окно вперёд ничего чужого не
//     выбрасывает); пропустить чужое можно кнопкой «⏭ Пропустить». В логе -- кто сделал.
// CHANGELOG v2.30 (лог: время на каждой строке, читаемые коды, без шума от своих же глушений):
//   * МЕТКА ВРЕМЕНИ НА КАЖДОЙ СТРОКЕ. Часть сообщений (ошибки yt-dlp и ffmpeg, сбои прав,
//     непереданные ЛС) печаталась в обход общего вида строки и стояла в живом логе без
//     времени. Теперь console.log/console.error обёрнуты один раз: строка со штампом
//     остаётся как есть, остальным штамп добавляется (CLI-команды печатают как раньше).
//   * КОДЫ ВЫХОДА ЧИТАЕМО: 'код 3199971767' -> 'код -1094995529 (ffmpeg: не смог прочитать
//     поток)', 'exited with code 4294967274' -> 'code -22 (неверные данные)', адреса
//     буферов ('[in#0 @ 0x...]') из строки убраны. Обрезка длинных строк -- по слову, а не
//     посередине ('...Error opening input files: In' больше не будет).
//   * ШУМ ОТ СВОИХ ЖЕ ДЕЙСТВИЙ УБРАН: когда поток глушит сам бот (/skip, /stop, /leave,
//     конец очереди), смерть yt-dlp и ffmpeg больше не пишется как ошибка ('Broken pipe').
//   * [FIX] ВЫХОД БОТА БОЛЬШЕ НЕ ВЫГЛЯДИТ КАК «ВЫКИНУЛИ». После /stop (и /leave) событие
//     voiceStateUpdate принимало наш собственный выход за чужое действие и писало
//     'бота выключили/выкинули -- очередь помню' -- сразу после того, как очередь была
//     стёрта. Отметка о нашем выходе ставится в destroyMusic; если бота выкинул человек,
//     строка остаётся (это по-прежнему видно в логе).
//   * [FIX] трек, который не удалось запустить, называется в логе по имени, и сказано,
//     что бот берёт следующий (раньше были только ошибки yt-dlp/ffmpeg без контекста).
//   * [FIX] СМЕРТЬ ПОТОКА БОЛЬШЕ НЕ СЪЕДАЕТ ТРЕК. Если yt-dlp/ffmpeg умирали на середине
//     (в том числе при возобновлении «с места»), плеер видел не ошибку, а обычный конец
//     трека: очередь ехала дальше, и трек молча пропадал (поймано живым прогоном:
//     возобновлённый сет умер через 7 секунд и пропустился). Теперь такой трек
//     возвращается в очередь и играет снова; если продолжение с места явно не вышло
//     (замолчал почти сразу после возобновления) -- с НАЧАЛА, чтобы не потерять его.
//     Осознанные /skip и /jump к этому не относятся (у них своя отметка).
// CHANGELOG v2.29 (политика из шаблона, минимальный конфиг, боевой конфиг против примера):
//   * `node . privacy [--check] [--offline]` -- PRIVACY.md собирается из шаблона
//     privacy.template.md: название приложения и ник владельца спрашиваются у Discord,
//     серверы/таймаут/сроки хранения берутся из config.json, значок ключа -- из этого
//     файла, дата -- сегодняшняя. Подстановка без значения = отказ писать файл (лучше понятная
//     ошибка, чем дырка в публичном тексте), а шапка-инструкция шаблона в PRIVACY.md
//     не попадает. Руками политику больше не правят: в ней именно так и осталось старое
//     название приложения -- руками такое не заметишь.
//   * config.minimal.json -- конфиг-скелет: обязательные поля и значения по умолчанию,
//     чтобы на чистом сервере хватило вписать TOKEN и id сервера.
//   * [FIX] при старте видно, если боевой config.json отстал от config.example.json
//     (строки-подсказки и ключи со значениями по умолчанию): 'в config.json нет N строк
//     из config.example.json -- сервер ...: ...'. Раньше расхождение замечалось случайно.
// CHANGELOG v2 (переход на discord.js v14 / keyv v5 / node 24):
//   * intents строками (v13-стиль) + partials: ['Channel'] (иначе ЛС не работают)
//   * keyv v5: const { Keyv } = require('keyv');
//   * channel.type: enum ChannelType (0 = GUILD_TEXT, 1 = DM)
//   * permissionOverwrites: overwrite.allow/deny -- PermissionsBitField (не Collection)
//   * displayAvatarURL: { extension: 'png', forceStatic: false, size: 1024 }
//   * users.fetch: один аргумент (опции cache/force убраны в v14)
//   * user.tag -- null (только username, без discriminator), uu()/uuu() без '#0'
//   * setBitrate: число bps (не строка '64000')
//   * embed timestamp: только Date/number/ISO (locale-строка d() кидала 'Invalid time value')
//   * color 'BLUE' (v13-стиль, капсом) НЕ распознаётся EmbedBuilder -> 'Blue'/hex
//   * channelCreate/channelUpdate: в v14 каналы приходят без guild -> берём через .guild ?? client.guilds.cache.get
//   * [FIX v2] NaN-баг в логе переименования: скобки вокруг 'Владельцы канала: ' + (owners.size ? ... : ...)
//   * [FIX v2] e.message там, где e не существует (users.fetch .catch(() => null))
// CHANGELOG v2.18 (бот играет там, где слушает автор трека; /announce и /dm без интентов):
//   * ПОЕХАЛИ К АВТОРУ ТРЕКА: перед стартом трека бот смотрит, в каком голосовом канале
//     сидит тот, кто этот трек добавил, и переезжает туда (если он вообще в голосовом).
//     Так каждый трек играет там, где его слушает автор; бот остаётся в этом канале до
//     трека другого автора или до /leave. Автор вне голосового -- бот не двигается.
//     Сам он по-прежнему никогда не заходит и не выходит: переезд возможен только когда
//     он уже где-то играет, и не сразу после явного /join|/play (m.justJoinedAt), чтобы
//     не уехать от человека, который только что его позвал. В логе видно причину:
//     '[music] перешёл в «X» -- автор трека Y слушает здесь'.
//     Тот же смысл и у паузы: если бот стоит ОДИН (пауза, слушателей нет), а автор
//     музыки зашёл в другой голосовой канал -- бот едет туда и продолжает с того же
//     места ('здесь никого, а автор трека ... слушает здесь'). Приоритет -- у автора
//     НЕДОИГРАННОГО трека, а если тот уже ушёл -- у автора СЛЕДУЮЩЕГО в очереди (иначе
//     пауза запирала бы бота в пустой комнате и следующий трек не начался бы никогда).
//     Переезд делается один раз на событие (_noFollow -- бот не бегает между двумя
//     авторами туда-сюда). Логика паузы/продолжения не дублируется: после переезда
//     checkListeners вызывается заново и сам снимает паузу обычным путём.
//   * /announce и /dm -- слэш-команды вместо текстовых (мост из пандалогии и `panda dm`):
//     текст и вложение приходят в самой команде, то есть интент Message Content им НЕ
//     нужен, а Discord именно это и советует вместо запроса этого интента.
//   * «Переслать в общий» -- команда-контекстное меню (правый клик по сообщению):
//     Discord отдаёт выбранное сообщение ЦЕЛИКОМ (текст + вложения) без интента
//     Message Content, поэтому это замена мосту из пандалогии, если интент отзовут.
//     Оригинал удаляется только в канале-источнике (как у моста); если staff
//     переслал сообщение из другого канала, оригинал остаётся (чужое не удаляем).
//     Отправка у моста и у меню -- ОДНА функция relayPipe (поведение не разъезжается).
//   * [/join] ЗАЩИТА ОТ ПЕРЕХВАТА: если бот играет трек, а его автр сидит в той же
//     комнате (то есть бот поёт именно для него), другой DJ не уведёт бота командой
//     /join -- отказ виден только вызвавшему, а в лог идёт 'кто просил / что играет /
//     для кого'. Если автора в комнате нет -- /join работает, но при живых слушателях
//     в ответе и в логе прямо сказано, что они остались без музыки. Без музыки и во
//     время /leave -- /join как раньше.
//   * [login] ОДНА строка при старте: в скольких серверах живёт приложение и сколько
//     людей в них суммарно ('приложение в 2 серверах, участников суммарно ~11745')
//     -- порог ревью Discord считается именно по людям всех серверов, а memberCount
//     приходит в GUILD_CREATE, то есть видно без интентов.
//   * [music] Stage-каналы: бот заходит и туда, а в лог пишется подсказка, что для
//     слышимости Stage Moderator должен сделать его спикером (Discord иначе не
//     пускает бота вещать в эфир).
// CHANGELOG v2.17 (интенты по факту, /rolecheck, руками двигать очередь):
//   * [intents] ОТЧЁТ ПРИ СТАРТЕ: что РЕАЛЬНО доступно приложению -- Message Content
//     (по интенту в гейтвее), Guild Members (события), полный список участников
//     (проверяется ФАКТОМ -- пришёл ли список) и журнал аудита (пробный запрос).
//   * [intents] Guild Members ПОДКЛЮЧЁН в гейтвее ("GUILD_MEMBERS": true в config.json):
//     вход/выход теперь мгновенные (guildMemberAdd/Remove), а опрос раз в 45 сек
//     остаётся резервным путём. Один и тот же переход они не обрабатывают дважды
//     (отметка на 5 минут -- иначе только что вошедший «выходил» бы по устаревшему
//     REST-списку и получал таймаут). Интент может быть ОТОЗВАН -- тогда login падает
//     'Used disallowed intents', бот сам снимает интент и стартует без него.
//   * [/rolecheck user:@кто] -- что бот помнит о человеке: роли (save_roles), что
//     вернёт при входе, текущее наказание с точным сроком и историю за окно.
//     Работает и для того, кто НЕ на сервере (одиночный REST-запрос без интента).
//   * [/queue] треков на страницу -- из конфига (queue_page, по умолчанию 15; было 10)
//     + защита от лимита сообщения 2000
//     символов (страница собирается по бюджету, листание идёт по показанным номерам).
//   * [/queue] КНОПКИ-СТРЕЛКИ: меню «🎚 Двигать трек» + «⬆ Выше» / «⬇ Ниже» / «✖ Готово».
//     Логика перестановки -- общая с /move (queueMove), авторство -- в логе.
//   * [welcome] в ЛС переносится ТЕКСТ и КАРТИНКА из сообщения с правилами
//     (раньше была только ссылка, а Discord рисовал её как название сервера).
//     Нужны ОБА ключа: welcome_channel -- где искать, welcome_message -- что именно
//     (поиска сообщения по id без канала в API нет).
//   * [лог] уборка старых записей больше не пишет «убрал N» -- пишет про СРОК ХРАНЕНИЯ
//     (понятно, что данные старше окна, а не что-то потерялось).
// CHANGELOG v2.16 (точные роли, кнопки под /queue, защита от пустого списка):
//   * [роли] ТОЧНОСТЬ: снимок поллера бывает до 45 секунд старым, поэтому роль,
//     снятая за секунды до выхода человека, попадала в базу и возвращалась при входе.
//     Теперь правки ролей после снимка достраиваются по журналу аудита
//     (gateway-событие MemberRoleUpdate + REST-запрос как фолбэк), а если возвращать
//     нечего -- старая запись стирается (иначе она воскрешала бы уже потерянную роль).
//   * [/queue] БЫСТРЫЕ КНОПКИ под очередью: «⏭ Пропустить», «🧹 Очистить» и меню
//     «🗑 Убрать трек» с номерами текущей страницы (те же номера, что в /remove).
//     Права -- как у слэш-команд (DJ/админ/модер); листание -- по-прежнему только
//     тем, кто открыл очередь. Логика общая со /skip, /clear, /remove (одна правка).
//   * [poll] ЗАЩИТА ОТ «ПУСТОГО» СПИСКА УЧАСТНИКОВ: если Discord вернёт пустой или
//     внезапно усохший список (403 с пустым телом, лимит, сбой), тик пропускается --
//     раньше это выглядело бы как «ВСЕ вышли» и каждому выписался бы таймаут за
//     выход (а перезаход -- бан). Плюс явная строка про интент Guild Members: без
//     него полный список недоступен и вход/выход молча перестают работать.
// CHANGELOG v2.15 (управление наказаниями, история за месяц, чистый лог событий):
//   * [/unban user:@кто reason:...] -- снять таймаут/бан вручную (админ/модер): снимается
//     и запись таймаута в базе, и бан в Discord, и отложенный таймер разбона (иначе он
//     позже написал бы «unbanned» уже после ручного снятия). Кто снял и почему -- в журнал,
//     в лог и в историю (/bans).
//   * ИСТОРИЯ НАКАЗАНИЙ (bans_history_days, по умолчанию НАВСЕГДА): /bans показывает,
//     кто сколько раз выходил с сервера, получал таймаут/бан и у кого наказание
//     снимали. Пишутся события exit/timeout/ban/unban. Ключ = 0 (или не задан) --
//     копим всю статистику; задано число дней -- старые события убирает свип.
//   * [FIX] СПАМ В ЛОГЕ «[nick] +🔑 (sweep)» каждые 45 секунд: fetch(id) БЕЗ force
//     возвращал КЭШ (а в кэше ник старый -- discord.js без интента GuildMembers его не
//     обновляет), поэтому свип заново «ставил» уже стоящий ключ и писал ту же строку.
//     Теперь ник читается из REST (force: true) и только когда состояние неизвестно, а
//     что бот поставил сам -- помнится в памяти процесса ($nickSet).
// CHANGELOG v2.14 (по просьбам владельца: видеть наказания, помнить роли, удобная очередь):
//   * [ban] ОТЧЁТ ПРИ СТАРТЕ: сколько банов/таймаутов поднято из базы -- пишется ВСЕГДА,
//     в том числе когда наказаний нет ('поднято 0: активных банов/таймаутов нет').
//     В строке видно имя, точный срок и что это: бан или только таймаут.
//   * [/bans] -- кто сейчас в наказании: имя, бан/таймаут, срок до секунды и причина.
