// ГДЕ СТОИТ ЭТО МЕСТО. Блок -- В САМОМ НАЧАЛЕ, сразу после чтения config.json, и вот
// почему: стартовые строки ([db], [music]) печатаются РАНЬШЕ общей обёртки со штампом
// (она ниже, v2.30), а именно с них начинается любой разбор. Поэтому в файл пишет
// ЗЕРКАЛО, а обёртка со штампом штамп и добавляет -- она вызывается ПОЗЖЕ и передаёт
// зеркалу уже помеченную строку; будь в ней своя запись в файл, каждая строка попала бы
// туда дважды (проверяется стендом).
