//     файлов, а сам факт падения с кодом 0 (Ctrl+C) отчёта не создаёт -- это выход,
//     а не сбой;
//   * сервисные команды (node . dump/backup/...) отчётов не пишут вовсе -- любой
//     аргумент значит, что запущена команда, а не бот (см. BOT_RUN выше).
