// [v14] мёртвый обработчик 'voiceStateUpdate_OFFed' из v13 удалён (был unreachable).
// ============================================================================
// [v2.1] REST-ПОЛЛЕР УЧАСТНИКОВ -- замена guildMemberAdd/guildMemberRemove.
// [v2.17] ВАЖНО: полный список участников (REST) -- это как раз одна из вещей,
// которую даёт интент Guild Members. Без интента он не работает, поэтому поллер
// теперь РЕЗЕРВНЫЙ путь (на случаи «бот запустился без интента» и «бот был выключен»),
// а основной -- мгновенные события гейтвея (см. handleMemberEvent).
// ============================================================================

const POLL_PERIOD = 45 * 1000; // раз в 45 сек (лимиты REST не трогаем)

// Снапшоты участников по серверам: server_id -> Map<user_id, {user, member}>
var $membersSnapshot = {};
// Когда последний раз предупреждали о сбое списка участников (чтобы не залить лог):
var $pollWarnAt = {};
// [v2.15] Когда каждый снимок собран: нужен, чтобы достроить по журналу аудита правки
// ролей, случившиеся ПОСЛЕ снимка (см. saveMemberRoles/rolesWithChangesAfter):
var $membersSnapshotAt = {};

// [v2.5] Поллер отдаёт СЫРОЙ JSON участника из REST, а логам нужен объект User:
// у сырого нет displayAvatarURL() (была ошибка 'memberUser.displayAvatarURL is not
// a function'), а упоминание рисовалось как [object Object]. Разрешаем в User.
async function resolveUser (uid, raw)
{
    let user = client.users.cache.get (uid);
    if (!user) user = await client.users.fetch (uid).catch (() => null);
    if (user) return user;
    // крайний случай (пользователь недоступен) -- лог не должен падать:
    let stub =
    {
        id: uid,
        username: (raw && raw.user && raw.user.username) || uid,
        displayAvatarURL: () => null,
        toString: () => '<@' + uid + '>',
    };
    return stub;
}

// ============================================================================
// [v2.17] МГНОВЕННЫЕ ВХОД/ВЫХОД (интент Guild Members) + РЕЗЕРВНЫЙ ОПРОС.
// Работают оба пути, но один и тот же переход они не обрабатывают дважды: отметка
// «уже разобрано событием» живёт 5 минут (поллер тикает раз в 45 сек). Отметка
// нужна в ОБЕ стороны: REST-список Discord отстаёт от гейтвея, поэтому без неё
// только что вошедший в следующем тике выглядел бы как вышедший и получил
// таймаут за выход (а он рядом -> бан).
// ============================================================================
const MEMBER_EVENT_TTL = 5 * 60 * 1000;
var $memberEvent = {}; // server -> Map<uid, { at, join }>

function memberEventMark (server, uid, isJoin)
{
    if (!$memberEvent[server]) $memberEvent[server] = new Map ();
    const map = $memberEvent[server];
    map.set (uid, { at: Date.now (), join: !!isJoin });
    if (map.size > 300) // старые отметки больше не нужны -- не копим
        for (const [id, rec] of map)
            if (Date.now () - rec.at > MEMBER_EVENT_TTL) map.delete (id);
}

// true -- этот же переход уже разобран событием (значит, поллеру делать нечего)
function memberEventFresh (server, uid, isJoin)
{
    const map = $memberEvent[server];
    if (!map) return false;
    const rec = map.get (uid);
    if (!rec) return false;
    return (rec.join === !!isJoin) && (Date.now () - rec.at <= MEMBER_EVENT_TTL);
}

// Участник из гейтвея -- в том же виде, в каком его отдаёт REST-поллер (raw):
// роли у события уже на руках, их и запоминаем (joined_at нам не нужен).
function rawOfMember (member)
{
    return {
        user: { id: member.id, username: (member.user && member.user.username) || member.id },
        roles: member.roles ? [...member.roles.cache.keys ()] : null,
        nick: member.nickname || null,
    };
}

async function handleMemberEvent (member, isJoin)
{
    try
    {
        const server = member && member.guild ? member.guild.id : null;
        if (!server || !(server in SERVERS) || !SERVERS[server].allow) return;
        if (member.user && member.user.bot) return; // боты: ни приветствия, ни наказаний
        const uid = member.id;
        if (memberEventFresh (server, uid, isJoin)) return; // поллер уже разобрался
        memberEventMark (server, uid, isJoin);
        // У guildMemberRemove объект бывает частичным -- дотягиваем, чтобы знать роли
        if (member.partial)
        {
            try { await member.fetch (); }
            catch (e) { /* не отдали -- роли просто не запомним */ }
        }
        const raw = rawOfMember (member);
        const who = (member.user && member.user.username) ? member.user : await resolveUser (uid, raw);
        console.log ('[' + (d()) + '] участник ' + who.username + (isJoin ? ' ЗАШЁЛ на ' : ' ВЫШЕЛ с ') +
            SERVERS[server].name + ' (мгновенно)');
        if (isJoin)
        {
            await logMemberJoinLeave (server, who, true);
            await restoreMemberRoles (server, uid, raw); // роли -- до таймаутов
            await handleMemberJoin (server, uid, raw);
        }
        else
        {
            await logMemberJoinLeave (server, who, false);
            // since = сейчас: снимок актуален, правки ролей достраивать не надо
            await handleMemberLeave (server, uid, raw, Date.now ());
        }
        // Снимок поллера подтягиваем к реальности (если REST отстаёт -- спасёт отметка):
        const snap = $membersSnapshot[server];
        if (snap)
        {
            if (isJoin) snap.set (uid, raw); else snap.delete (uid);
            $membersSnapshotAt[server] = Date.now ();
        }
    }
    catch (e)
    {
        console.error ('[memberEvent] ' + (isJoin ? 'вход' : 'выход') + ': ' + oneLine (e.message));
    }
}

// Эти два события приходят ТОЛЬКО с интентом Guild Members. Нет интента -- просто
// молчат, и всё делает опрос (это и есть автоматический откат).
client.on ('guildMemberAdd',    member => { void handleMemberEvent (member, true); });
client.on ('guildMemberRemove', member => { void handleMemberEvent (member, false); });

// Лог входа/выхода участника в журнал (как было на событиях):
async function logMemberJoinLeave (server, memberUser, isJoin)
{
    try
    {
        let log_channel = SERVERS[server].log_channel || '';
        if (!log_channel) return;
        let channel = client.channels.cache.get (log_channel);
        if (!channel) channel = await client.channels.fetch (log_channel).catch (() => null);
        if (!channel)
        {
            console.error ('[member] лог-канал ' + log_channel + ' не найден');
            return;
        }
        let log_text = isJoin
            ? `${memberUser} **зашёл** 👋 на сервер \`${SERVERS[server].name}\` 🟩`
            : `${memberUser} **вышел** 🚪 с сервера \`${SERVERS[server].name}\` 🟥`;
        let author = {name: memberUser.username}; // без icon_url, если аватара нет
        // [FIX v2.9.1] у заглушки (пользователь недоступен) аватары нет -- null в icon_url
        // Discord не примет, а записи о входе/выходе терять нельзя. Проверяем значение:
        let icon = (typeof memberUser.displayAvatarURL === 'function')
            ? memberUser.displayAvatarURL ({extension: 'png', forceStatic: false, size: 1024})
            : null;
        if (icon) author.icon_url = icon;
        channel.send
        (
            {
                content: `${memberUser}`,
                embeds:
                [
                    {
                        author: author,
                        color: isJoin ? 0x00FF00 : 0xFF0000, // GREEN / RED
                        description: log_text,
                        footer:
                        {
                            text: SERVERS[server].name,
                        },
                        timestamp: dt(),
                    },
                ]
            }
        )
        .catch (console.error);
    }
    catch (e)
    {
        // Ошибка лога НЕ должна ронять поллер (иначе снапшот не обновится и
        // один и тот же человек будет 'входить' на каждом тике).
        console.error ('[member] запись входа/выхода: ' + e.message);
    }
}

// ============================================================================
// [v2.14] ОТЧЁТ ПО БАНАМ/ТАЙМАУТАМ: сколько поднято из базы при старте и что активно
// сейчас. Владелец просил видеть после каждого перезапуска, не был ли кто наказан
// за время, пока бот не работал (раньше это приходилось выяснять только по журналу
// Discord), и видеть по команде, кто сидит в наказании и до какого часа.
// ============================================================================

// Русские формы числительных: plural(2,'трек','трека','треков') -> 'трека'
function plural (n, one, few, many)
{
    const a = Math.abs (n) % 100, b = a % 10;
    if (a > 10 && a < 20) return many;
    if (b > 1 && b < 5) return few;
    if (b === 1) return one;
    return many;
}

// Что лежит в базе: активные (срок ещё идёт) и просроченные (срок вышел, пока бота
// не было -- их снимет sweepExpiredBans). Сортировка по сроку окончания.
async function storedBans (server)
{
    let active = [], expired = [];
    try
    {
        for await (const [id, until] of $db[server]['membersBanTimeout'].iterator())
        {
            if (typeof until !== 'number') continue; // не таймаут-запись
            if (Date.now() < until) active.push ({ id, until });
            else expired.push ({ id, until });
        }
    }
    catch (e) { console.error ('[ban] не смог прочитать базу: ' + oneLine (e.message)); }
    active.sort ((a, b) => a.until - b.until);
    return { active, expired };
}

// Действующие баны сервера из Discord (id -> причина). Это ЕДИНСТВЕННЫЙ способ отличить
// настоящий бан от простого таймаута: в базе лежит только срок, а бана при
// onLeaveBanRealy: false может и не быть.
async function guildBans (server)
{
    const guild = client.guilds.cache.get (server);
    const map = new Map ();
    if (!guild) return map;
    try
    {
        const bans = await guild.bans.fetch ();
        for (const [id, ban] of bans) map.set (id, (ban && ban.reason) || '');
    }
    catch (e) { console.error ('[ban] список банов не получен: ' + oneLine (e.message)); }
    return map;
}

// ============================================================================
// [v2.15] ИСТОРИЯ НАКАЗАНИЙ: кто сколько раз выходил с сервера и сколько раз
// получал таймаут/бан. Текущее наказание в базе -- одно число (до какого срока),
// истории из него не видно, поэтому пишем отдельные события:
//   exit    -- человек вышел с сервера (видит поллер)
//   timeout -- за выход записан таймаут
//   ban     -- реально выдан бан (сразу при выходе или при перезаходе в таймаут)
//   unban   -- наказание снято (само по сроку или вручную через /unban)
// Срок хранения -- bans_history_days: 0 (по умолчанию) -- копим всегда, число -- окно.
// Плюс жёсткий предел на длину списка событий (200), чтобы одна запись не росла вечно.
// ============================================================================

// Таймеры снятия наказаний: server -> Map<uid, timeout>. Нужны, чтобы можно было
// ОТМЕНИТЬ снятие (/unban): иначе старый таймер сработает позже и попытается снять
// то, что уже снято вручную (в лог попало бы «unbanned» после снятия).
const $banTimers = {};
function banTimerSet (server, uid, ms, fn)
{
    const map = $banTimers[server] = $banTimers[server] || new Map ();
    banTimerClear (server, uid);
    const t = setTimeout
    (
        () =>
        {
            if (map.get (uid) === t) map.delete (uid);
            try { fn (); } catch (e) { console.error ('[ban] таймер ' + uid + ': ' + oneLine (e.message)); }
        },
        ms
    );
    map.set (uid, t);
    return t;
}
function banTimerFor (server, uid)
{
    const map = $banTimers[server];
    return !!(map && map.get (uid));
}
function banTimerClear (server, uid)
{
    const map = $banTimers[server];
    if (!map) return false;
    const t = map.get (uid);
    if (!t) return false;
    clearTimeout (t);
    map.delete (uid);
    return true;
}

// [v2.18] Срок хранения истории наказаний. 0 (или не задано) -- НАВСЕГДА: статистика
// за годы ценнее, чем съезжающее окно. Свип в этом случае вообще ничего не удаляет.
function banHistoryDays (server)
{
    const days = Number ((SERVERS[server] || {}).bans_history_days);
    if (!Number.isFinite (days)) return 0; // не задано -- храним всегда
    return (days > 0) ? Math.floor (days) : 0;
}

// Окно истории в человеческом виде: «за 30 дн» или «за всё время».
function banHistoryLabel (server)
{
    const days = banHistoryDays (server);
    return days ? ('за ' + days + ' дн') : 'за всё время';
}

// Записать событие по человеку. Окно истории -- bans_history_days, плюс жёсткий
// предел на длину списка (200), чтобы база не росла бесконечно.
async function banHistoryAdd (server, uid, kind)
{
    if (!uid || !(kind in { exit: 1, timeout: 1, ban: 1, unban: 1 })) return;
    try
    {
        const days = banHistoryDays (server);
        const cut = days ? Date.now () - days * 86400000 : 0;
        let rec = await db (server, 'banHistory', uid);
        let events = (rec && Array.isArray (rec.events)) ? rec.events : [];
        events.push ({ at: Date.now (), kind: kind });
        events = events.filter (e => e && typeof e.at === 'number' && e.at >= cut).slice (-200);
        await db (server, 'banHistory', uid, { at: Date.now (), events: events });
    }
    catch (e) { console.error ('[ban] не смог записать историю ' + uid + ': ' + oneLine (e.message)); }
}

// Сводка по истории за окно: кто сколько раз выходил, сколько таймаутов и банов.
async function bansHistory (server)
{
    const days = banHistoryDays (server);
    const cut = days ? Date.now () - days * 86400000 : 0;
    const rows = [];
    try
    {
        for await (const [id, rec] of $db[server]['banHistory'].iterator())
        {
            const events = (rec && Array.isArray (rec.events))
                ? rec.events.filter (e => e && typeof e.at === 'number' && e.at >= cut)
                : [];
            if (!events.length) continue;
            const c = k => events.filter (e => e.kind === k).length;
            rows.push ({ id: id, exit: c ('exit'), timeout: c ('timeout'), ban: c ('ban'),
                         unban: c ('unban'), last: Math.max (...events.map (e => e.at)) });
        }
    }
    catch (e) { console.error ('[ban] история не прочиталась: ' + oneLine (e.message)); }
    // Сначала те, у кого были баны, потом по выходам, потом по свежести:
    rows.sort ((a, b) => (b.ban - a.ban) || (b.exit - a.exit) || (b.last - a.last));
    return rows;
}

// Уборка: записи, где за окно не осталось ни одного события, больше не нужны.
async function sweepBanHistory (server)
{
    // История хранится навсегда (bans_history_days: 0) -- убирать нечего.
    if (!banHistoryDays (server)) return;
    const cut = Date.now () - banHistoryDays (server) * 86400000;
    let keys = [];
    try
    {
        for await (const [id, rec] of $db[server]['banHistory'].iterator())
        {
            const events = (rec && Array.isArray (rec.events)) ? rec.events : [];
            if (!events.some (e => e && typeof e.at === 'number' && e.at >= cut)) keys.push (id);
        }
        for (const key of keys) await db (server, 'banHistory', key, null);
    }
    catch (e) { console.error ('[ban] уборка истории: ' + oneLine (e.message)); return; }
    // [v2.17] Формулировка -- про СРОК ХРАНЕНИЯ, а не «убрал»: видно, что данные
    // старше окна (bans_history_days) удалены из базы и что актуального в них нет.
    if (keys.length)
        console.log ('[' + (d()) + '] [ban] истёк срок хранения истории ' + banHistoryDays (server) +
            ' дн (bans_history_days): удалено из базы ' + keys.length + ' ' +
            plural (keys.length, 'запись', 'записи', 'записей') + ' -- событий в них уже не было, активные наказания не тронуты');
}

// Имена наказанных: у забаненного нет объекта участника (он не на сервере) -- берём
// пользователя по REST. Если и его не отдали -- остаётся id (падать из-за этого нельзя).
async function namesFor (ids)
{
    const map = new Map ();
    for (const id of [...new Set (ids)].slice (0, 40))
    {
        let user = client.users.cache.get (id);
        if (!user) user = await client.users.fetch (id).catch (() => null);
        map.set (id, user ? user.username : id);
    }
    return map;
}

// Одна сводка для старта и для /bans: строки -- по людям, каждая уже с точным сроком,
// плюс история за окно bans_history_days.
async function bansOverview (server)
{
    const { active, expired } = await storedBans (server);
    const bans = await guildBans (server);
    const hist = await bansHistory (server);
    const names = await namesFor ([...active.map (a => a.id), ...hist.map (h => h.id)]);
    // [v2.28] «Бан не подтверждён Discord»: в базе таймаут есть, а бана у Discord нет,
    // хотя по конфигу он должен был быть выдан при выходе (onLeaveBanRealy). Значит вызов
    // бана НЕ прошёл: чаще всего нет права «Банить участников» или роль бота ниже роли
    // человека. Это не «бог знает что» и не навсегда: при перезаходе бот попробует снова,
    // а в конце срока запись уйдёт сама (и ложного «разбанил» не будет).
    const leaveBan = (SERVERS[server].onLeaveBanRealy || false) && (SERVERS[server].onLeaveBanTimeout || 0) > 0;
    const rows = active.map (a =>
    ({
        id: a.id,
        until: a.until,
        isBan: bans.has (a.id),
        reason: bans.get (a.id) || '',
        name: names.get (a.id) || a.id,
        left: dd (a.until),
        at: d (a.until, true),
        unconfirmed: leaveBan && !bans.has (a.id),
    }));
    const histRows = hist.slice (0, 10).map (h => Object.assign ({}, h, { name: names.get (h.id) || h.id }));
    return { rows, expired, hist, histRows, histDays: banHistoryDays (server) };
}

// ============================================================================
// [v2.24] ЛИМИТЫ DISCORD -- одной таблицей, чтобы не выяснять их опытным путём:
//   * обычное сообщение (content): 2000 символов;
//   * описание embed'а (description): 4096; в одном сообщении до 10 embed'ов и до 6000
//     символов суммарно (поэтому /help и стартовая ЛС режутся на несколько -- см. helpEmbeds);
//   * статус голосового канала: 500; название активности (профильный статус): 128;
//     ник: 32; название канала: 100; причина в журнале аудита: 512.
// Отчёты собираются из ЖИВЫХ данных (длинные причины наказаний, длинные списки ролей),
// поэтому без проверки ответ уходил за лимит и Discord отклонял СООБЩЕНИЕ ЦЕЛИКОМ: вместо
// списка человек видел «Ошибка: Invalid Form Body». Ниже -- общая страховка.
// ============================================================================
const MSG_TEXT_LIMIT = 2000;

// Уложить текст в лимит сообщения по границе строки и честно сказать, что показано не всё.
function fitMsgText (text, limit = MSG_TEXT_LIMIT)
{
    if (text.length <= limit) return text;
    const cut = text.lastIndexOf ('\n', limit - 120);
    return (cut > 0 ? text.slice (0, cut) : text.slice (0, limit - 120)) +
        '\n_…показано не всё: ответ не влезает в лимит Discord (' + limit + ' символов)._ ';
}

// Текст отчёта для человека (ЛС/ответ на /bans): имена, сроки, причина + история.
function bansReportText (o, max = 20)
{
    const banned = o.rows.filter (r => r.isBan).length;
    let text;
    if (!o.rows.length)
        text = '✅ Активных банов и таймаутов нет' +
            (o.expired.length
                ? ' (просроченных записей в базе: ' + o.expired.length + ' -- бот снимет их в ближайшем тике)'
                : '') + '.';
    else
    {
        const lines = o.rows.slice (0, max).map (r =>
            '• **' + r.name + '** -- ' + (r.isBan ? '🚫 бан' : '⏳ таймаут') +
            (r.unconfirmed ? ' (бан не подтверждён Discord)' : '') +
            ', снимется `' + r.at + '` (через `' + r.left + '`)' +
            (r.reason ? '\n  причина: `' + clipText (oneLine (r.reason, 160), 160) + '`' : ''))
            .join ('\n');
        const unconf = o.rows.filter (r => r.unconfirmed).length;
        text = '🛡️ **Наказания сейчас (' + o.rows.length + ': ' + banned + ' ' + plural (banned, 'бан', 'бана', 'банов') +
            ', ' + (o.rows.length - banned) + ' ' + plural (o.rows.length - banned, 'таймаут', 'таймаута', 'таймаутов') + ')**\n' +
            lines +
            (o.rows.length > max ? '\n*...и ещё ' + (o.rows.length - max) + '*' : '') +
            (unconf ? '\n⚠️ **Бан не подтверждён Discord: ' + unconf + '** -- таймаут в базе есть, а бана у Discord нет,\n' +
                '  хотя по конфигу бот должен был забанить при выходе. Обычно это нехватка права\n' +
                '  «Банить участников» или роль бота НИЖЕ роли человека. Что делать: выдать право /\n' +
                '  поднять роль бота -- бан прилетит сам при следующем перезаходе (таймаут сохранится);\n' +
                '  либо снять наказание вручную: `/unban user:@кто`. Само это не «навсегда»:\n' +
                '  запись уйдёт в конце срока (`снимется …`), ложного разбана при этом не будет.' : '') +
            (o.expired.length ? '\n_Просроченных записей в базе: ' + o.expired.length + ' -- снимутся сами._' : '');
    }
    // [v2.15] История за окно: кто сколько раз выходил и сколько раз получал наказание.
    // Она копится с этой версии -- у более старых событий данных просто нет.
    if (o.hist)
    {
        const days = o.histDays;
        const window = days ? ('За ' + days + ' дн') : 'За всё время';
        if (!o.hist.length)
            text += '\n\n📊 ' + window + ' наказаний не было (история ведётся с этой версии).';
        else
            text += '\n\n📊 **' + window + ' (' + o.hist.length + ' ' +
                plural (o.hist.length, 'человек', 'человека', 'человек') + '):**\n' +
                o.histRows.map (h =>
                    '• **' + h.name + '** -- выходов ' + h.exit + ', таймаутов ' + h.timeout +
                    ', банов ' + h.ban + (h.unban ? ', снято ' + h.unban : '') +
                    ' _(последнее: ' + d (h.last, true) + ')_').join ('\n') +
                (o.hist.length > o.histRows.length ? '\n*...и ещё ' + (o.hist.length - o.histRows.length) + '*' : '');
    }
    return text;
}

// [v2.14] Строка при СТАРТЕ: сколько наказаний поднято из базы. Пишется ВСЕГДА --
// в том числе когда наказаний нет (владелец смотрит как раз на эти строки).
async function reportStoredBans (server)
{
    try
    {
        const o = await bansOverview (server);
        const banned = o.rows.filter (r => r.isBan).length;
        const tail = o.expired.length
            ? '; просроченных записей: ' + o.expired.length + ' -- сниму сейчас (срок вышел, пока бот не работал)'
            : '';
        if (!o.rows.length)
            console.log ('[' + (d()) + '] [ban] из базы поднято 0: активных банов/таймаутов нет -- никто не наказан' + tail);
        else
            console.log ('[' + (d()) + '] [ban] из базы поднято ' + o.rows.length + ' ' +
                plural (o.rows.length, 'активное', 'активных', 'активных') + ' (' + banned + ' ' +
                plural (banned, 'бан', 'бана', 'банов') + ', ' + (o.rows.length - banned) + ' ' +
                plural (o.rows.length - banned, 'таймаут', 'таймаута', 'таймаутов') + '): ' +
                o.rows.map (r => r.name + ' до ' + r.at + ' (осталось ' + r.left +
                    (r.isBan ? ', бан' : (r.unconfirmed
                        ? ', только таймаут -- бан не подтверждён Discord (нет права «Банить участников» или роль бота ниже?)'
                        : ', только таймаут')) + ')').join (' | ') +
                tail);
    }
    catch (e)
    {
        // Отчёт не должен мешать старту: ошибку видно, бот продолжает работать.
        console.error ('[ban] отчёт при старте: ' + e.message);
    }
}

// [!!!] Рестарт-безопасность: ban-таймеры живут в памяти (setTimeout) и умирают
// вместе с процессом. Теперь при каждом старте (и в каждом тике поллера)
// проверяем просроченные membersBanTimeout в SQLite и снимаем баны.
async function sweepExpiredBans (server)
{
    let unbannedAny = false;
    try
    {
        let rows = [];
        for await (const [key, value] of $db[server]['membersBanTimeout'].iterator())
        {
            rows.push ([key, value]);
        }
        const members = client.guilds.cache.get (server).members;
        for (let [id, until] of rows)
        {
            if (typeof until !== 'number') continue; // не таймаут-запись
            if (Date.now() < until) continue;         // срок ещё не вышел
            // [v2.13] Сначала СНИМАЕМ бан, только потом чистим запись. Раньше было
            // наоборот: если снятие не удалось по-настоящему (нет прав, сеть), запись
            // уже была стёрта -- бот «забывал» о человеке, который в бане остался.
            try
            {
                const user = await members.unban (id, 'Таймаут истёк (снято при проверке)');
                await db (server, 'membersBanTimeout', id, null);
                unbannedAny = true;
                console.log ('[' + (d()) + '] участник ' + (user ? user.username : id) + ' разбанен (свип по базе)');
            }
            catch (e)
            {
                if (/Unknown Ban|404/i.test (e.message))
                {
                    // человека и так нет в бане (запись просто устарела) -- чистим;
                    // «unbanned» в лог НЕ пишем: снимать было нечего.
                    await db (server, 'membersBanTimeout', id, null);
                    unbannedAny = true;
                }
                else if (/Missing Permissions|50013|Missing Access|50001/i.test (e.message))
                {
                    // [v2.26] Прав не хватает -- повторять каждый тик (45 сек) смысла нет:
                    // в логе был бы бесконечный спам. Говорим один раз и запись убираем,
                    // честно сказав, что бан (если он есть) надо снять руками.
                    await db (server, 'membersBanTimeout', id, null);
                    console.error ('[' + (d()) + '] участник ' + id + ' НЕ разбанен (срок истёк): ' + banWhy (e) +
                        ' -- запись убрал, чтобы не спамить каждый тик; разбань вручную, если бан есть');
                }
                else
                    console.error ('[sweepExpiredBans] ' + id + ': не смог снять бан (' + e.message + ') -- запись оставлена, попробую в следующем тике');
            }
        }
    }
    catch (e)
    {
        console.error ('[sweepExpiredBans] ошибка: ' + e.message);
    }
    return unbannedAny;
}

// Полная выгрузка участников гильдии через REST (пагинация по 1000):
async function fetchAllMembersRest (guildId)
{
    let members = new Map(); // user_id -> raw member object
    let after = '0';
    for (;;)
    {
        const data = await client.rest.get
        (
            '/guilds/' + guildId + '/members?limit=1000&after=' + after
        );
        if (!Array.isArray (data) || !data.length) break;
        for (let m of data)
        {
            members.set (m.user.id, m);
        }
        after = data[data.length - 1].user.id;
        if (data.length < 1000) break;
    }
    return members;
}

// ============================================================================
// [v2.13] ПРИВЕТСТВЕННАЯ ЛС НОВИЧКУ (возвращена по просьбе владельца).
// Ключи config.json: welcome_channel -- канал знакомства (там правила и знакомство),
// welcome_message -- id сообщения в нём. Нужны ОБА: в Discord НЕТ способа найти
// сообщение по id без канала (поиск есть только по тексту внутри канала), поэтому
// канал -- это «где искать», а message -- «что именно». Зато бот не просто даёт
// ссылку: он читает это сообщение и переносит в ЛС его ТЕКСТ и КАРТИНКИ [v2.17].
// Нет id сообщения -- ссылка на канал. Пустой/неверный welcome_channel -- приветствие
// выключено целиком. Кому: всем, кто заходит НЕ в таймауте за выход (перезаходы идут
// своим путём, см. handleMemberJoin).
// [v2.40] А КУДА ВЕСТИ -- отдельный ключ: welcome_public_channel (+ необязательный
// welcome_public_message). Служебный канал с текстом правил часто ЗАКРЫТ («#архивная»):
// текст в ЛС доедет, а по ссылке новичок увидит «нет доступа». Задан публичный канал
// (например «о сервере» -- туда обычно идут приглашения) -- ссылка и название в
// приветствии берутся оттуда, а текст и картинки всё равно читаются из служебного.
// ============================================================================
const WELCOME_SRC_TTL = 10 * 60 * 1000; // не дёргать REST на каждый вход
const $welcomeSrc = {};                 // server -> { at, data }

// [v2.40] КУДА ВЕСТИ НОВИЧКА. `welcome_channel` -- СЛУЖЕБНЫЙ: в нём лежит сообщение с
// текстом правил, и часто он ЗАКРЫТ ("#архивная"): текст в ЛС доедет, а по ссылке
// новичок не увидит НИЧЕГО -- «нет доступа». Поэтому ссылку и название канала можно
// брать из ПУБЛИЧНОГО канала (`welcome_public_channel`, например «о сервере» -- туда
// обычно и падают приглашения и правила). Текст и картинки при этом по-прежнему
// читаются из служебного сообщения (`welcome_channel` + `welcome_message`).
function welcomePublicChannel (server)
{
    const s = SERVERS[server] || {};
    const pub = String (s.welcome_public_channel || '');
    return /^\d{17,20}$/.test (pub) ? pub : '';
}
function welcomeLink (server)
{
    const s = SERVERS[server] || {};
    const pub = welcomePublicChannel (server);
    const channel = pub || String (s.welcome_channel || '');
    const message = pub ? String (s.welcome_public_message || '') : String (s.welcome_message || '');
    if (!/^\d{17,20}$/.test (channel)) return null;
    return 'https://discord.com/channels/' + server + '/' + channel +
        (/^\d{17,20}$/.test (message) ? '/' + message : '');
}

// Прочитать само сообщение с правилами: текст, картинки и прочие вложения.
// Не отдалось (удалили, нет прав, канал в архиве) -- null: приветствие отправится
// со ссылкой, как раньше. refresh -- для `panda welcome`: владелец правит текст и
// сразу смотрит результат, без ожидания кэша.
async function welcomeSource (server, refresh = false)
{
    const s = SERVERS[server] || {};
    const chId = String (s.welcome_channel || '');
    const msgId = String (s.welcome_message || '');
    if (!/^\d{17,20}$/.test (chId) || !/^\d{17,20}$/.test (msgId)) return null;
    const cached = $welcomeSrc[server];
    if (!refresh && cached && Date.now () - cached.at < WELCOME_SRC_TTL) return cached.data;
    let data = null;
    try
    {
        const ch = client.channels.cache.get (chId) || await client.channels.fetch (chId);
        const msg = ch && ch.messages
            ? (ch.messages.cache.get (msgId) || await ch.messages.fetch (msgId))
            : null;
        if (msg)
        {
            const atts = [...msg.attachments.values ()];
            const isImg = a => /^image\//.test (a.contentType || '') ||
                /\.(png|jpe?g|gif|webp|avif)$/i.test (a.name || '');
            data = {
                text: (msg.content || '').trim (),
                images: atts.filter (isImg).map (a => a.url),
                files: atts.filter (a => !isImg (a)).map (a => ({ url: a.url, name: a.name || 'файл' })),
                embeds: (msg.embeds || []).length,
            };
        }
    }
    catch (e)
    {
        console.error ('[welcome] не смог прочитать сообщение ' + msgId + ' в канале ' + chId +
            ': ' + oneLine (e.message, 120) + ' -- в приветствии будет только ссылка');
    }
    $welcomeSrc[server] = { at: Date.now (), data };
    return data;
}

// Текст приветствия ОТДЕЛЬНОЙ функцией: его же показывает `panda welcome` (проверка
// на себе -- владелец может посмотреть глазами новичка и поправить welcome_message).
async function welcomeEmbed (server, user, refresh = false)
{
    const s = SERVERS[server] || {};
    const link = welcomeLink (server);
    // название канала знакомства: «зайди в #канал» понятнее одной ссылки.
    // [v2.40] Показываем тот канал, на который ведёт ссылка: задан публичный --
    // значит он и называется (в служебном имени новичку нет смысла).
    let chName = '';
    const nameChId = welcomePublicChannel (server) || String (s.welcome_channel || '');
    try
    {
        let ch = client.channels.cache.get (nameChId) ||
                 await client.channels.fetch (nameChId);
        if (ch && ch.name) chName = '#' + ch.name;
    }
    catch (e) { /* канал не отдался -- обойдёмся ссылкой */ }
    // [v2.17] Текст сообщения с правилами переносим в ЛС (раньше была только ссылка,
    // а Discord рисовал её как название сервера -- выглядело как будто текст потерялся).
    const src = await welcomeSource (server, refresh);
    let rules = '';
    if (src && src.text)
    {
        const cut = clipText (src.text, 1200);
        rules = '\n' + cut + (/\n$/.test (cut) ? '' : '\n');
        if (cut.length < src.text.length) rules += '_(текст длинный -- целиком по ссылке ниже)_\n';
    }
    if (src && src.files.length)
        rules += '📎 Вложение: ' + src.files.map (f => '[' + oneLine (f.name, 40) + '](' + f.url + ')').join (', ') + '\n';
    // [v2.18] welcome_prefix (по умолчанию true): добавлять ли к сообщению с правилами
    // СВОЙ текст -- приветствие и краткое описание возможностей бота. Поставь false --
    // и в ЛС уйдёт ТОЛЬКО текст и картинки из сообщения с правилами (+ ссылка).
    const prefixOn = s.welcome_prefix !== false;
    const rulesPart =
        `📜 **Правила и знакомство**` + (chName ? ' -- в канале ' + code (chName) : '') + `:` +
        (rules ? rules + '🔗 ' + link + '\n' : '\n' + link + '\n');
    // [v2.24] Описание embed'а -- до 4096 символов. Текст правил (до 1200) плюс список
    // файлов-вложений могли упереться в лимит, и тогда Discord отклонял ЛС ЦЕЛИКОМ:
    // новичок не получал вообще ничего. Страховка на всякий случай (в обычной жизни
    // длина далека от лимита):
    let desc = prefixOn
        ? `${user}, привет! 👋\n\n` + rulesPart +
          `\n🎵 **Музыка:** \`/play ссылка или запрос\`, очередь -- \`/queue\`,\n` +
          `выйти боту из канала -- \`/leave\` (управляют админы, модеры и роль DJ).\n` +
          `📌 Инструкция по боту -- в любой момент \`/help\`.\n` +
          `\nЕсли что-то непонятно или не работает -- напиши администрации.`
        : rulesPart;
    if (desc.length > 4000)
        desc = desc.slice (0, 3950) + '\n_(текст длинный -- целиком по ссылке в этом письме)_';
    const embed =
    {
        color: 0x00CCFF,
        title: '🐼 Добро пожаловать на ' + (s.name || 'сервер') + '!',
        description: desc,
        timestamp: dt(),
    };
    // Картинка из сообщения с правилами -- прямо в письме (как и было задумано):
    if (src && src.images.length)
        embed.image = { url: src.images[0] };
    if (s.name) embed.footer = { text: s.name };
    return embed;
}

// [v2.18] Проверочное приветствие для `panda welcome` и `/welcome`: одна логика на
// текстовую команду и на слэш (иначе ответы и лог со временем разъехались бы).
// refresh: правишь welcome_message и сразу видишь результат (без 10-минутного кэша).
async function welcomeCheckSend (server, user, whoLabel)
{
    if (!welcomeLink (server))
        return { ok: false, why: 'Приветствие выключено: в `config.json` не задан `welcome_channel` (или он неверный).' };
    try
    {
        const src = await welcomeSource (server, true);
        await user.send ({ embeds: [await welcomeEmbed (server, user)] });
        console.log ('[' + (d()) + '] [welcome] проверка: ' + whoLabel + ' -> ' + uu (user) +
            (src ? ' -- с текстом' + (src.images.length ? ' и картинкой' : '') + ' из сообщения с правилами'
                 : ' -- только ссылка (сообщение с правилами не прочиталось)'));
        return { ok: true, src: src };
    }
    catch (e)
    {
        console.error ('[' + (d()) + '] [welcome] проверка: ЛС не ушло (' + e.message + ')');
        return { ok: false, why: 'ЛС не ушло: `' + code (e.message) + '`' };
    }
}

async function welcomeDM (server, uid, raw)
{
    const link = welcomeLink (server);
    if (!link) return; // welcome_channel не задан -- приветствие выключено
    const name = (raw && raw.user && raw.user.username) || uid;
    try
    {
        const user = await client.users.fetch (uid).catch (() => null);
        if (!user || typeof user.send !== 'function')
        {
            console.error ('[welcome] ЛС новичку ' + name + ' не отправить: пользователь недоступен');
            return;
        }
        const src = await welcomeSource (server);
        await user.send ({ embeds: [await welcomeEmbed (server, user)] });
        console.log ('[' + (d()) + '] [welcome] ЛС новичку ' + name + ' отправлена (' + link + ')' +
            (src ? ' -- текст и картинки взяты из сообщения с правилами' : ' -- только ссылка (сообщение с правилами не прочиталось)') +
            (((SERVERS[server] || {}).welcome_prefix === false) ? ' [welcome_prefix: false -- без описания бота]' : ''));
    }
    catch (e)
    {
        // «личка закрыта» -- обычное дело, это не ошибка бота: пишем причину и живём
        console.error ('[welcome] ЛС новичку ' + name + ' не ушла: ' + oneLine (e.message));
    }
}

// [v2.26] ПОЧЕМУ БАН (или РАЗБАН) НЕ ПОЛУЧИЛСЯ -- одной строкой и с подсказкой, что
// делать. Discord на разные случаи отвечает одним и тем же «Missing Permissions»,
// а по логу должно быть видно, это права бота, его позиция в списке ролей или что-то ещё.
function banWhy (e)
{
    const msg = oneLine (String ((e && e.message) || e), 160);
    if (/Missing Permissions|50013/i.test (msg))
        return msg + ' [у бота нет права «Банить/Разбанивать участников» ИЛИ его роль стоит НИЖЕ роли человека -- проверь права роли бота]';
    if (/Unknown Member|10007/i.test (msg))
        return msg + ' [человека нет на сервере]';
    if (/Unknown Ban|10026/i.test (msg))
        return msg + ' [бана и не было -- снимать нечего]';
    if (/higher|hierarchy/i.test (msg))
        return msg + ' [роль бота должна стоять ВЫШЕ роли человека в списке ролей]';
    if (/Missing Access|50001/i.test (msg))
        return msg + ' [у бота нет доступа к действию -- проверь права и роль]';
    return msg;
}

// Обработка ВХОДА (бывший guildMemberAdd): бан-таймаут при перезаходе.
// [v2.13] Всё, что бот пишет в ЛС и в журнал, -- по факту: если бана не будет
// (onEnterBanRealy выключен), то и «ограничения входа» в письме не будет; если
// срок уже прошёл (запись просто не вычищена) -- это обычный вход, а не перезаход.
// Источник правды о таймауте -- база (until); setTimeout в памяти -- только удобство
// (снять бан вовремя), и если процесс перезапустился, снятие доделает sweepExpiredBans.
async function handleMemberJoin (server, uid, raw)
{
    const guild = client.guilds.cache.get (server);
    const serverName = SERVERS[server].name;
    let onLeaveBanTimeout = SERVERS[server].onLeaveBanTimeout || 0;
    let onEnterBanRealy = SERVERS[server].onEnterBanRealy || false;
    let until = await db (server, 'membersBanTimeout', uid); // конец таймаута (Date.now-мс)
    const left = until ? until - Date.now () : 0;
    const username = (raw && raw.user && raw.user.username) || uid;
    // Срок истёк, а запись ещё не вычищена (бот был выключен в момент снятия):
    // это НЕ «перезаход в таймауте» -- убираем запись и ведём себя как с обычным входом
    if (until && left <= 0)
    {
        await db (server, 'membersBanTimeout', uid, null);
        until = null;
    }
    if (!until)
    {
        // [v2.13] обычный вход (не в таймауте) -- приветственная ЛС новичку
        await welcomeDM (server, uid, raw);
        return;
    }
    const user = await client.users.fetch (uid).catch (() => null);
    if (onEnterBanRealy)
    {
        // Только здесь вход ДЕЙСТВИТЕЛЬНО ограничивается: поэтому письмо, бан и
        // запись в журнал идут вместе, а не как раньше -- письмо всем без разбора.
        // [v2.14] ТОЧНЫЕ СРОКИ вместо «~3 мин»: видно и остаток до секунды (dd),
        // и момент, когда ограничение снимется (d(until, true)).
        if (user && typeof user.send === 'function')
            await user.send
            (
                {
                    embeds:
                    [
                        {
                            color: 0xFF0000, // 'RED',
                            description:
                                `${user}, вам временно **ограничен** 🏃 вход на сервер \`${serverName}\` 🟥\n` +
                                `Причина: перезаход во время таймаута (\`${onLeaveBanTimeout} мин.\` за выход).\n` +
                                `Ограничение снимется \`${d(until, true)}\` -- это через \`${dd(until)}\``,
                        },
                    ],
                }
            )
            .catch (e => console.error ('[memberJoin] ЛС о таймауте ' + username + ' не ушла: ' + e.message));
        else
            console.error ('[memberJoin] ЛС о таймауте ' + username + ' не отправить: пользователь недоступен');
        guild.members.ban (uid,
            { reason: 'Забанен ботом до ' + d (until, true) + ' (перезаход во время таймаута, осталось ' + dd (until) + ')' })
        .then
        (
            async () =>
            {
                // [v2.13] в лог -- ровно то, что произошло: бан выдан за перезаход,
                // сколько оставалось и до какого момента (по секундам, без «~»).
                console.log ('[' + (d()) + '] участник ' + username + ' забанен до ' + d (until, true) +
                    ' (оставалось ' + dd (until) + ', перезаход во время таймаута)');
                banHistoryAdd (server, uid, 'ban');
                // [v2.15] таймер снятия -- через реестр, чтобы /unban мог его отменить
                banTimerSet (server, uid, left, async () =>
                {
                    // [v2.26] Сперва снимаем бан, только потом стираем запись (в другом
                    // порядке неудачное снятие оставило бы человека в бане, а бот бы о нём забыл)
                    try
                    {
                        const u = await guild.members.unban (uid, 'Таймаут истёк');
                        await db (server, 'membersBanTimeout', uid, null);
                        banHistoryAdd (server, uid, 'unban');
                        console.log ('[' + (d()) + '] участник ' + (u ? u.username : uid) + ' разбанен (срок истёк)');
                    }
                    catch (e)
                    {
                        if (/Unknown Ban|10026|404/i.test (String (e && e.message)))
                        {
                            await db (server, 'membersBanTimeout', uid, null);
                            console.log ('[' + (d()) + '] участник ' + username + ' уже не в бане (разбанен вручную или раньше) -- запись убрал');
                        }
                        else
                            console.error ('[' + (d()) + '] участник ' + username + ' НЕ разбанен (срок истёк): ' + banWhy (e) +
                                ' -- запись оставил, сниму при следующей проверке/запуске');
                    }
                });
            }
        )
        .catch (e => console.error ('[' + (d()) + '] участник ' + username + ' НЕ забанен (перезаход): ' + banWhy (e) +
            ' -- таймаут в базе остался, значит при следующем входе до конца срока попробую снова (и снова напишу в ЛС)'));
        return;
    }
    // [v2.13] Таймаут записан, но бана по конфигу нет (onEnterBanRealy выключен):
    // сообщаем ровно это -- без выдуманного «ограничения входа» и без письма.
    console.log ('[' + (d()) + '] участник ' + username + ' вернулся во время таймаута, но бан не выдан' +
        ' (onEnterBanRealy выключен, оставалось ' + dd (until) + ')');
}

// Обработка ВЫХОДА (бывший guildMemberRemove): бан-за-выход.
// Причины банов: 'Забанен ботом на N мин.' (сразу при выходе, onLeaveBanRealy)
// и 'Забанен ботом на ~N мин. (перезаход во время таймаута)' (при перезаходе).
async function handleMemberLeave (server, uid, raw, since = 0)
{
    const guild = client.guilds.cache.get (server);
    let log_channel = SERVERS[server].log_channel || '';
    let onLeaveBanTimeout = SERVERS[server].onLeaveBanTimeout || 0;
    let onLeaveBanRealy = SERVERS[server].onLeaveBanRealy || false;
    // [v2.26] Нужен только для честной подсказки в логе: что будет с человеком дальше
    // (попробует ли бот забанить его при перезаходе).
    const onEnterBanRealy = SERVERS[server].onEnterBanRealy || false;
    // [v2.14] Сначала запоминаем роли выходящего -- ДО таймаута и до любых банов.
    // Это делает сама PANDAMIA (раньше это умел только сторонний бот), см. saveMemberRoles.
    // [v2.15] since -- время снимка поллера: роль, снятая за секунды до выхода, в базу
    // НЕ попадёт (её правку достроит rolesWithChangesAfter по журналу аудита).
    await saveMemberRoles (server, uid, raw, since);
    // [v2.15] Сам выход записываем в историю ВСЕГДА (даже если таймаут-механизм выключен):
    // /bans показывает «кто сколько раз выходил с сервера» именно по этим событиям.
    await banHistoryAdd (server, uid, 'exit');
    if (await db (server, 'membersBanTimeout', uid))
    {
        // Уже в таймауте (перезаход) -- банить повторно не надо.
        return;
    }
    if (!onLeaveBanTimeout) return; // функция выключена
    let username = raw && raw.user ? (raw.user.username + (raw.nick ? ' (' + raw.nick + ')' : '')) : uid;
    if (onLeaveBanRealy)
    {
        // [v2.14] точный срок бана: и причина в аудите Discord, и строка в логе.
        const untilLeave = Date.now () + onLeaveBanTimeout * 60 * 1000;
        // [v2.26] СНАЧАЛА фиксируем сам таймаут (запись в базе), и только потом пробуем
        // забанить. Раньше запись жила ВНУТРИ .then после успешного бана: если бан не
        // получился (у бота нет права «Банить участников», его роль ниже роли человека,
        // сбой сети или Discord), не оставалось ВООБЩЕ ничего -- ни таймаута, ни события
        // в историю, ни бана при перезаходе. Человек заходил как обычно, а в логе была
        // одна строка про ошибку. Теперь факт наказания не зависит от того, удался ли
        // вызов: запись есть всегда, и при перезаходе бот попробует забанить снова.
        await db (server, 'membersBanTimeout', uid, untilLeave);
        let banned = false;
        try
        {
            await guild.members.ban
            (
                uid,
                {
                    days: 0,
                    reason: 'Забанен ботом до ' + d (untilLeave, true) + ' (выход с сервера, таймаут ' + onLeaveBanTimeout + ' мин.)',
                }
            );
            banned = true;
            banHistoryAdd (server, uid, 'ban');
            // [v2.13] бан выдан сразу при выходе (onLeaveBanRealy: true)
            console.log ('[' + (d()) + '] участник ' + username + ' забанен до ' + d (untilLeave, true) +
                ' (' + onLeaveBanTimeout + ' мин., при выходе)');
        }
        catch (e)
        {
            // [v2.26] Неудавшийся бан -- это НЕ «ничего»: таймаут уже записан (значит
            // человек попадёт в проверку при перезаходе), а в историю идёт событие «таймаут»,
            // чтобы в /bans было видно, что наказание было, просто Discord его не принял.
            // Причину и что будет дальше пишем прямо в лог.
            banHistoryAdd (server, uid, 'timeout');
            console.error ('[' + (d()) + '] участник ' + username + ' НЕ забанен (бан при выходе не выдался): ' + banWhy (e) +
                ' -- таймаут ' + onLeaveBanTimeout + ' мин. всё равно записан: вернётся раньше срока -- ' +
                (onEnterBanRealy
                    ? 'попробую забанить снова (onEnterBanRealy)'
                    : 'будет только строка в логе, бан не выдам (onEnterBanRealy выключен)'));
        }
        banTimerSet (server, uid, onLeaveBanTimeout * 60 * 1000, async () =>
        {
            if (!banned)
            {
                // [v2.26] Бана не было (вызов не удался) -- снимать нечего: забываем таймаут
                // и пишем это прямо, чтобы в конце срока не было попытки снять несуществующий бан.
                await db (server, 'membersBanTimeout', uid, null);
                console.log ('[' + (d()) + '] участник ' + username + ' таймаут истёк спустя ' + onLeaveBanTimeout +
                    ' мин. (бана не было -- снимать нечего)');
                return;
            }
            // [v2.26] ПОРЯДОК ВАЖЕН: сперва снимаем бан, и только потом стираем запись.
            // Раньше было наоборот: если снятие не прошло (права/сеть), запись уже стёрта,
            // и человек остался бы в бане навсегда, а бот бы про него «забыл».
            try
            {
                const user = await guild.members.unban (uid, 'Таймаут истёк');
                await db (server, 'membersBanTimeout', uid, null);
                banHistoryAdd (server, uid, 'unban');
                console.log ('[' + (d()) + '] участник ' + (user ? user.username : uid) + ' разбанен (срок истёк)');
            }
            catch (e)
            {
                if (/Unknown Ban|10026|404/i.test (String (e && e.message)))
                {
                    // человека уже разбанили (руками или раньше) -- это не ошибка
                    await db (server, 'membersBanTimeout', uid, null);
                    console.log ('[' + (d()) + '] участник ' + username + ' уже не в бане (разбанен вручную или раньше) -- запись убрал');
                }
                else
                    console.error ('[' + (d()) + '] участник ' + username + ' НЕ разбанен (срок истёк): ' + banWhy (e) +
                        ' -- запись оставил, сниму при следующей проверке/запуске');
            }
        });
    }
    else
    {
        // [FIX v2.13] Бан здесь НЕ выдаётся (onLeaveBanRealy: false) -- ставится только
        // таймаут: бан прилетит, если человек зайдёт раньше срока (handleMemberJoin,
        // onEnterBanRealy). Раньше в логе писалось «banned on N min.», хотя никакого
        // бана не было -- теперь написано ровно то, что сделано.
        const untilTimeout = Date.now () + onLeaveBanTimeout * 60 * 1000;
        await db (server, 'membersBanTimeout', uid, untilTimeout);
        banHistoryAdd (server, uid, 'timeout');
        console.log ('[' + (d()) + '] участник ' + username + ' таймаут до ' + d (untilTimeout, true) +
            ' (' + onLeaveBanTimeout + ' мин., бан -- только если вернётся раньше)');
        banTimerSet (server, uid, onLeaveBanTimeout * 60 * 1000, async () =>
        {
            await db (server, 'membersBanTimeout', uid, null);
            console.log ('[' + (d()) + '] участник ' + username + ' таймаут истёк спустя ' + onLeaveBanTimeout +
                ' мин. (не вернулся)');
        });
    }
}

// ============================================================================
// [v2.14] РОЛИ ЖИВУТ МЕЖДУ ПЕРЕЗАХОДАМИ (config: save_roles, по умолчанию ВКЛЮЧЕНО)
// Раньше этим занимался сторонний бот: человек выходил с сервера, терял роли и
// получал их обратно только благодаря ему. Теперь это умеет и PANDAMIA:
//   * на выходе роли участника кладутся в базу (ключ -- его id);
//   * на входе бот ДОБАВЛЯЕТ то, чего сейчас нет, и НИЧЕГО не отнимает. Поэтому
//     работать это может одновременно с другим ботом-хранителем: кто успел -- тот и
//     вернул, второй просто ничего не меняет (у нас -- add-only);
//   * ненужное в базу не пишем: @everyone, роли интеграций (managed -- их нельзя
//     выдать) и роли, которых на сервере уже нет; свой список -- save_roles_exclude;
//   * [v2.18] записи хранятся НАВСЕГДА (save_roles_days: 0 -- значение по
//     умолчанию). Можно задать число дней -- тогда старое убирает свип.
// Выключить совсем: "save_roles": false у сервера.
// ============================================================================
const ROLE_SAVE_DAYS_DEFAULT = 0; // 0 = не забывать никогда

function roleSaveOn (server)
{
    return (SERVERS[server] || {}).save_roles !== false;
}

// Можно ли эту роль выдать обратно: не исключена в конфиге, не @everyone, не роль
// интеграции (managed) и всё ещё существует на сервере.
function roleRestorable (server, guild, id)
{
    const s = SERVERS[server] || {};
    const skip = (Array.isArray (s.save_roles_exclude) ? s.save_roles_exclude : []).map (String);
    if (skip.includes (String (id))) return false;
    const role = guild.roles.cache.get (id);
    return !!(role && !role.managed && role.id !== guild.id);
}

// [v2.18] Срок хранения записей о ролях. 0 (или не задано) -- НАВСЕГДА: роли --
// основная задача бота, и терять их из-за «срока давности» незачем. Но кому нужно
// ограничить базу -- ставит любое число дней, и старое убирает свип.
function roleSaveDays (server)
{
    const d = Number ((SERVERS[server] || {}).save_roles_days);
    if (!Number.isFinite (d)) return ROLE_SAVE_DAYS_DEFAULT; // не задано (0)
    return (d > 0) ? Math.floor (d) : 0;
}

// Подпись срока для логов и отчётов: «навсегда» или «N дн».
function roleSaveLabel (server)
{
    const days = roleSaveDays (server);
    return days ? (days + ' дн') : 'навсегда';
}

// [v2.15] Роли с учётом правок, случившихся ПОСЛЕ снимка поллера (since -- время
// снимка). Сначала смотрим кольцо журнала аудита (приходит мгновенно), а если там
// ничего -- спрашиваем журнал через REST (бот мог быть перезапущен в этот момент).
// Нет прав/журнал недоступен -- остаёмся при снимке, как раньше.
async function rolesWithChangesAfter (server, uid, roles, since)
{
    let out = (roles || []).slice ();
    let changes = $roleChanges.filter (r => r.targetId === uid && r.at >= since);
    if (!changes.length && since)
    {
        const guild = client.guilds.cache.get (server);
        if (!guild) return out;
        try
        {
            const logs = await guild.fetchAuditLogs ({ type: AuditLogEvent.MemberRoleUpdate, limit: 50 });
            const got = [];
            for (const e of logs.entries.values ())
            {
                if (e.targetId !== uid || e.createdTimestamp < since) continue;
                const d = roleDeltaOf (e.changes);
                if (d.add.length || d.remove.length) got.push ({ add: d.add, remove: d.remove, at: e.createdTimestamp });
            }
            changes = got.sort ((a, b) => a.at - b.at); // старые правки -- первыми
        }
        catch (e) { return out; } // нет «Просматривать журнал аудита» -- снимок как есть
    }
    for (const ch of changes)
    {
        const rm = new Set ((ch.remove || []).map (String));
        out = out.filter (id => !rm.has (String (id)));
        for (const id of (ch.add || []))
            if (!out.some (have => String (have) === String (id))) out.push (id);
    }
    return out;
}

// Запомнить роли выходящего участника (вызывается ДО выдачи таймаута).
// [v2.15] since -- время снимка поллера: всё, что человек потерял/получил после
// снимка, достраивается по журналу аудита (см. rolesWithChangesAfter).
async function saveMemberRoles (server, uid, raw, since = 0)
{
    if (!roleSaveOn (server)) return;
    const guild = client.guilds.cache.get (server);
    if (!guild) return;
    let roles = (raw && Array.isArray (raw.roles)) ? raw.roles : null;
    if (!roles) return; // данных о ролях нет -- запоминать нечего
    if (since) roles = await rolesWithChangesAfter (server, uid, roles, since);
    const name = (raw && raw.user && raw.user.username) || uid;
    const keep = roles.filter (id => roleRestorable (server, guild, id));
    if (!keep.length)
    {
        // [v2.15] Возвращать нечего (роли исключены/удалены/сняты до выхода). Если
        // запись осталась от ПРОШЛОГО выхода -- стираем: иначе она вернула бы роль,
        // которую человек уже потерял (та самая неточность).
        await db (server, 'memberRoles', uid, null).catch (() => {});
        return;
    }
    try
    {
        await db (server, 'memberRoles', uid, { at: Date.now (), roles: keep });
        console.log ('[' + (d()) + '] [roles] запомнил ' + keep.length + ' ' + plural (keep.length, 'роль', 'роли', 'ролей') +
            ' для ' + name + ': ' + keep.map (id => '«' + ((guild.roles.cache.get (id) || {}).name || id) + '»').join (', '));
    }
    catch (e) { console.error ('[roles] не смог сохранить роли ' + name + ': ' + oneLine (e.message)); }
}

// Вернуть роли при входе. Важно: только ДОБАВЛЯЕМ (ничего не снимаем) -- так этот
// механизм не мешает другим ботам и не спорит с ручной выдачей ролей администрацией.
async function restoreMemberRoles (server, uid, raw)
{
    if (!roleSaveOn (server)) return 0;
    const guild = client.guilds.cache.get (server);
    if (!guild) return 0;
    const name = (raw && raw.user && raw.user.username) || uid;
    let saved = null;
    try { saved = await db (server, 'memberRoles', uid); }
    catch (e) { console.error ('[roles] не смог прочитать роли ' + name + ': ' + oneLine (e.message)); return 0; }
    if (!saved || !Array.isArray (saved.roles) || !saved.roles.length) return 0;
    const days = roleSaveDays (server);
    if (days && Date.now () - (Number (saved.at) || 0) > days * 86400000)
    {
        await db (server, 'memberRoles', uid, null).catch (() => {});
        console.log ('[' + (d()) + '] [roles] запись о ролях ' + name + ' старше ' + days + ' дн -- забываю');
        return 0;
    }
    const have = new Set ((raw && Array.isArray (raw.roles)) ? raw.roles : []);
    const want = saved.roles.filter (id => !have.has (id) && roleRestorable (server, guild, id));
    if (!want.length) return 0;
    try
    {
        const member = await guild.members.fetch (uid);
        await member.roles.add (want, 'PANDAMIA: возврат ролей после перезахода');
        console.log ('[' + (d()) + '] [roles] вернул ' + want.length + ' ' + plural (want.length, 'роль', 'роли', 'ролей') + ' ' + name + ': ' +
            want.map (id => '«' + ((guild.roles.cache.get (id) || {}).name || id) + '»').join (', '));
        return want.length;
    }
    catch (e)
    {
        // Запись НЕ удаляем: если не вышло из-за бана/прав/сети, попробуем в следующий вход.
        console.error ('[roles] не смог вернуть роли ' + name + ': ' + oneLine (e.message) + ' -- запись оставлена, попробую в следующий вход');
        return 0;
    }
}

// Уборка старых записей о ролях. Записи без даты (старый формат) убираются всегда --
// у них нет возраста, вернуть они ничего не могут. При хранении «навсегда» (0) свип
// роли не трогает вообще.
async function sweepSavedRoles (server)
{
    if (!roleSaveOn (server)) return;
    const days = roleSaveDays (server);
    let keys = [];
    try
    {
        for await (const [key, value] of $db[server]['memberRoles'].iterator())
        {
            if (!value || typeof value.at !== 'number' ||
                (days && Date.now () - value.at > days * 86400000))
                keys.push (key);
        }
        for (const key of keys) await db (server, 'memberRoles', key, null);
    }
    catch (e) { console.error ('[roles] уборка: ' + oneLine (e.message)); return; }
    // [v2.17] Ясная формулировка: это истёк срок хранения (save_roles_days), а не потеря.
    // [v2.18] При хранении «навсегда» тут могут быть только записи без даты.
    if (keys.length)
        console.log ('[' + (d()) + '] [roles] ' + (days
            ? 'истёк срок хранения ' + days + ' дн (save_roles_days)'
            : 'в базе записи без даты') + ': удалено из базы ' +
            keys.length + ' ' + plural (keys.length, 'запись', 'записи', 'записей') +
            ' о ролях -- эти роли всё равно не вернулись бы (' +
            (days ? 'запись просрочена' : 'в старой записи нет даты') + ')');
}

// ============================================================================
// [v2.17] /rolecheck -- «что бот помнит о человеке»: роли, наказания и что именно
// он вернёт при следующем входе. Работает и для НЕ-участника сервера: роли и
// наказания лежат в базе по id, а для проверки самого человека хватает REST
// «Get Guild Member» (одиночный запрос -- интента Guild Members не требует).
// ============================================================================
async function rolecheckReport (server, target)
{
    const s = SERVERS[server] || {};
    const guild = client.guilds.cache.get (server);
    const out = [];
    out.push ('🔎 **' + target.username + '** `' + target.id + '`');
    // --- есть ли человек на сервере и какие роли у него сейчас ---
    let member = null, memberWhy = '';
    try { member = await guild.members.fetch (target.id); }
    catch (e) { memberWhy = oneLine (e.message, 90); }
    const haveRoles = member ? new Set (member.roles.cache.keys ()) : null;
    if (member)
        out.push ('\n**На сервере:** да' + (member.nickname ? ' (ник: ' + member.nickname + ')' : '') +
            '\nРоли сейчас (' + (member.roles.cache.size - 1) + '): ' +
            (member.roles.cache.filter (r => r.id !== guild.id).map (r => '«' + r.name + '»').join (', ') || '--'));
    else
        out.push ('\n**На сервере:** нет' + (memberWhy ? ' _(проверить не смог: `' + memberWhy + '`)_' : ''));
    // --- роли, которые бот помнит (save_roles) ---
    let saved = null, saveWhy = '';
    try { saved = await db (server, 'memberRoles', target.id); }
    catch (e) { saveWhy = oneLine (e.message, 90); }
    const nameOf = id => '«' + ((guild.roles.cache.get (id) || {}).name || id) + '»';
    if (!roleSaveOn (server))
        out.push ('\n**Роли при входе:** функция выключена (`save_roles: false`)');
    else if (saveWhy)
        out.push ('\n**Роли при входе:** база не прочиталась (`' + saveWhy + '`)');
    else if (!saved || !Array.isArray (saved.roles) || !saved.roles.length)
        out.push ('\n**Роли при входе:** записи нет -- возвращать нечего');
    else
    {
        const days = roleSaveDays (server);
        const age = Math.round ((Date.now () - (Number (saved.at) || 0)) / 86400000);
        out.push ('\n**Роли при входе** (`save_roles`, хранение ' + roleSaveLabel (server) + '): запомнено ' +
            saved.roles.length + ' ' + plural (saved.roles.length, 'роль', 'роли', 'ролей') +
            ' (' + (Number (saved.at) ? d (saved.at, true) : '?') + ')');
        out.push ('• помню: ' + saved.roles.map (nameOf).join (', '));
        if (days && age > days)
            out.push ('• ⏳ запись старше ' + days + ' дн -- при входе она забывается, роли возвращаться НЕ будут');
        else
        {
            const want = saved.roles.filter (id => !(haveRoles && haveRoles.has (id)) && roleRestorable (server, guild, id));
            out.push (want.length
                ? '• ✅ вернётся при входе: ' + want.map (nameOf).join (', ')
                : '• ✅ возвращать нечего: ' + (haveRoles ? 'все эти роли у человека уже есть'
                    : 'роли уже есть / исключены в конфиге / их больше нет на сервере'));
            const skip = saved.roles.filter (id => !want.includes (id));
            if (skip.length)
                out.push ('• вычеркнуто: ' + skip.map (id => nameOf (id) +
                    (haveRoles && haveRoles.has (id) ? ' (уже есть)' :
                        (!guild.roles.cache.get (id) ? ' (роли нет на сервере)' : ' (исключена в config)'))).join (', '));
        }
    }
    // --- наказания: то же, что /bans, но по одному человеку (и с проверкой реального бана) ---
    const until = await db (server, 'membersBanTimeout', target.id).catch (() => null);
    const bans = await guildBans (server);
    const isBan = bans.has (target.id);
    const why = isBan && bans.get (target.id) ? ' (причина: ' + oneLine (bans.get (target.id), 200) + ')' : '';
    const unconfirmed = !isBan && !!until && until > Date.now () &&
        (s.onLeaveBanRealy || false) && (s.onLeaveBanTimeout || 0) > 0;
    if (until && until > Date.now ())
        out.push ('\n**Сейчас в наказании:** ' + (isBan ? '🚫 бан' : '⏳ таймаут (бана в Discord нет)') +
            ' до `' + d (until, true) + '` -- осталось `' + dd (until) + '`' + why +
            (unconfirmed ? '\n• ⚠️ бан не подтверждён Discord: по конфигу бот должен был забанить при выходе,\n' +
                '  значит вызов не прошёл (обычно нет права «Банить участников» / роль бота ниже).\n' +
                '  При перезаходе бот попробует снова; в конце срока запись уйдёт сама. Вручную -- `/unban`.' : ''));
    else if (isBan)
        out.push ('\n**Сейчас в наказании:** 🚫 бан в Discord' + why);
    else
        out.push ('\n**Сейчас в наказании:** нет' + (until ? ' _(запись о таймауте просрочена -- её снимет свип)_' : ''));
    // --- история за окно (как в /bans) ---
    const hist = await bansHistory (server);
    const row = hist.find (h => h.id === target.id);
    out.push ('\n**История ' + banHistoryLabel (server) + ':** ' + (row
        ? 'выходов ' + row.exit + ', таймаутов ' + row.timeout + ', банов ' + row.ban + ', снятий ' + row.unban +
          ' _(последнее: ' + d (row.last, true) + ')_'
        : 'ничего не записано'));
    if (s.name) out.push ('\n—_' + s.name + '_');
    return out.join ('\n');
}

// ============================================================================
// [v2.22] /mydata -- «что бот помнит обо мне». Доступна КАЖДОМУ (о себе), о другом
// человеке -- только staff (иначе это была бы разведка чужих данных).
// Зачем: человек видит ровно то, что о нём лежит, сколько этого, сколько хранится,
// как это удалить и где прочитать целиком. Прятать нечего: ни текстов сообщений,
// ни профилей, ни чего-либо ещё, кроме id-roles/счётчиков/очереди, в базе нет.
// ============================================================================
async function myDataReport (server, target, self)
{
    const out = [];
    const bytesOf = (_v) => { try { return Buffer.byteLength (JSON.stringify (_v), 'utf8'); } catch (e) { return 0; } };
    const guild = client.guilds.cache.get (server);
    const nameOf = _id => '«' + ((guild && guild.roles.cache.get (_id) || {}).name || _id) + '»';
    let rec = 0, bytes = 0;

    out.push ('🗂 **' + (self ? 'Что бот помнит о тебе' : 'Что бот помнит о ' + target.username) + '**');
    out.push ('Ключ записи -- твой id `' + target.id + '`. Ни имён, ни профилей, ни текстов сообщений бот не хранит.');

    // --- 1. роли для возврата ---
    const saved = await db (server, 'memberRoles', target.id).catch (() => null);
    const savedN = (saved && Array.isArray (saved.roles)) ? saved.roles.length : 0;
    if (savedN)
    {
        rec++; bytes += bytesOf (saved);
        out.push ('\n**1. Роли, чтобы вернуть при входе** (`memberRoles`)');
        out.push ('• ' + savedN + ' ' + plural (savedN, 'роль', 'роли', 'ролей') + ', записано ' +
            (Number (saved.at) ? d (saved.at, true) : 'без даты (старый формат)'));
        out.push ('• ' + saved.roles.map (nameOf).join (', '));
        out.push ('• хранение: ' + roleSaveLabel (server) + '; запись весит ~' + bytesOf (saved) + ' байт');
        if (!roleSaveOn (server)) out.push ('• но сейчас функция выключена (`save_roles: false`) -- при входе роли не вернутся');
    }
    else
    {
        out.push ('\n**1. Роли, чтобы вернуть при входе:** записи нет' +
            (roleSaveOn (server) ? '' : ' (и функция выключена: `save_roles: false`)'));
    }

    // --- 2. история наказаний ---
    const hist = await db (server, 'banHistory', target.id).catch (() => null);
    const ev = (hist && Array.isArray (hist.events)) ? hist.events.filter (e => e && Number (e.at)) : [];
    if (ev.length)
    {
        const cnt = (_k) => ev.filter (_e => _e.kind === _k).length;
        const ats = ev.map (_e => Number (_e.at));
        rec++; bytes += bytesOf (hist);
        out.push ('\n**2. История наказаний** (`banHistory`)');
        out.push ('• ' + ev.length + ' ' + plural (ev.length, 'событие', 'события', 'событий') + 
            ': выходов ' + cnt ('exit') + ', таймаутов ' + cnt ('timeout') + 
            ', банов ' + cnt ('ban') + ', снятий ' + cnt ('unban'));
        out.push ('• первое ' + d (Math.min (...ats), true) + ', последнее ' + d (Math.max (...ats), true) +
            ' (хранение: ' + banHistoryLabel (server) + ')');
    }
    else out.push ('\n**2. История наказаний:** ничего не записано');

    // --- 3. таймер выхода (живёт, пока идёт таймаут) ---
    const until = await db (server, 'membersBanTimeout', target.id).catch (() => null);
    if (until)
    {
        rec++; bytes += 8;
        out.push ('\n**3. Таймер выхода** (`membersBanTimeout`): ' + (until > Date.now ()
            ? 'активен до `' + d (until, true) + '` -- осталось `' + dd (until) + '`'
            : 'запись просрочена, её снимет свип'));
    }

    // --- 4. очередь музыки ---
    // [v2.24] Очередь живёт в m.tracks (поля m.queue в состоянии музыки нет). Из-за опечатки
    // этот раздел ВСЕГДА писал «в очереди треков нет», даже когда треки человека стояли
    // в очереди -- то есть отчёт о хранении показывал меньше, чем бот реально помнит.
    const m = musicOf (server);
    const inQ = (m.tracks || []).filter (_t => String ((_t && _t.byId) || '') === target.id).length;
    const cur = !!(m.current && String (m.current.byId || '') === target.id);
    if (inQ || cur)
    {
        out.push ('\n**4. Музыка** (`musicState`): ' + (inQ
            ? 'в очереди ' + inQ + ' ' + plural (inQ, 'трек', 'трека', 'треков') + ', которые добавил' + (self ? 'а' : '') + ' ' + (self ? 'ты' : 'он')
            : 'в очереди треков нет') + (cur ? ', и сейчас играет трек ' + (self ? 'твой' : 'его') : ''));
        out.push ('• хранятся только название, ссылка и автор трека; список живёт до `/stop` или конца очереди' +
            ' (сама очередь -- общая для сервера, поэтому в «Итого» ниже она не считается)');
    }
    else out.push ('\n**4. Музыка:** ничего не записано');

    // --- итог, сроки, удаление ---
    out.push ('\n**Итого в базе:** ' + rec + ' ' + plural (rec, 'запись', 'записи', 'записей') + ', ~' + bytes +
        ' байт -- всё в одном локальном файле SQLite на машине владельца бота, никуда не отправляется' +
        (DB_KEYS.length ? '; записи зашифрованы (AES-256-GCM)' : '') + '.');
    out.push ('**Чего там никогда не бывает:** текстов и истории сообщений, ников и аватаров, e-mail и телефонов, IP-адресов, платежных данных, записей голоса.');
    out.push ('**Сроки:** ' + (banHistoryLabel (server) === roleSaveLabel (server)
        ? 'роли и история -- ' + roleSaveLabel (server)
        : 'роли -- ' + roleSaveLabel (server) + '; история -- ' + banHistoryLabel (server)) +
        '; таймер выхода -- до окончания наказания; очередь музыки -- до `/stop` или конца очереди.');
    out.push ('**Как удалить:** попроси staff -- `/forget user:' + (self ? '@ты' : '@' + target.username) +
        '` стирает сразу роли, историю и треки из очереди (авторство играющего трека тоже стирается); ' +
        'либо напиши владельцу бота (контакт есть в `/help`).\n' +
        '_Активное наказание `/forget` не трогает: это уже не хранение данных, а действие модерации -- его снимает `/unban`._');
    if (privacyUrlOf (server)) out.push ('📄 Полная политика конфиденциальности: ' + privacyUrlOf (server));
    return out.join ('\n');
}

// [v2.2.3] РЕСТАРТ-БЕЗОПАСНАЯ сверка тегов 🔑: события, случившиеся пока бот был выключен
// (выдача прав, вход в канал), событиями уже не догнать -- поллер сам сверяет всех,
// кто сейчас в голосовых каналах: есть оверрайд с правами -> тег, нет -> снять:
async function sweepNicks (server)
{
    try
    {
        const guild = client.guilds.cache.get (server);
        if (!guild || !(SERVERS[server].addTag || false)) return;
        const tag = '🔑';
        // [FIX v2.3.2] REST-эндпоинт voice-states ботам недоступен (404) -- берём
        // кэш гейтвея: guild.voiceStates заполнен из GUILD_CREATE/voice-событий:
        let states = guild.voiceStates.cache;
        let checked = 0, added = 0, removed = 0;
        for (let vs of states.values ())
        {
            if (vs.id === client.user.id) continue;
            const channel = vs.channel || client.channels.cache.get (vs.channelId);
            if (!channel) continue;
            const ow = channel.permissionOverwrites.cache.get (vs.id);
            const hasRights = !!ow &&
            (
                ow.allow.has (PermissionsBitField.Flags.ManageChannels) ||
                ow.allow.has (PermissionsBitField.Flags.ManageRoles) ||
                ow.allow.has (PermissionsBitField.Flags.MoveMembers) ||
                ow.allow.has (PermissionsBitField.Flags.DeafenMembers) ||
                ow.allow.has (PermissionsBitField.Flags.MuteMembers)
            );
            // [FIX v2.3.2] VoiceState несёт member из гейтвея (vs.member) даже без
            // GuildMembers-интента; REST нужен только чтобы прочитать СВЕЖИЙ ник
            // (без интента кэш не обновляется на смену ника -- [FIX v2.3.6]).
            const base = vs.member || guild.members.cache.get (vs.id);
            if (!base || base.user.bot) continue;
            checked++;
            // Каким ник ДОЛЖЕН быть: 🔑 -- всем, у кого права в канале, кроме ADM/MOD
            // ([v2.3.5]: у staff ключа нет, даже самодорисованный бот снимает).
            const wantTag = hasRights && !isStaff (server, base);
            // [FIX v2.15] Уже знаем, что ник такой, каким должен быть? Тогда сверять нечего.
            // Раньше здесь был REST-запрос и ПОВТОРНАЯ запись того же 🔑 каждые 45 сек, и в
            // лог шла одна и та же строка «+🔑 (sweep)» -- тот самый спам. Теперь сверяемся
            // с состоянием, которое бот поставил сам.
            const known = $nickSet[server] ? $nickSet[server].get (vs.id) : undefined;
            if (known === wantTag) continue;
            // Не знаем -- читаем РЕАЛЬНЫЙ ник из REST. fetch(id) БЕЗ force вернул бы кэш
            // (discord.js: «есть в кэше -- в REST не идём»), а в кэше ник старый.
            let member = await guild.members.fetch ({user: vs.id, force: true}).catch (() => null);
            const fresh = !!member; // прочитали из REST, а не из кэша/войс-события
            if (!member) member = base;
            if (!member || member.user.bot) continue;
            let nick = member.nickname || member.user.username;
            // [FIX v2.3.3] charCodeAt (0xD83D) ловит ЛЮБОЙ эмодзи в начале ника
            // (💙, 🔊...) и свип срезал их, думая что это ключ. Точная проверка:
            let hasTag = nick.startsWith (tag); // 🔑
            // Свежий ник не прочитался (REST не отдал, сети нет)? Тогда верим тому, что
            // бот поставил сам: повторная установка -- не событие и не должна шуметь.
            if (!fresh && known !== undefined) hasTag = known;
            if (hasTag === wantTag) { nickSetMark (server, vs.id, hasTag); continue; } // уже так
            if (wantTag)
                await setNickLogged (member, tag + nick, server)
                    .then (() => { added++; console.log ('[' + (d()) + '] [nick] +🔑 (sweep) ' + member.user.username + ' в ' + channel.name); })
                    .catch (e => console.error ('[nick][sweep] ошибка для ' + member.user.username + ': ' + e.message));
            else
                await setNickLogged (member, nick.slice (tag.length), server)
                    .then (() => { removed++; console.log ('[' + (d()) + '] [nick] -🔑 ' + (isStaff (server, member) ? '(staff) ' : '(sweep) ') + member.user.username); })
                    .catch (e => console.error ('[nick][sweep] ошибка для ' + member.user.username + ': ' + e.message));
        }
        // [v2.4] итог свипа -- только в DEBUG (периодический шум в логе ни к чему):
        if (DEBUG && checked > 0 && (added > 0 || removed > 0))
            console.log ('[' + (d()) + '] [nick][sweep] проверено ' + checked + ' в голосе: +' + added + '/-' + removed + ' ключей');
    }
    catch (e)
    {
        console.error ('[nick][sweep] ошибка: ' + e.message);
    }
}

// [v2.3] Личные каналы: заход в «➕ Создать канал» -> канал «@Ник» с правами владельца + 🔑.
// Ничего не храним: пустой канал -- удаляется. После рестарта осиротевшие чистятся свипом.
async function tempCreateFor (server, member)
{
    const guild = client.guilds.cache.get (server);
    const catId = SERVERS[server].temp_category || '';
    const lobbyId = SERVERS[server].temp_lobby || '';
    if (!guild || !catId) return;
    // у человека уже есть личный канал? -- возвращаем туда:
    let exists = guild.channels.cache.find
    (
        c => c.parentId === catId &&
             c.type === ChannelType.GuildVoice &&
             c.permissionOverwrites.cache.has (member.id)
    );
    if (exists)
    {
        if (member.voice.channelId && member.voice.channelId !== exists.id)
            await member.voice.setChannel (exists.id).catch (() => {});
        return;
    }
    let name = '@' + (member.nickname || member.user.username);
    let created = await guild.channels.create
    (
        {
            name: name,
            type: ChannelType.GuildVoice,
            parent: catId,
            permissionOverwrites:
            [
                {
                    id: member.id,
                    allow:
                    [
                        PermissionsBitField.Flags.ManageChannels,
                        PermissionsBitField.Flags.MoveMembers,
                        PermissionsBitField.Flags.MuteMembers,
                        PermissionsBitField.Flags.DeafenMembers,
                        PermissionsBitField.Flags.Stream,
                    ],
                },
            ],
        }
    )
    .catch (e => { console.error ('[temp] ошибка создания: ' + e.message); return null; });
    if (!created) return;
    console.log ('[' + (d()) + '] [temp] создал ' + created.name + ' для ' + member.user.username);
    if (member.voice.channelId === lobbyId)
        await member.voice.setChannel (created.id)
            .catch (e => console.error ('[temp] ошибка перевода: ' + e.message));
    // ключ владельцу (он в своём канале -- права есть; ADM/MOD -- не трогаем):
    if ((SERVERS[server].addTag || false) && !isStaff (server, member))
    {
        let nick = member.nickname || member.user.username;
        // [FIX v2.3.3] точная проверка ключа (см. комментарий в sweepNicks):
        if (!nick.startsWith ('🔑'))
            await setNickLogged (member, '🔑' + nick, server)
                .then (() => console.log ('[' + (d()) + '] [nick] +🔑 (temp) ' + member.user.username))
                .catch (e => console.error ('[temp] ошибка смены ника: ' + e.message));
    }
    await tempSweep (server); // заодно убрать осиротевшие
}

// Удаление ПУСТЫХ личных каналов в категории:
// [FIX v2.3.1] пустоту определяем ТОЛЬКО по кэшу голосовых состояний (voiceStates):
// channel.members требует кэша участников, которого без GuildMembers-интента НЕТ.
async function tempSweep (server)
{
    const guild = client.guilds.cache.get (server);
    const catId = SERVERS[server].temp_category || '';
    const lobbyId = SERVERS[server].temp_lobby || '';
    if (!guild || !catId) return;
    for (let [, ch] of guild.channels.cache)
    {
        if (ch.parentId !== catId || ch.type !== ChannelType.GuildVoice || ch.id === lobbyId) continue;
        let busy = false;
        for (let [, vs] of guild.voiceStates.cache)
            if (vs.channelId === ch.id) { busy = true; break; }
        if (busy) continue; // в канале кто-то есть -- живём
        await ch.delete ('PANDAMIA: pustoy lichny kanal')
            .then (() => console.log ('[' + (d()) + '] [temp] удалил пустой ' + ch.name))
            .catch (e => console.error ('[temp] ошибка удаления: ' + e.message));
    }
}

// [v2.3.1] кто-то в лобби (в т.ч. с момента до старта бота) -- создать личный канал:
async function tempLobbyCheck (server)
{
    const guild = client.guilds.cache.get (server);
    const lobbyId = SERVERS[server].temp_lobby || '';
    if (!guild || !lobbyId) return;
    for (let [, vs] of guild.voiceStates.cache)
    {
        if (vs.channelId !== lobbyId) continue;
        let member = vs.member || await guild.members.fetch (vs.id).catch (() => null);
        if (member && !member.user.bot)
            await tempCreateFor (server, member).catch (e => console.error ('[temp] ошибка лобби: ' + e.message));
    }
}

// ============================================================================
// [v2.23] НАСТРОЙКИ, КОТОРЫЕ МОЛЧА НИЧЕГО НЕ ДЕЛАЮТ.
// Часть ключей config.json работает только ВМЕСТЕ с соседним или при определённом
// его значении: welcome_message без welcome_channel найти невозможно (в Discord нет
// поиска сообщения по id без канала), temp_lobby без temp_category не создаёт личных
// каналов, pipe_channel_source без pipe_channel_target некуда пересылать, а таймаут за
// выход с выключенными onLeaveBanRealy и onEnterBanRealy вообще никого не ограничивает.
// Раньше всё это выглядело как «бот просто ничего не делает» -- без единой строки в
// логе. Теперь при старте каждая такая настройка получает строку [config], а если всё
// настроено правильно -- функция молчит. Проверяются СМЫСЛОВЫЕ нестыковки (пары и
// «ни на что не влияет»); существование каналов и ролей -- отдельно, в
// checkConfigChannels (там есть guild).
// ============================================================================
function configSanityIssues ()
{
    const out = [];
    const idOk = v => /^\d{17,20}$/.test (String (v === undefined || v === null ? '' : v).trim ());
    const has = v => String (v === undefined || v === null ? '' : v).trim () !== '';
    // PREFIX без пробела на конце: 'panda ping' не соберётся ни в одну команду.
    if (has (PREFIX) && !/\s$/.test (String (PREFIX)))
        out.push ('PREFIX = "' + PREFIX + '": нет пробела на конце -- текстовые команды (' +
            'panda ping, panda help, panda dm) работать не будут');
    if (has (privacy_url) && !PRIVACY_URL)
        out.push ('privacy_url: не похоже на ссылку http(s) -- /mydata и /help её не покажут');
    // [v2.42] Ссылка на политику задаётся только верхним ключом, а показывать её или нет
    // решает каждый сервер своим show_privacy_url. Молча «угадывать» неверный тип нельзя:
    // строка "false" была бы правдой (флаг сработал бы), а строка "no" -- уже нет.
    if (show_privacy_url !== undefined && typeof show_privacy_url !== 'boolean')
        out.push ('show_privacy_url = "' + show_privacy_url + '": ожидается true или false -- ' +
            'беру значение по умолчанию (ссылка показывается, если privacy_url задан)');
    if (has (MUSIC_CFG.filter) && MUSIC_CFG.normalize === false)
        out.push ('MUSIC.filter задан, но MUSIC.normalize: false -- фильтр не применяется (играю как записано)');
    // [v2.41] Проверка очереди заранее: слишком большая глубина -- лишние запросы к YouTube
    if (MUSIC_QUEUE_CHECK && QUEUE_CHECK_DEPTH > 100)
        out.push ('MUSIC.queue_check_depth: ' + QUEUE_CHECK_DEPTH + ' -- это много запросов к YouTube ' +
            'на один проход; держи 20-30 (0 -- не проверять очередь заранее)');
    if (MUSIC_QUEUE_CHECK && MUSIC_CFG.queue_check_gap_ms !== undefined &&
        Number (MUSIC_CFG.queue_check_gap_ms) < 1000)
        out.push ('MUSIC.queue_check_gap_ms меньше 1000 -- поднимаю до 1000 (чаще не надо: это защита от лимитов YouTube)');
    // [v2.54] История добавлений: мусор в ключе молча выключал бы /history (0)
    if (MUSIC_CFG.history_len !== undefined &&
        !(Number.isFinite (Number (MUSIC_CFG.history_len)) && String (MUSIC_CFG.history_len).trim () !== ''))
        out.push ('MUSIC.history_len = "' + MUSIC_CFG.history_len + '": ожидается число -- ' +
            'иначе выходит 0, и /history будет отвечать, что история выключена (ставь 25 или не пиши ключ вовсе)');
    else if (Number (MUSIC_CFG.history_len) > 200)
        out.push ('MUSIC.history_len: ' + MUSIC_CFG.history_len + ' -- держу 200 (это запись в базе и текст сообщения, а не архив)');
    // [v2.56] Второй лимит истории -- по трекам: мусор в ключе превратился бы в 0
    // (то есть «без лимита»), и длинные плейлисты снова вытеснили бы одиночные заходы.
    if (MUSIC_CFG.history_tracks !== undefined &&
        !(Number.isFinite (Number (MUSIC_CFG.history_tracks)) && String (MUSIC_CFG.history_tracks).trim () !== ''))
        out.push ('MUSIC.history_tracks = "' + MUSIC_CFG.history_tracks + '": ожидается число -- ' +
            'иначе выходит 0, и лимита по трекам не будет (ставь 500 или не пиши ключ вовсе)');
    else if (Number (MUSIC_CFG.history_tracks) > 5000)
        out.push ('MUSIC.history_tracks: ' + MUSIC_CFG.history_tracks + ' -- держу 5000 ' +
            '(это запись в базе и текст сообщения, а не архив)');
    // [v2.57] Самообновление /queue: мусор в ключе выключил бы его молча (0), а слишком
    // частое -- упирало бы в лимиты Discord на правки сообщений (5 за 5 секунд на канал).
    if (MUSIC_CFG.queue_live_ms !== undefined &&
        !(Number.isFinite (Number (MUSIC_CFG.queue_live_ms)) && String (MUSIC_CFG.queue_live_ms).trim () !== ''))
        out.push ('MUSIC.queue_live_ms = "' + MUSIC_CFG.queue_live_ms + '": ожидается число МИЛЛИСЕКУНД -- ' +
            'иначе выходит 0 и /queue перестанет обновляться сам (ставь 30000 или не пиши ключ вовсе)');
    else if (Number (MUSIC_CFG.queue_live_ms) > 0 && Number (MUSIC_CFG.queue_live_ms) < 10000)
        out.push ('MUSIC.queue_live_ms: ' + MUSIC_CFG.queue_live_ms + ' -- это МИЛЛИСЕКУНДЫ, и меньше 10 секунд не беру: ' +
            'поднимаю до 10000. Похоже, ты указал секунды -- тогда пиши 30000 для полминуты или 60000 для минуты (правки сообщений в Discord ' +
            'ограничены примерно 5 за 5 секунд на канал)');
    // [v2.55] Живой лог в файл: мусор в ключе не должен молча менять поведение --
    // строка "шесть" превратилась бы в 0 (не удалять ничего) или "no" в NaN.
    if (log_keep_months !== undefined &&
        !(Number.isFinite (Number (log_keep_months)) && String (log_keep_months).trim () !== ''))
        out.push ('log_keep_months = "' + log_keep_months + '": ожидается число месяцев -- ' +
            'иначе выходит 0 (файлы лога не удаляются никогда; можно вообще не писать ключ)');
    if (log_dir !== undefined && typeof log_dir !== 'string')
        out.push ('log_dir = ' + JSON.stringify (log_dir) + ': ожидается папка строкой -- ' +
            'беру значение по умолчанию (logs)');
    for (let server in SERVERS)
    {
        // Значение не объект (в конфиг случайно попала строка/число) -- не падаем:
        // просто считаем блок пустым, и он получит предупреждение про allow ниже.
        const s = (SERVERS[server] && typeof SERVERS[server] === 'object') ? SERVERS[server] : {};
        const nm = (s.name || server) + ' (' + server + ')';
        // Ключа allow нет -- сервер не обслуживается вообще (все шаги пропускают его).
        if (!('allow' in s))
        {
            out.push ('сервер ' + nm + ': нет ключа "allow" -- бот его НЕ обслуживает (поставь "allow": true)');
            continue; // остальные настройки выключенного сервера не разбираем
        }
        if (s.allow === false) continue; // выключен осознанно -- придираться не к чему
        if (idOk (s.welcome_message) && !idOk (s.welcome_channel))
            out.push ('сервер ' + nm + ': welcome_message задан, а welcome_channel пуст/неверен -- ' +
                'сообщение с правилами найти негде, приветствие новичкам ВЫКЛЮЧЕНО');
        if (s.welcome_public_channel !== undefined && String (s.welcome_public_channel).trim () !== '' &&
            !idOk (s.welcome_public_channel))
            out.push ('сервер ' + nm + ': welcome_public_channel не id канала -- ' +
                'ссылка в приветствии будет вести в служебный канал (welcome_channel)');
        if (idOk (s.welcome_public_message) && !idOk (s.welcome_public_channel))
            out.push ('сервер ' + nm + ': welcome_public_message задан, а welcome_public_channel пуст -- ' +
                'ссылка на сообщение потеряется (укажи и канал, или очисти message)');
        if (idOk (s.temp_lobby) && !idOk (s.temp_category))
            out.push ('сервер ' + nm + ': temp_lobby задан, а temp_category пуст/неверен -- ' +
                'личные каналы (@ник) создаваться не будут');
        if (idOk (s.pipe_channel_source) && !idOk (s.pipe_channel_target))
            out.push ('сервер ' + nm + ': pipe_channel_source задан, а pipe_channel_target пуст -- ' +
                'пересылать некуда, мост ничего не делает');
        if ((Number (s.onLeaveBanTimeout) > 0) && s.onLeaveBanRealy === false && s.onEnterBanRealy === false)
            out.push ('сервер ' + nm + ': onLeaveBanTimeout = ' + s.onLeaveBanTimeout + ', но onLeaveBanRealy ' +
                'и onEnterBanRealy выключены -- таймаут только записывается, никто не ограничивается');
        for (let key of ['role_admin', 'role_moder', 'role_dj', 'role_for_manage',
                         'role_for_no_speak', 'role_for_no_stream', 'role_for_no_media', 'role_for_no_chat'])
        {
            if (!has (s[key])) continue;
            if (!idOk (s[key]))
                out.push ('сервер ' + nm + ': ' + key + ' = "' + s[key] + '": не похоже на id роли -- ' +
                    'настройка молча не работает');
        }
        // [v2.42] Ссылка на политику -- одна на всех (верхний privacy_url): у сервера только флаг.
        if (s.privacy_url !== undefined)
            out.push ('сервер ' + nm + ': privacy_url задан у сервера -- своего адреса там нет, ' +
                'ссылка всегда берётся из ВЕРХНЕГО ключа privacy_url (этот можно убрать)');
        if (s.show_privacy_url !== undefined && typeof s.show_privacy_url !== 'boolean')
            out.push ('сервер ' + nm + ': show_privacy_url = "' + s.show_privacy_url + '": ожидается ' +
                'true или false -- беру верхнее show_privacy_url');
        else if (s.show_privacy_url === true && !PRIVACY_URL)
            out.push ('сервер ' + nm + ': show_privacy_url: true, но верхний privacy_url пуст -- ' +
                'показывать нечего (ссылка появится, как только её впишут)');
        if (has (s.owner_server) && !idOk (s.owner_server))
            out.push ('сервер ' + nm + ': owner_server = "' + s.owner_server + '": не похоже на id -- ' +
                'в помощи он не показывается');
        if (has (s.queue_page) && Number.isFinite (Number (s.queue_page)) && Number (s.queue_page) > 25)
            out.push ('сервер ' + nm + ': queue_page = ' + s.queue_page + ' -- страница будет 25 ' +
                '(больше Discord не принимает)');
    }
    return out;
}

// [v2.29] ОТСТАЛ ЛИ БОЕВОЙ config.json ОТ config.example.json.
// Зачем: подсказки и новые ключи со значениями по умолчанию живут в примере, а в боевой
// файл их никто не переносит сам -- расхождение замечаешь случайно (так и случилось:
// backup_keep был в примере, а в конфиге его не было, и владелец искал его руками).
// Сравниваем ключи по блокам: верхний уровень, MUSIC и каждый рабочий сервер -- с блоком
// ID_СЕРВЕРА из примера. Молчим, когда всё на месте: нет расхождения -- нет строки.
// Предупреждаем только о СТРОКАХ файла: подсказка это (_comment) или значение,
// которое бот применит и без ключа, -- решает владелец, это не ошибка.
function configDriftIssues ()
{
    const _fs = require ('fs'), _path = require ('path');
    const _exFile = _path.join (__dirname, 'config.example.json');
    if (!_fs.existsSync (_exFile)) return [];
    let _ex = null;
    try { _ex = JSON.parse (_fs.readFileSync (_exFile, 'utf8')); } catch (e) { return []; }
    const _cfg = require ('./config.json');
    const _miss = (a, b) => Object.keys (b || {}).filter (_k => !(_k in (a || {})));
    const out = [];
    const _say = (where, keys) =>
    {
        if (!keys.length) return;
        out.push ('в config.json нет ' + keys.length + (keys.length === 1 ? ' строки' : ' строк') +
            ' из config.example.json -- ' + where + ': ' + keys.slice (0, 8).join (', ') +
            (keys.length > 8 ? ', ...и ещё ' + (keys.length - 8) : ''));
    };
    _say ('верхний уровень', _miss (_cfg, _ex));
    _say ('MUSIC', _miss (_cfg.MUSIC, _ex.MUSIC));
    const _srvEx = (_ex.SERVERS || {})['ID_СЕРВЕРА'];
    if (_srvEx)
        for (const _id of Object.keys (SERVERS))
            if (/^\d{17,20}$/.test (_id) && SERVERS[_id].allow !== false)
                _say ('сервер ' + _id + (SERVERS[_id].name ? ' («' + SERVERS[_id].name + '»)' : ''),
                    _miss (SERVERS[_id], _srvEx));
    if (out.length)
        out.push ('это строки-подсказки (_comment) и ключи со значениями по умолчанию: без них бот работает, ' +
            'но значения берёт из кода, а не из примера -- перенести их проще всего копией из config.example.json');
    return out;
}

// [v2.5] Проверка id из config.json при старте: битый id вылезет сразу,
// а не загадочной ошибкой переноса/лога через час. Молчим, если всё цело.
async function checkConfigChannels (server)
{
    const guild = client.guilds.cache.get (server);
    if (!guild) return;
    for (let key of ['log_channel', 'pipe_channel_source', 'pipe_channel_target', 'channel_common', 'temp_lobby'])
    {
        let id = SERVERS[server][key];
        if (!id) continue;
        let ch = guild.channels.cache.get (id) || await guild.channels.fetch (id).catch (() => null);
        if (!ch)
        {
            console.error ('[config] ' + key + ' = ' + id + ': канала нет -- исправь config.json и ПЕРЕЗАПУСТИ бота');
            continue;
        }
        if ((key === 'channel_common' || key === 'temp_lobby') && !ch.isVoiceBased ())
            console.error ('[config] ' + key + ' = ' + id + ' ("' + ch.name + '"): не голосовой канал');
    }
    // [v2.23] Роли из config.json: id, которой на сервере нет (удалили, перепутали,
    // скопировали из чужого конфига), молча обнуляет настройку -- а вместе с ней и
    // права: «role_dj» пропадёт -> музыку сможет любой с правами в канале,
    // «role_admin» пропадёт -> админы потеряют права в боте без единой строки в логе.
    for (let key of ['role_admin', 'role_moder', 'role_dj', 'role_for_manage',
                     'role_for_no_speak', 'role_for_no_stream', 'role_for_no_media', 'role_for_no_chat'])
    {
        let id = SERVERS[server][key];
        if (!id) continue;
        if (!guild.roles.cache.get (String (id)))
            console.error ('[config] ' + key + ' = ' + id + ': такой роли на сервере нет -- ' +
                'настройка молча не работает');
    }
}

// ============================================================================
// [v2.17] ЧТО РЕАЛЬНО ДОСТУПНО ПРИЛОЖЕНИЮ. Привилегированные интенты Discord может
// отозвать (письмо от 10.09.2026, срок 09.10.2026) -- и тогда часть возможностей
// тихо исчезнет. Поэтому при КАЖДОМ старте пишем по строке на возможность и ПО ФАКТУ
// (доступна она сейчас), а не по настройке в конфиге
// ============================================================================
async function reportIntents (server)
{
    const name = SERVERS[server].name;
    const has = i => client.options.intents.has (i);
    const yes = ok => ok ? 'да' : 'НЕТ';
    const msgContent = has (GatewayIntentBits.MessageContent);
    const members    = has (GatewayIntentBits.GuildMembers);
    console.log ('[' + (d()) + '] [intents] ' + name + ' | Message Content (текст сообщений, команды "panda ..."): ' +
        yes (msgContent) + (msgContent ? '' : ' -- пересылка из пандалогии и текстовые команды молчат' +
            ' (вместо пересылки: правый клик по сообщению -> «Переслать в общий»)'));
    console.log ('[' + (d()) + '] [intents] ' + name + ' | Guild Members (мгновенные вход/выход): ' +
        yes (members) + (members ? '' : ' -- вход/выход только опросом раз в 45 сек'));
    // Список участников: это и есть резервный путь. Проверяем ФАКТОМ -- пришёл ли список.
    const n = $membersSnapshot[server] ? $membersSnapshot[server].size : 0;
    console.log ('[' + (d()) + '] [intents] ' + name + ' | полный список участников (REST): ' +
        (n ? 'да -- ' + n + ' участников' : 'НЕТ -- список не пришёл, вход/выход не работают') +
        ' (от него зависят вход/выход, таймаут за выход и возврат ролей)');
    // Журнал аудита (GuildModeration) -- не привилегированный, но без него не видно
    // авторство мутов/переносов. Тоже проверяем запросом, а не настройкой.
    let audit = false, why = '';
    try
    {
        const guild = client.guilds.cache.get (server);
        await guild.fetchAuditLogs ({limit: 1});
        audit = true;
    }
    catch (e) { why = oneLine (e.message, 90); }
    console.log ('[' + (d()) + '] [intents] ' + name + ' | журнал аудита (авторство мутов/переносов): ' +
        (audit ? 'да' : 'НЕТ -- ' + why));
}

// ============================================================================
// [v2.28] ПРАВА БОТА -- ОТЧЁТ ПРИ СТАРТЕ. Раньше о нехватке прав было видно только
// по ПЕРВОЙ ЖИВОЙ ошибке («Missing Permissions») -- то есть в момент, когда кого-то
// уже наказывают, выдают ключ или переносят. Теперь при старте сразу понятно, чего
// не хватает и что с этим делать.
// Проверяем ровно те права, которые код действительно использует:
//   ManageRoles   -- записи прав в канале (мут/глухота/ключ 🔑) и roles.add при возврате ролей;
//   ManageChannels-- создание/удаление каналов (новые каналы, общий канал, скрытие);
//   ManageNicknames-- тег 🔑 в нике;
//   MoveMembers   -- переносы между каналами (drag-n-drop ботом);
//   MuteMembers   -- серверный мут голоса; DeafenMembers -- глухота;
//   KickMembers   -- кик в отдельных случаях модерации;
//   BanMembers    -- бан за выход (таймаут-механизм) и разбан;
//   ViewAuditLog  -- авторство мутов/переносов (кто это сделал);
//   Connect/Speak -- чтобы музыка вообще звучала (в канале, где играет бот).
// Если всё на месте -- одна строка «всё на месте» (чтобы отсутствие строк было видно).
// ============================================================================
async function reportBotPermissions (server)
{
    const guild = client.guilds.cache.get (server);
    if (!guild) return;
    let me = guild.members.me;
    if (!me) { try { me = await guild.members.fetchMe (); } catch (e) { return; } }
    if (!me) return;
    const P = PermissionsBitField.Flags;
    const need =
    [
        [P.ManageRoles, 'Управлять ролями', 'мут, глухота, ключ 🔑, возврат ролей'],
        [P.BanMembers, 'Банить участников', 'бан за выход (таймаут) и /unban'],
        [P.ManageChannels, 'Управлять каналами', 'создание/удаление каналов, права в них'],
        [P.ManageNicknames, 'Управлять никами', 'тег 🔑 перед ником'],
        [P.MoveMembers, 'Перемещать участников', 'переносы между каналами'],
        [P.MuteMembers, 'Выключать микрофон', 'серверный мут'],
        [P.DeafenMembers, 'Выключать звук', 'глухота'],
        [P.KickMembers, 'Выгонять участников', 'кик (в отдельных случаях модерации)'],
        [P.ViewAuditLog, 'Просматривать журнал аудита', 'авторство мутов и переносов'],
        [P.Connect, 'Подключаться', 'зайти в голосовой канал (иначе тишина)'],
        [P.Speak, 'Говорить', 'чтобы музыку было слышно'],
    ];
    const miss = need.filter (n => !me.permissions.has (n[0]));
    const name = SERVERS[server].name;
    if (!miss.length)
    {
        console.log ('[' + (d()) + '] [perms] ' + name + ': права на мут, бан, роли, каналы и музыку -- на месте');
        return;
    }
    for (const [flag, label, why] of miss)
        console.log ('[' + (d()) + '] [perms] ' + name + ': НЕТ права «' + label + '» -- ' + why +
            ' работать не будет (Discord ответит Missing Permissions). Где включить: Настройки сервера -> ' +
            'Роли -> роль бота -> Права, и подними эту роль ВЫШЕ ролей тех, кого наказываешь');
    console.log ('[' + (d()) + '] [perms] ' + name + ': не хватает ' + miss.length + ' ' +
        plural (miss.length, 'права', 'прав', 'прав') + ' -- это то, что уже будет ломаться в бою');
}

// Один тик поллера по серверу:
async function pollMembers (server)
{
    try
    {
        const guild = client.guilds.cache.get (server);
        if (!guild) return;
        let current;
        try { current = await fetchAllMembersRest (server); }
        catch (e)
        {
            // [v2.16] ПОЛНЫЙ список участников требует интента Guild Members
            // (привилегированный). Если Discord его отозвал, здесь будет 403/Missing
            // Access -- скажем об этом ЯВНО (не чаще раза в 10 минут) и пропустим тик:
            // без списка молча перестали бы работать вход/выход (приветствие новичку,
            // таймаут за выход, возврат ролей), и по логу это было бы незаметно.
            const now = Date.now ();
            if (now - ($pollWarnAt[server] || 0) > 10 * 60 * 1000)
            {
                $pollWarnAt[server] = now;
                console.error ('[poll] список участников не пришёл (' + oneLine (e.message, 150) + '): проверь интент Guild Members в портале приложения' +
                    ' -- без него не работают вход/выход, таймаут за выход и возврат ролей');
            }
            return;
        }
        let previous = $membersSnapshot[server];
        // [v2.15] возраст снимка: на выходе по нему достраиваем изменения ролей
        // (роль, снятая за секунды до выхода, не должна вернуться при входе).
        const prevAt = $membersSnapshotAt[server] || 0;
        // [v2.16] Защита от пустого/обрезанного списка (403 с пустым телом, лимит,
        // сбой): иначе разница снапшотов выглядела бы как «ВСЕ вышли» и каждому
        // сразу выписался бы таймаут за выход (а перезаход — бан). Тик пропускаем.
        if (previous && previous.size > 5 && (current.size === 0 ||
            (previous.size >= 100 && current.size < previous.size / 2)))
        {
            const now = Date.now ();
            if (now - ($pollWarnAt[server] || 0) > 10 * 60 * 1000)
            {
                $pollWarnAt[server] = now;
                console.error ('[poll] список участников подозрительно мал: было ' + previous.size +
                    ', стало ' + current.size + ' -- пропускаю тик, никого не наказываю');
            }
            return;
        }
        if (previous)
        {
            // [v2.5] Каждый участник -- в своём предохранителе, а снапшот
            // обновляется ВСЕГДА (finally). Раньше одно падение (например,
            // logMemberJoinLeave на сыром JSON) оставляло старый снапшот, и
            // следующие тики снова считали человека 'вошедшим' -- повторные
            // строки JOINED и повторные выдачи бан-таймаутов.
            try
            {
                // входы:
                for (let [uid, raw] of current)
                {
                    if (previous.has (uid)) continue;
                    // [v2.17] событие гейтвея уже разобрало этот вход -- не повторяем
                    if (memberEventFresh (server, uid, true)) continue;
                    try
                    {
                        let memberUser = await resolveUser (uid, raw);
                        console.log ('[' + (d()) + '] участник ' + memberUser.username + ' ЗАШЁЛ на ' + SERVERS[server].name);
                        await logMemberJoinLeave (server, memberUser, true);
                        // [v2.14] роли назад (до таймаутов: человек ещё точно на сервере)
                        await restoreMemberRoles (server, uid, raw);
                        await handleMemberJoin (server, uid, raw);
                    }
                    catch (e) { console.error ('[pollMembers] вход ' + uid + ': ' + e.message); }
                }
                // выходы:
                for (let [uid, raw] of previous)
                {
                    if (current.has (uid)) continue;
                    // [v2.17] либо событие уже разобрало выход, либо человек только что
                    // вошёл (REST-список отстаёт) -- в обоих случаях никого не наказываем
                    if (memberEventFresh (server, uid, false) || memberEventFresh (server, uid, true)) continue;
                    try
                    {
                        let memberUser = await resolveUser (uid, raw);
                        console.log ('[' + (d()) + '] участник ' + memberUser.username + ' ВЫШЕЛ с ' + SERVERS[server].name);
                        await logMemberJoinLeave (server, memberUser, false);
                        await handleMemberLeave (server, uid, raw, prevAt);
                    }
                    catch (e) { console.error ('[pollMembers] выход ' + uid + ': ' + e.message); }
                }
            }
            finally
            {
                $membersSnapshot[server] = current;
                $membersSnapshotAt[server] = Date.now ();
            }
        }
        else
        {
            $membersSnapshot[server] = current;
            $membersSnapshotAt[server] = Date.now ();
        }
    }
    catch (e)
    {
        console.error ('[pollMembers] ошибка: ' + e.message);
    }
}

// Старт поллинга после готовности клиента:
client.on
(
    'clientReady', // [v2.4] 'ready' в v15 уйдёт -- без warnings в логе (только события)
    async () =>
    {
        // [v2.18] СКОЛЬКО ЛЮДЕЙ ВИДИТ ПРИЛОЖЕНИЕ. Порог ревью Discord считается по
        // УНИКАЛЬНЫМ ПОЛЬЗОВАТЕЛЯМ всех серверов, а не по числу серверов (и не по
        // числу экземпляров бота). memberCount приходит в событии GUILD_CREATE, поэтому
        // видно без интентов -- можно сверить одним взглядом, «сколько нас всего».
        // ОДНА строка про все серверы сразу (включая те, где бот есть, а конфига нет):
        {
            let total = 0;
            const list = [];
            for (const g of client.guilds.cache.values ())
            {
                const n = typeof g.memberCount === 'number' ? g.memberCount : 0;
                total += n;
                if (list.length < 8) list.push ((g.name || g.id) + (n ? ' ~' + n : ''));
            }
            const more = client.guilds.cache.size > list.length ? ' и ещё ' + (client.guilds.cache.size - list.length) : '';
            console.log ('[' + (d()) + '] [login] приложение в ' + client.guilds.cache.size + ' серверах, участников суммарно ~' + total +
                (list.length ? ' (' + list.join (' | ') + more + ')' : ''));
        }
        for (let server in SERVERS)
        {
            if (!SERVERS[server].allow) continue;
            // Первый снапшот -- просто запоминаем (без логов и банов),
            // чтобы рестарт бота не разбудил ложные "выходы":
            $membersSnapshot[server] = await fetchAllMembersRest (server).catch (() => null);
            $membersSnapshotAt[server] = Date.now ();
            // [v2.25] Список участников требует интента Guild Members. Если Discord его
            // отозвал -- не пишем непонятное 'ERR', а прямо говорим, что именно не работает.
            if ($membersSnapshot[server])
                console.log ('[' + (d()) + '] [poll] снимок готов: ' + $membersSnapshot[server].size + ' участников @ ' + SERVERS[server].name);
            else
                console.error ('[' + (d()) + '] [poll] снимок участников НЕ ПОЛУЧЕН @ ' + SERVERS[server].name +
                    ': нет доступа к списку (интент Guild Members) -- вход/выход, приветствие новичку, таймаут за выход' +
                    ' и возврат ролей работать не будут');
            // [v2.17] Что реально доступно приложению (интенты могли отозвать):
            await reportIntents (server);
            // [v2.5] заодно проверить id из config.json (молчит, если всё цело):
            await checkConfigChannels (server);
            // [v2.28] и права бота -- чтобы проблемы были видны ДО первого живого наказания:
            await reportBotPermissions (server);
            // [v2.14] Сперва отчёт: сколько наказаний поднято из базы (пишется всегда),
            // и только потом снятие просроченных -- чтобы в логе было видно исходное
            // состояние, а не только «уже снял».
            await reportStoredBans (server);
            // Рестарт-безопасность: снять истёкшие бан-таймауты из SQLite:
            await sweepExpiredBans (server);
            // [v2.14] убрать слишком старые записи о ролях (save_roles_days):
            await sweepSavedRoles (server);
            // [v2.15] история наказаний: старые события (bans_history_days) убираются сами.
            await sweepBanHistory (server);
            // [v2.3] почистить пустые личные каналы после рестарта:
            await tempSweep (server);
            // [v2.10] вернуть музыку с прошлого запуска (очередь + тот же канал):
            await resumeMusic (server);
        }            setInterval
            (
                async () =>
                {
                    for (let server in SERVERS)
                    {
                        if (!SERVERS[server].allow) continue;
                        // [FIX v2.3.1] КАЖДЫЙ шаг в своём предохранителе -- падение одного
                        // шага (сеть, кэш) больше не отменяет остальные (ключи, кабинеты):
                        let steps =
                        [
                            () => pollMembers (server),
                            () => sweepExpiredBans (server),
                            () => sweepSavedRoles (server),   // [v2.14] старые записи о ролях
                            () => sweepBanHistory (server),   // [v2.15] старая история наказаний
                            () => sweepNicks (server),        // ключи 🔑
                            () => tempSweep (server),         // пустые кабинеты
                            () => tempLobbyCheck (server),    // лобби -> кабинет
                        ];
                        for (let step of steps)
                        {
                            try { await step (); }
                            catch (e) { console.error ('[' + (d()) + '] [tick] ' + (step.name || 'step') + ': ' + e.message); }
                        }
                    }
                },
                POLL_PERIOD
            );
    }
);

// ============================================================================
// [v2.2] МУЗЫКА! ## DJ -- как у Cloudy ;-D
// Слэш-команды (работают БЕЗ Message Content интента):
//   /play <ссылка или поиск>   -- YouTube (ГЛАВНЫЙ), плейлисты, SoundCloud и
//                                 всё, что умеет yt-dlp
//   /stop  /skip  /pause  /resume  /queue  /nowplaying
// Право управления: роль DJ (config: role_dj) или админ/модер.
// Голос: @discordjs/voice; аудио: yt-dlp (o:-) -> ffmpeg -> Discord.
// ============================================================================

const
{
    joinVoiceChannel,
    createAudioPlayer,
    createAudioResource,
    entersState,
    VoiceConnectionStatus,
    AudioPlayerStatus,
    StreamType,
} = require ('@discordjs/voice');
const ytdlp = require ('youtube-dl-exec');
const ffmpegPath = require ('ffmpeg-static');
const { spawn } = require ('child_process'); // [v2.14] свой ffmpeg: выравнивание громкости
const
{
    SlashCommandBuilder,
    REST,
    Routes,
    MessageFlags,
    ActionRowBuilder, // [v2.14] кнопки листания очереди
    ButtonBuilder,
    ButtonStyle,
    StringSelectMenuBuilder, // [v2.15] меню «убрать трек» под /queue
} = require ('discord.js');

// Настройки музыки из config.json (объект MUSIC). Все необязательны.
// [FIX v2.14] Раньше здесь стояло `typeof MUSIC !== 'undefined' && MUSIC.proxy`, но
// MUSIC НИКОГДА не читался из конфига (объекта не было в require выше) -- то есть
// MUSIC.proxy в config.json молча не работал, всегда брался порт по умолчанию.
// Теперь MUSIC берётся из конфига, как и обещает README.
const MUSIC_CFG = MUSIC || {};
// Прокси для yt-dlp (YouTube напрямую из РФ недоступен).
// [v2.2.2] Стратегия: сначала через прокси; если не отвечает 3 секунды -- DIRECT:
// [v2.23] Раньше здесь стояло `MUSIC_CFG.proxy || env || 'socks5://127.0.0.1:10808'`, и
// ПУСТАЯ строка (а подсказка в конфиге обещает «пустая строка -- без прокси») молча
// подменялась сперва переменной окружения, а затем ЗАШИТЫМ адресом -- то есть бот всё
// равно лез в несуществующий прокси и терял 3 секунды на каждой песне. Теперь смысл
// ключа честный: ключ есть -- берём его как есть (пустой = DIRECT); ключа нет --
// переменная окружения MUSIC_PROXY, иначе DIRECT. Зашитого адреса в коде больше нет.
// [v2.60] ПРОКСИ МОЖЕТ БЫТЬ НЕСКОЛЬКО -- чтобы обрыв одного не останавливал музыку.
// Владелец спросил: «есть же публичные прокси, которые только DNS?» -- таких нет:
// SOCKS/HTTP прокси всегда несёт твой трафик через чужую машину (даже если не скрывает
// адрес), а чужой открытый прокси -- это чужие логи, перегрузка и быстрые лимиты от
// YouTube. Честный ответ на «локальный прокси икнул» -- иметь ВТОРОЙ СВОЙ (другой
// профиль VPN, другой сервер). Поэтому в ключе proxy можно перечислить адреса через
// запятую (или массивом) -- бот пробует их по порядку, а «икнувший» пропускает минуту.
function musicProxyList (raw)
{
    const arr = Array.isArray (raw) ? raw : String (raw === undefined || raw === null ? '' : raw).split (',');
    const out = [];
    for (const s of arr)
    {
        const v = String (s === undefined || s === null ? '' : s).trim ();
        if (v && !/^(direct|none|off|no)$/i.test (v) && !out.includes (v)) out.push (v);
    }
    return out;
}
const MUSIC_PROXY_RAW = ('proxy' in MUSIC_CFG) ? MUSIC_CFG.proxy : process.env.MUSIC_PROXY;
const MUSIC_PROXIES_ALL = musicProxyList (MUSIC_PROXY_RAW);
const MUSIC_PROXIES = MUSIC_PROXIES_ALL.slice (0, 3);   // больше трёх -- уже путаница, а не подспорье
const MUSIC_PROXY = MUSIC_PROXIES[0] || '';   // где нужен «главный»: строка при старте
const MUSIC_PROXY_TIMEOUT = 3000; // мс -- «не получилось за 3 сек» -> следующий маршрут
// [v2.60] «Икнувший» прокси -- не «мёртвый насмерть», а «пропускаем его минуту». Раньше
// на один обрыв был общий флаг proxyStreamDead, и он же глушил сразу ВСЕ прокси; теперь
// состояние своё у каждого адреса -- если адресов два, работу подхватывает второй.
const PROXY_BAD_TTL = 60000;
const proxyBadUntil = new Map ();
function proxyMarkBad (addr) { if (addr) proxyBadUntil.set (String (addr), Date.now () + PROXY_BAD_TTL); }
function proxyMarkGood (addr) { if (addr) proxyBadUntil.delete (String (addr)); }
function proxyBrieflyBad (addr) { const t = proxyBadUntil.get (String (addr === undefined || addr === null ? '' : addr)); return !!t && t > Date.now (); }
// [v2.14] ВЫРАВНИВАНИЕ ГРОМКОСТИ: yt-dlp -> ffmpeg(-af loudnorm) -> Discord.
// Записи бывают сведены с разной громкостью (одна тише, другая громче) -- фильтр
// loudnorm приводит их к среднему уровню, поэтому между песнями нет «качелей»
// громкости. Выключается в конфиге: MUSIC.normalize = false; свой фильтр --
// MUSIC.filter. Если ffmpeg почему-то не поднялся -- трек играет как раньше
// (обычным путём), музыка из-за этого не встаёт.
const MUSIC_NORMALIZE = MUSIC_CFG.normalize !== false;
const MUSIC_NORMALIZE_FILTER = MUSIC_CFG.filter || 'loudnorm=I=-16:TP=-1.5:LRA=11';
// [v2.26] СТАТУС ГОЛОСОВОГО КАНАЛА (шапка канала, где сидит бот). Пока бот в канале, он
// писал туда свою строку («что играет • очередь • в канале человек • бот тут N мин»).
// Проблема: роут у Discord ТОЛЬКО ПИШУЩИЙ -- прочитать прежнюю строку нельзя (проверено
// живым запросом, 405), поэтому текст, который поставил АВТОР канала, восстановить
// невозможно: бот затирает его на время и снимает при выходе.
//   "channel_status": false -- бот не трогает шапку канала вообще (ни пишет, ни снимает);
//   вся информация остаётся в ПРОФИЛЬНОМ статусе бота («Слушает: … · в очереди 2 …»),
//   его видно везде, даже вне голосового.
// Свою прежнюю строку можно снять разово: `node . clearstatus <id канала>`.
const MUSIC_CHANNEL_STATUS = MUSIC_CFG.channel_status !== false;
// [v2.28] Одинокий бот на паузе не ждёт автора, которого нет в голосовом, а переставляет
// его треки в конец очереди и играет тому, кто слушает прямо сейчас. По умолчанию ВКЛ;
// выключается в конфиге: MUSIC.skip_absent_author = false.
const MUSIC_SKIP_ABSENT = MUSIC_CFG.skip_absent_author !== false;
// [v2.41] ЗАРАНЕЕ ПРОЧЁСЫВАЕМ ОЧЕРЕДЬ: мёртвые видео узнаём и убираем ДО эфира, а не
// когда до трека дошла предзагрузка (человек ждал свою песню, чтобы услышать «её нет»).
// Настройки -- с заботой о лимитах YouTube (главный вопрос владельца):
//   queue_check     -- включено ли (true по умолчанию);
//   queue_check_depth -- сколько треков проверять ЗА ОДИН ПРОХОД (по умолчанию 20);
//   queue_check_gap_ms -- пауза между проверками (по умолчанию 5 сек).
// Так это «не больше 20 запросов за проход», а не «не дальше 20-го трека»: длинный
// плейлист разбирается целиком, просто за несколько проходов, швов почти не видно.
const MUSIC_QUEUE_CHECK = MUSIC_CFG.queue_check !== false;
const QUEUE_CHECK_DEPTH = Math.max (0, Math.min (200,
    Math.round (Number (MUSIC_CFG.queue_check_depth === undefined ? 20 : MUSIC_CFG.queue_check_depth) || 0)));
const QUEUE_CHECK_GAP_MS = Math.max (1000, Math.min (60000,
    Math.round (Number (MUSIC_CFG.queue_check_gap_ms === undefined ? 5000 : MUSIC_CFG.queue_check_gap_ms) || 5000)));
// Насколько передний край очереди проверять САМИМ yt-dlp (а не дешёвым oEmbed): у первых
// треков ошибка стоит дорого -- их будут слушать через считанные минуты, а oEmbed про
// региональные блокировки не знает (отвечает «есть», хотя бот её не сыграет). 0 -- только
// oEmbed; больше 5 -- уже заметная доля от обычной работы бота, смысла нет.
const QUEUE_CHECK_STRICT = 3;
// [v2.54] ИСТОРИЯ ДОБАВЛЕНИЙ (/history) -- отдельный ключ MUSIC.history_len (по умолчанию
// 25): сколько последних ПАЧЕК /play помнить. 0 -- не помнить вовсе (команда так и
// скажет). Это НЕ очередь: очередь живёт своей жизнью и стирается /stop, а история --
// это след добавлений (кто, когда и что поставил), и она переживает и доигранное, и
// /stop, и перезапуск. Верхняя граница -- чтобы запись в базу не распухала.
const MUSIC_HISTORY_LEN = Math.max (0, Math.min (200,
    Math.round (Number (MUSIC_CFG.history_len === undefined ? 25 : MUSIC_CFG.history_len) || 0)));
// [v2.56] ВТОРОЙ ЛИМИТ ИСТОРИИ -- сколько ТРЕКОВ помнить суммарно (просьба владельца):
// пачка с 50 треками занимает вчетверо больше места, чем длинная очередь одиночных
// заходов, поэтому одного лимита по пачкам мало. 0 -- без этого лимита (только пачки).
// Верхняя граница -- 5000: это уже сотни килобайт в базе и текст на сотни строк.
const MUSIC_HISTORY_TRACKS = Math.max (0, Math.min (5000,
    Math.round (Number (MUSIC_CFG.history_tracks === undefined ? 500 : MUSIC_CFG.history_tracks) || 0)));
// [v2.57] ЖИВОЕ СООБЩЕНИЕ /queue: как часто бот сам перерисовывает его, пока висит
// (ключ MUSIC.queue_live_ms; по умолчанию 30000 = полминуты, 0 -- не обновлять само).
// Discord меняет сообщение ТОЛЬКО по нашему запросу, поэтому без этого текст застывал
// на моменте вызова и оживал лишь при листании или «🔄 Обновить». Ниже 10 секунд не
// опускаю даже по конфигу -- про лимиты Discord см. комментарий у queueLiveTick.
const QUEUE_LIVE_MS = (function ()
{
    const raw = Number (MUSIC_CFG.queue_live_ms === undefined ? 30000 : MUSIC_CFG.queue_live_ms) || 0;
    if (!raw) return 0;
    return Math.max (10000, Math.round (raw));
})();
if (MUSIC_QUEUE_CHECK && QUEUE_CHECK_DEPTH)
    console.log ('[' + (d()) + '] [music] проверка очереди заранее: ВКЛЮЧЕНА -- до ' + QUEUE_CHECK_DEPTH +
        ' треков за проход, пауза ' + Math.round (QUEUE_CHECK_GAP_MS / 1000) + ' с (первые ' + QUEUE_CHECK_STRICT +
        ' трека -- сразу через yt-dlp, остальные -- дешёвым oEmbed)');
else
    console.log ('[' + (d()) + '] [music] проверка очереди заранее: выключена (MUSIC.queue_check) -- мёртвые видео узнаём, когда трек подходит к эфиру');
// [v2.61] Одна строка при старте: обновляется ли сообщение /queue само и как часто.
// Раньше про это молчали, и «не обновляется» ничем не отличалось от «выключено».
console.log ('[' + (d()) + '] [music] живое сообщение /queue: ' + (QUEUE_LIVE_MS
    ? 'обновляю сам каждые ' + Math.round (QUEUE_LIVE_MS / 1000) + ' с, пока его видят (MUSIC.queue_live_ms)'
    : 'самообновление выключено (MUSIC.queue_live_ms: 0) -- освежается листанием или кнопкой «🔄 Обновить»'));
// [v2.23] Одна строка при старте о том, как бот ходит на YouTube: видно, что ключ
// MUSIC.proxy действительно подхватился (промах в этом месте раньше не был заметен).
console.log ('[' + (d()) + '] [music] YouTube: ' + (MUSIC_PROXY
    ? 'через прокси ' + MUSIC_PROXY +
      (MUSIC_PROXIES.length > 1 ? ' (запасные: ' + MUSIC_PROXIES.slice (1).join (', ') + ')' : '') +
      ' (не ответит за 3 сек -- пробую следующий маршрут)'
    : 'напрямую (DIRECT) -- прокси не задан') +
    (MUSIC_PROXIES_ALL.length > MUSIC_PROXIES.length
        ? ' | в конфиге ' + MUSIC_PROXIES_ALL.length + ' адресов прокси -- беру первые ' + MUSIC_PROXIES.length
        : ''));
// [v2.26] Одна строка при старте: трогаем ли мы шапку голосового канала (см. выше).
console.log ('[' + (d()) + '] [music] статус голосового канала (шапка): ' + (MUSIC_CHANNEL_STATUS
    ? 'пишу свой (что играет, очередь, люди) -- прежний текст автора канала вернуть нельзя, он затирается'
    : 'НЕ трогаю (MUSIC.channel_status: false) -- в шапке остаётся только то, что поставил автор канала'));
// Роль DJ -- задаётся в config.json сервера как role_dj.

// [v2.2.2] Быстрая TCP-проверка прокси (коннект за timeoutMs, иначе -- мёртв):
function pingProxy (addr, timeoutMs = MUSIC_PROXY_TIMEOUT)
{
    return new Promise (resolve =>
    {
        let host, port;
        try
        {
            let u = new URL (String (addr || ''));
            host = u.hostname;
            port = Number (u.port) || 1080;
        }
        catch { return resolve (false); }
        let s = new (require ('net').Socket) ();
        let done = false;
        let fin = ok => { if (done) return; done = true; try { s.destroy (); } catch {} resolve (ok); };
        s.setTimeout (timeoutMs, () => fin (false));
        s.once ('connect', () => fin (true));
        s.once ('error',    () => fin (false));
        s.connect (port, host);
    });
}

// [v2.52] ЕСЛИ ПРОКСИ МОЛЧИТ, А ЛОКАЛЬНЫЙ DNS НЕ ВИДИТ youtube.com -- DIRECT НЕ ЗАПАСНОЙ
// ПУТЬ, А ПУСТАЯ ТРАТА ВРЕМЕНИ. Живой случай владельца: прокси на миг отвалился,
// бот честно ушёл на DIRECT -- а на этой машине YouTube именно потому и ходят через
// прокси, что имя не резолвится локально. В итоге вместо музыки была невнятная
// «Unable to download API page ... Read timed out», а настоящую причину по строке
// не понять. Теперь бот один раз спрашивает DNS и знает: если имя локально не
// резолвится -- работаем ТОЛЬКО через прокси (yt-dlp резолвит имя на стороне прокси,
// см. socks5h в proxyForAgent), а если резолвится -- DIRECT остаётся запасным путём.
// Заодно 3-секундная проверка прокси кэшируется (раньше она шла НЕСКОЛЬКО РАЗ НА ТРЕК --
// метаданные, скачивание и поток; при мёртвом прокси это лишние секунды на каждую песню).
const PING_OK_TTL = 30000;   // мс: живой прокси не переспрашиваем
const PING_BAD_TTL = 60000;  // мс: молчащий -- тем более (успеет очнуться)
const DNS_TTL = 60000;       // мс: состояние локального DNS
const pingCache = new Map ();   // [v2.60] адрес -> { ok, at }: проверяем КАЖДЫЙ прокси отдельно
let dnsCache = { ok: null, at: 0 };

async function proxyAlive (addr)
{
    const a = String (addr || '');
    if (!a) return false;
    if (proxyBrieflyBad (a)) return false;   // «икнул» на стриме -- минуту не трогаем
    const now = Date.now ();
    const c = pingCache.get (a);
    if (c && c.at && (now - c.at) < (c.ok ? PING_OK_TTL : PING_BAD_TTL)) return c.ok;
    const ok = await pingProxy (a);
    pingCache.set (a, { ok: ok, at: now });
    return ok;
}

// Живые прокси из списка, в порядке конфига (сначала те, что отвечают на TCP). Если
// локальный DNS мёртв, DIRECT не запасной путь, поэтому в список возвращаем ВСЁ (даже
// «икнувшее»): альтернативы просто нет.
async function liveProxyList ()
{
    const alive = [], rest = [];
    for (const p of MUSIC_PROXIES)
        ((proxyBrieflyBad (p) || !(await proxyAlive (p))) ? rest : alive).push (p);
    return { alive: alive, rest: rest };
}

// Какой прокси брать для своих запросов (oEmbed-проверка): первый не «икнувший»,
// иначе (если DIRECT невозможен) хоть какой-то, иначе '' = напрямую.
async function proxyForFetch ()
{
    for (const p of MUSIC_PROXIES) if (!proxyBrieflyBad (p)) return p;
    return (await directUsable ()) ? '' : (MUSIC_PROXIES[0] || '');
}

// Резолвится ли youtube.com ЛОКАЛЬНО. null не бывает: не смогли проверить -- считаем,
// что резолвится (прежнее поведение, ничего не ломаем).
async function directUsable ()
{
    const now = Date.now ();
    if (dnsCache.ok !== null && (now - dnsCache.at) < DNS_TTL) return dnsCache.ok;
    let ok = true;
    try
    {
        const dns = require ('dns').promises;
        const r = await dns.lookup ('www.youtube.com');
        ok = !!(r && r.address);
    }
    catch { ok = false; }
    dnsCache = { ok: ok, at: now };
    return ok;
}

// КАКИМИ МАРШРУТАМИ ИДТИ. Возвращаем по порядку: обычно прокси, потом DIRECT
// (ошибка маршрута -- не ошибка видео, см. isNetworkError). Если локальный DNS мёртв,
// DIRECT из списка выкидывается совсем: иначе на выходе была бы невнятная DNS-ошибка
// вместо внятной причины. Именно от прокси тянется всё, а значит выкинуть его при
// 3-секундной заминке нельзя -- поэтому в этом случае прокси остаётся даже «икнувшим»
// (v2.60: альтернативы просто нет).
let directWarnedAt = 0;
// Возвращаем МАРШРУТЫ по порядку: у прокси в поле proxy адрес, у DIRECT -- пустая строка
// (адрес важен стал в v2.60: прокси может быть несколько, и обрыв одного не тушит музыку).
async function ytRoutes ()
{
    if (!MUSIC_PROXIES.length) return [{ proxy: '' }];
    const dnsOk = await directUsable ();
    if (!dnsOk && (Date.now () - directWarnedAt) > 600000)
    {
        directWarnedAt = Date.now ();
        console.log ('[' + (d()) + '] [music] youtube.com не резолвится локально -- иду через прокси (DIRECT на этой машине невозможен)');
    }
    const { alive, rest } = await liveProxyList ();
    const pRoutes = [...alive, ...rest].map (p => ({ proxy: p }));
    if (!dnsOk) return pRoutes;               // DIRECT бесполезен -- даже если все прокси молчат
    // Имя резолвится: живые прокси, потом DIRECT, потом «икнувшие» -- они могли очнуться
    return [...alive.map (p => ({ proxy: p })), { proxy: '' }, ...rest.map (p => ({ proxy: p }))];
}

// Строка при старте: честно видно, ЕСТЬ ли запасной путь DIRECT (владелец: «у меня
// отвалилось прокси -- DIRECT видимо не знает ip ютуба»). Если DIRECT невозможен, это
// надо знать сразу, а не выяснять чтением ошибки yt-dlp.
if (MUSIC_PROXY)
    directUsable ().then (ok => console.log ('[' + (d()) + '] [music] запасной путь DIRECT: ' + (ok
        ? 'есть -- youtube.com резолвится локально'
        : 'НЕ работает -- youtube.com локально не резолвится, поэтому всё идёт ТОЛЬКО через прокси (прокси отвалился -- музыка встанет, и это будет видно по этой строке)')));

// [v2.30] Обрезать по СЛОВУ, а не посередине: в логе стоял хвост вида
// '... Error opening input files: In', по которому ничего не понять.
function clipWords (s, max)
{
    const _s = String (s === undefined || s === null ? '' : s).trim ();
    if (_s.length <= max) return _s;
    const _cut = _s.slice (0, max);
    const _sp = _cut.lastIndexOf (' ');
    return (_sp > max * 0.6 ? _cut.slice (0, _sp) : _cut) + '...';
}

// [v2.9.2] Лог -- ОДНА строка. tinyspawn кладёт в message ошибки команду и stderr целиком
// (несколько строк), а журнал должен читаться построчно.
function oneLine (s, max = 200)
{
    return clipWords (String (s === undefined || s === null ? '' : s).replace (/\s+/g, ' '), max);
}

// [v2.30] КОДЫ ВЫХОДА ПО-ЧЕЛОВЕЧЕСКИ. ffmpeg печатает свои коды как беззнаковое
// 32-битное число ('3199971767', '4294967274') -- понять по нему нельзя ничего, а в
// логе оказывался именно он. Приводим к знаковому виду и, если код известный,
// добавляем словами.
const EXIT_HINTS =
{
    '-1':         'ffmpeg: общая ошибка',
    '-9':         'процесс убит (KILL)',
    '-13':        'нет доступа (EACCES)',
    '-15':        'процесс завершён (TERM)',
    '-22':        'неверные данные (EINVAL)',
    '-1094995529':'ffmpeg: не смог прочитать поток (Invalid data)',
};
function exitCodeText (code)
{
    let _n = Number (code);
    if (!Number.isFinite (_n)) return String (code);
    if (_n > 2147483647) _n -= 4294967296; // Windows отдаёт код беззнаковым
    const _h = EXIT_HINTS[String (_n)];
    return String (_n) + (_h ? ' (' + _h + ')' : '');
}

// Самое полезное из ошибки yt-dlp -- его stderr ('ERROR: [youtube] ...: Video unavailable').
// [v2.30] Выкидываем то, что человеку не нужно: адреса буферов ffmpeg ('[in#0 @ 0x...]')
// и нечитаемые коды ('exited with code 4294967274' -> 'code -22 (неверные данные)').
function ytDlpErr (e, max = 200)
{
    let _s = oneLine ((e && (e.stderr || e.message)) || e, max + 120);
    // адрес буфера печатается и как '0x...', и просто цифрами: '[in#0 @ 00000267706ed600]'
    _s = _s.replace (/\[[^\]]*@\s*(?:0x)?[0-9a-fA-F]{6,}\]/g, '').replace (/\s+/g, ' ').trim ();
    _s = _s.replace (/\bcode (\d{6,})/g, (_m, _n) => 'code ' + exitCodeText (_n));
    return clipWords (_s, max);
}

// [v2.10] Процесс yt-dlp упал в первые секунды? (нужно для продолжения с места: если
// экстрактор/ffmpeg не умеют --download-sections, ошибка видна сразу, и трек берём с начала)
function failedFast (proc, ms = 1500)
{
    if (!proc || typeof proc.then !== 'function') return Promise.resolve (false);
    return Promise.race
    ([
        proc.then (() => false).catch (() => true),
        new Promise (r => setTimeout (() => r (false), ms)),
    ]);
}

// [v2.35] «ЭТОГО ВИДЕО БОЛЬШЕ НЕТ» -- не сбой сети и не наша ошибка: удалили,
// закрыли доступ, канал снесён. Разница важна: такое видео бессмысленно пробовать
// снова (раньше бот честно жёг на нём четыре попытки yt-dlp: предзагрузка, трек,
// «продолжаю тот же трек» x3 -- и только потом пропускал). Живой опыт это подтвердил:
// `--download-sections` на живой DJ-сет отдаёт `ERROR: ffmpeg exited with code
// 4294967274`, а удалённое видео -- `ERROR: [youtube] TBMH2tO1SMo: Video unavailable`.
// ВАЖНО: «Sign in to confirm ...» и возрастные ограничения сюда НЕ попадают -- это
// про доступ с этого IP/прокси, видео может подождать и попробоваться позже.
function isGoneError (e)
{
    const s = String ((e && (e.stderr || e.message)) || e);
    // [v2.41] «THIS video is unavailable» -- так YouTube отвечает про видео, которого
    // просто нет (удалено/никогда не существовало); раньше оно не считалось «мертвым»,
    // потому что шаблон ждал «is NOT available». Ловится на живом yt-dlp.
    return /video unavailable|this video is unavailable|has been removed|removed by the uploader|is not available|private video|no longer available|has been terminated|blocked (?:it )?(?:on copyright|in your country)|not available in your country/i.test (s);
}

// [v2.35] СДВИГ СЧИТАЕТСЯ УДАВШИМСЯ ТОЛЬКО ЕСЛИ ЧТО-ТО ПРИШЛО. `--download-sections`
// (быстрый путь продолжения с места) умеет и промолчать: процесс стартовал, отдал
// НОЛЬ байт и упал через 30-45 секунд («ffmpeg exited with code 4294967274»), а старая
// проверка ждала всего 1.5 с и принимала такую пустышку за рабочий поток -- плееру
// нечего было играть, трек «кончался» через пару секунд и очередь ехала дальше
// (живой лог владельца: возобновлённый сет замолк почти сразу).
// Ждём первый байт: пришёл -- сдвиг рабочий; процесс умер или молчит дольше ms -- нет.
function streamFirstData (source, proc, ms)
{
    return new Promise (resolve =>
    {
        if (!source) return resolve (false);
        let done = false;
        const finish = ok =>
        {
            if (done) return;
            done = true;
            clearTimeout (timer);
            try { source.removeListener ('data', onData); } catch {}
            resolve (ok);
        };
        const onData = () => finish (true);
        const timer = setTimeout (() => finish (false), ms);
        source.once ('data', onData);
        if (proc && typeof proc.catch === 'function') proc.catch (() => finish (false));
    });
}

// [v2.35] КАК ПРОДОЛЖАТЬ С МЕСТА -- измерено на живых DJ-сетах (yt-dlp + наш ffmpeg):
//   * сдвиг до 2 минут делается НАШИМ ffmpeg-ом (-ss) за считанные секунды: поток с
//     начала отдаёт первые байты через ~5 с, звук после -ss -- через ~5-6 с (при
//     сдвиге 110 с -- ~10 с);
//   * `--download-sections` (быстрый путь) на этих источниках не работает: 45 секунд
//     ожидания, НОЛЬ байт и `ERROR: ffmpeg exited with code 4294967274`.
// Поэтому маленький сдвиг идём сразу через ffmpeg (надёжно), а sections пробуем только
// на больших сдвигах (там он окупается, если источник умеет) и ТОЛЬКО с проверкой,
// что поток реально отдал данные; не отдал -- сразу к обычному пути.
const SEEK_FFSEEK_MAX = 120;   // сдвиги до 2 минут -- сразу своим ffmpeg
const SEEK_SECTIONS_WAIT_MS = 8000; // сколько ждать первый байт от --download-sections

// [v2.2.2] Сетевая ли это ошибка (прокси/сеть), а не реальный ответ YouTube:
function isNetworkError (e)
{
    let s = String ((e && e.stderr) || (e && e.message) || e);
    return /SocksHTTPS|proxy|timed out|timeout|ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|refused|reset|URLError|getaddrinfo|network/i.test (s);
}

// [v2.2.2] yt-dlp для метаданных: сначала прокси (проверка 3 сек), не вышло -- DIRECT:
// [v2.41] Проверка очереди не должна сыпать в лог «proxy не сработал» на каждый мёртвый
// трек: она сама пишет итог одной строкой (а строка эта -- про трек, а не про маршрут).
let ytDlpQuiet = 0;
async function ytDlpRun (query, optsBase)
{
    let routes = await ytRoutes ();   // [v2.52] маршруты с учётом того, резолвится ли имя локально
    // [v2.56] ПРОКСИ ИНОГДА «ИКАЕТ»: одна неудачная попытка на живом прокси -- ещё не
    // повод отдать трек «потоком» (живой случай владельца: прокси отвалился на минуту,
    // и песня ушла в запасной путь с невнятной ошибкой). Если маршрут ОДИН (DIRECT на
    // этой машине невозможен -- имя не резолвится), даём ему вторую попытку через
    // паузу, но только на сетевую ошибку: ошибку самого видео повторять бессмысленно.
    let lastErr;
    for (let route of routes)
    {
        const addr = route && route.proxy ? String (route.proxy) : '';
        // Маршрут остался ОДИН (остальные недоступны)? Даём ему вторую попытку через
        // паузу -- одиночная заминка прокси ещё не повод терять трек.
        const tries = (addr && routes.length === 1) ? 2 : 1;
        for (let attempt = 1; attempt <= tries; attempt++)
        {
            if (attempt > 1)
            {
                if (!ytDlpQuiet)
                    console.log ('[' + (d()) + '] [music] прокси не ответил -- пробую ещё раз');
                await new Promise (res => setTimeout (res, 1200));
            }
            try
            {
                let opts = Object.assign ({}, optsBase, addr
                    ? { proxy: addr, socketTimeout: 10 } // не висим вечно в мёртвом прокси
                    : {});
                let r = await ytdlp (query, opts);
                if (addr) proxyMarkGood (addr);   // этот прокси работает
                return r;
            }
            catch (e)
            {
                lastErr = e;
                if (!ytDlpQuiet)
                    console.error ('[music] ' + (addr ? 'прокси ' + addr : 'DIRECT') + ' не сработал: ' + ytDlpErr (e, 150));
                if (!isNetworkError (e)) throw e; // реальная ошибка YouTube -- повторять бессмысленно
                // [v2.60] сеть подвела на прокси -- помечаем ИМЕННО ЕГО (а не все сразу)
                if (addr) proxyMarkBad (addr);
            }
        }
    }
    throw lastErr;
}

// Очереди по гильдиям: guild_id -> {connection, player, tracks:[], current, volume, textChannelId}
const MUSIC_VOLUME = 0.5; // громкость (команды смены громкости нет -- это константа)
const $music = {}; // guild_id -> состояние (см. musicOf)

function musicOf (guildId)
{
    if (!$music[guildId])
        $music[guildId] =
        {
            connection: null,
            player: createAudioPlayer (),
            tracks: [],
            current: null,
            volume: MUSIC_VOLUME,
            textChannelId: null,
            // [v2.10] сколько текущий трек уже сыграл (для сохранения позиции) и
            // «продолжить с места» для восстановленного после перезапуска трека:
            playedMs: 0,
            playingSince: null,
            seekTrack: null,
            seekSec: 0,
            // [v2.12] Музыка не забывает ничего:
            savedChannelId: null,   // канал, к которому относится сохранённая очередь
            pending: false,         // очередь ждёт слушателя/подключения (бота в канала нет)
            leftByUser: false,      // /leave: очередь помним, но сами обратно не заходим
            pausedByNobody: false,  // пауза из-за отсутствия живых слушателей
            playedToSomeone: false, // очередь реально кому-то играла
            streamRetries: 0,       // попытки продолжить трек с места обрыва потока
            // [v2.30] помощь Idle-обработчику: отличить «трек доиграл/пропущен» от
            // «поток умер». skipRequested ставится /skip и /jump, startedAtSec/
            // startedFromSeek -- в playNext (с какой секунды начали играть).
            skipRequested: false,
            startedAtSec: 0,
            startedFromSeek: false,
            // [v2.18] когда бот подключился по просьбе человека (/join, /play): сразу после
            // этого к автору трека НЕ переезжаем (иначе уехали бы от того, кто позвал)
            justJoinedAt: 0,
            lastErrorAt: 0,
            playerWired: false,     // обработчики плеера вешаются ОДИН раз
            // [v2.14] Ссылка на поток ИГРАЮЩЕГО трека (yt-dlp + наш ffmpeg). Нужна,
            // чтобы их глушить: player.stop() сам поток НЕ закрывает, и без этого
            // yt-dlp/ffmpeg оставались висеть в памяти после /skip, /stop, /leave.
            streamHandle: null,
            // [v2.19] какому серверу принадлежит это состояние: по нему берём настройки
            // (например queue_page -- сколько треков показывать на странице /queue),
            // потому что queuePage получает только m, а не guildId.
            guildId: guildId,
            // [v2.54] история добавлений (/history): null -- ещё не читали из базы
            // (читается один раз при старте или перед первой записью, см. historyLoad).
            history: null,
            historyFromDb: false,   // была ли уже НАСТОЯЩАЯ запись (иначе перенесём из очереди)
        };
    if (!$music[guildId].guildId) $music[guildId].guildId = guildId;
    return $music[guildId];
}

// [v2.14] Staff (админ/модер) ли вызывающий слэш-команду. Роли берём из сырого
// списка member._roles: он есть и у GuildMember, и у «лёгкого» объекта участника
// (у последнего нет member.roles.cache, на котором спотыкается isStaff).
function isStaffInteraction (interaction)
{
    const server = interaction.guildId;
    if (!(server in SERVERS)) return false;
    const member = interaction.member;
    if (!member) return false;
    const s = SERVERS[server];
    const roles = member._roles ||
        (member.roles && member.roles.cache ? [...member.roles.cache.keys ()] : []);
    return !!((s.role_admin && roles.includes (s.role_admin)) ||
              (s.role_moder && roles.includes (s.role_moder)));
}

// [v2.18] Админ ли вызывающий (то же правило, что у текстовой `panda dm`: только
// role_admin). Отдельно от isStaffInteraction: /dm и /announce -- админские и staff
// соответственно, и это видно в одном месте.
function isAdminInteraction (interaction)
{
    const server = interaction.guildId;
    if (!(server in SERVERS)) return false;
    const role_admin = SERVERS[server].role_admin;
    if (!role_admin) return false;
    const member = interaction.member;
    if (!member) return false;
    const roles = member._roles ||
        (member.roles && member.roles.cache ? [...member.roles.cache.keys ()] : []);
    return roles.includes (role_admin);
}

function isDJ (interaction)
{
    const server = interaction.guildId;
    if (!(server in SERVERS)) return false;
    let role_dj = SERVERS[server].role_dj || '';
    let member = interaction.member;
    if (!member) return false;
    // Админ/модер -- всегда DJ:
    if (member._roles.includes (SERVERS[server].role_admin)) return true;
    if (SERVERS[server].role_moder && member._roles.includes (SERVERS[server].role_moder)) return true;
    // Явная DJ-роль (если задана):
    if (role_dj && member._roles.includes (role_dj)) return true;
    // Если DJ-роль не задана в конфиге -- разрешаем всем (для небольших серверов):
    return !role_dj;
}

// Метаданные трека (название, длительность, источник):
async function trackInfo (query)
{
    // [v2.2.2] прокси -> DIRECT (если прокси не отвечает за 3 секунды):
    const info = await ytDlpRun
    (
        query,
        {
            dumpSingleJson: true,
            noWarnings: true,
            noPlaylist: true, // один трек; плейлист разворачиваем отдельно
        }
    );
    return {
        url: info.webpage_url || query,
        streamUrl: query,
        title: info.title || 'Без названия',
        duration: info.duration || 0,
        author: info.uploader || info.channel || info.extractor_key || '',
        isLive: !!info.is_live,
        thumbnail: info.thumbnail || '',
    };
}

// Разворот плейлиста (до 50 треков):
async function playlistInfo (query)
{
    // [v2.2.2] прокси -> DIRECT:
    const info = await ytDlpRun (query, { dumpSingleJson: true, noWarnings: true, flatPlaylist: true });
    if (!info._type || info._type !== 'playlist')
        return [await trackInfo (query)];
    let entries = (info.entries || []).slice (0, 50);
    return entries.map
    (
        e =>
        ({
            url: e.url || e.webpage_url || e.id,
            streamUrl: e.url || e.webpage_url,
            title: e.title || 'Без названия',
            duration: e.duration || 0,
            author: e.uploader || '',
            isLive: false,
            thumbnail: e.thumbnail || '',
        })
    );
}

// ============================================================================
// [v2.14] ВЫРАВНИВАНИЕ ГРОМКОСТИ (MUSIC.normalize, по умолчанию включено).
// Записи сведены с разной громкостью: одна тише, другая громче, и между песнями
// приходится крутить громкость вручную. Фильтр loudnorm приводит всё к одному
// среднему уровню, поэтому разницы не слышно.
// Как это устроено: между yt-dlp и Discord становится НАШ ffmpeg, который сразу
// отдаёт готовый PCM 48k/stereo (StreamType.Raw) -- то есть отдельный процесс
// ffmpeg всё равно нужен, просто теперь он наш и с фильтром.
// Если фильтр не поддерживается сборкой ffmpeg или его отключили в конфиге -- играем
// как раньше (без нормализации), музыка из-за этого не встаёт.
// ============================================================================
let musicNormalizeReady = false; // ставится при старте (probeNormalize)
function probeNormalize ()
{
    return new Promise (resolve =>
    {
        if (!MUSIC_NORMALIZE) return resolve (false);
        if (!ffmpegPath) return resolve (false);
        let p;
        try
        {
            p = spawn (ffmpegPath,
                ['-hide_banner', '-loglevel', 'error', '-f', 'lavfi',
                 '-i', 'anullsrc=r=48000:cl=stereo', '-af', MUSIC_NORMALIZE_FILTER,
                 '-t', '0.2', '-f', 'null', '-'],
                { windowsHide: true });
        }
        catch (e) { return resolve (false); }
        let err = '';
        let guard = setTimeout (() => { try { p.kill (); } catch {} resolve (false); }, 8000);
        p.stderr.on ('data', d => { err += String (d); });
        p.on ('error', () => { clearTimeout (guard); resolve (false); });
        p.on ('close', code =>
        {
            clearTimeout (guard); // таймер-предохранитель больше не держит событийный цикл
            if (code !== 0 && err.trim ())
                console.error ('[music] выравнивание громкости недоступно: ' + ytDlpErr ({ stderr: err }, 150));
            resolve (code === 0);
        });
    });
}

// ============================================================================
// [v2.37] КЭШ АУДИО НА ДИСКЕ (MUSIC.cache, по умолчанию включено).
// ЗАЧЕМ: раньше звук шёл потоком прямо из yt-dlp в Discord, то есть YouTube участвовал
// в проигрывании каждую секунду. Любой его сбой (403, Broken pipe, оборвавшийся сет)
// слышали слушатели, а перемотка и продолжение после перезапуска каждый раз заново
// просили звук у YouTube. Теперь трек живёт на диске.
// КАК (гибрид -- так выбрал владелец):
//   * короткий трек (до MUSIC.cache_full_max_min минут) скачивается ЦЕЛИКОМ и играет
//     уже файл: перемотка мгновенная и точная, YouTube во время игры не нужен. Обычно
//     этого даже не замечаешь: пока играет текущий трек, следующий уже скачивается
//     (предзагрузка), то есть паузы между песнями нет;
//   * длинный сет и любой прямой эфир играют сразу потоком, но параллельно ПИШУТСЯ на
//     диск: доиграл до конца -- файл готов, и со следующего раза (перемотка,
//     восстановление после перезапуска, повтор) трек берётся с диска.
//   * место ограничено MUSIC.cache_max_mb: старые файлы удаляются сами (текущий и
//     предзагруженный не трогаются). Папку кэша можно удалить целиком в любой момент --
//     бот скачает заново; в базе про кэш ничего нет.
// Файлы: music_cache/<sha1 адреса>.m4a; незавершённое лежит рядом с пометкой '.dl.' и
// готовым никогда не считается.
// ============================================================================
const pathMod = require ('path');
const MUSIC_CACHE = MUSIC_CFG.cache !== false;
const MUSIC_CACHE_DIR = pathMod.isAbsolute (String (MUSIC_CFG.cache_dir || 'music_cache'))
    ? String (MUSIC_CFG.cache_dir)
    : pathMod.join (__dirname, String (MUSIC_CFG.cache_dir || 'music_cache'));
// Значения по умолчанию важны: в конфиге этих ключей может не быть вообще (так и есть
// у боевого бота), а кэш при этом должен работать -- 4 ГБ и треки до 15 минут.
const MUSIC_CACHE_MAX_MB = MUSIC_CFG.cache_max_mb === undefined || MUSIC_CFG.cache_max_mb === null
    ? 4096
    : Math.max (0, Math.round (Number (MUSIC_CFG.cache_max_mb) || 0));
const MUSIC_CACHE_FULL_MAX = (MUSIC_CFG.cache_full_max_min === undefined || MUSIC_CFG.cache_full_max_min === null
    ? 15
    : Math.max (0, Math.round (Number (MUSIC_CFG.cache_full_max_min) || 0))) * 60;
// [v2.39] ХРАНИТЬ ЛИ УЖЕ ПРОИГРАННОЕ. По умолчанию нет: файл отыгравшего трека
// удаляется сразу, на диске живут только играющий трек и предзагрузка. Иначе
// скачанное копилось бы до лимита гигабайтами, хотя заново оно уже не понадобится
// (интернет безлимитный -- перекачать не грех). false -- удалять, true -- старое
// поведение (файлы живут до лимита cache_max_mb, удобно слушать плейлист по кругу).
const MUSIC_CACHE_KEEP_PLAYED = MUSIC_CFG.cache_keep_played === true;
// Одна строка при старте (как остальные отчёты): видно, включён ли кэш и куда он пишет.
if (MUSIC_CACHE)
    console.log ('[' + (d()) + '] [music] кэш аудио: ВКЛЮЧЁН -- ' + MUSIC_CACHE_DIR + ' (' +
        (MUSIC_CACHE_MAX_MB ? 'лимит ' + MUSIC_CACHE_MAX_MB + ' МБ, старое удаляется само' : 'без лимита места') + ')' +
        (MUSIC_CACHE_KEEP_PLAYED
            ? '; проигранное остаётся на диске (cache_keep_played: true)'
            : '; проигранные файлы удаляются сразу -- на диске только играющий и предзагрузка') +
        (MUSIC_CACHE_FULL_MAX ? '; треки до ' + Math.round (MUSIC_CACHE_FULL_MAX / 60) +
            ' мин качаю на диск до старта, длинные сеты пишу во время игры' : ''));
else
    console.log ('[' + (d()) + '] [music] кэш аудио: выключен (MUSIC.cache: false) -- звук идёт потоком, как раньше');
let cacheDirOk = false;
function cacheDirReady ()
{
    if (cacheDirOk) return true;
    try
    {
        fsMod.mkdirSync (MUSIC_CACHE_DIR, { recursive: true });
        cacheDirOk = true;
        cacheCleanStale (); // хвосты прошлого запуска уже никто не докачает
    }
    catch (e) { console.error ('[' + (d()) + '] [music] папка кэша недоступна (' + MUSIC_CACHE_DIR + '): ' +
        oneLine (e.message) + ' -- играю потоком, как раньше'); }
    return cacheDirOk;
}
// Недокачанные файлы ('.dl.') после перезапуска бессмысленны: тот поток уже мёртв.
function cacheCleanStale ()
{
    let names = [];
    let n = 0;
    try { names = fsMod.readdirSync (MUSIC_CACHE_DIR); } catch { return 0; }
    for (const f of names)
        if (f.includes ('.dl.'))
            try { fsMod.unlinkSync (pathMod.join (MUSIC_CACHE_DIR, f)); n++; } catch {}
    if (n) console.log ('[' + (d()) + '] [music] кэш: убрал ' + n + ' ' +
        plural (n, 'недокачанный файл', 'недокачанных файла', 'недокачанных файлов') + ' прошлого запуска');
    return n;
}
function fmtMb (bytes) { return Math.max (1, Math.round (Number (bytes || 0) / 1048576)) + ' МБ'; }
// Ключ файла -- от АДРЕСА (не от названия): тот же трек, добавленный заново, найдёт
// свою готовую запись; а переименованное видео не создаст вторую копию.
function cacheKeyOf (track)
{
    const src = String ((track && (track.url || track.streamUrl)) || '');
    return crypto.createHash ('sha1').update (src).digest ('hex').slice (0, 16);
}
// Готовый файл этого трека (или null). Незавершённые ('.dl.') и пустышки не считаются.
function cacheFind (track)
{
    if (!MUSIC_CACHE || !track || track.isLive || !cacheDirReady ()) return null;
    const base = cacheKeyOf (track) + '.';
    let names = [];
    try { names = fsMod.readdirSync (MUSIC_CACHE_DIR); } catch { return null; }
    for (const n of names)
    {
        if (!n.startsWith (base) || n.includes ('.dl.')) continue;
        const p = pathMod.join (MUSIC_CACHE_DIR, n);
        try { if (fsMod.statSync (p).size > 8192) return p; } catch {}
    }
    return null;
}
function cacheDropParts (key)
{
    let names = [];
    try { names = fsMod.readdirSync (MUSIC_CACHE_DIR); } catch { return; }
    for (const n of names)
        if (n.startsWith (key + '.dl.'))
            try { fsMod.unlinkSync (pathMod.join (MUSIC_CACHE_DIR, n)); } catch {}
}
// Скачанный кусок становится готовым файлом: убираем пометку '.dl.' из имени.
function cachePromoteParts (key, track)
{
    let names = [];
    try { names = fsMod.readdirSync (MUSIC_CACHE_DIR); } catch { return null; }
    let file = null, size = 0;
    for (const n of names)
    {
        if (!n.startsWith (key + '.dl.')) continue;
        const src = pathMod.join (MUSIC_CACHE_DIR, n);
        const dst = pathMod.join (MUSIC_CACHE_DIR, n.replace ('.dl.', '.'));
        try
        {
            const s = fsMod.statSync (src).size;
            if (s <= 8192) { fsMod.unlinkSync (src); continue; }
            fsMod.renameSync (src, dst);
            if (s > size) { size = s; file = dst; }
        }
        catch {}
    }
    if (file)
        console.log ('[' + (d()) + '] [music] сохранил на диск: ' + (track && track.title ? track.title : 'трек') + ' (' + fmtMb (size) + ')');
    return file;
}
// СКАЧАТЬ ТРЕК ЦЕЛИКОМ. holder.stop() -- прервать (предзагрузку выбросили).
async function cacheDownload (track, holder = {})
{
    cacheDirReady ();
    // [v2.52] маршрут -- как везде (см. ytRoutes): при мёртвом локальном DNS DIRECT
    // даже не рассматривается, иначе вместо музыки была бы DNS-ошибка
    const viaProxy = ((await ytRoutes ())[0] || {}).proxy || '';   // [v2.60] адрес прокси или '' = DIRECT
    const key = cacheKeyOf (track);
    cacheDropParts (key); // не докачиваем старое -- качаем заново
    const proc = ytdlp.exec
    (
        track.url,
        {
            o: pathMod.join (MUSIC_CACHE_DIR, key + '.dl.%(ext)s'),
            noPart: true,
            quiet: true,
            noWarnings: true,
            noPlaylist: true,
            ...(viaProxy ? { proxy: viaProxy, socketTimeout: 10 } : {}),
            f: 'bestaudio[acodec!=none][ext=m4a]/bestaudio[acodec!=none]/bestaudio/best',
            retries: 3,
        }
    );
    holder.stop = () =>
    {
        holder.cancelled = true;
        try { proc.weKilled = true; } catch {}
        try { if (typeof proc.kill === 'function') proc.kill (); } catch {}
        cacheDropParts (key);
    };
    try { await proc; }
    catch (e)
    {
        cacheDropParts (key);
        if (holder.cancelled) return null;
        throw e;
    }
    return cachePromoteParts (key, track);
}
// ПИСАТЬ ПОТОК НА ДИСК ПО ХОДУ ИГРЫ (длинные сеты): тот же звук, что уходит в Discord,
// дублируется в файл. Доиграло до конца -- файл готов; прервали -- недописанное убираем.
function cacheTeeStart (track)
{
    if (!MUSIC_CACHE || !track || track.isLive || cacheFind (track) || !cacheDirReady ()) return null;
    const key = cacheKeyOf (track);
    const part = pathMod.join (MUSIC_CACHE_DIR, key + '.dl.stream');
    let ws;
    try { ws = fsMod.createWriteStream (part); } catch { return null; }
    ws.on ('error', () => { ws.__dead = true; });
    return {
        key, part, ws,
        finalize ()
        {
            try
            {
                if (ws.__dead) { try { fsMod.unlinkSync (part); } catch {} return null; }
                const size = fsMod.existsSync (part) ? fsMod.statSync (part).size : 0;
                if (size <= 8192) { try { fsMod.unlinkSync (part); } catch {} return null; }
                const file = pathMod.join (MUSIC_CACHE_DIR, key + '.m4a');
                fsMod.renameSync (part, file);
                console.log ('[' + (d()) + '] [music] сохранил на диск: ' + (track.title || 'трек') + ' (' + fmtMb (size) + ')');
                pruneCache ([file]);
                return file;
            }
            catch { return null; }
        },
        abort ()
        {
            if (this.__done) return;
            this.__done = true;
            try { ws.destroy (); } catch {}
            // [v2.37] Файл надо убрать ОБЯЗАТЕЛЬНО, а Windows не отдаёт занятый файл сразу:
            // поэтому пробуем несколько раз (и сразу, и после закрытия потока). Иначе
            // такие недописанные хвосты копились бы за сессию (полный пример -- предзагрузка
            // удалённого видео: поток умер, а файл остался нулевого размера).
            const drop = () =>
            {
                try { if (!fsMod.existsSync (part)) return true; fsMod.unlinkSync (part); return true; }
                catch { return false; }
            };
            ws.once ('close', drop);
            let tries = 0;
            const again = setInterval (() => { if (drop () || ++tries >= 8) clearInterval (again); }, 400);
        },
    };
}
// ЛИМИТ МЕСТА: больше cache_max_mb -- убираем самые старые файлы (текущий и
// предзагруженный не трогаем). Недописанное чистится в первую очередь.
function pruneCache (keepPaths = [])
{
    if (!MUSIC_CACHE_MAX_MB) return;
    const limit = MUSIC_CACHE_MAX_MB * 1048576;
    let names = [];
    try { names = fsMod.readdirSync (MUSIC_CACHE_DIR); } catch { return; }
    const keep = new Set ((keepPaths || []).filter (Boolean).map (p => pathMod.basename (p)));
    const items = [];
    let total = 0;
    for (const n of names)
    {
        const p = pathMod.join (MUSIC_CACHE_DIR, n);
        try { const st = fsMod.statSync (p); if (!st.isFile ()) continue; items.push ({ n, p, size: st.size, at: st.mtimeMs }); total += st.size; }
        catch {}
    }
    if (total <= limit) return;
    items.sort ((a, b) => a.at - b.at); // старые -- первыми
    let freed = 0;
    for (const it of items)
    {
        if (total - freed <= limit) break;
        if (keep.has (it.n)) continue;
        try { fsMod.unlinkSync (it.p); freed += it.size;
            console.log ('[' + (d()) + '] [music] кэш переполнен -- убрал старый файл (' + fmtMb (it.size) + ')'); } catch {}
    }
}
// [v2.39] НА ДИСКЕ -- ТОЛЬКО ТО, ЧТО ЗВУЧИТ СЕЙЧАС (или ждёт своей очереди следующим).
// Файлы нужны ровно на время, пока трек играет: скачали -- отыграли -- забыли. Всё,
// что к текущему моменту не играет и не предзагружено, отсюда уходит.
// MUSIC.cache_keep_played: true отключает уборку (файлы живут до лимита cache_max_mb).
// Отдельные файлы Windows отдаёт не сразу (их ещё читает только что убитый ffmpeg),
// поэтому по ним делается короткая повторная попытка -- но только если трек к тому
// моменту так и не понадобился снова.
function cacheKeysInUse ()
{
    // ВАЖНО: папка кэша общая на ВСЕ серверы, где стоит бот, поэтому в защищённый
    // список входит играющее и предзагруженное НА КАЖДОМ из них -- иначе уборка
    // на одном сервере снесла бы файл трека, который прямо сейчас звучит на другом.
    const set = new Set ();
    for (const id of Object.keys ($music))
    {
        const m = $music[id];
        if (!m) continue;
        for (const t of [m.current, m.preload && m.preload.track])
            if (t && !t.isLive) set.add (cacheKeyOf (t));
    }
    return set;
}
function cacheDropUnused (retries = 5)
{
    if (!MUSIC_CACHE || MUSIC_CACHE_KEEP_PLAYED || !cacheDirOk) return;
    const keep = cacheKeysInUse ();
    let names = [];
    try { names = fsMod.readdirSync (MUSIC_CACHE_DIR); } catch { return; }
    const busy = [];
    let dropped = 0, freed = 0;
    for (const n of names)
    {
        const k = n.split ('.')[0];
        if (!/^[0-9a-f]{16}$/.test (k)) continue; // не наш файл (имена кэша -- <sha1 адреса>.m4a)
        if (keep.has (k)) continue;               // играющий трек и предзагрузка остаются
        const p = pathMod.join (MUSIC_CACHE_DIR, n);
        let st;
        try { st = fsMod.statSync (p); } catch { continue; }
        if (!st.isFile ()) continue;
        try { fsMod.unlinkSync (p); dropped++; freed += st.size; }
        catch { busy.push (p); }
    }
    if (dropped)
        console.log ('[' + (d()) + '] [music] кэш: убрал ' + dropped + ' ' +
            plural (dropped, 'файл', 'файла', 'файлов') + ' (' + fmtMb (freed) +
            ') -- на диске остаются только играющий трек и предзагрузка');
    if (busy.length && retries > 0)
        setTimeout (() =>
        {
            const still = cacheKeysInUse ();
            let left = 0;
            for (const p of busy)
            {
                if (still.has (pathMod.basename (p).split ('.')[0])) continue; // снова нужен -- не трогаем
                try { fsMod.unlinkSync (p); } catch { left++; }
            }
            if (left && retries > 1) setTimeout (() => cacheDropUnused (retries - 1), 700);
        }, 700).unref (); // уборка не держит процесс
}

// ИГРАТЬ ФАЙЛ С ДИСКА: наш ffmpeg читает файл (сдвиг -- ДО входа, поэтому мгновенный и
// точный), дальше всё как обычно (выравнивание громкости -> PCM для Discord).
function openCachedTrack (track, file, seekSec = 0)
{
    if (!ffmpegPath) return null; // без ffmpeg файл не отдать
    const args = ['-hide_banner', '-loglevel', 'error'];
    const cut = (!track.isLive && seekSec >= 1) ? Math.max (0, Math.floor (seekSec)) : 0;
    if (cut) args.push ('-ss', String (cut));
    args.push ('-i', file);
    if (musicNormalizeReady) args.push ('-af', MUSIC_NORMALIZE_FILTER);
    args.push ('-f', 's16le', '-ar', '48000', '-ac', '2', 'pipe:1');
    let ff;
    try { ff = spawn (ffmpegPath, args, { windowsHide: true }); }
    catch (e) { console.error ('[music] с диска не заиграть: ' + oneLine (e.message)); return null; }
    ff.stdin.on ('error', () => {});
    ff.stdout.on ('error', () => {});
    ff.on ('error', () => {});
    let err = '';
    ff.stderr.on ('data', ch => { err += String (ch); });
    ff.on ('close', code =>
    {
        if (code === 0 || code === null || ff.weKilled) return;
        console.error ('[' + (d()) + '] [music] играю с диска, но ffmpeg оборвался: код ' + exitCodeText (code) +
            (err.trim () ? ' -- ' + ytDlpErr ({ stderr: err }, 160) : ''));
    });
    const resource = createAudioResource (ff.stdout, { inputType: StreamType.Raw, inlineVolume: true });
    if (resource.volume) resource.volume.setVolume (MUSIC_VOLUME);
    return { resource, viaProxy: false, source: null, proc: null, ff, fromCache: true, seeked: true };
}

// ============================================================================
// `node . cache [--clear] [--prune]` -- ЧТО ЛЕЖИТ В КЭШЕ МУЗЫКИ.
// Только чтение, пока не попросить уборку: кэш -- это просто скачанные треки, а НЕ
// данные бота (в базе про них нет ничего, папку можно удалить в любой момент).
//   node . cache           -- отчёт: сколько файлов, сколько занимает, лимит
//   node . cache --prune   -- применить лимит MUSIC.cache_max_mb (убрать самое старое)
//   node . cache --clear   -- стереть кэш целиком (бот скачает заново)
// ============================================================================
function cacheCli (args = [])
{
    const _mb = n => (Number (n || 0) / 1048576).toFixed (1) + ' МБ';
    const _when = t => new Date (t).toLocaleString ();
    if (!MUSIC_CACHE)
    {
        console.log ('[cache] кэш музыки выключен в конфиге (MUSIC.cache: false) -- файлов нет и не будет');
        return 0;
    }
    const _dir = pathMod.resolve (MUSIC_CACHE_DIR);
    console.log ('[cache] папка кэша музыки: ' + _dir);
    if (!fsMod.existsSync (_dir))
    {
        console.log ('[cache] папки ещё нет -- она появится, когда бот скачает первый трек');
        console.log ('[cache] пределы: лимит ' + (MUSIC_CACHE_MAX_MB ? MUSIC_CACHE_MAX_MB + ' МБ' : 'без лимита') +
            ', на диск до старта качаются треки до ' + (MUSIC_CACHE_FULL_MAX ? Math.round (MUSIC_CACHE_FULL_MAX / 60) + ' мин' : '0 мин'));
        return 0;
    }
    let names = [];
    try { names = fsMod.readdirSync (_dir); }
    catch (e) { console.log ('[cache] не смог прочитать папку: ' + oneLine (e.message)); return 1; }
    const files = [];
    for (const n of names)
    {
        const p = pathMod.join (_dir, n);
        let st = null;
        try { st = fsMod.statSync (p); } catch { continue; }
        if (st.isFile ()) files.push ({ n, p, size: st.size, at: st.mtimeMs, part: n.includes ('.dl.') });
    }
    const parts = files.filter (f => f.part);
    const done = files.filter (f => !f.part).sort ((a, b) => b.at - a.at);
    const total = done.reduce ((a, f) => a + f.size, 0);
    const partSize = parts.reduce ((a, f) => a + f.size, 0);
    if (args.includes ('--clear'))
    {
        let n = 0, bytes = 0, bad = 0;
        for (const f of files)
            try { fsMod.unlinkSync (f.p); n++; bytes += f.size; } catch { bad++; }
        console.log ('[cache] удалил: файлов ' + n + ' (' + _mb (bytes) + ')' + (bad ? ', не отдались: ' + bad : ''));
        console.log ('[cache] ничего не потеряно: это скачанные треки, а не данные бота -- он скачает их заново');
        return 0;
    }
    console.log ('[cache] готовых треков: ' + done.length + ' (' + _mb (total) + ')' +
        (parts.length ? ', недописанных хвостов: ' + parts.length + ' (' + _mb (partSize) + ')' : '') +
        ', лимит: ' + (MUSIC_CACHE_MAX_MB ? MUSIC_CACHE_MAX_MB + ' МБ' : 'без лимита'));
    if (!files.length)
    {
        console.log ('[cache] пока пусто -- ничего не скачано');
        return 0;
    }
    console.log ('[cache] самое свежее (файл = <sha1 адреса>.m4a, имена треков бот в кэше не хранит):');
    for (const f of done.slice (0, 10))
        console.log ('  ' + f.n.padEnd (26) + _mb (f.size).padStart (10) + '  ' + _when (f.at));
    if (done.length > 10) console.log ('  ... и ещё ' + (done.length - 10));
    console.log ('[cache] удалять можно ВСЁ и в любой момент: в базе про кэш ничего нет, при необходимости бот скачает заново');
    console.log ('[cache] стереть целиком: `node . cache --clear`' +
        '; применить лимит к старому: `node . cache --prune`' +
        '; выключить кэш совсем: MUSIC.cache = false в config.json');
    if (args.includes ('--prune'))
    {
        console.log ('[cache] применяю лимит (' + MUSIC_CACHE_MAX_MB + ' МБ)...');
        pruneCache ([]);
        let after = 0;
        try { for (const n of fsMod.readdirSync (_dir)) after += fsMod.statSync (pathMod.join (_dir, n)).size; } catch {}
        console.log ('[cache] после уборки в папке ' + _mb (after));
    }
    return 0;
}

if (process.argv.slice (2).some (_a => /^cache$/i.test (_a)))
{
    let _code = 0;
    try { _code = cacheCli (process.argv.slice (2)); }
    catch (e) { console.log ('[cache] ошибка: ' + ((e && e.message) || e)); _code = 1; }
    process.exit (_code);
}

// Аудио-ресурс: yt-dlp стримит в stdout -> ffmpeg ресемплирует в Opus для Discord:
// [v2.2.2] стрим по той же стратегии, что и метаданные: прокси -> DIRECT:
// [v2.25] seekMode -- КАК продолжать с места:
//   'sections' (по умолчанию) -- yt-dlp сам отдаёт поток с N-й секунды
//     (--download-sections, требует ffmpeg у yt-dlp): быстро и точно, но не все
//     источники это умеют;
//   'ffseek' -- берём поток с начала и пропускаем N секунд УЖЕ в своём ffmpeg
//     (-ss после -i): работает для любого источника (медленнее на старте, зато
//     место не теряется -- это резервный путь, см. playNext);
//   'none' -- с начала.
async function createTrackStream (track, seekSec = 0, seekMode = 'sections')
{
    // [v2.37] ФАЙЛ УЖЕ НА ДИСКЕ -- сеть не нужна ВООБЩЕ: ни yt-dlp, ни прокси, ни
    // ожидания. Сдвиг в файле точный и мгновенный (ffmpeg -ss до входа).
    const _cached = MUSIC_CACHE ? cacheFind (track) : null;
    if (_cached)
    {
        const r = openCachedTrack (track, _cached, seekSec);
        if (r) return r; // не вышло -- играем как раньше, потоком
    }
    let viaProxy = ((await ytRoutes ())[0] || {}).proxy || '';   // [v2.52, v2.60] см. ytRoutes
    // [v2.10] продолжение с места после перезапуска: yt-dlp отдаёт поток с N-й секунды
    // (--download-sections, нужен ffmpeg). Если так не умеет -- процесс падает сразу,
    // и playNext пробует резервный путь (ffseek), а потом берёт трек с начала.
    // [v2.12] продолжать с места -- всегда, когда есть с чего (даже с секунды)
    const seek = (seekMode === 'sections' && seekSec >= 1 && !track.isLive);
    // [v2.25] резервный путь: сдвиг делает НАШ ffmpeg (см. ниже)
    const seekInFfmpeg = (seekMode === 'ffseek' && seekSec >= 1 && !track.isLive);
    const ytdlpStream = ytdlp.exec
    (
        track.url,
        {
            o: '-',                        // стрим в stdout [!!!!]
            quiet: true,
            noWarnings: true,
            noPlaylist: true,
            // [v2.2.2] через прокси, если жив; иначе DIRECT (v2.60: адрес -- из маршрута,
            // а не из «главного» прокси: их может быть несколько):
            ...(viaProxy ? { proxy: viaProxy, socketTimeout: 10 } : {}),
            f: 'bestaudio[acodec!=none][ext=m4a]/bestaudio[acodec!=none]/bestaudio/best',
            // буфер под riff-сети:
            bufferSize: '4M',
            retries: 3,
            ...(seek ? { ffmpegLocation: ffmpegPath, downloadSections: '*' + Math.max (0, Math.floor (seekSec) - 1) + '-inf' } : {}),
        }
    );
    // [FIX v2.2.1] yt-dlp может упасть (видео недоступно, сеть, прокси) -- его промис раньше
    // никто не ловил, и НЕПОЙМАННЫЙ reject убивал весь процесс бота. Гасим здесь.
    // [v2.9.2] В лог -- одна строка (см. ytDlpErr): читаемая причина, без простыни.
    if (ytdlpStream && typeof ytdlpStream.catch === 'function')
        ytdlpStream.catch (e =>
        {
            // [v2.35] Помним причину смерти потока на самом процессе: Idle-обработчик
            // видит только «трек кончился» и по этой отметке отличит удалённое видео
            // (его надо убрать сразу) от обычного обрыва (его надо продолжить).
            ytdlpStream.lastErr = e;
            // [v2.30] Поток глушили мы сами (/skip, /stop, /leave, переезд) -- это не
            // событие: yt-dlp просто не смог дописать в уже закрытый пайп ('Broken pipe').
            if (ytdlpStream.weKilled) return;
            console.error ('[music] yt-dlp завершился: ' + ytDlpErr (e));
        });
    // [v2.14] Громкость: yt-dlp -> ffmpeg(loudnorm) -> PCM 48k/stereo (StreamType.Raw).
    // Не смогли поднять ffmpeg -- тихо откатываемся к обычному пути (Arbitrary),
    // который сами конвертирует внутри @discordjs/voice.
    // [v2.25] ffmpeg нужен либо для выравнивания громкости, либо для резервного сдвига:
    let ff = null, input = ytdlpStream.stdout, raw = false;
    if (musicNormalizeReady || seekInFfmpeg)
    {
        try
        {
            // -ss ПОСЛЕ -i -- поток не seekable (пайп), поэтому ffmpeg декодирует и
            // выбрасывает всё до нужной секунды (звук появится на ней, а не раньше).
            const args = ['-hide_banner', '-loglevel', 'error', '-i', 'pipe:0'];
            if (seekInFfmpeg) args.push ('-ss', String (Math.max (0, Math.floor (seekSec))));
            if (musicNormalizeReady) args.push ('-af', MUSIC_NORMALIZE_FILTER);
            args.push ('-f', 's16le', '-ar', '48000', '-ac', '2', 'pipe:1');
            ff = spawn (ffmpegPath, args, { windowsHide: true });
        }
        catch (e)
        {
            console.error ('[music] ffmpeg не поднялся: ' + oneLine (e.message) + ' -- играю без него');
            ff = null;
        }
        if (ff)
        {
            // пайп yt-dlp -> ffmpeg; EPIPE/обрыв пайпа -- не повод писать в лог шум
            ytdlpStream.stdout.on ('error', () => {});
            ff.stdin.on ('error', () => {});
            ff.stdout.on ('error', () => {});
            ytdlpStream.stdout.pipe (ff.stdin);
            // ffmpeg может умереть на середине (битый поток, нехватка ресурсов).
            // Это не повод ронять бота -- пишем одной строкой.
            let ffErr = '';
            ff.stderr.on ('data', d => { ffErr += String (d); });
            ff.on ('error', () => {});
            // [v2.35] если yt-dlp уже сказал «видео больше нет» -- наша ffmpeg-ошибка
            // ('Invalid data found') лишь следствие: не пишем в лог второй раз.
            const ffNoiseIfGone = () => isGoneError (ytdlpStream.lastErr);
            ff.on ('close', code =>
            {
                if (code === 0 || code === null) return; // нормально отработал
                if (ff.weKilled) return; // [v2.30] глушили мы сами -- не событие
                if (ffNoiseIfGone ()) return; // [v2.35] причина уже названа yt-dlp-ом
                console.error ('[' + (d()) + '] [music] выравнивание громкости оборвалось: код ' + exitCodeText (code) +
                    (ffErr.trim () ? ' -- ' + ytDlpErr ({ stderr: ffErr }, 160) : '') +
                    ' -- звук этого трека оборвался: до конца он не доиграет, очередь продолжаю со следующего');
            });
            input = ff.stdout;
            raw = true;
        }
    }
    // [v2.37] ДЛИННЫЙ ТРЕК: играем сразу потоком, но тот же звук пишем на диск -- если он
    // доиграет до конца, файл останется готовым и со следующего раза трек играет с диска.
    // Только при игре С НАЧАЛА: продолжение с места дало бы обрезанный файл.
    let tee = null;
    if (!seek && !seekInFfmpeg && !track.isLive && MUSIC_CACHE)
    {
        tee = cacheTeeStart (track);
        if (tee)
        {
            ytdlpStream.stdout.pipe (tee.ws);
            ytdlpStream.then (() => { if (ytdlpStream.weKilled) tee.abort (); else tee.finalize (); },
                              () => tee.abort ());
        }
    }
    const resource = createAudioResource
    (
        input,
        {
            // Raw -- уже готовый PCM 48k/stereo от нашего ffmpeg (или Arbitrary, если
            // нормализация выключена: тогда конвертацию делает @discordjs/voice):
            inputType: raw ? StreamType.Raw : StreamType.Arbitrary,
            inlineVolume: true,
        }
    );
    if (resource.volume)
        resource.volume.setVolume (MUSIC_VOLUME); // [FIX v2.9.1] было musicOf('') -- создавало мусорную запись $music['']
    // [v2.9] source/proc отдаём наружу: у предзагрузки нужно уметь всё это глушить
    // (иначе непригодившийся трек оставил бы висеть yt-dlp, ждущий читателя в пайпе).
    // [v2.25] seeked -- сработал ли ЗАПРОШЕННЫЙ сдвиг (playNext по этому решает,
    // пробовать резервный путь или брать трек с начала):
    return { resource, viaProxy, source: ytdlpStream.stdout, proc: ytdlpStream, ff: ff, tee: tee,
             seeked: (seekMode === 'sections' && seek) || (seekMode === 'ffseek' && !!ff) };
}

// Воспроизведение следующего трека:
// ============================================================================
// [v2.18] ИГРАЕМ ТАМ, ГДЕ СЛУШАЕТ АВТОР ТРЕКА.
// Если человек, который добавил трек, сейчас сидит в голосовом канале -- бот в момент
// старта этого трека переезжает туда и остаётся там до трека другого автора (или до
// /leave). Автора в голосе нет -- никуда не едем.
// Своей инициативы у бота нет: переезжаем ТОЛЬКО когда он уже где-то играет (сам он
// по-прежнему не заходит -- только /join, /play или человек, который его позвал), и не
// переезжаем сразу после явного /join|/play (см. m.justJoinedAt в joinVoice).
// ============================================================================
function authorVoiceId (guildId, track)
{
    if (!track || !track.byId) return null;
    const guild = client.guilds.cache.get (guildId);
    if (!guild || !guild.voiceStates) return null;
    if (client.user && track.byId === client.user.id) return null; // «автор» -- сам бот
    const vs = guild.voiceStates.cache.get (track.byId);
    const chId = vs ? (vs.channelId || (vs.channel && vs.channel.id) || null) : null;
    if (!chId) return null;
    const ch = client.channels.cache.get (chId) ||
        (guild.channels && guild.channels.cache ? guild.channels.cache.get (chId) : null);
    if (!ch) return null;
    if (typeof ch.isVoiceBased === 'function' && !ch.isVoiceBased ()) return null;
    return ch.id;
}

// [v2.27] К КОМУ ЕХАТЬ, ЕСЛИ БОТ ОДИН. Ищем самого «нужного» слушателя: сперва автора
// НЕДОИГРАННОГО трека, потом -- автора ближайшего СЛЕДУЮЩЕГО, и так дальше по очереди.
// Так пауза не запирает бота в пустой комнате, когда дальше есть человек, которому эти
// же треки и адресованы. Канал считается только голосовой и только не тот, где бот уже
// сидит. Возвращает { ch, track } или null (ехать некуда -- остаёмся как есть).
function pickAuthorChannel (guildId, curChId)
{
    const m = $music[guildId];
    if (!m) return null;
    const cand = [];
    if (m.current) cand.push (m.current);
    for (const t of (m.tracks || []))
    {
        if (t !== m.current) cand.push (t);
        if (cand.length > 500) break; // защита от патологически длинной очереди
    }
    for (const t of cand)
    {
        const aCh = authorVoiceId (guildId, t);
        if (!aCh || aCh === curChId) continue;
        const ch = client.channels.cache.get (aCh);
        if (ch) return { ch: ch, track: t };
    }
    return null;
}

// Переехать к автору трека. Возвращает название канала, куда переехали (или null).
function followTrackAuthor (guildId, track)
{
    const m = musicOf (guildId);
    if (!m.connection) return null;                             // бот нигде -- сам не заходит
    if (m.leaving) return null;                                 // бот уже уходит
    if (Date.now () - (m.justJoinedAt || 0) < 5000) return null; // только что позвали -- остаёмся
    const chId = authorVoiceId (guildId, track);
    if (!chId) return null;
    if (m.connection.joinConfig && m.connection.joinConfig.channelId === chId) return null; // уже там
    // [v2.36] ОТ СЛУШАТЕЛЕЙ НЕ УХОДИМ. Автор мог перейти в другую комнату, а в этой ещё
    // сидят и слушают: бот остаётся там, где слушают, и уедет за автором только когда в
    // его комнате не останется НИКОГО, кроме автора (или когда автор сам позовёт /join).
    const here = m.connection.joinConfig ? m.connection.joinConfig.channelId : null;
    if (here)
    {
        const g0 = client.guilds.cache.get (guildId);
        let others = 0;
        if (g0)
            for (const vs of g0.voiceStates.cache.values ())
                if (vs.channelId === here && vs.id !== (client.user && client.user.id) &&
                    String (vs.id) !== String (track.byId || '') && !voiceIsBot (g0, vs)) others++;
        if (others > 0)
        {
            const hereCh = client.channels.cache.get (here);
            console.log ('[' + (d()) + '] [music] остаюсь в «' + (hereCh ? hereCh.name : here) + '»: там ещё ' + others +
                ' ' + plural (others, 'слушатель', 'слушателя', 'слушателей') + ', а автор трека (' +
                (track.byName || track.byId) + ') слушает в другой комнате -- уйду, когда они уйдут (или по /join)');
            return null;
        }
    }
    const guild = client.guilds.cache.get (guildId);
    const ch = client.channels.cache.get (chId) ||
        (guild && guild.channels && guild.channels.cache ? guild.channels.cache.get (chId) : null);
    if (!ch) return null;
    const who = track.byName || '<@' + track.byId + '>';
    try
    {
        // тот же путь, что у /play и /join (умеет и переезд, и первый заход)
        joinVoice (guildId, ch, guild, 'автор трека ' + who + ' слушает здесь');
        m.savedChannelId = ch.id; // после перезапуска продолжаем там же
        if (ch.type === ChannelType.GuildStageVoice)
            console.log ('[' + (d()) + '] [music] «' + ch.name + '» -- Stage-канал: чтобы музыку было слышно, ' +
                'Stage Moderator должен сделать бота спикером');
        return ch.name;
    }
    catch (e)
    {
        console.error ('[music] к автору трека не переехал: ' + oneLine (e.message));
        return null;
    }
}

// [v2.30] «Трек кончился» раньше, чем мог? Значит поток умер (см. Idle-обработчик).
// Для трека с известной длительностью признак один: до конца ещё явно далеко
// (запас 5 сек -- на неточную длительность в метаданных).
// У эфира/потока длительности нет и быть не может, и там нельзя сравнивать с нулём:
// трек мог быть продолжен С МЕСТА (startedAt), поэтому считаем «почти сразу» от той
// секунды, с которой реально начали играть.
function streamEndedEarly (track, at, startedAt = 0)
{
    if (!track) return false;
    if (!track.isLive && Number (track.duration) > 0)
        return at < Number (track.duration) - 5;
    const from = Number (startedAt) > 0 ? Number (startedAt) : 0;
    return at < from + 20;
}

async function playNext (guildId)
{
    const m = musicOf (guildId);
    if (m.leaving) return; // [v2.9] бот уже уходит -- новый трек не запускаем
    // [v2.14] Прошлый поток больше не нужен: глушим его ДО всего остального (иначе
    // после каждого перехода висел бы yt-dlp, ждущий читателя в пайпе).
    killStream (m.streamHandle);
    m.streamHandle = null;
    if (!m.tracks.length)
    {
        m.current = null;
        m.playedMs = 0;
        m.playingSince = null;
        m.streamRetries = 0;
        m.pausedByNobody = false;
        // [v2.12] очередь доиграла до конца: её больше не надо помнить. Логируем как
        // событие один раз (до этого такую строку в логе было не найти вовсе).
        if (m.playedToSomeone)
        {
            console.log ('[' + (d()) + '] [music] очередь доиграна до конца -- вычеркиваю её из памяти');
            m.playedToSomeone = false;
            await clearMusicState (guildId);
        }
        scheduleVoiceStatus (guildId); // [v2.7] «очередь: —» в статусе канала
        schedulePresence ();           // [v2.8] трек кончился -- «смотрит канал»
        return;
    }
    // [v2.35] ТРЕКИ, КОТОРЫХ БОЛЬШЕ НЕТ НА YOUTUBE. Если предзагрузка уже выяснила,
    // что видео удалено/закрыто (isGoneError), незачем ещё раз запускать yt-dlp и
    // ждать четыре неудачных попытки: убираем такой трек сразу и говорим об этом в
    // логе и в канал (люди видели в логе "Video unavailable" без объяснений).
    while (m.tracks.length && m.tracks[0] && m.tracks[0].gone)
    {
        const dead = m.tracks.shift ();
        deadDropNote (guildId); // [v2.43] по факту не запустился -- в /queue видно, сколько таких
        console.error ('[' + (d()) + '] [music] видео больше нет на YouTube (проверено предзагрузкой): ' +
            (dead.title || 'трек') + ' -- убрал из очереди' +
            (dead.warn ? ' (этот трек проверка заранее помечала подозрительным)' : ''));
        // [v2.39] Про это уже сказали в канал автора, как только выяснили (см. предзагрузку)
        // -- второй раз то же самое человеку не нужно.
        if (!dead.goneTold)
            trackNotice (guildId, dead, '🗑 **' + (dead.title || 'Трек') + '** -- видео больше нет на YouTube, убрал из очереди.');
    }
    // [v2.35] Пустые записи в очереди (бывает после ручной правки базы) -- убираем:
    // дальше всё считает, что в очереди объекты треков.
    while (m.tracks.length && !m.tracks[0]) { m.tracks.shift (); console.error ('[' + (d()) + '] [music] в очереди была пустая запись -- убрал'); }
    if (!m.tracks.length) return playNext (guildId); // очередь была пустой только из-за этого
    if (m.seekTrack !== m.tracks[0]) m.streamRetries = 0; // новый трек -- счётчик попыток с нуля
    let track = m.tracks.shift ();
    m.current = track;
    // [v2.18] перед стартом переезжаем туда, где слушает автор ЭТОГО трека (если он в голосовом):
    followTrackAuthor (guildId, track);
    // [v2.14] ОДНА строка на запуск трека. Раньше рядом появлялась отдельная
    // «предзагрузка сыграла: X (без паузы)» -- по логу это читалось как «предыдущий
    // ролик уже отыграл». Теперь всё в строке «играю»: это просто пометка, что трек
    // не искали заново, а взяли готовый поток (заготовка ждала, пока играл прошлый).
    const fromPreload = !!(m.preload && m.preload.track === track);
    // [v2.37] файл уже на диске? тогда так и пишем: видно, что трек играет без YouTube
    const fromDisk = !!(MUSIC_CACHE && !track.isLive && cacheFind (track));
    // [v2.44] ПЕРЕМОТКА ВИДНА В САМОЙ СТРОКЕ «играю». После /seek трек запускается заново,
    // и в логе появлялась ВТОРАЯ, ничем не отличающаяся строка «играю: тот же трек» --
    // по ней нельзя было понять, перемотка это или повторный запуск. Теперь так и пишем.
    const seekFrom = (m.seekTrack === track && (m.seekSec || 0) >= 1) ? Math.round (m.seekSec) : 0;
    console.log ('[' + (d()) + '] [music] играю: ' + (track.title || track.url || 'трек') +
        (seekFrom ? ' (продолжаю с ' + fmtDur (seekFrom) + ')'
                  : (fromDisk ? ' (с диска)' : (fromPreload ? ' (из предзагрузки, без паузы)' : '')))); // [v2.4] активное событие в лог
    scheduleVoiceStatus (guildId, true); // [v2.7] сразу показать новый трек и очередь
    schedulePresence (true);             // [v2.8] «слушает» этот трек
    try
    {
        let resource = null, viaProxy = false, handle = null;
        let startedAt = 0; // [v2.12] с какой секунды трек реально начал играть (0 -- с начала)
        const p = m.preload;
        // [v2.35] ТРЕКИ С ПОМЕТКОЙ `gone` СЮДА НЕ ДОХОДЯТ -- их убирает цикл выше
        // ("видео больше нет на YouTube (проверено предзагрузкой)"), поэтому брать
        // мёртвую заготовку повторно не приходится. Остаётся защита от другой
        // ситуации: заготовка есть, но её yt-dlp уже упал -- такую не берём, пусть
        // трек стартует свежим потоком (иначе упавший процесс простоит в тишине).
        if (p && p.track === track && !(track.gone && p.proc && p.proc.lastErr))
        {
            // [v2.9] этот трек уже готовился пока играл предыдущий -- берём готовое
            m.preload = null; // вынули: теперь это обычный играющий ресурс, не предзагрузка
            const r = await p.promise; // в бою уже готова (песня играла минуты)
            if (r) { resource = r.resource; viaProxy = r.viaProxy; handle = { resource: r.resource, source: p.source, proc: p.proc, ff: p.ff, tee: p.tee }; }
        }
        else
        {
            // готовили не этот трек (или вообще ничего) -- выкидываем, иначе утечёт ffmpeg
            dropPreload (m);
        }
        if (!resource)
        {
            // [v2.10] этот трек может быть восстановлен после перезапуска -- тогда
            // пробуем начать с того же места, а не с начала:
            // [v2.12] ВСЕГДА пробуем продолжить с места (даже с 1 секунды и даже если
            // до конца трека оставалось 15 сек): не вышло -- тогда берём с начала.
            // [v2.12.2] если этот трек когда-то был «прерван» и ждёт в очереди не
            // первым (/move), его позиция приехала вместе с ним (track.seek)
            // [v2.37] КОРОТКИЙ ТРЕК СНАЧАЛА НА ДИСК. Он небольшой (песня -- единицы
            // мегабайт), качается за считанные секунды, зато дальше YouTube в проигрывании
            // не участвует вообще: ни обрывов по дороге, ни «403», а перемотка и продолжение
            // после перезапуска работают по файлу -- сразу и точно. Обычно этого шага даже не
            // видно: трек уже качается предзагрузкой, пока играет предыдущий. Не получилось --
            // играем потоком, как раньше (музыка из-за кэша встать не должна).
            if (MUSIC_CACHE && !track.isLive && Number (track.duration) > 0 &&
                Number (track.duration) <= MUSIC_CACHE_FULL_MAX && !cacheFind (track))
            {
                try
                {
                    console.log ('[' + (d()) + '] [music] качаю на диск: ' + (track.title || 'трек'));
                    await cacheDownload (track);
                }
                catch (e)
                {
                    if (isGoneError (e))
                        console.error ('[' + (d()) + '] [music] видео больше нет на YouTube (' + (track.title || 'трек') +
                            ') -- запускать поток бессмысленно: ' + ytDlpErr (e, 120));
                    else
                        console.error ('[' + (d()) + '] [music] на диск не легло (' + (track.title || 'трек') +
                            '): ' + ytDlpErr (e, 150) + ' -- беру потоком');
                }
            }
            let seekSec = (m.seekTrack === track) ? (m.seekSec || 0) : (track.seek || 0);
            if (track.isLive) seekSec = 0; // у прямого эфира позиции нет
            // [v2.25] продолжение с места: быстрый путь (--download-sections) -> резервный
            // (сдвиг своим ffmpeg, работает для любого источника) -> с начала.
            // [v2.35] ПОРЯДОК ДРУГОЙ, и вот почему (измерено на живом DJ-сете):
            //   * sections на таких источниках отдаёт НОЛЬ байт и падает через 30-45 с
            //     (`ERROR: ffmpeg exited with code 4294967274`) -- и это тот самый случай,
            //     когда возобновлённый сет замолкал через пару секунд;
            //   * свой ffmpeg со сдвигом даёт звук за ~5-6 с (при сдвиге 110 с -- ~10 с).
            // Поэтому маленький сдвиг (до SEEK_FFSEEK_MAX) -- сразу своим ffmpeg, а
            // sections -- только на больших сдвигах и только с ПРОВЕРКОЙ, что поток
            // реально отдал данные (streamFirstData). Не вышло -- сразу резервный путь,
            // не тратя 45 секунд. Что sections не работает на этом источнике, помним
            // до конца работы бота (m.seekSections -- уже проверено один раз).
            const _noSec = (m.seekNoSections || []).includes (track.url); // уже выяснили: не умеет
            const _trySections = seekSec >= 1 && seekSec > SEEK_FFSEEK_MAX && !_noSec;
            let opened = await createTrackStream (track, seekSec, _trySections ? 'sections' : (seekSec >= 1 ? 'ffseek' : 'none'));
            // [v2.37] с диска сдвиг делается по файлу и уже сработал -- никаких проверок
            // «а отдал ли поток байты» здесь не нужно (иначе готовый файл выбрасывался бы зря)
            if (_trySections && !opened.fromCache)
            {
                const _ok = opened.seeked && !(await failedFast (opened.proc)) &&
                    await streamFirstData (opened.source, opened.proc, SEEK_SECTIONS_WAIT_MS);
                if (!_ok)
                {
                    // помним до конца работы бота: этот адрес sections не умеет --
                    // больше на него не тратим ни секунды
                    m.seekNoSections = [...(m.seekNoSections || []), track.url].slice (-20);
                }
                if (!_ok)
                {
                    killStream (opened);
                    console.error ('[' + (d()) + '] [music] секция с ' + fmtDur (seekSec) +
                        ' ничего не отдала за ' + Math.round (SEEK_SECTIONS_WAIT_MS / 1000) + ' с -- беру тот же трек через ffmpeg');
                    opened = await createTrackStream (track, seekSec, 'ffseek');
                }
            }
            if (seekSec >= 1 && (!opened.seeked || await failedFast (opened.proc)))
            {
                killStream (opened);
                // [v2.36] ЕСЛИ СДВИГ НЕ УДАЛСЯ, ТРЕК НЕ НАЧИНАЕТСЯ ЗАНОВО. Для
                // перемотки по просьбе человека у нас есть прежнее место (m.seekReturnSec):
                // возвращаемся туда -- то есть «продолжаем то, что слушали». С начала
                // берём только когда прежнего места нет (восстановление после перезапуска).
                const back = (m.seekTrack === track) ? Math.max (0, Math.round (m.seekReturnSec || 0)) : 0;
                m.seekReturnSec = 0;
                if (back >= 1)
                {
                    console.error ('[' + (d()) + '] [music] перемотка на ' + fmtDur (seekSec) + ' не удалась ' +
                        '(источник не умеет навигацию) -- продолжаю с ' + fmtDur (back) + ', как и играло');
                    musicNotice (guildId, '⚠️ **' + (track.title || 'Трек') + '** -- источник не умеет навигацию, ' +
                        'перемотка не вышла. Продолжаю с `' + fmtDur (back) + '` (где и играло).');
                    opened = await createTrackStream (track, back, 'ffseek');
                }
                else
                {
                    console.error ('[' + (d()) + '] [music] продолжение с ' + fmtDur (seekSec) + ' не удалось -- беру трек с начала');
                    opened = await createTrackStream (track, 0, 'none');
                }
                seekSec = back;
            }
            m.seekReturnSec = 0;
            resource = opened.resource;
            viaProxy = opened.viaProxy;
            handle = { resource: opened.resource, source: opened.source, proc: opened.proc, ff: opened.ff };
            startedAt = seekSec;
        }
        // [v2.12.2] позиция «прерванного» трека не теряется, если он стоит в очереди
        // не первым: кладём её в сам трек (вернётся, когда очередь до него дойдёт).
        // А у трека, который играем сейчас, заявка на сдвиг считана.
        if (m.seekTrack && m.seekTrack !== track && m.seekSec) m.seekTrack.seek = m.seekSec;
        m.seekTrack = null;
        m.seekSec = 0;
        if (track.seek) track.seek = 0; // свой сдвиг у этого трека уже использован
        // [v2.12] если трек продолжается с места -- позиция считается от него, иначе
        // следующее сохранение «теряло» уже прослушанное (было: всегда 0)
        m.playedMs = startedAt * 1000;
        m.playingSince = Date.now ();
        // [v2.30] помним, С КАКОЙ секунды начали и было ли это продолжением с места:
        // по этому Idle-обработчик решает, стоит ли пробовать с места снова или
        // начать трек с начала (см. streamEndedEarly).
        m.startedAtSec = startedAt;
        m.startedFromSeek = startedAt >= 1;
        m.pausedByNobody = false;
        wireStreamErrors (m, track, resource, viaProxy, guildId);
        m.streamHandle = handle; // [v2.14] чем глушить этот трек (см. killStream)
        m.player.play (resource);
        m.playFailStreak = 0; // трек заиграл -- цепочка неудач сброшена (см. catch ниже)
        // [v2.43] ПРОВЕРКА ЗАРАНЕЕ ОШИБЛАСЬ -- И ЭТО НОРМАЛЬНО. Трек доехал до эфира и
        // заиграл (прокси поменяли, регион отпустил): снимаем пометку «под вопросом»,
        // чтобы ⚠ в /queue не пугала зря.
        if (track.warn)
        {
            console.log ('[' + (d()) + '] [music] проверка очереди: трек заиграл -- снимаю пометку «под вопросом» (' +
                (track.title || 'трек') + ')');
            track.warn = '';
            track.warnAt = 0;
        }
        startPreload (guildId); // [v2.9] пока играет -- готовим следующий трек
        cacheDropUnused (); // [v2.39] проигранное уходит с диска -- остаёмся при текущем и предзагрузке
        // [v2.12] играет кому-то живому? тогда естественный конец очереди = забыть её;
        // и если слушателей нет -- сразу пауза (музыка не играет в пустоту)
        const chId = m.connection ? m.connection.joinConfig.channelId : null;
        if (chId && humansInChannel (guildId, chId)) m.playedToSomeone = true;
        saveMusicState (guildId); // [v2.10] очередь и позиция -- на диск (перезапуск не сбросит)
        checkListeners (guildId);
    }
    catch (e)
    {
        // [v2.30] Сказать и ЧТО не заиграло, и что дальше: раньше строка молчала об
        // обоих, и в логе были только «непонятные» ошибки от yt-dlp/ffmpeg.
        console.error ('[' + (d()) + '] [music] трек не заиграл: ' + (track.title || track.url || 'трек') +
            ' -- ' + oneLine (e.message) + ' (беру следующий)');
        m.current = null;
        // [v2.43] ТРЕК ДОШЁЛ ДО ОЧЕРЕДИ И НЕ ЗАПУСТИЛСЯ -- вот теперь это ФАКТ, а не догадка.
        // Ровно этого и ждёт проверка заранее: из очереди она ничего не убирает (ответ
        // зависит от нашего IP и прокси), а здесь трек уходит по делу -- с настоящей
        // причиной в канал его автора и в счёт для /queue.
        deadDropNote (guildId);
        {
            const _why = isGoneError (e) ? 'видео больше нет на YouTube' : ytDlpErr (e, 160);
            trackNotice (guildId, track, (isGoneError (e) ? '🗑 **' : '⚠️ **') + (track.title || 'Трек') +
                '** -- ' + (isGoneError (e) ? 'видео больше нет на YouTube: убрал из очереди.'
                    : 'не запустился, пропускаю.' + (_why ? ' Причина: ' + _why : '')));
        }
        // [v2.35] ПРЕДОХРАНИТЕЛЬ ОТ БЕСКОНЕЧНОГО КРУГА: если причина не в одном битом
        // треке (а, скажем, сломалась сама подготовка потока), эта цепочка не кончалась
        // -- бот рекурсивно звал сам себя и вычерпывал память до падения всего процесса
        // (поймано стендом: 'JavaScript heap out of memory'). Теперь после десяти
        // подряд неудач честно останавливаемся: очередь и место в ней остаются.
        m.playFailStreak = (m.playFailStreak || 0) + 1;
        if (m.playFailStreak >= 10)
        {
            console.error ('[' + (d()) + '] [music] ' + m.playFailStreak + ' треков подряд не заиграли -- ' +
                'останавливаюсь, чтобы не крутиться без конца (очередь помню, проверь лог выше)');
            m.playFailStreak = 0;
            return;
        }
        playNext (guildId); // пропустить битый трек
    }
}

// ============================================================================
// [v2.9] ПРЕДЗАГРУЗКА следующего трека: пока играет текущий, поток следующего уже
// готовится (yt-dlp качает в пайп и упирается в backpressure -- память не растёт).
// Раньше yt-dlp запускался только после Idle, поэтому между песнями была слышна
// пауза на поиск/буферизацию; теперь следующая песня стартует мгновенно.
// ============================================================================

// Выбросить предзагрузку: чужие ffmpeg/yt-dlp должны умереть, а не висеть в памяти.
function dropPreload (m)
{
    const p = m && m.preload;
    if (!p) return;
    m.preload = null;
    p.cancelled = true;
    // [v2.37] если предзагрузка -- это скачивание на диск, его тоже надо прервать
    // (иначе yt-dlp до качает файл, который уже никому не нужен)
    try { if (p.dlStop) p.dlStop (); } catch {}
    // [v2.44] ff: p.ff -- ОБЯЗАТЕЛЬНО. В списке его не было, и ffmpeg выравнивания
    // громкости этой заготовки не помечался «убит нами»: после /seek, /clear и любой
    // смены трека в лог летело ложное «выравнивание громкости оборвалось: код -22 ...
    // звук этого трека оборвётся раньше» (а трек в этот момент даже не играл).
    killStream ({ resource: p.resource, source: p.source, proc: p.proc, ff: p.ff, tee: p.tee });
}

// Глушим поток трека целиком: сам ресурс, поток yt-dlp и его процесс (а также наш
// ffmpeg выравнивания громкости -- иначе процесс остался бы висеть в пайпе).
function killStream (r)
{
    if (!r) return;
    // [v2.30] Помечаем процессы, которые глушим МЫ САМИ: иначе их смерть (/skip, /stop,
    // /leave, конец очереди) сыпала в лог 'yt-dlp завершился: ... Broken pipe' и
    // 'ffmpeg остановился' -- это не события, а шум от собственного же действия.
    try { if (r.proc) r.proc.weKilled = true; } catch {}
    try { if (r.ff) r.ff.weKilled = true; } catch {}
    try { if (r.resource) r.resource.playStream.destroy (); } catch {}
    try { if (r.source) r.source.destroy (); } catch {}
    try { if (r.tee) r.tee.abort (); } catch {} // [v2.37] недописанный файл кэша -- в корзину
    try { if (r.proc && typeof r.proc.kill === 'function') r.proc.kill (); } catch {}
    try { if (r.ff) { r.ff.stdin.destroy (); r.ff.stdout.destroy (); r.ff.kill (); } } catch {}
}

// Начать готовить первый трек очереди (повторные вызовы безопасны).
// [v2.62] ПРЕДЗАГРУЗКА ПРОБУЕТ НЕСКОЛЬКО РАЗ. Живой случай владельца: YouTube ответил
// 'HTTP Error 403: Forbidden' на скачивание следующего трека -- одна попытка, и заготовки
// нет; когда очередь дошла, тот же трек открылся сразу. Одна сетевая заминка (или 403 от
// лимита) ещё не значит, что трек мёртв, поэтому теперь до PRELOAD_TRIES попыток с паузой.
// Если видео реально удалено ('Video unavailable') -- попытки не тратим: помечаем сразу.
const PRELOAD_TRIES = 3;
const PRELOAD_RETRY_MS = 5000;
const sleep = ms => new Promise (r => setTimeout (r, ms));

// Общая попытка с повторами для предзагрузки: зовём fn до PRELOAD_TRIES раз с паузой.
// Отдаём результат fn, а если всё не вышло -- бросаем последнюю ошибку (по ней вызывает
// обычный обработчик: «видео больше нет» / «предзагрузка не удалась»).
async function preloadRetry (fn, p, next)
{
    let lastErr = null;
    for (let i = 1; i <= PRELOAD_TRIES; i++)
    {
        if (p.cancelled) return null;
        try { return await fn (); }
        catch (e) { lastErr = e; }
        if (p.cancelled) return null;
        if (isGoneError (lastErr)) throw lastErr;   // видео нет -- повторять бессмысленно
        if (i < PRELOAD_TRIES)
        {
            console.log ('[' + (d()) + '] [music] предзагрузка не вышла (попытка ' + i + '/' + PRELOAD_TRIES + ', ' +
                (next.title || 'трек') + '): ' + ytDlpErr (lastErr, 120) + ' -- пробую ещё раз через ' +
                Math.round (PRELOAD_RETRY_MS / 1000) + ' с');
            await sleep (PRELOAD_RETRY_MS);
        }
    }
    throw lastErr;
}

function startPreload (guildId)
{
    const m = musicOf (guildId);
    const next = m.tracks[0];
    if (!next) { dropPreload (m); return; }
    if (m.preload && m.preload.track === next) return; // этот уже готовим
    dropPreload (m);                                   // готовили не то -- выкидываем
    // [v2.37] КОРОТКИЙ ТРЕК ГОТОВИМ СКАЧИВАНИЕМ НА ДИСК: пока играет текущий, следующий
    // уже лежит файлом -- между песнями нет не только паузы, но и ни одного запроса к
    // YouTube (а перемотка и восстановление потом вообще мгновенные).
    if (MUSIC_CACHE && !next.isLive && next.duration > 0 && next.duration <= MUSIC_CACHE_FULL_MAX && !cacheFind (next))
    {
        const cp = { track: next, resource: null, viaProxy: false, cancelled: false, cacheOnly: true };
        const holder = {};
        cp.dlStop = () => holder.stop && holder.stop ();
        m.preload = cp;
        // [v2.62] Скачивание пробуем несколько раз с паузой (см. PRELOAD_TRIES).
        cp.promise = (async () =>
        {
            let lastErr = null;
            for (let i = 1; i <= PRELOAD_TRIES; i++)
            {
                if (cp.cancelled) return null;
                try
                {
                    const file = await cacheDownload (next, holder);
                    if (file)
                    {
                        console.log ('[' + (d()) + '] [music] предзагрузка готова (уже на диске): ' + (next.title || 'трек') +
                            (i > 1 ? ' -- со попытки ' + i : ''));
                        return { resource: null, viaProxy: false, fromCache: true };
                    }
                    lastErr = new Error ('файл на диск не лёг');
                }
                catch (e) { lastErr = e; }
                if (cp.cancelled) return null;
                // [v2.35] видео больше нет (удалено/закрыто) -- помним это на треке, чтобы
                // очередь не тратила на него четыре попытки, а убрала сразу. Повторять
                // такую ошибку бессмысленно -- сразу выходим.
                if (isGoneError (lastErr))
                {
                    next.gone = true;
                    console.error ('[' + (d()) + '] [music] видео больше нет на YouTube (' + (next.title || 'трек') +
                        ') -- уберу его из очереди, когда дойдёт; очередь не трогаю: ' + ytDlpErr (lastErr, 120));
                    return null;
                }
                if (i < PRELOAD_TRIES)
                {
                    console.log ('[' + (d()) + '] [music] предзагрузка не вышла (попытка ' + i + '/' + PRELOAD_TRIES + ', ' +
                        (next.title || 'трек') + '): ' + ytDlpErr (lastErr, 120) + ' -- пробую ещё раз через ' +
                        Math.round (PRELOAD_RETRY_MS / 1000) + ' с');
                    await sleep (PRELOAD_RETRY_MS);
                }
            }
            console.error ('[music] предзагрузка не удалась (' + (next.title || 'трек') + '): ' + ytDlpErr (lastErr));
            return null;
        })();
        return;
    }
    const p = { track: next, resource: null, viaProxy: false, cancelled: false };
    m.preload = p;
    // [v2.62] И поток пробуем несколько раз с паузой (preloadRetry): одна сетевая заминка
    // не повод играть без заготовки; ошибку самого видео не повторяем.
    p.promise = preloadRetry (() => createTrackStream (next), p, next).then
    (
        r =>
        {
            if (p.cancelled || !r)
            {
                if (r) killStream (r); // предзагрузку уже выбросили -- глушим всё, что успело открыться
                return null;
            }
            p.resource = r.resource;
            p.viaProxy = r.viaProxy;
            p.source = r.source;
            p.proc = r.proc;
            p.ff = r.ff;
            p.tee = r.tee; // [v2.37] запись на диск живёт вместе с заготовкой
            // [v2.35] ГЛАВНОЕ ПРО УДАЛЁННОЕ ВИДЕО: поток заготовки создан, а падает он
            // П О З Ж Е. Промис yt-dlp внутри createTrackStream гасится своим catch-ем,
            // поэтому outer-промис (этот .then) об ошибке не узнаёт -- без этой проверки
            // трек не помечался как «его больше нет» и очередь узнавала об этом только по
            // факту. Теперь помечаем сразу (в логе -- строка с названием), и когда очередь
            // дойдёт до него -- играть его больше не пытаемся.
            if (r.proc && typeof r.proc.catch === 'function')
                r.proc.catch (e =>
                {
                    if (!isGoneError (e) || next.gone) return;
                    next.gone = true;
                    console.error ('[' + (d()) + '] [music] видео больше нет на YouTube (' + (next.title || 'трек') +
                        ') -- уберу из очереди, когда дойдёт; очередь не трогаю: ' + ytDlpErr (e, 120));
                });
            // Обработчик ошибок вешаем сразу (а не когда трек начнёт играть): иначе
            // 'error' у потока без слушателя уронил бы процесс.
            wireStreamErrors (m, next, r.resource, r.viaProxy, guildId);
            // [v2.14] ясно, ЧТО именно готово: это следующий трек, а не отыгравший
            console.log ('[' + (d()) + '] [music] предзагрузка готова (следующий): ' + (next.title || 'трек'));
            return r;
        },
        e =>
        {
            // не получилось -- не беда: playNext просто возьмёт свежий поток
            p.cancelled = true;
            // [v2.35] Видео больше нет (удалено/закрыто)? Тогда запоминаем это на самом
            // треке: когда очередь до него дойдёт, бот не будет заново запускать yt-dlp
            // и ждать четыре неудачные попытки -- уберёт его сразу и скажет почему.
            // Раньше в лог падал голый 'Video unavailable', и трек молча пропадал.
            if (isGoneError (e))
            {
                next.gone = true;
                console.error ('[' + (d()) + '] [music] видео больше нет на YouTube (' + (next.title || 'трек') +
                    ') -- уберу его из очереди, когда дойдёт; очередь не трогаю: ' + ytDlpErr (e, 120));
                // [v2.39] Скажем автору СРАЗУ, а не когда очередь дойдёт до мертвяка: у него
                // будет время поставить другой трек, и он точно будет знать, что дело не в нём
                // (владелец: «чтобы в следующий раз он знал, что не надо тыкать этот трек»).
                next.goneTold = true;
                trackNotice (guildId, next, '🗑 **' + (next.title || 'Трек') + '** -- видео больше нет на YouTube: ' +
                    'уберу из очереди, когда дойдёт. Поставь другой трек, если он нужен.');
                return null;
            }
            console.error ('[music] предзагрузка не удалась (' + (next.title || 'трек') + '): ' + ytDlpErr (e));
            return null;
        }
    );
}

// [FIX v2.2.1] ошибка в потоке (битое/удалённое видео) раньше валила весь бот.
// [v2.9] теперь поток может быть (а) играющим -- пропускаем трек и едем дальше,
// или (б) только предзагруженным -- просто выбрасываем испорченную заготовку.
function wireStreamErrors (m, track, resource, viaProxy, guildId)
{
    // [FIX v2.9.1] Заготовка подписывается на ошибки СРАЗУ (иначе 'error' у потока без
    // слушателя уронил бы процесс), а когда трек начинает играть, playNext зовёт эту
    // функцию ВТОРОЙ раз. Без проверки на один поток вешались ДВА обработчика: одна
    // ошибка давала две строки в логе, причём вторая называла играющий трек
    // «предзагрузкой» (проверено стендом: listeners=2).
    if (resource.__errWired) return;
    resource.__errWired = true;
    resource.playStream.once ('error', e =>
    {
        const playing = m.current === track;
        // [v2.2.2] сеть упала при стриме через прокси -- следующие треки временно DIRECT.
        // [v2.60] помечаем ИМЕННО ЭТОТ адрес (viaProxy -- теперь строка с адресом), а не
        // все прокси сразу: если в конфиге есть второй, музыка продолжится через него.
        if (viaProxy && isNetworkError (e)) proxyMarkBad (viaProxy);
        if (!playing)
        {
            console.error ('[music] обрыв потока (предзагрузка): ' + oneLine (e.message));
            if (m.preload && m.preload.track === track) m.preload = null; // сломанную заготовку не берём
            return;
        }
        // [v2.35] Видео больше нет -- повтор не поможет: убираем и говорим в канал.
        if (isGoneError (e))
        {
            console.error ('[' + (d()) + '] [music] видео больше нет на YouTube (' + (track.title || 'трек') +
                ') -- убираю из очереди: ' + ytDlpErr (e, 120));
            deadDropNote (guildId); // [v2.43] реальная причина убрать трек -- он не сыграл
            trackNotice (guildId, track, '🗑 **' + (track.title || 'Трек') + '** -- видео больше нет на YouTube, убираю из очереди.');
            m.current = null;
            m.playedMs = 0;
            m.playingSince = null;
            m.streamRetries = 0;
            try { m.player.stop (true); } catch {}
            return;
        }
        // [v2.12] ОБРЫВ ПОТОКА у играющего трека: трек НЕ выбрасываем -- пробуем
        // продолжить его С МЕСТА обрыва (как просили: «всегда пытаться»).
        const at = Math.round (playedMsOf (m) / 1000);
        if (at > (m.lastErrorAt || 0) + 30) m.streamRetries = 0; // играл нормально -- счётчик с нуля
        m.lastErrorAt = at;
        const attempt = (m.streamRetries || 0) + 1;
        if (attempt <= MUSIC_STREAM_RETRIES)
        {
            m.streamRetries = attempt;
            m.playedMs = at * 1000;
            m.playingSince = null;
            m.current = null;
            m.tracks.unshift (track); // трек возвращается в начало очереди...
            m.seekTrack = track;      // ...и playNext продолжит его с этой секунды
            m.seekSec = at;
            console.error ('[music] поток оборвался (' + (at ? 'на ' + fmtDur (at) : 'в самом начале') +
                ', ' + oneLine (e.message) + ') -- продолжаю тот же трек, попытка ' + attempt + '/' + MUSIC_STREAM_RETRIES);
            saveMusicState (guildId);
            m.player.stop (true); // Idle -> playNext (с места обрыва)
            return;
        }
        console.error ('[music] поток обрывается снова (' + attempt + ' раз) -- пропускаю: ' + (track.title || 'трек'));
        m.streamRetries = 0;
        m.current = null;
        // [v2.39] И причину тоже: «не удалось воспроизвести» само по себе ничего не
        // объясняет, а автору важно понять -- трек битый, видео удалили или это сеть.
        const _why = ytDlpErr (e, 160);
        trackNotice (guildId, track, '⚠️ **' + (track.title || 'Трек') + '** -- не удалось воспроизвести, пропускаю.' +
            (_why ? ' Причина: ' + _why : ''));
        m.player.stop (true); // Idle -> playNext
    });
}

// ============================================================================
// [v2.7] СТАТУС В ГОЛОСОВОМ КАНАЛЕ: что играет / очередь / сколько людей / сколько
// бот тут. Discord рисует эту строку в самом канале (PUT /channels/{id}/voice-status).
// У роута жёсткий лимит, поэтому вызовы склеиваются дебаунсом, а в лог идёт ТОЛЬКО
// ошибка -- иначе статус забил бы журнал событий (там должны быть люди, не интерфейс).
// ============================================================================
const VOICE_STATUS_MIN_GAP = 3000; // мс: не чаще одного раза в 3 сек на сервер (лимит роута)
const musicRest = new REST ({ version: '10' }).setToken (TOKEN);
const $voiceStatus = {}; // guildId -> { timer, last, text, channelId }

// «40 сек» / «12 мин» / «1 ч 5 мин» -- коротко, для строки статуса:
function fmtAgo (ms)
{
    let s = Math.max (0, Math.round (ms / 1000));
    let h = s / 3600 | 0, mi = (s % 3600) / 60 | 0;
    if (h) return h + ' ч ' + mi + ' мин';
    if (mi) return mi + ' мин';
    return s + ' сек';
}

// [v2.35] «20:12» -- только время (для истории добавлений в /queue).
function hhmm (ms)
{
    const dt = new Date (Number (ms) || 0);
    return pad (dt.getHours ()) + ':' + pad (dt.getMinutes ());
}

// [v2.34] БОТ ЛИ ЭТО ГОЛОСОВОЕ СОСТОЯНИЕ? Раньше признаком было только
// `vs.member.user.bot`, но member приходит не всегда: у чужого бота, зашедшего в
// канал до нас, член сервера может быть не приложен (частичное состояние, кэш
// участников ещё не догрузился). Тогда ЧУЖОЙ БОТ считался живым слушателем -- и бот
// «играл в пустую комнату», будучи уверенным, что его слушают. Теперь смотрим и кэш
// участников, и кэш пользователей; не выяснили -- считаем человеком (лучше заиграть
// живому слушателю, чем молчать из-за неизвестного состояния).
function voiceIsBot (guild, vs)
{
    if (vs.member && vs.member.user) return !!vs.member.user.bot;
    const mem = guild.members.cache.get (vs.id);
    if (mem && mem.user) return !!mem.user.bot;
    const usr = client.users.cache.get (vs.id);
    return usr ? !!usr.bot : false;
}

// Сколько ЛЮДЕЙ в голосовом канале (боты и сам бот не считаются). Считаем по кэшу
// голосовых состояний: channel.members без интента GuildMembers пуст (в коде уже
// есть такое место -- tempSweep).
function humansInChannel (guildId, channelId)
{
    const guild = client.guilds.cache.get (guildId);
    if (!guild || !channelId) return 0;
    const selfId = client.user ? client.user.id : null; // до ready client.user может быть null
    let n = 0;
    for (const vs of guild.voiceStates.cache.values ())
        if (vs.channelId === channelId && vs.id !== selfId && !voiceIsBot (guild, vs)) n++;
    return n;
}

// [v2.34] То же, но без догадок -- для СТАРТА бота. Здесь цена ошибки высока: решив
// «есть слушатель», бот запускает yt-dlp и играет в пустую комнату, а решив «никого» --
// молчит, когда человек сидит и ждёт музыку. Поэтому по каждому непонятному состоянию
// спрашиваем у Discord (REST); не ответил -- считаем живым слушателем.
async function humansInChannelChecked (guildId, channelId)
{
    const guild = client.guilds.cache.get (guildId);
    if (!guild || !channelId) return 0;
    const selfId = client.user ? client.user.id : null;
    let n = 0;
    for (const vs of guild.voiceStates.cache.values ())
    {
        if (vs.channelId !== channelId || vs.id === selfId) continue;
        if (vs.member && vs.member.user) { if (!vs.member.user.bot) n++; continue; }
        const mem = guild.members.cache.get (vs.id) ||
            (typeof guild.members.fetch === 'function'
                ? await guild.members.fetch (vs.id).catch (() => null) : null);
        if (mem && mem.user) { if (!mem.user.bot) n++; continue; }
        n++; // выяснить не удалось -- пусть лучше играет
    }
    return n;
}

// Обрезка длинного текста (названия трека) под лимит поля: с многоточием.
function clipText (s, max)
{
    s = String (s);
    max = Math.max (4, max | 0);
    return s.length <= max ? s : s.slice (0, max - 1) + '…';
}

// Текст статуса для текущего состояния. null -- бот не в голосовом канале.
function voiceStatusText (guildId)
{
    const m = $music[guildId];
    if (!m || !m.connection) return null;
    const chId = m.connection.joinConfig.channelId;
    const people = humansInChannel (guildId, chId);
    let parts = [];
    // [v2.11] строка «что играет» общая с профильным статусом (см. nowPlayingLine):
    // у прямого эфира длительности нет -- там своя иконка 🔴 вместо 🎶
    // [v2.12] отдельно показываем паузу «нет слушателей» -- видно, что бот не сломался
    if (m.pausedByNobody && m.current)
        parts.push ('😴 нет слушателей: ' + (m.current.title || 'трек') +
            (m.current.isLive ? '' : ' — ' + fmtDur (m.current.duration)));
    else
        parts.push (nowPlayingLine (m.current, m.player.state.status === AudioPlayerStatus.Paused) ||
            '😴 музыка не играет');
    parts.push ('📜 очередь: ' + (m.tracks.length ? m.tracks.length : '—'));
    parts.push ('🎧 в канале: ' + people);
    if (m.since) parts.push ('⏱ бот тут: ' + fmtAgo (Date.now () - m.since));
    return parts.join (' • ').slice (0, 500); // 500 -- лимит поля статуса
}

// [v2.11] Записи статуса уходят в Discord ПО ОЧЕРЕДИ (своя на каждый канал).
// Раньше была гонка: если «что играет» уже летит в REST, а /leave в этот момент снимает
// статус, ответы могли прийти в обратном порядке -- и в канале оставалась старая строка
// до следующего захода. В очереди порядок строгий: последний запрос = итоговое состояние.
// ВАЖНО (проверено живым запросом к API): прочитать прежний статус канала НЕЛЬЗЯ --
// Discord не отдаёт его ни в объекте канала, ни отдельным роутом (405 Method Not Allowed),
// роут только пишущий. Поэтому «вернуть значение создателя канала» технически невозможно;
// взамен бот всегда снимает СВОЙ статус при выходе/переезде и пишет его только при
// реальном изменении -- лишний раз чужую строку не затрёт.
const $statusChain = {}; // channelId -> Promise (хвост очереди записей)

function voiceStatusPush (channelId, status)
{
    if (!channelId) return Promise.resolve ();
    const prev = $statusChain[channelId] || Promise.resolve ();
    const next = prev
        .catch (() => {}) // прошлая ошибка не должна ломать очередь
        .then (() => musicRest.put (Routes.channelVoiceStatus (channelId), { body: { status: status } }))
        .catch (e =>
        {
            console.error ('[' + (d()) + '] [music] статус канала не ' +
                (status === null ? 'снялся: ' : 'записался: ') + e.message);
            throw e; // вызывающий решает, что делать (writeVoiceStatus откатит состояние)
        });
    // когда очередь отпустила канал -- убираем хвост из памяти (но не глушим ошибку):
    next.catch (() => {}).then
    (
        () => { if ($statusChain[channelId] === next) delete $statusChain[channelId]; }
    );
    $statusChain[channelId] = next;
    return next;
}

// Снять статус с канала (при выходе/переезде) -- иначе в нём останется старая строка:
function clearVoiceStatus (channelId)
{
    // [v2.26] Статус канала выключен в конфиге -- не трогаем шапку ВООБЩЕ, в том числе не
    // снимаем её: там может быть текст автора канала, а не наш. Свою прежнюю строку (если
    // бота убили и он не успел её снять) можно убрать разово: `node . clearstatus <id>`.
    if (!MUSIC_CHANNEL_STATUS) return;
    if (!channelId) return;
    // status: null -- это именно «снять статус» (по документации Discord):
    voiceStatusPush (channelId, null).catch (() => {});
}

// Записать текущий статус в канал, где сидит бот:
async function writeVoiceStatus (guildId)
{
    const st = $voiceStatus[guildId] = $voiceStatus[guildId] || {};
    const text = voiceStatusText (guildId);
    if (text === null)
    {
        // бота уже нет в канале -- статус снимаем и чистим память о нём
        const old = st.channelId;
        st.text = null;
        st.channelId = null;
        clearVoiceStatus (old);
        return;
    }
    const channelId = $music[guildId].connection.joinConfig.channelId;
    if (st.text === text && st.channelId === channelId) return; // не дёргаем API зря
    const prev = { text: st.text, channelId: st.channelId };
    st.text = text;
    st.channelId = channelId;
    st.last = Date.now ();
    try
    {
        await voiceStatusPush (channelId, text);
    }
    catch (e)
    {
        console.error ('[' + (d()) + '] [music] статус канала не записался: ' + e.message);
        st.text = prev.text; // вернём, чтобы попробовать снова
        st.channelId = prev.channelId;
    }
}

// Дебаунс: события сыпятся пачками (вошёл человек, сменился трек) -- пишем один раз,
// причём пишется ВСЕГДА актуальный текст (он берётся в момент записи, а не в момент вызова).
// immediate=true -- «событие важное» (сменился трек, пауза, стоп): пишем сразу, если
// прошлый запрос был достаточно давно по меркам лимита.
function scheduleVoiceStatus (guildId, immediate = false)
{
    if (!MUSIC_CHANNEL_STATUS) return; // [v2.26] статус канала выключен -- шапка не наша
    if (!guildId || !(guildId in SERVERS)) return;
    if (!$music[guildId] || !$music[guildId].connection) return; // не сидим -- нечего показывать
    const st = $voiceStatus[guildId] = $voiceStatus[guildId] || {};
    if (st.timer) return;
    const wait = immediate ? Math.max (VOICE_STATUS_MIN_GAP - (Date.now () - (st.last || 0)), 0) : VOICE_STATUS_MIN_GAP;
    st.timer = setTimeout
    (
        () =>
        {
            st.timer = null;
            writeVoiceStatus (guildId).catch (e => console.error ('[' + (d()) + '] [music] статус: ' + e.message));
        },
        wait
    );
}

// [v2.26] `node . clearstatus <id канала>` -- снять СВОЮ строку статуса с голосового канала.
// Зачем: если бот писал статус, а потом его убили (не дали выйти), строка остаётся в шапке
// канала (Discord хранит её до изменения). Роут только ПИШУЩИЙ -- прочитать, что там
// сейчас, нельзя, поэтому команда просто снимает статус с указанного канала.
// При MUSIC.channel_status: false это единственное место, где бот вообще пишет в шапку.
if (/^clearstatus$/i.test (String (process.argv[2] || '')))
{
    const _ch = String (process.argv[3] || '').trim ();
    if (!/^\d{17,20}$/.test (_ch))
    {
        console.log ('[clearstatus] укажи id голосового канала:  node . clearstatus <id канала>\n' +
            '[clearstatus] id виден при включённом режиме разработчика (ПКМ по каналу -> «Копировать ID»),\n' +
            '[clearstatus] либо его печатает  node . dump  (строка musicState)');
        process.exit (1);
    }
    voiceStatusPush (_ch, null)
        .then (() => { console.log ('[clearstatus] статус (шапка) канала ' + _ch + ' снят'); process.exit (0); })
        .catch (e => { console.error ('[clearstatus] не получилось: ' + oneLine (e && e.message || e)); process.exit (1); });
}

// Раз в минуту обновляем счётчик «бот тут N мин» (в лог не пишется -- там только события):
const voiceStatusTick = setInterval
(
    () =>
    {
        for (let g in $music)
            if ($music[g].connection) scheduleVoiceStatus (g);
    },
    60 * 1000
);
if (voiceStatusTick.unref) voiceStatusTick.unref ();

// [v2.10] Позиция внутри трека «бежит» сама, событий у неё нет -- кладём её в базу
// по таймеру. [v2.12.2] Пишем только когда трек РЕАЛЬНО играет (current +
// playingSince): раньше тик молотил запись и на простое, и на паузе, а меняться там
// было нечему (и в простое он ещё и стирал/переписывал одну и ту же строку).
// Очередь, переходы, /stop и /leave пишутся по событиям -- этот тик только про сек.
// 20 сек -> 5 сек: даже если окно закрыли крестиком (без Ctrl+C, т.е. без
// saveAllMusic), очередь всё равно цела, теряются лишь секунды позиции.
const musicSaveTick = setInterval
(
    () =>
    {
        for (let g in $music)
        {
            const m = $music[g];
            if (m && m.current && m.playingSince) saveMusicState (g);
        }
    },
    5 * 1000
);
if (musicSaveTick.unref) musicSaveTick.unref ();

// [v2.12] Ctrl+C -- сохраняем музыку В МОМЕНТ выхода, а не «как успел по таймеру»:
// позиция восстанавливается точнее. [v2.12.2] Уточнение: это именно Ctrl+C/SIGTERM.
// Закрытие окна крестиком на Windows убивает процесс без сигнала -- здесь ничего не
// помочь, но очередь и трек к тому моменту уже в базе (пишутся по событиям), а
// позиция отстаёт максимум на один тик (5 сек), см. musicSaveTick.
let $exiting = false;
async function saveAllMusic ()
{
    const ids = Object.keys ($music).filter
    (
        g => $music[g] && ($music[g].current || $music[g].tracks.length || $music[g].connection)
    );
    await Promise.race
    ([
        Promise.all (ids.map (g => saveMusicState (g).catch (() => {}))),
        new Promise (r => setTimeout (r, 1500)), // база не должна задерживать выход
    ]);
}
for (let sig of ['SIGINT', 'SIGTERM'])
    process.on (sig, () =>
    {
        if ($exiting) return;
        $exiting = true;
        console.log ('[' + (d()) + '] [music] сохраняю очередь перед выходом...');
        saveAllMusic ().finally (() => process.exit (0));
    });

// ============================================================================
// [v2.12] МУЗЫКА ПОМНИТ ВСЁ (очередь, текущий трек, позицию, канал)
//   * очередь НЕ устаревает: бот обязан доиграть задуманное, когда бы его ни
//     включили (раньше через 10 минут всё забывалось);
//   * нет живых слушателей -- пауза, вернулся слушатель -- продолжаем;
//   * после перезапуска/падения бот сам заходит в тот же канал, как только там
//     появляется живой слушатель; после `/leave` -- ждёт `/join` (сам не лезет);
//   * забывает очередь только `/stop` и естественный конец (доиграла до конца).
// ============================================================================

// Предел попыток «продолжить с места обрыва» для одного трека (потом пропускаем,
// а не бьёмся в мёртвый источник бесконечно):
const MUSIC_STREAM_RETRIES = 3;

function trackToJson (t)
{
    // [v2.14] byId/byName -- кто добавил трек: нужны после перезапуска, чтобы в /queue
    // было видно авторство и работала чистка «по автору».
    return { url: t.url, title: t.title, duration: t.duration || 0, author: t.author || '',
             isLive: !!t.isLive, seek: t.seek || 0,
             byId: t.byId || null, byName: t.byName || '',
             // [v2.35] когда трек поставили -- для истории добавлений в /queue
             addAt: Number (t.addAt) || 0,
             // [v2.39] откуда добавили (текстовый канал) -- туда уходит сообщение,
             // если с треком что-то не так. Переживает перезапуск вместе с треком:
             // поле сохраняет себя в базу, иначе после рестарта уведомление ушло бы
             // «в последний канал вообще», то есть могло попасть к чужим людям.
             addIn: t.addIn || null };
}

// ============================================================================
// [v2.31] АВТОР ОБЯЗАТЕЛЕН У КАЖДОГО ТРЕКА.
// byId/byName проставляются при добавлении (/play) и переживают перезапуск (они
// записываются в базу вместе с треком). По этому полю работают чистка, удаление,
// перестановка и сводка по авторам -- без него непонятно, чей это трек.
// У треков из СТАРЫХ баз автора нет: такой трек показываем как «без автора» и
// считаем НИЧЬИМ -- обычный DJ его не убирает и не переставляет, staff может.
// ============================================================================
function byIdOf (t) { return (t && t.byId) ? String (t.byId) : ''; }
function byNameOf (t) { return (t && t.byName) ? String (t.byName) : 'без автора'; }
// Запись принадлежит этому человеку? (пустой id -- ничья запись, не чья-то)
function isBy (t, id) { return !!id && byIdOf (t) === String (id); }

// [v2.36] АВТОРСКИЕ БЛОКИ: треки одного автора в очереди не чередуются ("под-плейлисты").
// Куда поставить новую пачку /play: сразу за последним треком ЭТОГО ЖЕ автора, а если его
// треков в очереди нет -- в самый конец (новый блок). Так очередь всегда читается
// блоками, /push и перестановка не рвут чужие плейлисты, а чередование -- при желании --
// делается осознанно (staff: /move, /jump).
function authorBlockInsertAt (tracks, byId)
{
    if (!byId) return tracks.length;
    for (let i = tracks.length - 1; i >= 0; i--)
        if (tracks[i] && isBy (tracks[i], byId)) return i + 1;
    return tracks.length;
}

// [v2.14] Подпись автора трека для /queue -- теперь есть ВСЕГДА: пустое место
// читалось как «автор неизвестен», и непонятно было, почему трек нельзя тронуть.
function byLabel (t)
{
    // [v2.61] Тот же переход на ссылку-упоминание, что и в списке очереди (queueLines).
    return byIdOf (t) ? ' · ' + u (byIdOf (t)) : ' · 👤 ' + byNameOf (t);
}

// сколько миллисекунд играет текущий трек (пауза не считается):
function playedMsOf (m)
{
    return (m.playedMs || 0) + (m.playingSince ? Date.now () - m.playingSince : 0);
}

// [v2.12] Музыка не забывает ничего: очередь, текущий трек, позиция и канал лежат в
// базе и переживают и перезапуск, и падение, и /leave. Стирает состояние только /stop
// и естественный конец очереди (когда она доиграла живым слушателям).
async function saveMusicState (guildId)
{
    try
    {
        const m = $music[guildId];
        if (!m || !guildId) return;
        if (!m.current && !m.tracks.length) // помнить нечего
        {
            await db (guildId, 'musicState', 'queue', null);
            return;
        }
        const channelId = m.connection ? m.connection.joinConfig.channelId : (m.savedChannelId || null);
        // [v2.12] «текущий» бывает играющим (m.current) или ЖДУЩИМ продолжения после
        // /leave/обрыва (m.seekTrack): тогда позиция -- из seekSec, а не из часов.
        // Иначе после перезапуска место в треке терялось (в базу уходил 0).
        const playing = !!m.current;
        const waiting = m.current || m.seekTrack || null;
        let elapsed = 0;
        if (m.current) elapsed = Math.round (playedMsOf (m) / 1000);
        else if (m.seekTrack) elapsed = Math.max (0, Math.round (m.seekSec || 0));
        // [v2.12-fix] ЖДУЩИЙ трек (после /leave, обрыва или попытки продолжить) лежит
        // где-то в m.tracks -- так его ждёт playNext. В базу он уходит полем current,
        // и второй раз в tracks он не нужен: иначе после перезапуска resumeMusic
        // склеивал его сам с собой и трек играл бы дважды (стенд: 'Дубликат' x2).
        // Сверяемся по объекту, а не по позиции: /move может сдвинуть его глубже.
        const rest = (waiting && !playing) ? m.tracks.filter (t => t !== waiting) : m.tracks;
        // [v2.12.2] и запоминаем, на каком месте в очереди он стоял (0 = первым):
        // /move 1 4 не должен после перезапуска откатываться обратно в начало.
        const curIdx = (waiting && !playing) ? Math.max (0, m.tracks.indexOf (waiting)) : 0;
        await db (guildId, 'musicState', 'queue',
        {
            at: Date.now (),
            channelId: channelId,
            textChannelId: m.textChannelId || null,
            current: waiting ? trackToJson (waiting) : null,
            curIdx: curIdx,
            elapsed: elapsed,
            tracks: rest.map (trackToJson),
            left: !!m.leftByUser, // вышел по /leave -- сами не возвращаемся, ждём /join
            // [v2.57] Какое сообщение /queue ведёт самообновление (чтобы оно пережило
            // перезапуск). ТЕКСТА тут нет сознательно: он длинный, а сохраняем мы часто
            // (каждая смена трека и позиции) -- незачем гонять его в базу. После
            // перезапуска текст пуст, поэтому первая же проверка обновит сообщение.
            qMsg: (QUEUE_LIVE_MS && m.qMsg) ? { ch: m.qMsg.ch, id: m.qMsg.id, page: m.qMsg.page,
                actorId: m.qMsg.ctx && m.qMsg.ctx.actorId, actorName: m.qMsg.ctx && m.qMsg.ctx.actorName,
                staff: !!(m.qMsg.ctx && m.qMsg.ctx.staff) } : null,
        });
    }
    catch (e) { console.error ('[music] не смог сохранить очередь: ' + oneLine (e.message)); }
}

// Забыть очередь совсем (только /stop и естественный конец):
async function clearMusicState (guildId)
{
    await db (guildId, 'musicState', 'queue', null)
        .catch (e => console.error ('[music] не смог стереть очередь: ' + oneLine (e.message)));
}

// ============================================================================
// [v2.54] ИСТОРИЯ ДОБАВЛЕНИЙ -- ЗАПИСЬ musicState/history, ОТДЕЛЬНО от очереди.
// Раньше «кто и когда поставил» жило прямо в очереди (строка «Последние добавления»
// в /queue строилась из неё же), поэтому доигранное и убранное пропадало вместе со
// своими треками, а длинные пачки показывались одним куцым огрызком. Теперь пачка
// записывается НАВСЕГДА (до MUSIC.history_len пачек) и видна командой /history:
// кто, когда и что добавил -- трек, эфир или плейлист (со составом). Очередь -- своё,
// история -- своё: /stop и /clear очередь стирают, а историю не трогают.
// ============================================================================
const HISTORY_MSG_LIMIT = 1800; // сколько символов отдаём под список -- с запасом до лимита Discord

// [v2.56] ЛИМИТОВ У ИСТОРИИ ДВА, И РЕЖЕМ МЫ ЦЕЛЫМИ ПАЧКАМИ.
//   history_len    -- сколько ПАЧЕК помнить (как было);
//   history_tracks -- сколько ТРЕКОВ помнить суммарно: пачка из 50 треков съедает
//                     впятеро больше места, чем пять одиночных заходов, и без второго
//                     лимита именно такие плейлисты вытесняют из истории мелкие добавки.
// Половина пачки в истории смысла не имеет (её состав и её авторство -- одно целое),
// поэтому уходят пачки ЦЕЛИКОМ, от самых старых. НОВЕЙШАЯ пачка не выбрасывается
// никогда, даже если одна перебирает лимит: иначе история окажется пустой сразу после
// /play, а это выглядит как «/history не работает».
function historyTrim (list)
{
    const out = (Array.isArray (list) ? list : []).slice ();
    if (out.length > MUSIC_HISTORY_LEN) out.length = MUSIC_HISTORY_LEN;
    if (MUSIC_HISTORY_TRACKS)
    {
        let total = 0;
        for (let i = 0; i < out.length; i++)
        {
            total += historyTracksOf (out[i]);
            if (total > MUSIC_HISTORY_TRACKS && i > 0) { out.length = i; break; }
        }
    }
    return out;
}
function historyTracksOf (e) { return Math.max (1, Number (e && e.n) || 1); }
function historyTotalTracks (list)
{
    return (Array.isArray (list) ? list : []).reduce ((s, e) => s + historyTracksOf (e), 0);
}

async function historyLoad (guildId)
{
    const m = musicOf (guildId);
    if (Array.isArray (m.history)) return m.history;   // уже читали -- в базу не ходим
    m.history = [];
    m.historyFromDb = false;
    if (!MUSIC_HISTORY_LEN) return m.history;
    try
    {
        const rec = await db (guildId, 'musicState', 'history');
        const list = rec && Array.isArray (rec.list) ? rec.list : [];
        m.history = historyTrim (list.filter (e => e && typeof e === 'object' && Number (e.at)));
        m.historyFromDb = !!rec;
    }
    catch (e) { console.error ('[music] не смог прочитать историю добавлений: ' + oneLine ((e && e.message) || e)); }
    return m.history;
}

// [v2.54] ПЕРВЫЙ ЗАПУСК ПОСЛЕ ОБНОВЛЕНИЯ: история ещё ни разу не писалась (ключа в базе
// нет), а в очереди лежат треки с метками добавления (addAt) -- ровно то, что показывала
// старая строка «Последние добавления» в /queue. Чтобы /history не открывался пустым,
// переносим эти пачки ОДИН раз -- дальше история пишется сама и стирается только
// полностью (удалить ключ musicState/history в базе). Очередь при этом не меняется.
async function historySeedFromQueue (guildId)
{
    if (!MUSIC_HISTORY_LEN) return 0;
    const m = $music[guildId];
    if (!m) return 0;
    // Сами читаем базу (в память история попадает только по historyLoad): если запись
    // там УЖЕ есть, переносить нечего -- она и есть настоящая история.
    await historyLoad (guildId);
    if (m.historyFromDb || m.history.length) return 0;
    const byKey = new Map ();
    // ПО ОБЪЕКТУ, а не по списку: ждущий продолжения трек лежит И в m.current, И в
    // m.tracks (так его ждёт playNext) -- без этой проверки он посчитался бы дважды
    // и пачка получилась бы на трек больше, чем на самом деле.
    const seen = new Set ();
    for (const t of [...m.tracks, m.current, m.seekTrack])
    {
        if (!t || seen.has (t)) continue;
        seen.add (t);
        const at = Number (t.addAt) || 0;
        if (!at) continue; // трек из старой базы -- времени добавления у него нет
        const key = byIdOf (t) + '@' + at;
        let b = byKey.get (key);
        if (!b) { b = { at: at, byId: byIdOf (t), byName: byNameOf (t), inCh: t.addIn ? String (t.addIn) : '',
                         n: 0, live: 0, titles: [], urls: [], ids: [], q: '' }; byKey.set (key, b); }
        b.n++;
        if (t.isLive) b.live++;
        if (b.titles.length < 3) b.titles.push (t.title || t.url || '');
        // [v2.56] Ключи треков -- чтобы у перенесённых из очереди пачек тоже работала
        // «судьба» (см. historyFate). Метка добавления у пачки общая, треки -- свои.
        if (b.ids.length < 500) b.ids.push (ytKey (t.url));
        // [v2.56] ссылки переносим вместе с названиями -- чтобы из /history можно было
        // добавить пачку заново, не разыскивая её в YouTube (то же, что у новых пачек).
        if (b.urls.length < 3 && /^https?:/i.test (String (t.url || ''))) b.urls.push (String (t.url).slice (0, 200));
    }
    const list = historyTrim ([...byKey.values ()].sort ((a, b) => b.at - a.at));
    if (!list.length) return 0;
    m.history = list;
    await historySave (guildId);
    console.log ('[' + (d()) + '] [music] история добавлений: перенёс в неё ' + list.length + ' ' +
        plural (list.length, 'пачку', 'пачки', 'пачек') + ' из очереди (строка «Последние добавления» переехала в /history)');
    return list.length;
}

async function historySave (guildId)
{
    const m = $music[guildId];
    if (!m || !Array.isArray (m.history)) return;
    try { await db (guildId, 'musicState', 'history', { at: Date.now (), list: historyTrim (m.history) }); }
    catch (e) { console.error ('[music] не смог сохранить историю добавлений: ' + oneLine ((e && e.message) || e)); }
}

// Одна пачка /play -- одна запись. Зовётся из /play ПОСЛЕ того, как треки уже встали
// в очередь (иначе в историю попало бы то, чего в очереди не оказалось).
async function historyAdd (guildId, entry)
{
    if (!MUSIC_HISTORY_LEN) return;
    const m = musicOf (guildId);
    await historyLoad (guildId);
    m.history.unshift
    ({
        at: Number (entry.at) || Date.now (),
        byId: entry.byId ? String (entry.byId) : '',
        byName: String (entry.byName || '').slice (0, 80),
        inCh: entry.inCh ? String (entry.inCh) : '',
        n: Math.max (1, Number (entry.n) || 1),
        live: Math.max (0, Number (entry.live) || 0),
        // [v2.56] ЧТО ЧЕЛОВЕК НАПИСАЛ В /play (ссылка, запрос или адрес плейлиста): по
        // этому видно, откуда пачка, и это же можно вставить в /play второй раз, не
        // разыскивая трек заново. У плейлистов тут адрес плейлиста, а сами треки -- в
        // titles/urls (их первые три, иначе одна пачка съела бы всё сообщение).
        q: String (entry.q || '').replace (/\s+/g, ' ').trim ().slice (0, 120),
        titles: (entry.titles || []).slice (0, 3).map (t => String (t || '').slice (0, 90)),
        urls: (entry.urls || []).filter (u => /^https?:/i.test (String (u || '')))
            .slice (0, 3).map (u => String (u).slice (0, 200)),
        // [v2.56] КЛЮЧИ ТРЕКОВ ПАЧКИ -- по ним /history и отвечает на «а что с ней
        // стало»: сколько ещё ждёт в очереди, что играет прямо сейчас, а что уже
        // доиграно или убрано. Сравнение по видео-id, а не по названию: одноимённых
        // треков у одного автора бывает много (тогда «судьба» врала бы). 500 --
        // верхняя граница, она же предел MUSIC.history_tracks: длиннее пачки в
        // истории всё равно не живут.
        ids: (entry.ids || []).slice (0, 500).map (s => String (s || '')).filter (Boolean),
    });
    m.history = historyTrim (m.history);
    await historySave (guildId);
}

// Ключ трека для сверки с очередью: у треков нет отдельного поля с id, зато есть
// канонический адрес (webpage_url у одиночного, watch-ссылка у плейлиста), по нему
// и достаём видео-id. «Голый» id из старой базы возвращается как есть.
function ytKey (url)
{
    const s = String (url || '');
    let m = s.match (/[?&]v=([\w-]{6,20})/);            if (m) return m[1];
    m = s.match (/youtu\.be\/([\w-]{6,20})/);           if (m) return m[1];
    m = s.match (/\/live\/([\w-]{6,20})/);              if (m) return m[1];
    m = s.match (/\/shorts\/([\w-]{6,20})/);            if (m) return m[1];
    m = s.match (/^([\w-]{6,20})$/);                    if (m) return m[1];
    return s.slice (0, 60);
}

// СУДЬБА ПАЧКИ (v2.56): что из неё ещё ждёт в очереди, что играет сейчас, а что уже
// доиграно или убрано. Считается по ключам треков (e.ids), а не по числам: пачка из
// 33 треков после /clear выглядит как «в очереди уже нет», и это правда.
function historyFate (m, e)
{
    const ids = Array.isArray (e.ids) ? e.ids.filter (Boolean) : [];
    if (!ids.length) return '';   // пачка из старой базы -- ключей нет, обещать нечего
    const total = Math.max (Number (e.n) || ids.length, ids.length);
    const cur = m.current ? ytKey (m.current.url) : '';
    const wait = new Set (m.tracks.map (t => ytKey (t.url)));
    let inQ = 0;
    for (const id of ids) if (wait.has (id)) inQ++;
    if (cur && ids.includes (cur))
        return '▶ сейчас в эфире' + (inQ ? ', в очереди ещё ' + inQ + ' из ' + total : '');
    if (!inQ) return 'в очереди уже нет (доиграно или убрано)';
    if (inQ >= total) return 'в очереди: вся пачка';
    return 'в очереди: ' + inQ + ' из ' + total;
}

// Ссылки для повторного добавления: берём только короткие адреса (длинный не влезет,
// а обрезанная ссылка бесполезна) -- не больше двух. Ссылку-запуск (e.q) показываем
// отдельно, поэтому её тут не дублируем.
function historyLinks (e)
{
    const out = [];
    for (const u of (e.urls || []))
    {
        const s = String (u || '');
        if (s.length <= 90 && !out.includes (s)) out.push (s);
        if (out.length >= 2) break;
    }
    return out;
}

// Текст /history. Ограничен по числу пачек (history_len), по числу треков
// (history_tracks) и по длине сообщения: Discord в 2000 символов не влезет двадцатью
// пятью пачками плейлистов, поэтому строки идут от свежих к старым, а остаток честно
// называется. У каждой пачки может быть вторая строка «↳» -- судьба, запрос /play и
// ссылки; если она не влезает, пачка уходит в «Раньше -- ещё N» целиком.
function historyText (guildId)
{
    const m = musicOf (guildId);
    const list = Array.isArray (m.history) ? m.history : [];
    const two = n => String (n).padStart (2, '0');
    const stamp = t => { const x = new Date (t); return two (x.getDate ()) + '.' + two (x.getMonth () + 1) +
        ' ' + two (x.getHours ()) + ':' + two (x.getMinutes ()); };
    if (!MUSIC_HISTORY_LEN)
        return '🕘 История добавлений выключена (`MUSIC.history_len`: 0).\n_' +
            'Поставь число (например 25) -- и снова буду помнить, кто что ставил._';
    if (!list.length)
        return '🕘 Истории добавлений пока нет -- её начнут писать новые `/play`.\n_' +
            'Помню последние ' + MUSIC_HISTORY_LEN + ' ' + plural (MUSIC_HISTORY_LEN, 'пачку', 'пачки', 'пачек') +
            ' (`MUSIC.history_len`); очередь -- отдельно: `/queue`._';
    const sum = historyTotalTracks (list);
    const head = '🕘 **История добавлений** -- ' + plural (list.length, 'последняя', 'последние', 'последние') +
        ' ' + list.length + ' ' + plural (list.length, 'пачка', 'пачки', 'пачек') + ', ' + sum + ' ' +
        plural (sum, 'трек', 'трека', 'треков') + (list.length >= MUSIC_HISTORY_LEN ||
            (MUSIC_HISTORY_TRACKS && sum >= MUSIC_HISTORY_TRACKS)
            ? ' (_MUSIC.history_len_: ' + MUSIC_HISTORY_LEN +
              (MUSIC_HISTORY_TRACKS ? ', _history_tracks_: ' + MUSIC_HISTORY_TRACKS : '') + ')' : '') + ':\n' + QSEP;
    const shown = [];
    let len = head.length, hidden = 0;
    for (const e of list)
    {
        const what = (e.n > 1)
            ? 'плейлист: ' + e.n + ' ' + plural (e.n, 'трек', 'трека', 'треков') +
              (e.live ? ' (' + e.live + ' 🔴 ' + plural (e.live, 'эфир', 'эфира', 'эфиров') + ')' : '') +
              ((e.titles || []).length ? ': ' + e.titles.join (', ') +
                  (e.n > e.titles.length ? ' и ещё ' + (e.n - e.titles.length) : '') : '')
            : (e.live ? 'эфир: ' : 'трек: ') + ((e.titles || [])[0] || 'без названия');
        const line = '`' + stamp (e.at) + '` **' + (e.byName || 'без автора') + '** -- ' + what;
        // [v2.56] Вторая строка -- что стало с пачкой, что человек написал в /play и
        // адреса для повторного добавления. Собирается только из того, что есть.
        const sub = [];
        const fate = historyFate (m, e);
        if (fate) sub.push (fate);
        if (e.q) sub.push ('запуск: `' + String (e.q).slice (0, 80) + '`');
        const links = historyLinks (e);
        if (links.length && !/^https?:/i.test (String (e.q || ''))) sub.push (links.join (' '));
        const subLine = sub.length ? '\n   ↳ ' + sub.join (' · ') : '';
        if (len + line.length + subLine.length + 2 > HISTORY_MSG_LIMIT)
        {
            hidden = list.length - shown.length;
            break;
        }
        shown.push (line + subLine);
        len += line.length + subLine.length + 1;
    }
    const tail = '\n' + QSEP + '\n_Один `/play` = одна пачка: кто, когда и что поставил.\n' +
        'Строка «↳» -- судьба пачки (что ждёт в очереди, что доиграно и убрано),\n' +
        'что ты написал в `/play` -- это можно вставить заново, ссылки на сами треки.\n' +
        (hidden ? 'Раньше -- ещё ' + hidden + ' ' + plural (hidden, 'пачка', 'пачки', 'пачек') + '.\n' : '') +
        'Старое уходит само: помню ' + MUSIC_HISTORY_LEN + ' ' + plural (MUSIC_HISTORY_LEN, 'пачку', 'пачки', 'пачек') +
        (MUSIC_HISTORY_TRACKS ? ' и до ' + MUSIC_HISTORY_TRACKS + ' треков суммарно (пачка уходит целиком)' : '') +
        ' -- ключи `MUSIC.history_len`' + (MUSIC_HISTORY_TRACKS ? ' и `MUSIC.history_tracks`' : '') + '._';
    return head + '\n' + shown.join ('\n') + tail;
}

// ============================================================================
// [v2.24] ПРИСУТСТВИЕ бота -- ОТДЕЛЬНО от очереди.
// Бот может сидеть в канале и без единого трека (/join «посидеть с ботом», /stop,
// доигравшая очередь), и это состояние тоже должно переживать перезапуск: «сам он
// не отключается без /leave». Раньше присутствие жило внутри записи очереди, а та
// стиралась, как только очередь пустела, -- после перезагрузки бот в канал не
// возвращался вообще. Теперь это своя запись (musicState/voice).
// ============================================================================
async function writeVoiceState (guildId, channelId, left)
{
    try
    {
        if (!channelId) { await db (guildId, 'musicState', 'voice', null); return; }
        await db (guildId, 'musicState', 'voice',
            { at: Date.now (), channelId: channelId, left: !!left });
    }
    catch (e) { console.error ('[music] не смог сохранить, где сижу: ' + oneLine (e.message)); }
}

// Где бот сидит ПРЯМО СЕЙЧАС -- по живому соединению. Вызывается при каждом заходе
// и переезде (обёртка над joinVoice); не в канале -- запись стирается.
async function saveVoiceState (guildId)
{
    const m = $music[guildId];
    const chId = (m && m.connection && m.connection.joinConfig)
        ? m.connection.joinConfig.channelId : null;
    await writeVoiceState (guildId, chId, !!(m && m.leftByUser));
}

async function readVoiceState (guildId)
{
    try
    {
        const v = await db (guildId, 'musicState', 'voice');
        return (v && typeof v === 'object' && v.channelId) ? v : null;
    }
    catch (e) { return null; }
}

// Сколько ещё треков в очереди после «текущего» (для красивых строк в логе):
function restCount (m)
{
    return Math.max (0, m.tracks.length - (m.seekTrack ? 1 : 0));
}

// Короткая выжимка очереди с теми же номерами, что в /queue (для ответов вроде /move):
function queuePreview (m, max = 5)
{
    const total = m.tracks.length;
    const list = m.tracks.slice (0, max).map ((t, i) => (i + 1) + '. ' + (t.title || 'трек') + byLabel (t)).join ('\n');
    return '**Очередь (' + total + '):**\n' + list + (total > max ? '\n*...и ещё ' + (total - max) + ' -- /queue*' : '');
}

// ============================================================================
// [v2.14] УПРАВЛЕНИЕ ОЧЕРЕДЬЮ ГЛАЗАМИ DJ: видеть, кто добавил трек, сколько ещё
// ждать до конца плейлиста и листать очередь кнопками.
// ============================================================================

// Сколько ещё ждать до конца очереди: остаток ТЕКУЩЕГО трека (с учётом позиции) плюс
// длительности всех треков в очереди. Эфиры и треки без длины считаем отдельно --
// у них длительности нет и быть не может.
function queueLeft (m)
{
    let sec = 0, unknown = 0, live = 0;
    for (const t of m.tracks)
    {
        if (t.isLive) live++;
        else if (t.duration > 0) sec += t.duration;
        else unknown++;
    }
    let curLeft = 0;
    if (m.current && !m.current.isLive && m.current.duration > 0)
    {
        curLeft = Math.max (0, m.current.duration - Math.floor (playedMsOf (m) / 1000));
        sec += curLeft;
    }
    return { sec, curLeft, unknown, live };
}

// [v2.17-v2.19] Сколько треков на страницу: ключ queue_page в конфиге, по умолчанию 15
// (25 -- максимум ещё и потому, что больше пунктов меню Discord не принимает).
// [v2.19] Сколько треков показывать на странице /queue -- из конфига (queue_page),
// по умолчанию 15. Так надёжнее: длинные названия и длинные ники больше не упирают
// сообщение в лимит Discord (раньше стояло жёсткое 25 и страница то и дело
// обрезалась). 25 -- абсолютный максимум: больше пунктов меню Discord не принимает.
const QUEUE_PAGE_DEFAULT = 15;
const QUEUE_PAGE_MAX = 25;
// Лимит сообщения Discord -- ~2000 символов. Бюджет списка считается от РЕАЛЬНОГО
// текста всего остального (шапка, «до конца очереди», подсказка) и служит ТОЛЬКО
// страховкой: при настройке по умолчанию страница в него влезает с запасом, а если
// названия совсем огромные -- мы сначала укорачиваем их, и только в крайнем случае
// показываем меньше строк (лучше это, чем отказ Discord).
function queuePageSize (m)
{
    const n = Number ((SERVERS[(m && m.guildId) || ''] || {}).queue_page);
    if (!Number.isFinite (n) || n <= 0) return QUEUE_PAGE_DEFAULT;
    return Math.min (QUEUE_PAGE_MAX, Math.max (1, Math.floor (n)));
}
const QUEUE_MSG_LIMIT = 1980;
// Запас на служебные строки: заголовок «Очередь (N)», переводы строк, хвост
// «...и ещё N: /queue from:M» (самая длинная часть -- сам хвост) и РАЗДЕЛИТЕЛИ
// блоков [v2.32] (до трёх линий QSEP по 12 символов).
const QUEUE_GLUE = 150;
// Подсказка внизу. Короткая -- когда очередь не влезла в одну страницу (все действия
// и так есть кнопками), полная -- когда всё видно сразу.
// [v2.32] Визуальный разделитель блоков в сообщении /queue: «Сейчас», «Очередь»,
// «По авторам», «До конца очереди» -- раньше всё сливалось в один поток строк.
const QSEP = '────────────';
// [v2.44] СПРАВОЧНЫЕ БЛОКИ -- МЕЛКИМ ШРИФТОМ (`-#` -- subtext Discord) и СВЕРХУ
// списка. Просьба владельца: «это справка, уменьшить шрифт и поднять выше, чтобы
// видеть треки и кнопки одновременно». Раньше сводки стояли МЕЖДУ списком и кнопками,
// и на длинной очереди приходилось скроллить между треками и элементами управления.
// В subtext кладём ТОЛЬКО простой текст (без `**` и без косых кавычек): так он
// одинаково выглядит в любом клиенте, а не превращается в звёздочки.
const QSMALL = '-# ';
// [v2.53] ПОДСКАЗКА СЕЙЧАС НЕ ПОКАЗЫВАЕТСЯ. Просьба владельца: «подумал, убрать
// этот текст совсем -- выглядит очень ненужным, во всяком случае на данный момент;
// полностью из кода не убирай, может передумаю; даже конфиг не нужен». Поэтому текст
// СОХРАНЁН ниже целиком, а в сообщение его подставляет queueHintText(): вернуть --
// поставить QUEUE_HINT_SHOW = true. Ни ключа в конфиге, ни второй ветки сборки нет --
// бюджет страницы считается по тому же queueHintText (), поэтому список треков просто
// получает освободившееся место, а сообщение остаётся в тех же границах.
const QUEUE_HINT_SHOW = false;
const QUEUE_HINT_SHORT = QSMALL + 'Действия -- кнопками ниже.';
const QUEUE_HINT_FULL =
    QSMALL + 'Перемотать внутри трека -- «◀ 30 с» / «30 с ▶» / «⏱ На таймкод…» или /seek;' +
    ' свой трек (у админов и модеров -- любой).' + '\n' +
    QSMALL + 'Подвинуть -- выбери трек в меню ниже (выше/ниже, в начало, в конец' +
    ' или «На позицию…»), либо командой /move номер to номер.' + '\n' +
    QSMALL + 'Прыгнуть по очереди -- /jump или кнопка «⤴ Перепрыгнуть» (список треков):' +
    ' DJ -- по своим, админы и модеры -- любым.' +
    ' Срочный переход (прерванный трек заиграет следующим, с того же места) либо «Обрезать до трека»' +
    ' (всё до него убрать -- DJ только если всё убираемое его).' + '\n' +
    QSMALL + 'Чистить -- /clear (остаться) или /stop (уйти): спросят подтверждение.' + '\n' +
    QSMALL + 'DJ распоряжается только своими треками (и ставит их только на свои же' +
    ' места), админы и модеры -- любыми.';

// Что именно поставить в сообщение как подсказку (см. QUEUE_HINT_SHOW).
function queueHintText ()
{
    return QUEUE_HINT_SHOW ? QUEUE_HINT_FULL : '';
}

// [v2.28] Сводка ПО АВТОРАМ для /queue: сколько треков и сколько времени у каждого.
// На миксе из нескольких DJ сразу видно, чья это гора; убрать чужое/своё можно через
// «🗑 Удалить треки автора» под очередью [v2.31] или `/clear author:@кто`. Время -- по
// известным длительностям; у эфиров его нет, поэтому они показаны отдельно (🔴), а
// треки без автора (добавлены до v2.31) считаются одной строкой в конце.
function queueAuthorsText (m)
{
    const map = new Map ();
    let noAuthor = 0;
    const add = t =>
    {
        if (!t) return;
        const key = t.byId ? String (t.byId) : '';
        if (!key) { noAuthor++; return; }
        let o = map.get (key);
        if (!o) { o = { name: t.byName || u (key), n: 0, sec: 0, live: 0 }; map.set (key, o); }
        o.n++;
        if (t.isLive) o.live++;
        else if (t.duration > 0) o.sec += t.duration;
    };
    add (m.current);
    for (const t of m.tracks) add (t);
    if (!map.size && !noAuthor) return '';
    const list = [...map.values ()].sort ((a, b) => b.n - a.n || String (a.name).localeCompare (String (b.name)));
    const top = list.slice (0, 6).map (o => o.name + ' — ' + o.n + ' ' +
        plural (o.n, 'трек', 'трека', 'треков') +
        (o.sec ? ' (~' + fmtAgo (o.sec * 1000) + ')' : '') +
        (o.live ? ' + ' + o.live + ' 🔴' : ''));
    return QSMALL + '👥 По авторам: ' + (top.length ? top.join (', ') : 'только треки без автора') +
        (list.length > 6 ? ' и ещё ' + (list.length - 6) + ' ' + plural (list.length - 6, 'автор', 'автора', 'авторов') : '') +
        (noAuthor ? (top.length ? ', ' : '') + 'без автора: ' + noAuthor : '');
}

// [v2.54] СТРОКА «Последние добавления» ИЗ /queue УБРАНА (просьба владельца). Её
// работу забрала команда /history: там те же пачки, но полностью -- и треки, и эфиры,
// и целые плейлисты со составом, и не только из текущей очереди (доигранное и убранное
// тоже), и не 4 огрызка, а MUSIC.history_len пачек. Функция queueAddsText удалена
// вместе со строкой -- её текст есть в истории git (v2.35–v2.53).

// Сколько символов остаётся на СПИСОК: лимит минус шапка, «до конца очереди»,
// подсказка и служебные строки. Считается по живым строкам, поэтому
// бюджет один и тот же при отрисовке страницы и в queuePageOf (один и тот же m).
function queueListBudget (m)
{
    // [v2.44] В бюджете -- ПОЛНАЯ подсказка, а не короткая: она теперь стоит в письме
    // ВСЕГДА (раньше выбиралась по длине, и владелец видел «примечания то есть, то нет»).
    // Не влезает -- укорачивается САМ СПИСОК, а не справка (см. queueView).
    const chrome = queueHeadText (m).length + queueWaitText (m).length +
        queueAuthorsText (m).length + queueCheckText (m).length +
        QUEUE_GLUE + queueHintText ().length;
    // [v2.54] Истории добавлений в /queue больше нет -- её место в бюджете тоже убрано
    // (проверяется стендом: на странице по-прежнему 15 треков).
    return Math.max (200, QUEUE_MSG_LIMIT - chrome);
}

// Строки одной страницы при заданной обрезке названия (titleClip).
// [v2.18] Автор у идущих ПОДРЯД треков одного человека пишется один раз (обычное
// дело -- DJ залил плейлист), смена автора всегда видна.
function queueLines (slice, start, titleClip, m)
{
    const lines = [];
    // [v2.65] У НАЧАТЫХ, НО НЕ ДОИГРАННЫХ ТРЕКОВ ВИДНО МЕСТО: `02:44/03:14`.
    // Позиция берётся из `track.seek` (её кладёт /leave и срочный переход вместе
    // с треком) либо из `m.seekSec`, если это трек, ждущий продолжения (обрыв/пауза).
    // У обычных треков ничего не меняется -- там просто длина.
    const seekOf = t =>
    {
        let at = Number (t && t.seek) || 0;
        if (m && m.seekTrack === t && (Number (m.seekSec) || 0) > at) at = Number (m.seekSec) || 0;
        return Math.max (0, Math.round (at));
    };
    for (let i = 0; i < slice.length; i++)
    {
        const t = slice[i];
        // [v2.32] АВТОР -- У КАЖДОГО ТРЕКА. В v2.31 у соседних треков одного автора ник
        // писался один раз (экономили место), но при листании длинного плейлиста это
        // читалось как «трек ничей»: видно одно «👤 Фантазёр», а рядом пять строк без
        // хозяина. Теперь имя есть всегда (для бюджета сжимаем длинный ник, названия
        // треков при нехватке места всё равно укорачиваются -- треки не выбрасываем).
        // [v2.61] АВТОР -- ССЫЛКОЙ НА ПРОФИЛЬ (упоминание), а не голым ником: по нику
        // нельзя ни написать человеку, ни открыть профиль (просьба владельца). У треков
        // старой базы id нет -- у них остаётся ник. Пингов это не вызывает: сообщение
        // очереди отправляется и правится с allowedMentions: { parse: [] }.
        const byId = byIdOf (t);
        const by = byNameOf (t);
        const label = byId ? ' · ' + u (byId)
            : (by ? ' · 👤 ' + clipText (by, 24) : '');
        // [v2.32] Номер -- в косых кавычках (`12`), а не «12.»: Discord принимает «12.»
        // за начало markdown-СПИСКА и сам переформатирует строки (первый пункт «уезжал»
        // от остальных и в логе, и на экране). В кавычках номер ровный, моноширинный,
        // и рендер его не трогает; нумерацию это не меняет (/remove ждёт те же числа).
        // [v2.43] ⚠ -- трек, который проверка заранее сочла недоступным. Он остаётся
        // в очереди (удаляем только по факту), но человеку видно, что с ним может быть беда.
        const at = seekOf (t);
        const timeTxt = (at >= 1 && t.duration > 0)
            ? fmtDur (Math.min (at, t.duration)) + '/' + fmtDur (t.duration)
            : fmtDur (t.duration, t.isLive);
        lines.push ('`' + (start + i) + '` · ' + (t.warn ? '⚠ ' : '') + '**' +
            clipText (t.title || 'трек', titleClip) + '** `' + timeTxt + '`' + label);
    }
    return lines;
}

function queuePage (m, start)
{
    const total = m.tracks.length;
    const budget = queueListBudget (m);
    const size = queuePageSize (m);
    start = Math.min (Math.max (1, Math.round (start) || 1), Math.max (1, total));
    const slice = m.tracks.slice (start - 1, start - 1 + size);
    // [v2.19] Сначала пытаемся показать ВСЕ треки страницы с полными названиями, а если
    // не влезло в лимит Discord -- укорачиваем названия (не выбрасываем треки):
    // короткое имя с «…» лучше, чем трек, до которого не добраться.
    let lines = null;
    for (const clip of [120, 80, 60, 45, 30, 25, 20])
    {
        lines = queueLines (slice, start, clip, m);
        if (lines.join ('\n').length <= budget) break;
    }
    // Крайняя страховка. Срабатывает только если ОДНОВРЕМЕННО: queue_page выставлен
    // большим (например 25), у ВСЕХ треков страницы длинющие названия И у каждого свой
    // длинный ник (ник Clippом не уменьшаем -- он и есть адресат). Тогда показываем
    // столько, сколько влезло, а хвост сообщения ведёт на реальный следующий номер --
    // трек доступен через /queue from:N, потерянного куска между страницами нет.
    while (lines.length > 1 && lines.join ('\n').length > budget) lines.pop ();
    return { start, total, count: lines.length, list: lines.join ('\n'), size: size };
}

// Кнопки и меню под ответом /queue. Всё состояние -- в самих компонентах (customId),
// поэтому между нажатиями держать ничего не надо.
//   Навигация по плейлисту [v2.31]: «⏮ В начало / ◀ Влево / Вправо ▶ / ⏭ В конец».
//       Шаг равен размеру страницы (queue_page), крайние кнопки гаснут на первой и
//       последней странице (в customId -- ЦЕЛЕВАЯ страница: если страницу срезало по
//       длине, шаг остаётся верным);
//   ⏭ Пропустить / 🧹 Очистить / ⏹ Стоп -- частые действия (оба вида чистки спросят
//       подтверждение и скажут, что именно уйдёт);
//   🗑 Убрать трек -- меню с номерами ТЕКУЩЕЙ страницы (те же номера, что в /remove);
//   🗑 Удалить треки автора [v2.31] -- выбрать автора и убрать всё его сразу;
//   ◀ 30 с / 30 с ▶ [v2.35] -- перемотка внутри ТЕКУЩЕГО трека (та же логика, что
//       у /seek: трек возвращается в очередь с отметкой секунды). У прямого эфира
//       позиции нет -- кнопки погашены;
//   🗂 Трек: подвинуть или убрать… [v2.35; порядок слов с v2.66 -- просьба владельца:
//     «подвинуть или убрать смотрится лучше», главное действие первым] -- ОДИН список
//     треков текущей страницы.
//       Раньше рядом стояли два меню с одними и теми же номерами (одно убирало
//       сразу, второе начинало перестановку) и занимали два ряда из пяти. Выбрал
//       трек -- появляются «🗑 Убрать» / «⬆ Выше» / «⬇ Ниже» / «✖ Готово» [v2.17].
// Права проверяются при нажатии: сообщение очереди видит весь канал, а действия -- DJ.
// [v2.31] DJ распоряжается только СВОИМИ записями (staff -- любыми), поэтому в меню
// ему попадают только его треки, а в выборе авторов -- только он сам.
// На какой странице окажется номер n (страницы бывают короче queue_page -- если названия
// срезали список по длине). Идём теми же шагами, что и листание, поэтому трек
// после перестановки виден там, куда ведёт страница, а не «между страницами».
function queuePageOf (m, n)
{
    let start = 1;
    for (let guard = 0; guard < 2000; guard++)
    {
        const p = queuePage (m, start);
        if (!p.count) return 1;
        if (n <= p.start + p.count - 1) return p.start;
        start = p.start + p.count;
    }
    return 1;
}

// Начало последней страницы -- для кнопки «⏭ В конец» (страницы бывают короче
// queue_page из-за длинных названий, поэтому идём теми же шагами, что листание).
function queueLastStart (m)
{
    let start = 1;
    for (let guard = 0; guard < 2000; guard++)
    {
        const p = queuePage (m, start);
        if (!p.count) return 1;
        const next = p.start + p.count;
        if (next > p.total) return p.start;
        start = next;
    }
    return 1;
}

function queueComponents (page, m, moveSel = 0, opts = {})
{
    const { start, total, count } = page;
    const actorId = opts.actorId || '';
    const staff = !!opts.staff;
    // [v2.31] чем вызывающий вправе распорядиться (DJ -- только своими записями)
    const mine = t => staff || isBy (t, actorId);
    // [v2.49] «Вправо» идёт на start + count, «Влево» -- на start - size. Это НЕ
    // произвол: страница может оказаться короче queue_page (названия срезали список),
    // и тогда вперёд нужно шагать ровно на число ПОКАЗАННЫХ строк -- иначе треки между
    // start+count и start+size не увидит ни одна страница (тем же правилом идут
    // queuePageOf, queueLastStart и хвост «...и ещё N» в queueView). Назад шаг в size
    // безопасен: он не больше любой страницы, поэтому ничего не пропускает (в худшем
    // случае страница повторится). Разъедутся эти два числа -- и часть очереди
    // станет недоступной, так что менять что-то одно нельзя.
    const step = page.size || count || 1;
    const rows = [];
    // [v2.55] «🔄 Обновить» -- перерисовать это сообщение из ЖИВОЙ очереди, не листая
    // (просьба владельца: «список обновляется только когда я по нему перемещаюсь»).
    // Discord перерисовывает сообщение только по нажатию, поэтому без такой кнопки текст
    // (что играет, сколько ждать, кто сколько поставил) застывал на моменте, когда /queue
    // вызвали. Стоит МЕЖДУ «◀ Влево» и «Вправо ▶» -- как «обновить» в навигации.
    const refreshBtn = at => new ButtonBuilder ()
        .setCustomId ('q:rf:' + at).setLabel ('🔄 Обновить').setStyle (ButtonStyle.Secondary);
    if (total > 0)
    {
        const atEnd = (start + count) > total;
        // [v2.32] В customId -- не только целевая страница, но и САМА КНОПКА
        // (q:p:first / q:p:prev / q:n:next / q:n:last). Раньше было просто «q:p:страница»,
        // и на первой странице «В начало» и «Влево» давали ОДИН customId (как и
        // «Вправо» с «В конец» на последней) -- Discord отбивал всё сообщение:
        // COMPONENT_CUSTOM_ID_DUPLICATED, и `/queue` не открывался вовсе.
        rows.push
        (
            new ActionRowBuilder ().addComponents
            (
                new ButtonBuilder ()
                    .setCustomId ('q:p:first:1').setLabel ('⏮ В начало')
                    .setStyle (ButtonStyle.Secondary).setDisabled (start <= 1),
                new ButtonBuilder ()
                    .setCustomId ('q:p:prev:' + Math.max (1, start - step)).setLabel ('◀ Влево')
                    .setStyle (ButtonStyle.Secondary).setDisabled (start <= 1),
                // [v2.55] -- и это ПЯТАЯ кнопка ряда: больше пяти Discord не принимает,
                // поэтому «Обновить» встало именно здесь, а не отдельным рядом.
                refreshBtn (start),
                new ButtonBuilder ()
                    .setCustomId ('q:n:next:' + (start + count)).setLabel ('Вправо ▶')
                    .setStyle (ButtonStyle.Secondary).setDisabled (atEnd),
                new ButtonBuilder ()
                    .setCustomId ('q:n:last:' + queueLastStart (m)).setLabel ('В конец ⏭')
                    .setStyle (ButtonStyle.Secondary).setDisabled (atEnd)
            )
        );
    }
    else
    {
        // [v2.55] Очередь пуста, а играть может быть что есть (играет последний трек
        // очереди, /clear, доигранное) -- «Обновить» нужно и здесь: шапка («сейчас»,
        // слушатели, где пою) застывает так же. Ряд из одной кнопки -- лимит в пять
        // рядов при этом не трогается.
        rows.push (new ActionRowBuilder ().addComponents (refreshBtn (1)));
    }
    // [v2.35] РЯДЫ ПЕРЕСОБРАНЫ ПОД ЖЁСТКИЙ ЛИМИТ DISCORD (не больше пяти). До этого
    // в ряду действий стояли пять кнопок (пропуск, вход, выход, чистка, стоп/выход) --
    // для перемотки ±30 с там места не было, а убирать что-то из них нельзя.
    // [v2.44] ЛИМИТ -- ПЯТЬ РЯДОВ И ПЯТЬ КНОПОК В РЯДУ, и он тут вплотную:
    //   [1] листание (4)
    //   [2] ИГРАЮЩИЙ ТРЕК: ◀ 30 с / 30 с ▶ / ⏱ На таймкод… / ⏭ Пропустить (4)
    //   [3] канал и чистка: ▶ Войти / ⏏ Выйти / 🧹 Очистить / 🧹⏏ Очистка/Выход (4)
    //   [4] список треков, [5] меню автора.
    // Так «⏱ На таймкод…» (просьба владельца) получил своё место, а листание и меню
    // автора остались на виду: раньше при шестом ряде Discord молча выбрасывал последний.
    //   * [v2.46] «⏭ Пропустить» переехал сюда же: это тоже действие с ИГРАЮЩИМ треком,
    //     и вместе с перемоткой ряд читается как «что делать с тем, что звучит сейчас».
    //     ВНУТРЬ блока «🎵 Сейчас:» кнопку положить нельзя -- Discord рисует ряды кнопок
    //     только ПОД всем текстом сообщения, между строк их вставить нечем (ограничение
    //     самого Discord, а не наше).
    //   * «Войти» -- /join (зайти и остаться), «Выйти» -- /leave (отложить СВОИ треки
    //     и играть дальше), а «Очистка/Выход» -- /stop (/clear + /leave).
    const liveNoSeek = !m.current || m.current.isLive;
    rows.push
    (
        new ActionRowBuilder ().addComponents
        (
            new ButtonBuilder ()
                .setCustomId ('q:s:m').setLabel ('◀ 30 с').setStyle (ButtonStyle.Secondary)
                .setDisabled (liveNoSeek),
            new ButtonBuilder ()
                .setCustomId ('q:s:p').setLabel ('30 с ▶').setStyle (ButtonStyle.Secondary)
                .setDisabled (liveNoSeek),
            // [v2.44] Точное место -- окном ввода, совсем как «#️⃣ На позицию…» у трека
            // в очереди: та же логика перемотки, что у /seek (см. seekMusic).
            new ButtonBuilder ()
                .setCustomId ('q:sk:' + start).setLabel ('⏱ На таймкод…').setStyle (ButtonStyle.Secondary)
                .setDisabled (liveNoSeek),
            // [v2.46] «⏭ Пропустить» -- сюда же: это действие с играющим треком.
            new ButtonBuilder ()
                .setCustomId ('q:skip').setLabel ('⏭ Пропустить').setStyle (ButtonStyle.Secondary)
                .setDisabled (!m.current)
        )
    );
    // [v2.62] «⤴ Перепрыгнуть» (v2.65 -- стрелка вместо ⏭, чтобы не путать с «⏭ Пропустить»)
    // -- /jump прямо из очереди (окно ввода номера -> подтверждение
    // варианта). Доступно и обычному DJ (по своим трекам -- см. jumpGuard). Встало в этот
    // ряд (перед «▶ Войти») -- пятая кнопка в ряду, лимит Discord ровно пять.
    // «▶ Войти» сменил зелёный на нейтральный: зелёный в боте значит «подтверждаю/ок», а
    // вход/выход -- обычное перемещение, и в ряду он смотрелся чужеродно.
    rows.push
    (
        new ActionRowBuilder ().addComponents
        (
            new ButtonBuilder ()
                .setCustomId ('q:jmp').setLabel ('⤴ Перепрыгнуть').setStyle (ButtonStyle.Secondary)
                .setDisabled (!total),
            new ButtonBuilder ()
                .setCustomId ('q:join').setLabel ('▶ Войти').setStyle (ButtonStyle.Secondary),
            new ButtonBuilder ()
                .setCustomId ('q:leave').setLabel ('⏏ Выйти').setStyle (ButtonStyle.Secondary),
            new ButtonBuilder ()
                .setCustomId ('q:clear').setLabel ('🧹 Очистить').setStyle (ButtonStyle.Danger)
                .setDisabled (!total && !m.current),
            new ButtonBuilder ()
                .setCustomId ('q:stop').setLabel ('🧹⏏ Очистка/Выход').setStyle (ButtonStyle.Danger)
                .setDisabled (!total && !m.current && !m.connection)
        )
    );
    if (count && !moveSel)
    {
        // [v2.35] ОДИН СПИСОК ТРЕКОВ ВМЕСТО ДВУХ. Раньше рядом стояли два меню с
        // ОДНИМИ И ТЕМИ ЖЕ номерами («🗑 Убрать трек» -- убирало сразу, «🎚 Двигать трек»
        // -- начинало перестановку): два ряда только ради выбора трека. Теперь выбор
        // один, а действия (убрать / выше / ниже) появляются кнопками ПОСЛЕ выбора -- это
        // и освободило ряд для перемотки ±30 с при лимите Discord в пять рядов.
        const opts = [];
        for (let i = 0; i < count; i++)
        {
            const n = start + i;
            const t = m.tracks[n - 1];
            if (!t || !mine (t)) continue; // чужое меню DJ не показывает вовсе
            // label -- до 100 символов (лимит Discord), в value -- номер как в /queue:
            opts.push ({ label: ('№' + n + ' · ' + (t.title || 'трек')).slice (0, 100),
                         value: String (n), default: n === moveSel });
        }
        if (opts.length)
        {
            const tr = new StringSelectMenuBuilder ()
                .setCustomId ('q:tr:' + start)
                .setPlaceholder (moveSel ? ('№' + moveSel + ' выбран -- или выбери другой')
                                         : (staff ? '🗂 Трек: подвинуть или убрать…' : '🗂 Свой трек: подвинуть или убрать…'));
            tr.addOptions (opts);
            rows.push (new ActionRowBuilder ().addComponents (tr));
        }
    }
    // [v2.32] МЕНЮ АВТОРА -- ДЛЯ ВСЕХ, а права проверяются при действии. Так видно,
    // ЧТО вообще можно (и почему нельзя, если нельзя): выбрать автора и получить
    // подтверждение с описанием того, что произойдёт. В режиме перестановки ряд скрыт:
    // рядов компонентов не может быть больше пяти.
    if (!moveSel)
    {
        // value не может быть пустым (Discord такое меню отвергает), поэтому ничьи
        // треки (из старых баз) идут со значением '0' -- снежинкой такой id быть не
        // может, а в обработчике '0' снова читается как «без автора».
        const authorOpts = queueAuthorList (m, actorId, true).map (o =>
        ({
            label: ('👤 ' + o.name).slice (0, 100),
            description: o.n + ' ' + plural (o.n, 'трек', 'трека', 'треков') +
                (o.id === String (actorId) ? ' (твои)' : ''),
            value: (o.id || '0'),
        }));
        if (authorOpts.length)
        {
            const da = new StringSelectMenuBuilder ()
                .setCustomId ('q:da')
                .setPlaceholder ('👤 Автор: поднять или убрать…');
            da.addOptions (authorOpts.slice (0, 25));
            rows.push (new ActionRowBuilder ().addComponents (da));
        }
    }
    // [v2.36] ДЕЙСТВИЯ ВЫБРАННОГО ТРЕКА -- ДВЕ СТРОКИ. Раньше можно было только «выше /
    // ниже»: перетащить сороковой трек в начало -- сорок нажатий. Теперь сразу видно
    // «в начало», «в конец» и «на позицию» (точный номер -- окном ввода).
    // [v2.38] ПОКА ДВИГАЕМ -- ТОЛЬКО КНОПКИ ПЕРЕНОСА (просьба владельца: «выводит
    // слишком много кнопок»). Раньше сверху оставались ещё листание, перемотка,
    // вход/выход и чистка, а сами кнопки переноса уезжали в самый низ. Теперь остаются
    // ровно два ряда: что сделать с выбранным треком и «✖ Вернуться» -- назад к обычным
    // кнопкам очереди. Какой трек выбран -- сказано в самом сообщении.
    if (moveSel >= 1 && moveSel <= total)
    {
        rows.length = 0; // ничего лишнего: в режиме переноса -- только перенос
        rows.push
        (
            new ActionRowBuilder ().addComponents
            (
                // [v2.35] Убрать выбранный трек -- отсюда же, где его двигают:
                // раньше для этого надо было лезть в отдельное меню.
                new ButtonBuilder ()
                    .setCustomId ('q:rx:' + moveSel + ':' + start).setLabel ('🗑 Убрать')
                    .setStyle (ButtonStyle.Danger),
                new ButtonBuilder ()
                    .setCustomId ('q:mt:' + moveSel).setLabel ('⏫ В начало')
                    .setStyle (ButtonStyle.Primary).setDisabled (moveSel <= 1),
                new ButtonBuilder ()
                    .setCustomId ('q:mb:' + moveSel).setLabel ('⏬ В конец')
                    .setStyle (ButtonStyle.Primary).setDisabled (moveSel >= total),
                new ButtonBuilder ()
                    .setCustomId ('q:mp:' + moveSel).setLabel ('#️⃣ На позицию…')
                    .setStyle (ButtonStyle.Secondary)
            )
        );
        rows.push
        (
            new ActionRowBuilder ().addComponents
            (
                new ButtonBuilder ()
                    .setCustomId ('q:mu:' + moveSel).setLabel ('⬆ Выше')
                    .setStyle (ButtonStyle.Primary).setDisabled (moveSel <= 1),
                new ButtonBuilder ()
                    .setCustomId ('q:md:' + moveSel).setLabel ('⬇ Ниже')
                    .setStyle (ButtonStyle.Primary).setDisabled (moveSel >= total),
                new ButtonBuilder ()
                    .setCustomId ('q:mx:' + start).setLabel ('✖ Вернуться')
                    .setStyle (ButtonStyle.Secondary)
            )
        );
    }
    return rows.slice (0, 5); // лимит Discord: не больше пяти рядов
}

// ============================================================================
// [v2.15] ЧАСТЫЕ ДЕЙСТВИЯ С ОЧЕРЕДЬЮ: одна логика на слэш-команду и на кнопки/меню
// под /queue (иначе ответы и лог со временем разъехались бы). Возвращают
// { ok, text }: ok = действие выполнено (ответ можно показывать всем), иначе
// причина (её показываем только нажавшему). В лог идёт авторство -- видно, кто убрал.
// ============================================================================
function queueSkip (guildId, who, opts = {})
{
    const m = musicOf (guildId);
    if (!m.current) return { ok: false, text: '🤷 Сейчас ничего не играет.' };
    // [v2.53] ПРОПУСК -- ТОЛЬКО ПО СВОЕМУ ТРЕКУ. То же правило, что у перемотки (v2.50):
    // пропустить чужую песню -- это не «перемотать», а выбросить её из эфира совсем,
    // и раньше её мог выбросить любой DJ (владелец: «и пропускать трек без нужных прав
    // нельзя»). Свой трек пропускает его автор, а любой -- админы и модеры; трек без
    // автора (из старой базы) -- ничей, его пропускает тот, кому он играет.
    if (!opts.staff && byIdOf (m.current) && !isBy (m.current, opts.actorId))
        return { ok: false, text: ownOnlyText ('Пропустить', m.current) };
    const skipped = m.current.title || 'трек';
    m.skipRequested = true; // [v2.30] это осознанный пропуск, а не обрыв потока:
                            // Idle-обработчик не должен возвращать трек в очередь
    m.player.stop (true); // Idle-хэндлер запустит следующий (он же выставит m.current)
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'пропустил: ' + skipped);
    return { ok: true, text: '⏭ Пропущено: **' + skipped + '**' +
        (m.current ? ' -- играю **' + (m.current.title || 'трек') + '**' : '') };
}

// [v2.26] Очистка -- это очистка: убираем И то, что играет. Раньше текущий трек молча
// доигрывал, и получалось «ничейно»: очередь пуста, а музыка ещё играет то, что из неё
// убрали (а длинные сеты так и вовсе приходилось добивать /stop).
// [v2.28] Теперь чистка общая (queueWipe), а вот /clear и /stop разведены по смыслу:
//   /clear -- «остаться и забыть»: очередь и музыка стёрты, бот ОСТАЁТСЯ в канале;
//   /stop  -- «уйти и забыть»: то же плюс выход из голосового канала.
// Состояние в базе стирается в обоих случаях -- чтобы после перезапуска ничего из
// убранного не воскресло.
function queueWipe (guildId)
{
    const m = musicOf (guildId);
    const w =
    {
        n: m.tracks.length,
        playing: m.current ? (m.current.title || 'трек') : '',
        waiting: (!m.current && m.seekTrack) ? (m.seekTrack.title || 'трек') : '',
    };
    m.tracks = [];
    m.current = null;
    m.seekTrack = null;
    m.seekSec = 0;
    m.pending = false;
    m.pausedByNobody = false;
    m.playedToSomeone = false; // очередь стёрта осознанно -- не пишем «доиграна до конца»
    m.playedMs = 0;
    m.playingSince = null;
    dropPreload (m);
    m.player.stop (true);     // тишина: играть больше нечего (Idle-хэндлер запустит нечего)
    clearMusicState (guildId); // и из базы -- чтобы убранное не воскресло после перезапуска
    cacheDropUnused (); // [v2.39] очередь стёрта -- и кэш тоже: играть больше нечего
    return w;
}

// [v2.31] УБРАТЬ ЧАСТЬ ОЧЕРЕДИ ПО ОДНОМУ ПРИЗНАКУ (свои записи, треки одного автора).
// Одна реализация на все входы (слэш-команды, кнопка «Очистить», меню «Удалить треки
// автора») -- иначе ответы и лог со временем разъехались бы.
// keep -- предикат: трек остаётся, если он истинен. Играющий и ждущий тоже попадают
// под правило: уходит -- прерывается, а не доигрывается «ничейным».
// Возвращает null, если убирать нечего; иначе -- что именно ушло.
function queuePurge (guildId, keep)
{
    const m = musicOf (guildId);
    const goneQ = m.tracks.filter (t => !keep (t)).length;
    const playing = (m.current && !keep (m.current)) ? (m.current.title || 'трек') : '';
    const waiting = (!playing && m.seekTrack && !keep (m.seekTrack)) ? (m.seekTrack.title || 'трек') : '';
    if (!goneQ && !playing && !waiting) return null; // нечего убирать
    m.tracks = m.tracks.filter (keep);
    if (waiting) { m.seekTrack = null; m.seekSec = 0; }
    if (playing)
    {
        m.current = null;      // чтобы база не сохранила снятый трек как играющий
        m.playedMs = 0;
        m.playingSince = null;
        m.player.stop (true);  // Idle-хэндлер сразу запустит следующий (если есть)
    }
    // очередь опустела совсем -- помнить нечего (как и у полной чистки)
    if (!m.tracks.length && !m.current && !m.seekTrack)
    {
        m.pending = false;
        clearMusicState (guildId);
        cacheDropUnused (); // [v2.39] убирать больше нечего -- чистим и кэш
    }
    else saveMusicState (guildId);
    dropPreload (m);
    startPreload (guildId);
    scheduleVoiceStatus (guildId, true);
    schedulePresence (true);
    return { goneQ: goneQ, playing: playing, waiting: waiting, left: m.tracks.length };
}

// [v2.31] Один и тот же понятный отказ там, где DJ пытается тронуть чужую запись.
function ownOnlyText (action, track)
{
    return '🚫 ' + action + ' -- только свои записи: этот трек добавил ' +
        (byIdOf (track) ? byNameOf (track) : 'неизвестный автор (трек из старой базы)') + '.\n' +
        '_Так очередь остаётся общей, а распоряжается каждый своим. Админы и модеры могут всё._';
}

// [v2.31] ЧТО ИМЕННО УЙДЁТ при чистке -- и для подтверждения, и для ответа, и для лога.
// scope 'own' -- только записи этого человека, 'all' -- вся очередь (только staff).
function queueClearPlan (m, actorId, scope)
{
    const all = (scope === 'all');
    const hit = t => !!t && (all || isBy (t, actorId));
    const n = m.tracks.filter (hit).length;
    const playing = (m.current && hit (m.current)) ? m.current : null;
    const waiting = (!m.current && m.seekTrack && hit (m.seekTrack)) ? m.seekTrack : null;
    return {
        all: all, n: n, playing: playing, waiting: waiting,
        left: m.tracks.length - n,                              // останется в очереди
        any: !!(n || playing || waiting),
        ownN: m.tracks.filter (t => isBy (t, actorId)).length,  // для выбора «только свои»
        ownPlaying: !!(m.current && isBy (m.current, actorId)),
        total: m.tracks.length,
    };
}

// [v2.31] Убрать из очереди треки одного автора (targetId = '' -- ничьи, из старых баз).
// Общая логика для `/clear author:@кто` и для меню «🗑 Удалить треки автора».
function queueClearAuthor (guildId, targetId, who)
{
    const target = String (targetId === undefined || targetId === null ? '' : targetId);
    const hit = t => !!t && byIdOf (t) === target;
    const m = musicOf (guildId);
    const canSee = m.tracks.some (hit) || hit (m.current) || hit (m.seekTrack);
    if (!canSee)
        return { ok: false, text: target
            ? '🈳 Нет ни треков от ' + u (target) + ', ни его играющего -- удалять нечего.'
            : '🈳 Треков без автора в очереди нет -- удалять нечего.' };
    const w = queuePurge (guildId, t => !hit (t));
    if (!w) return { ok: false, text: '🈳 Удалять нечего.' };
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'убрал из очереди треки ' +
        (target ? u (target) : 'без автора') + ' (' + w.goneQ + ')' +
        (w.playing ? ' -- и прервал его играющий трек' : (w.waiting ? ' -- и его ждущий трек' : '')));
    return {
        ok: true,
        text: '🧹 Убрал ' + w.goneQ + ' ' + plural (w.goneQ, 'трек', 'трека', 'треков') +
            (target ? ' от ' + u (target) : ' без автора') +
            ' (в очереди осталось ' + w.left + ').' +
            (w.playing ? ' **' + w.playing + '** прервал -- играю следующий.' : '') +
            (w.waiting ? ' Ждущий **' + w.waiting + '** тоже убран.' : ''),
    };
}

// [v2.31] Подтверждение чистки: в нём видно, ЧТО именно уйдёт. Обычный DJ распоряжается
// только своими записями, поэтому выбора у него нет; админы/модеры могут выбрать
// «только свои» или «всю очередь» -- кнопки появляются по правам.
function queueClearConfirm (m, actorId, staff, opts = {})
{
    const leave = !!opts.leave;
    const own = queueClearPlan (m, actorId, 'own');
    const all = queueClearPlan (m, actorId, 'all');
    const amounts = plan =>
    {
        const p = [];
        if (plan.n) p.push (plan.n + ' ' + plural (plan.n, 'трек', 'трека', 'треков') + ' из очереди');
        if (plan.playing) p.push ('играющий **' + (plan.playing.title || 'трек') + '**');
        if (!plan.playing && plan.waiting) p.push ('ждущий **' + (plan.waiting.title || 'трек') + '**');
        return p.length ? p.join (' + ') : 'нечего';
    };
    const msgId = opts.msgId || '0';
    const cancel = new ButtonBuilder ()
        .setCustomId ('q:cq:x').setLabel ('✖ Отмена').setStyle (ButtonStyle.Secondary);
    if (!staff)
    {
        if (!own.any)
        {
            const empty = !m.tracks.length && !m.current && !m.seekTrack;
            const noAuth = m.tracks.filter (t => !byIdOf (t)).length;
            return {
                text: (empty ? '🈳 Очередь и так пуста -- чистить нечего.'
                             : '🈳 Своих треков в очереди нет -- убирать нечего.') +
                    (m.tracks.length ? '\nВ очереди ' + m.tracks.length + ' ' +
                        plural (m.tracks.length, 'чужой трек', 'чужих трека', 'чужих треков') +
                        ' -- ими распоряжаются админы и модеры' +
                        (noAuth ? '; у ' + noAuth + ' автор не записан (треки из старой базы) -- это тоже не моё' : '') + '.' : '') +
                    (leave && m.connection ? '\n_Вывести бота без чистки чужого -- `/leave` (очередь останется)._'
                                           : (leave ? '' : '\n_Выйти из канала можно командой `/leave`._')),
                rows: [new ActionRowBuilder ().addComponents (cancel)],
            };
        }
        const ownTotal = own.n + (own.playing ? 1 : 0) + (own.waiting ? 1 : 0);
        const rows = [new ActionRowBuilder ().addComponents
        (
            new ButtonBuilder ().setCustomId ('q:cq:own:' + msgId)
                .setLabel ('✅ Да, убрать: ' + plural (ownTotal, 'свой трек', 'своих трека', 'своих треков'))
                .setStyle (ButtonStyle.Danger),
            cancel
        )];
        return {
            text: (leave ? '⏹ Остановить музыку и убрать' : '🧹 Убрать') + ' **только свои** записи?\n' +
                '• уйдёт: ' + amounts (own) + '\n' +
                (own.left || (m.current && !own.playing)
                    ? 'Чужое останется: ' + (own.left ? own.left + ' ' + plural (own.left, 'трек', 'трека', 'треков') + ' в очереди' : 'играющий трек') +
                      (leave ? ' -- музыку не выключу и из канала не уйду.' : ' -- их не трогаю.')
                    : (leave ? 'Очередь станет пустой -- остановлю музыку и выйду из канала.'
                             : 'Очередь станет пустой -- будет тишина, из канала не уйду.')),
            rows: rows,
        };
    }
    // staff: выбор из двух вариантов (в customId -- id сообщения очереди, чтобы обновить список)
    const rows = [new ActionRowBuilder ().addComponents
    (
        new ButtonBuilder ().setCustomId ('q:cq:own:' + msgId).setLabel ('✅ Только мои')
            .setStyle (ButtonStyle.Secondary).setDisabled (!own.any),
        new ButtonBuilder ().setCustomId ('q:cq:all:' + msgId)
            .setLabel ('✅ Всю (' + (all.n + (all.playing ? 1 : 0)) + ')').setStyle (ButtonStyle.Danger),
        cancel
    )];
    return {
        text: (leave ? '⏹ **Стоп**: что убрать?' : '🧹 **Что убрать?**') + '\n' +
            '• **Только мои** -- ' + (own.any ? amounts (own) : 'нечего') + '\n' +
            '• **Вся очередь** -- ' + amounts (all) + '\n' +
            (leave ? '_Если после этого останутся чужие треки -- музыку не выключу и из канала не уйду._'
                   : '_Бот останется в канале -- уйти совсем: `⏹ Стоп` (или `/stop`)._'),
        rows: rows,
    };
}

// ============================================================================
// [v2.61] /jump -- ДВА ВАРИАНТА ПЕРЕХОДА, и логика одна на слэш-команду и на кнопки
// подтверждения (чтобы поведение не разъезжалось, как уже бывало с подсказками).
//   * urgent (по умолчанию) -- СРОЧНЫЙ ПЕРЕХОД: цель играет сразу, а прерванный трек
//     встаёт В НАЧАЛО оставшейся очереди -- то есть заиграет СЛЕДУЮЩИМ, с того же
//     места. Раньше он уезжал в КОНЕЦ, хотя владелец просил именно «следующим».
//     То, что стояло до цели, отправляется в конец (ничего не выбрасывается).
//   * cut -- ОБРЕЗАТЬ ДО ТРЕКА: всё до цели и прерванный убираются насовсем (это
//     и есть чистка одним движением -- поэтому только staff).
// ============================================================================
// [v2.62] ПРАВА НА ПРЫЖОК: staff -- любой трек и любой режим; обычный DJ -- только по
// СВОИМ правилам (то же «своё/чужое», что у /skip, /move и перемотки): цель должна быть
// его, «обрезать» можно только если всё убираемое тоже его, а срочно перебить ЧУЖОЙ
// играющий трек нельзя (иначе прыжок стал бы обходом правила «чужое не пропускать»).
function jumpGuard (m, n, cut, opts)
{
    const staff = !!(opts && opts.staff);
    const actorId = (opts && opts.actorId) ? String (opts.actorId) : '';
    if (staff) return null;
    const target = m.tracks[n - 1];
    if (!target || !isBy (target, actorId))
        return '🚫 **Прыгнуть можно только к своему треку** -- этот добавил ' +
            (byIdOf (target) ? u (byIdOf (target)) : 'не ты') + '.\n' +
            '_Свой трек поднять -- «⬆ Поднять» в меню автора; чужой пропускают только админы и модеры._';
    if (cut)
    {
        const gone = m.tracks.slice (0, n - 1).concat (m.current ? [m.current] : []);
        const foe = gone.find (t => !isBy (t, actorId));
        if (foe)
            return '🚫 **Обрезать очередь может только админ/модер** -- перед №' + n +
                ' есть чужие треки (' + (byIdOf (foe) ? u (byIdOf (foe)) : 'без автора') + ').\n' +
                '_Обычному DJ остаётся «Срочный переход»: он ничего не теряет._';
    }
    if (!cut && m.current && !isBy (m.current, actorId))
        return '🚫 **Сейчас играет чужой трек** -- срочный переход его перебьёт, а это могут только админы и модеры.\n' +
            '_Дождись конца или попроси «⬆ Поднять» свой трек._';
    return null;
}

function jumpMusic (guildId, n, cut, opts = {})
{
    const m = $music[guildId];
    if (!m || !m.tracks.length || !Number.isInteger (n) || n < 1 || n > m.tracks.length)
        return {
            ok: false,
            text: (m && m.tracks.length)
                ? '🤔 В очереди ' + m.tracks.length + ' треков -- номер от 1 до ' + m.tracks.length + '.'
                : '🈳 В очереди нет треков (играет только текущий).',
        };
    const denied = jumpGuard (m, n, cut, opts);
    if (denied) return { ok: false, text: denied };
    if (cut)
    {
        const gone = m.tracks.splice (0, n - 1);
        const wasCut = m.current;
        dropPreload (m);
        const targetCut = m.tracks[0];
        const cutTxt = (gone.length ? gone.length + ' ' + plural (gone.length, 'трек', 'трека', 'треков') + ' до него' : '') +
            (gone.length && wasCut ? ' и ' : '') + (wasCut ? 'прерванный **' + (wasCut.title || 'трек') + '**' : '');
        console.log ('[' + (d()) + '] [music] обрезал очередь до №' + n + ': ' + (targetCut.title || 'трек') +
            (cutTxt ? ' (убрано насовсем: ' + cutTxt + ')' : ''));
        if (wasCut) { m.skipRequested = true; m.player.stop (true); }
        else playNext (guildId);
        return {
            ok: true,
            text: '✂ Обрезал до №' + n + ': **' + (targetCut.title || 'трек') + '**' +
                (cutTxt ? '\n_Убрано насовсем: ' + cutTxt + '._' : ''),
        };
    }
    // [v2.63] СРОЧНЫЙ ПЕРЕХОД ТРОГАЕТ РОВНО ДВА ТРЕКА (уточнение владельца):
    //   * выбранный становится ТЕКУЩИМ (уходит из очереди);
    //   * играющий -- СЛЕДУЮЩИМ (встаёт первым в очереди, со своим местом).
    // Всё остальное ОСТАЁТСЯ НА СВОИХ МЕСТАХ. Раньше «то, что стояло до цели», уезжало
    // в конец, и порядок ломался без нужды -- теперь не двигаем ничего лишнего.
    const was = m.current;                       // что играло -- его не выбрасываем
    const wasAt = was ? Math.max (0, Math.round (playedMsOf (m) / 1000)) : 0;
    const target = m.tracks.splice (n - 1, 1)[0]; // цель вынимаем из её места
    m.tracks.unshift (target);                    // и ставим первой: playNext возьмёт её как текущую
    if (was)
    {
        was.seek = wasAt;
        m.tracks.splice (1, 0, was);              // играющий -- следующим, с того же места
    }
    dropPreload (m);                              // заготовка была для прежнего первого
    console.log ('[' + (d()) + '] [music] срочный переход к №' + n + ': ' + (target.title || 'трек') +
        (was ? ' (прерванный ' + (was.title || 'трек') + ' -- следующим, с ' + fmtDur (wasAt) + ')' : '') +
        ' (остальная очередь не двигалась)');
    if (was) { m.skipRequested = true; m.player.stop (true); } // Idle-хэндлер запустит цель
    else playNext (guildId);
    return {
        ok: true,
        text: '⤴ Перехожу к №' + n + ': **' + (target.title || 'трек') + '**' +
            (was ? '\n_Прерванный трек заиграет следующим, с ' + fmtDur (wasAt) + '._' : '') +
            (m.tracks.length > (was ? 2 : 1)
                ? '\n_Тронул только эти два трека -- остальная очередь стоит как стояла._' : '') +
            '\n_Убрать всё до него насовсем -- вариант «Обрезать до трека»._',
    };
}

// Подтверждение выбора, когда вариант в команде не указан: «срочно» и «обрезать»
// -- это разные последствия (одно ничего не теряет, второе чистит), поэтому спрашиваем.
function jumpConfirm (n)
{
    const cancel = new ButtonBuilder ()
        .setCustomId ('q:jp:x').setLabel ('✖ Отмена').setStyle (ButtonStyle.Secondary);
    return {
        text: '⤴ **Перейти к №' + n + '?** Что сделать с тем, что стоит до него:\n' +
            '• **Срочный переход** -- цель играет сразу, а прерванный трек встанет **следующим** (с того же места). Тронем только эти два трека: остальная очередь останется как стояла.\n' +
            '• **Обрезать до трека** -- всё до цели (и прерванный) уйдёт **насовсем**.',
        rows: [new ActionRowBuilder ().addComponents
        (
            new ButtonBuilder ().setCustomId ('q:jp:u:' + n).setLabel ('⤴ Срочный переход').setStyle (ButtonStyle.Primary),
            new ButtonBuilder ().setCustomId ('q:jp:c:' + n).setLabel ('✂ Обрезать до трека').setStyle (ButtonStyle.Danger),
            cancel
        )],
    };
}

// [v2.66] СПИСОК ТРЕКОВ ДЛЯ «ПЕРЕПРЫГНУТЬ» -- вместо окна с номером (просьба владельца:
// «в перепрыгнуть вместо номера выводится список треков, и нашим и вашим»). Номера --
// те же, что в /queue. Обычному DJ показываем только его треки (jumpGuard всё равно
// откажет по чужому), staff -- любые; не больше 25 -- лимит меню Discord.
function jumpPickerRows (m, actorId, staff)
{
    const opts = [];
    for (let i = 0; i < m.tracks.length && opts.length < 25; i++)
    {
        const t = m.tracks[i];
        if (!t) continue;
        if (!staff && !isBy (t, actorId)) continue;
        opts.push ({ label: ('№' + (i + 1) + ' · ' + (t.title || 'трек')).slice (0, 100), value: String (i + 1) });
    }
    if (!opts.length) return null;
    const sel = new StringSelectMenuBuilder ()
        .setCustomId ('q:jsel')
        .setPlaceholder (staff ? '⤴ Перепрыгнуть к треку…' : '⤴ Перепрыгнуть к своему треку…');
    sel.addOptions (opts);
    return [new ActionRowBuilder ().addComponents (sel)];
}

function queueClear (guildId, who, opts = {})
{
    const leave = !!opts.leave;
    const scope = (opts.scope === 'all') ? 'all' : 'own';
    const m = musicOf (guildId);
    const plan = queueClearPlan (m, opts.actorId, scope);
    if (!plan.any)
    {
        // /stop при ПУСТОЙ очереди и раньше просто выходил из канала -- оставляем это
        if (leave && m.connection && !m.tracks.length && !m.current && !m.seekTrack)
        {
            destroyMusic (guildId, {forget: true});
            console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'остановил бота: очередь была пуста, вышел из канала');
            return { ok: true, text: '⏹ Очередь и так пуста -- вышел из голосового канала.' };
        }
        return { ok: false, text: scope === 'all'
            ? '🈳 Очередь и так пуста -- чистить нечего.'
            : '🈳 Своих треков в очереди нет -- убирать нечего.' +
              (m.tracks.length ? ' Там ' + m.tracks.length + ' ' +
                  plural (m.tracks.length, 'чужой трек', 'чужих трека', 'чужих треков') +
                  ' -- ими распоряжаются админы и модеры.' : '') };
    }
    let w;
    if (scope === 'all')
    {
        const wi = queueWipe (guildId); // как было: вся очередь + играющий + база
        w = { goneQ: wi.n, playing: wi.playing, waiting: wi.waiting, left: 0 };
    }
    else w = queuePurge (guildId, t => !isBy (t, opts.actorId));
    // Выходим из канала, только если слушать действительно нечего: у /stop со «своими»
    // треками чужая музыка остаётся -- глушить её было бы свинством.
    let left = false;
    if (leave && (scope === 'all' || (!m.tracks.length && !m.current && !m.seekTrack)))
    {
        destroyMusic (guildId, {forget: true});
        left = true;
    }
    scheduleVoiceStatus (guildId, true);
    schedulePresence (true);
    // Лог и ответ собираем из того, что РЕАЛЬНО ушло: если из очереди не ушло ни
    // одного трека, а снят только играющий, так и пишем (иначе получалось «убрал 0»).
    const head = scope === 'own'
        ? (w.goneQ ? 'убрал свои треки из очереди (' + w.goneQ + ')'
                   : 'убрал своё из очереди (своих треков в ней не было)')
        : ((leave ? 'остановил и убрал очередь (' : 'очистил очередь (') + w.goneQ + ')');
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + head +
        (w.playing ? ' и снял играющий трек' : (w.waiting ? ' и снял ждущий трек' : '')) +
        (w.left ? ', в очереди осталось ' + w.left : '') +
        (left ? ', вышел из канала' : ''));
    const bits = [];
    if (w.goneQ) bits.push (w.goneQ + ' ' + plural (w.goneQ, 'трек', 'трека', 'треков'));
    // «Тишина» -- только если после снятия играющего действительно нечего играть: если
    // в очереди что-то осталось, Idle-хэндлер сразу возьмёт следующее.
    if (w.playing) bits.push ('играющий **' + w.playing + '**' +
        ((m.current || m.seekTrack || m.tracks.length) ? ' -- играю следующий' : ' -- тишина'));
    else if (w.waiting) bits.push ('ждущий **' + w.waiting + '**');
    return {
        ok: true,
        text: (scope === 'own' ? '🧹 Убрал свои' : (leave ? '⏹ Остановил и очистил' : '🧹 Очистил')) +
            (scope === 'own' && !w.goneQ ? ' (в очереди своих не было)' : '') +
            (bits.length ? ': ' + bits.join (' + ') + '.' : '.') +
            (w.left ? ' В очереди осталось ' + w.left + ' -- музыку не выключаю.' : '') +
            (left ? ' Вышел из канала.' : ''),
    };
}

// [v2.31] Кто есть в очереди -- для меню «🗑 Удалить треки автора». Обычному DJ видно
// только его самого (он и так распоряжается лишь своими записями), staff -- всех
// авторов, включая «без автора» (треки из старых баз: их видно и можно убрать целиком).
function queueAuthorList (m, actorId, staff)
{
    const map = new Map ();
    let noAuthor = 0;
    const add = t =>
    {
        if (!t) return;
        const id = byIdOf (t);
        if (!id) { noAuthor++; return; }
        let o = map.get (id);
        if (!o) { o = { id: id, name: byNameOf (t), n: 0 }; map.set (id, o); }
        o.n++;
    };
    add (m.current);
    for (const t of m.tracks) add (t);
    if (!staff) return [...map.values ()].filter (o => o.id === String (actorId));
    const list = [...map.values ()].sort ((a, b) => b.n - a.n || String (a.name).localeCompare (String (b.name)));
    if (noAuthor) list.push ({ id: '', name: 'без автора', n: noAuthor, none: true });
    return list;
}

function queueRemove (guildId, n, who, opts = {})
{
    const m = musicOf (guildId);
    if (!m.tracks.length) return { ok: false, text: '🈳 В очереди нет треков (играет только текущий).' };
    if (!Number.isInteger (n) || n < 1 || n > m.tracks.length)
        return { ok: false, text: '🤔 В очереди ' + m.tracks.length + ' ' +
            plural (m.tracks.length, 'трек', 'трека', 'треков') + ' -- номер от 1 до ' + m.tracks.length + '.' };
    // [v2.31] DJ распоряжается только своими записями (staff -- любыми).
    if (!opts.staff && !isBy (m.tracks[n - 1], opts.actorId))
        return { ok: false, text: ownOnlyText ('Убрать трек из очереди', m.tracks[n - 1]) };
    const gone = m.tracks.splice (n - 1, 1)[0];
    dropPreload (m);       // заготовка была для другого трека
    startPreload (guildId);
    saveMusicState (guildId);
    scheduleVoiceStatus (guildId, true);
    schedulePresence (true);
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'убрал из очереди №' + n + ': ' + (gone.title || 'трек'));
    return { ok: true, text: '🗑 Убрал №' + n + ': **' + (gone.title || 'трек') + '**' +
        (m.tracks.length ? ' (в очереди осталось ' + m.tracks.length + ')' : ' (очередь пуста)') };
}

// [v2.17] Перестановка трека в очереди: одна логика на /move и на кнопки «⬆/⬇»
// (иначе ответы и лог со временем разъехались бы). Номера те же, что в /queue
// (текущий трек в них не входит). Возвращает { ok, text, to }.
function queueMove (guildId, n, to, who, opts = {})
{
    const m = musicOf (guildId);
    const total = m.tracks.length;
    if (total < 2)
        return { ok: false, text: '↔️ Для перестановки нужно хотя бы два трека в очереди' +
            (m.current ? ' (сейчас играет только **' + (m.current.title || 'трек') + '**).' : '.') };
    if (!Number.isInteger (n) || !Number.isInteger (to) || n < 1 || n > total || to < 1 || to > total)
        return { ok: false, text: '🤔 В очереди ' + total + ' ' + plural (total, 'трек', 'трека', 'треков') +
            ' -- номера от 1 до ' + total + '.' };
    if (n === to) return { ok: false, text: '↔️ №' + n + ' уже на этом месте.' };
    // [v2.31] двигать можно только СВОЙ трек (staff -- любой): иначе DJ переставлял бы
    // чужую музыку в общей очереди.
    if (!opts.staff && !isBy (m.tracks[n - 1], opts.actorId))
        return { ok: false, text: ownOnlyText ('Переставить трек', m.tracks[n - 1]) };
    // [v2.32] И СТАВИТЬ ЕГО ТОЛЬКО НА СВОЁ ЖЕ МЕСТО: цель должна быть занята его треком.
    // Иначе DJ мог бы выдвинуть любую свою песню вперёд чужого плейлиста (или загнать
    // чужую назад), а обещали мы другого: каждый распоряжается только своим.
    // Среди своих мест двигаться можно свободно (напр. 20-й трек -- на 3-е своё).
    if (!opts.staff && !isBy (m.tracks[to - 1], opts.actorId))
        return { ok: false, text: '🚫 Ставить свои треки можно только на СВОИ ЖЕ места в очереди\n' +
            '_(№' + to + ' -- трек ' + (byNameOf (m.tracks[to - 1]) ? 'от **' + byNameOf (m.tracks[to - 1]) + '**' : 'без автора') +
            '). Своего трека в этом месте нет -- чужую очередь двигать нельзя._' };
    const moved = m.tracks.splice (n - 1, 1)[0];
    m.tracks.splice (to - 1, 0, moved);
    // ждущий продолжения трек (после /leave, обрыва или попытки продолжить) -- тот же
    // самый объект в очереди, так что место в нём едет вместе с ним: m.seekTrack/m.seekSec
    // указывают на ТРЕК, а не на номер.
    dropPreload (m);   // следующий трек мог смениться -- заготовка была не та
    startPreload (guildId);
    saveMusicState (guildId);
    scheduleVoiceStatus (guildId, true);
    schedulePresence (true);
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'переставил в очереди №' + n + ' -> №' + to + ': ' + (moved.title || 'трек'));
    return {
        ok: true,
        to: to,
        text: '↔️ **' + (moved.title || 'трек') + '**: №' + n + ' -> №' + to +
            (m.current ? ' (сейчас играет **' + (m.current.title || 'трек') + '**)' : '') +
            '\n' + queuePreview (m),
    };
}

// [v2.27] /push -- поднять треки одного автора наверх очереди (только ADM/MOD).
// Длинные плейлисты часто собирают вперемешку, и «своё» хочется и послушать, и
// протестировать сразу, не пролистывая чужие вставки. Порядок ВНУТРИ поднятых
// треков не меняется -- переносим их пачкой, как они и лежали.
function queuePush (guildId, targetId, who)
{
    const m = musicOf (guildId);
    const total = m.tracks.length;
    // [v2.32] targetId === '' -- треки без автора (из старых баз): их упоминать нечем.
    // whoTxt -- для «в скобках» (без автора / <@id>), whoWhat -- начало фразы
    // («Треки <@id>» / «Треки без автора»): так в тексте нет «Треки треков ...».
    const whoTxt = targetId ? u (targetId) : 'без автора';
    const whoWhat = targetId ? 'Треки ' + u (targetId) : 'Треки без автора';
    const same = t => t && String (t.byId || '') === String (targetId);
    if (!total)
        return { ok: false, text: '🈳 В очереди нет треков' +
            (m.current ? ' (играет только **' + (m.current.title || 'трек') + '**).' : ' -- двигать нечего.') };
    const mine = m.tracks.filter (same);
    if (!mine.length)
        return { ok: false, text: '🤔 В очереди нет ' + (targetId ? 'треков от ' + u (targetId) : 'треков без автора') + '.' +
            (m.current && same (m.current) ? ' Его трек и так играет прямо сейчас.' : '') +
            (m.tracks.some (t => !t.byId) && targetId
                ? '\n(у части треков автор не записан -- они добавлены до этой версии: `node . fixauthors <id>`)' : '') };
    // Ничего не меняем -- это не ошибка, а ответ «уже так»: без него /push отвечал
    // предупреждением «⚠️» и писал в журнал событие, которого не было.
    if (m.tracks.slice (0, mine.length).every (same))
        return { ok: true, text: '✅ ' + whoWhat + ' и так наверху (' + mine.length + ' ' +
            plural (mine.length, 'трек', 'трека', 'треков') + ').' };
    const rest = m.tracks.filter (t => !same (t));
    m.tracks = mine.concat (rest);
    dropPreload (m);   // следующий трек сменился -- заготовка была не та
    startPreload (guildId);
    saveMusicState (guildId);
    scheduleVoiceStatus (guildId, true);
    schedulePresence (true);
    const titles = mine.slice (0, 3).map (t => '**' + (t.title || 'трек') + '**').join (', ');
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'поднял наверх треки ' +
        (m.current && same (m.current) ? '<играет сейчас> + ' : '') + mine.length + ' шт. (' + whoTxt + ')');
    return {
        ok: true,
        text: '⬆️ Поднял наверх ' + mine.length + ' ' + plural (mine.length, 'трек', 'трека', 'треков') +
            ' (' + whoTxt + '):' + (titles ? ' ' + titles + (mine.length > 3 ? ' и ещё ' + (mine.length - 3) : '') : '') +
            (m.current && same (m.current) ? '\n(играющий трек остаётся как есть)' : '') +
            '\n' + queuePreview (m),
    };
}

// ============================================================================
// [v2.32] /seek -- ПЕРЕМОТАТЬ ТЕКУЩИЙ ТРЕК ("перейти к другому месту внутри него").
// У DJ были только "дальше" (/skip) и "прыжок по очереди" (/jump), а перемотать было
// нечем. Технически это тот же путь, что у продолжения с места: трек возвращается в
// начало очереди с отметкой "начинать с N-й секунды" и играет заново с неё -- быстрым
// путём (--download-sections), а если источник так не умеет -- своим ffmpeg.
// Прямой эфир: позиции у него нет и быть не может, поэтому "переход" для эфира -- это
// переход к тому, что идёт ПРЯМО СЕЙЧАС (свежий поток с живого края). Такой же смысл
// у перемотки В КОНЕЦ ролика, который стримится как эфир.
// Кнопки у этого действия нет СОЗНАТЕЛЬНО: это редкая и "острая" операция, случайное
// нажатие в меню прервало бы плейлист (подтверждение на каждое нажатие -- шум).
// ============================================================================
const SEEK_MAX_INPUT = 6 * 3600; // больше 6 часов не принимаем (это опечатка, а не время)
function parseSeekTime (raw)
{
    const s = String (raw === undefined || raw === null ? '' : raw).trim ().replace (/\s+/g, '');
    if (!/^\d{1,2}(?::\d{1,2}){0,2}$/.test (s)) return null;
    const parts = s.split (':').map (p => parseInt (p, 10));
    if (parts.some (n => !Number.isFinite (n))) return null;
    let sec = 0;
    for (const p of parts) sec = sec * 60 + p;
    return sec > SEEK_MAX_INPUT ? null : sec;
}

function seekMusic (guildId, sec, who, opts = {})
{
    const m = musicOf (guildId);
    if (!m.current) return { ok: false, text: '🤷 Сейчас ничего не играет -- перематывать нечего.' };
    const t = m.current;
    const title = '**' + (t.title || 'трек') + '**';
    // [v2.50] ПЕРЕМОТКА -- ТОЛЬКО ПО СВОЕМУ ТРЕКУ. «Своё/чужое» (v2.31) относилось к
    // очереди и к удалению, а ВНУТРЕННЯЯ навигация оставалась открыта всем DJ: любой
    // DJ мог утащить чужой трек к концу или в начало прямо посреди сета (живой
    // случай: твинк с ролью DJ и «⏱ На таймкод…» в чужом треке). Просьба владельца:
    // «бот для слушателей, и распоряжается каждый своим» -- как у перестановки и
    // удаления. Проверка стоит ЗДЕСЬ, у самой функции, потому что к ней ведут три
    // пути (/seek, «◀ 30 с / 30 с ▶» и окно «⏱ На таймкод…») -- и все три получают
    // правило одинаково, разъехаться не могут. staff -- любой трек; трек без автора
    // (из старой базы) -- ничей, его перематывает тот, кому он сейчас играет.
    if (!opts.staff && byIdOf (t) && !isBy (t, opts.actorId))
        return { ok: false, text: ownOnlyText ('Перематывать', t) };
    if (t.isLive)
    {
        m.skipRequested = true; // это осознанный переход, а не обрыв потока
        m.streamRetries = 0;
        m.playedMs = 0;
        m.playingSince = null;
        m.current = null;
        m.tracks.unshift (t);   // тот же трек -- но откроется заново, с живого края
        m.seekTrack = null;
        m.seekSec = 0;
        dropPreload (m);
        saveMusicState (guildId);
        try { m.player.stop (true); } catch {}
        console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'переходит к прямому эфиру: ' + (t.title || 'трек'));
        return { ok: true, text: '🔴 Это прямой эфир -- позиции у него нет. Перехожу к тому, что идёт сейчас: ' + title };
    }
    const dur = Number (t.duration) > 0 ? Number (t.duration) : 0;
    // [v2.36] Куда вернуться, если перемотка не выйдет: НЕ с начала трека, а туда,
    // где он и играл (просьба владельца: «если что-то не получается -- не надо
    // специально сначала, сообщать просто и продолжать то, что играло»).
    m.seekReturnSec = Math.max (0, Math.round (playedMsOf (m) / 1000));
    let to = Math.max (0, Math.round (sec));
    if (dur) to = Math.min (to, Math.max (0, dur - 5)); // ближе 5 сек к концу -- смысла нет ("конец" = /skip)
    m.skipRequested = true; // осознанный переход: Idle-эвристика "поток умер" не мешает
    m.streamRetries = 0;
    m.playedMs = to * 1000;
    m.playingSince = null;
    m.current = null;
    m.tracks.unshift (t); // [v2.12] тот же приём, что у продолжения с места
    m.seekTrack = t;
    m.seekSec = to;
    dropPreload (m);
    saveMusicState (guildId);
    try { m.player.stop (true); } catch {}
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'перемотал трек на ' + fmtDur (to) + ': ' + (t.title || 'трек'));
    return {
        ok: true,
        text: '⏩ ' + title + ' -- продолжаю с `' + fmtDur (to) + '`' +
            (dur ? ' (из ' + fmtDur (dur) + ')' : '') +
            '\n_Если источник не умеет навигацию, продолжу с того же места, где играло, -- в логе это видно._',
    };
}

// [v2.35] ПЕРЕМОТКА ±30 с КНОПКАМИ под /queue. Логика -- та же функция, что у /seek
// (никакого второго пути: иначе кнопки и команда со временем разъехались бы).
// У прямого эфира позиции нет и быть не может -- честно говорим об этом, а не делаем
// вид, что перемотали.
function queueSeekBy (guildId, delta, who, opts = {})
{
    const m = musicOf (guildId);
    if (!m.current)
        return { ok: false, text: '🤷 Сейчас ничего не играет -- перематывать нечего.' };
    // [v2.50] Чужой трек отбиваем ДО подсказки про эфир: правило одно, и человек должен
    // получить причину, а не рассуждение про прямой эфир.
    if (!opts.staff && byIdOf (m.current) && !isBy (m.current, opts.actorId))
        return { ok: false, text: ownOnlyText ('Перематывать', m.current) };
    if (m.current.isLive)
        return { ok: false, text: '🔴 Это прямой эфир -- позиции у него нет (`/seek 0` -- перейти к живому краю).' };
    const at = Math.max (0, Math.round (playedMsOf (m) / 1000));
    const res = seekMusic (guildId, at + delta, who, opts);
    if (!res.ok) return res;
    return { ok: true, text: res.text + '\n_Место, где играло: `' + fmtDur (at) + '`._' };
}

// Одна страница очереди: номера (те же, что в /remove,/move,/jump), автор каждого
// трека, позиция внутри текущего трека и ОБЩИЙ остаток по времени.
// moveSel -- номер выбранного для перестановки трека (0 -- ничего не выбрано):
// тогда внизу появляются кнопки «⬆ Выше» / «⬇ Ниже».
// Шапка «что играет сейчас» (с позицией внутри трека). Чистая функция от m -- её же
// для бюджета страницы зовёт queueListBudget, поэтому текст в сообщении и расчёт
// длины всегда совпадают.
function queueHeadText (m)
{
    if (m.current)
    {
        // [v2.61] У ПРЯМОГО ЭФИРА ПОЗИЦИИ НЕТ, но есть «сколько уже слушаем» -- и это
        // ещё и делает самообновление /queue заметным: у эфира раньше не менялось НИЧЕГО,
        // и сообщение казалось «неживым» (владелец: «что-то не особо сам обновляется»).
        const pos = m.current.isLive
            ? ' `🔴 в эфире ' + fmtDur (Math.floor (playedMsOf (m) / 1000)) + '`'
            : (m.current.duration > 0
                ? ' `' + fmtDur (Math.min (Math.floor (playedMsOf (m) / 1000), m.current.duration)) + ' / ' + fmtDur (m.current.duration) + '`'
                : '');
        return '🎵 **Сейчас:** ' + (m.current.isLive ? '🔴 ' : '') + '**' + (m.current.title || 'трек') + '**' + pos +
            byLabel (m.current) +
            (m.pausedByNobody ? ' _(пауза: нет слушателей)_' : '');
    }
    // [v2.34] Бот может уже сидеть в канале и просто ждать человека (после перезапуска
    // он заходит и молчит) -- тогда достаточно зайти в канал, /join не обязателен.
    if (m.pending && m.tracks.length)
        return '⏸ Музыка ждёт слушателя -- зайди в голосовой канал, и я начну с того же места' +
            (m.connection ? '' : ' (или позови `/join`)');
    return '🎵 **Сейчас:** —';
}

// «Сколько ещё ждать до конца очереди целиком» (учитывая место в текущем треке).
function queueWaitText (m)
{
    const q = queueLeft (m);
    let wait = QSMALL + '⏳ До конца очереди: ' + (q.sec ? fmtAgo (q.sec * 1000) : '0 сек');
    if (q.curLeft) wait += ' (включая ' + fmtDur (q.curLeft) + ' текущего)';
    if (q.live) wait += ' + ' + q.live + ' 🔴 ' + plural (q.live, 'эфир', 'эфира', 'эфиров') + ' (без конца)';
    if (q.unknown) wait += ' + ' + q.unknown + ' ' + plural (q.unknown, 'трек', 'трека', 'треков') + ' без длительности';
    return wait;
}

// [v2.43] ИТОГ ПРОВЕРКИ ОЧЕРЕДИ -- прямо в /queue, чтобы не читать лог. Что видно:
// сколько треков проверено и КОГДА, сколько сейчас «под вопросом» (⚠ в списке),
// сколько убрано по факту (уже при воспроизведении) и когда следующий проход.
// Убирать заранее бот больше не берётся: ответ зависит от нашего IP и прокси.
function queueCheckText (m)
{
    if (!MUSIC_QUEUE_CHECK || !QUEUE_CHECK_DEPTH) return '';
    const c = m.check || null;
    const warned = (m.tracks || []).filter (t => t && t.warn).length;
    const left = queueUncheckedLeft (m);
    const parts = [];
    if (c && c.checked) parts.push ('просмотрено ' + c.checked + ' (в ' + hhmm (c.at) + ')');
    if (warned) parts.push ('⚠ под вопросом: ' + warned + ', убирать не стал');
    if (c && c.dropped) parts.push ('убрано при воспроизведении: ' + c.dropped);
    // Когда следующий проход: ждём уже назначенное время, а если его нет, а непроверенное
    // осталось -- его найдёт тихий проход по таймеру.
    const pending = Number (m.deadScanAt) || 0;
    const soon = (pending > Date.now () ? pending : (left ? Date.now () + DEAD_RESCAN_MS : 0));
    const inMin = soon ? Math.max (1, Math.round ((soon - Date.now ()) / 60000)) : 0;
    let when;
    if (!m.tracks.length) when = 'проверять нечего: очередь пуста';
    else if (left) when = 'ещё ' + left + ' ' + plural (left, 'трек', 'трека', 'треков') +
        (inMin ? ' -- проход примерно через ' + inMin + ' мин' : '');
    else when = 'всё проверено, новых пока нет';
    return QSMALL + '🔎 Проверка очереди заранее: ' +
        (parts.length ? parts.join (', ') + '; ' : 'ещё не проходила; ') + when;
}

// [v2.44] /nowplaying -- ОДНА КАРТОЧКА «ЧТО ИГРАЕТ ПРЯМО СЕЙЧАС», не открывая /queue
// целиком: трек, позиция и остаток, кто его поставил и в каком канале, сколько людей
// слушает, сколько всего в очереди и когда она закончится, что будет дальше. Доступна
// всем (как /queue) -- это просто информация. Внимание: позиция берётся тем же счётом,
// что и в /queue (playedMsOf), поэтому цифры в двух ответах совпадают.
function nowPlayingText (m, guildId)
{
    const t = m.current || m.seekTrack || null;
    const paused = !!(m.player && m.player.state && m.player.state.status === AudioPlayerStatus.Paused);
    if (!t)
        return m.connection
            ? '🎧 В канале тишина -- играть нечего. Поставить трек: `/play`, позвать меня: `/join`.'
            : '🈳 Ничего не играет, и я не в канале.';
    const live = !!t.isLive;
    const dur = Number (t.duration) > 0 ? Number (t.duration) : 0;
    const at = Math.max (0, Math.round (playedMsOf (m) / 1000));
    const lines = [];
    lines.push ((paused ? '⏸ ' : (live ? '🔴 ' : '🎶 ')) + '**' + (t.title || 'трек') + '**' +
        (live ? ' -- прямой эфир' : (dur ? ' -- ' + fmtDur (dur) : '')));
    if (live)
        lines.push (QSMALL + 'позиции у эфира нет -- играю с живого края');
    else if (dur)
        lines.push (QSMALL + 'позиция ' + fmtDur (Math.min (at, dur)) + ' из ' + fmtDur (dur) +
            ' · до конца трека ' + fmtDur (Math.max (0, dur - at)));
    else
        lines.push (QSMALL + 'позиция ' + fmtDur (at) + ' (длительность неизвестна)');
    if (paused)
        lines.push (QSMALL + (m.pausedByNobody
            ? 'пауза: в канале нет живых слушателей -- зайди, и я продолжу'
            : 'пауза по просьбе человека: /resume продолжит'));
    lines.push (QSMALL + '👤 поставил: ' + byNameOf (t) + (t.addIn ? ' · в <#' + t.addIn + '>' : ''));
    const chId = (m.connection && m.connection.joinConfig) ? m.connection.joinConfig.channelId : null;
    const ch = chId ? client.channels.cache.get (chId) : null;
    lines.push (QSMALL + '🎧 ' + (ch ? 'пою в «' + ch.name + '»' : (chId ? 'пою в <#' + chId + '>' : 'в канале не сижу')) +
        ' · слушателей: ' + (chId ? humansInChannel (guildId, chId) : 0) +
        ' · в очереди: ' + m.tracks.length);
    lines.push (queueWaitText (m));
    // Дальше: сперва то, что уже готово (предзагрузка), иначе первый в очереди.
    const next = (m.preload && m.preload.track) || m.tracks[0] || null;
    if (next) lines.push (QSMALL + '⏭ Дальше: ' + (next.title || 'трек'));
    return lines.join ('\n');
}

function queueView (m, start, moveSel = 0, opts = {})
{
    const page = queuePage (m, start);
    const total = page.total;
    // [v2.49] ОСТАТОК СЧИТАЕТСЯ ПО ТЕКУЩЕМУ РАЗМЕРУ СТРАНИЦЫ, а не заранее. Раньше
    // он вычислялся один раз, а ниже список в крайнем случае укорачивается -- и хвост
    // сообщения писал «и ещё 185: /queue from:15», где число было уже неверным, а номер
    // в ссылке вёл на трек, который тут же и показан.
    const restNow = () => total - (page.start - 1 + page.count);
    // [v2.44] «что именно двигаем» -- мелким текстом СВЕРХУ (кнопки переноса стоят под
    // списком, и раньше эта подпись читалась только после прокрутки).
    const move = (moveSel >= 1 && moveSel <= total)
        ? QSMALL + '🗂 Выбран №' + moveSel + ': ' + (m.tracks[moveSel - 1].title || 'трек') +
          ' -- двигай его кнопками ниже; «✖ Вернуться» вернёт обычные кнопки очереди.'
        : '';
    const authors = queueAuthorsText (m);
    // [v2.54] Строки «Последние добавления» здесь больше нет: кто и когда ставил --
    // в /history (см. historyText), а очередь остаётся только очередью.
    const check = queueCheckText (m); // [v2.43] итог проверки очереди заранее
    // [v2.32] Блоки разделены линией (QSEP): «Сейчас» / справка / «Очередь».
    // [v2.44] ПОРЯДОК: шапка -> справка (мелким) -> подсказка -> СПИСОК (он теперь
    // последний, вплотную к кнопкам: треки и управление видны на одном экране).
    const build = hint => queueHeadText (m) +
        '\n' + QSEP + '\n' +
        [check, authors, queueWaitText (m), move, hint].filter (Boolean).join ('\n') +
        '\n' + QSEP +
        '\n**Очередь (' + total + ')**' + (page.start > 1 ? ' · с №' + page.start : '') + ':\n' + page.list +
        (restNow () > 0 ? '\n*...и ещё ' + restNow () + ': `/queue from:' + (page.start + page.count) + '`*' : '');
    // Очереди нет -- только шапка (подсказка про действия тогда не нужна).
    // [v2.45] Подсказка -- ВСЕГДА полная (бюджет страницы считает именно её), поэтому
    // набор блоков в сообщении не прыгает от страницы к странице.
    let content;
    if (!total) content = queueHeadText (m);
    else
    {
        // [v2.44] ПОДСКАЗКА ОДНА И ВСЕГДА. Раньше она выбиралась по длине сообщения
        // (влезла полная -- показываем её, не влезла -- короткую), и в живом чате это
        // читалось как «примечания к командам то есть, то нет». Бюджет страницы считает
        // полную подсказку, поэтому она есть всегда, а укорачивается при нехватке места
        // СПИСОК. Срезаем хвост списка -- только при ОДНОВРЕМЕННЫХ крайностях: queue_page
        // выставлен большим, все названия страницы длиннющие и у каждого трека свой
        // длинный ник (ник не укорачиваем -- он адресат). Ничего не теряется: хвост
        // сообщения ведёт на реальный следующий номер.
        content = build (queueHintText ());
        let guard = 0;
        while (content.length > QUEUE_MSG_LIMIT && page.count > 1 && guard++ < 50)
        {
            page.count--;
            page.list = page.list.split ('\n').slice (0, page.count).join ('\n');
            content = build (queueHintText ());
        }
        // Крайний случай (нужны сразу: максимальный queue_page, названия-монстры и
        // длинный ник у каждого трека): список уже из одного трека, сокращаем подсказку.
        // Лучше короткая справка, чем отбитое Discord по длине сообщение.
        if (content.length > QUEUE_MSG_LIMIT) content = build (QUEUE_HINT_SHORT);
    }
    return { content: content, components: queueComponents (page, m, moveSel, opts) };
}

// ============================================================================
// [v2.57] СООБЩЕНИЕ /queue ОБНОВЛЯЕТСЯ САМО, ПОКА ЕГО ВИДЯТ.
// Раньше текст застывал на моменте вызова: Discord перерисовывает сообщение только
// по нашему запросу, поэтому позиция в треке, остаток и счётчики оживали, лишь если
// листать или нажать «🔄 Обновить». Теперь бот помнит то сообщение, которое сам
// отправил (m.qMsg), и раз в QUEUE_LIVE_MS собирает ту же СТРАНИЦУ заново из живой
// очереди -- только если текст реально изменился (одинаковая правка всё равно
// считалась бы правкой).
//
// ПРО ЛИМИТЫ DISCORD, к которым это может упереться. На правки сообщений действует
// ограничение примерно 5 правок за 5 секунд на КАНАЛ (и оно одинаково для любого
// сообщения в нём). Наш шаг -- минута: в час выходит ~60 правок вместо допустимых
// ~3600, то есть в 60 раз реже предела, и даже минимальный разрешённый порог
// (10 секунд) в шесть раз безопаснее. Дополнительно:
//   * неизменившийся текст НЕ правим вообще (на паузе без слушателей правок нет);
//   * пока в сообщении открыто перенос/меню автора, самообновление молчит -- иначе
//     оно перерисовало бы меню прямо под руками; оно оживает, как только вернётся
//     обычный вид очереди (w.move);
//   * когда очередь доиграла совсем, делается ОДНА финальная правка и бот забывает
//     сообщение (m.qMsg = null) -- дальше в этом канале нет ни правок, ни запросов;
//   * сообщение удалили/нет прав (10008 и прочее) -- молча перестаём его вести;//     * 0 в конфиге выключает самообновление целиком (таймер даже не заводится).
// Первая самоправка пишется в лог одной строкой -- по ней видно, что оно действительно
// работает (дальше молча: 60 строк в час -- это уже спам, а не лог событий).
// ============================================================================
const QUEUE_LIVE_STEP = 5000;   // как часто проверяем, кому пора обновиться (5 с)

// Запомнить сообщение очереди как «живое». Зовётся при обычном /queue и при любой
// перерисовке кнопками -- иначе после листания самообновление вернуло бы первую страницу.
function queueWatch (m, msg, ctx, page, text, move)
{
    if (!QUEUE_LIVE_MS || !m || !msg || !msg.id) return;
    m.qMsg = { ch: msg.channelId, id: msg.id, ctx: ctx, page: Math.max (1, Number (page) || 1),
               text: String (text || ''), move: Math.max (0, Number (move) || 0), at: Date.now (),
               first: true };   // [v2.61] первая самоправка пишется в лог -- видно, что оно работает
}

// Восстановить живое сообщение из записи в базе (переживает перезапуск). Текст не
// берём -- его всё равно пересобираем из живой очереди на первой же проверке.
function queueWatchRestore (saved)
{
    if (!QUEUE_LIVE_MS || !saved || !saved.ch || !saved.id) return null;
    return { ch: String (saved.ch), id: String (saved.id), page: Math.max (1, Number (saved.page) || 1),
             ctx: { actorId: String (saved.actorId || ''), actorName: String (saved.actorName || ''),
                    staff: !!saved.staff },
             text: '', move: 0, at: Date.now () };
}

// Одна перерисовка для одного сервера. НИКОГДА не бросает: сбой правки не должен
// ронять бота -- он просто выключает самообновление для этого сообщения.
async function queueLiveTick (guildId)
{
    const m = $music[guildId], w = m && m.qMsg;
    if (!w) return;
    if (w.move) { w.at = Date.now (); return; }   // открыт перенос: не мешаем руками
    let view;
    try { view = queueView (m, w.page, 0, w.ctx); }
    catch (e) { m.qMsg = null; return; }
    const empty = !m.current && !m.tracks.length && !m.seekTrack;
    const content = view.content;
    if (content === w.text)               // менять нечего
    {
        if (empty) m.qMsg = null;         // очередь доиграла -- и этот вид уже показан
        return;
    }
    try
    {
        const ch = client.channels.cache.get (w.ch) || await client.channels.fetch (w.ch).catch (() => null);
        if (!ch) { m.qMsg = null; return; }
        const msg = await ch.messages.fetch (w.id);
        await msg.edit (Object.assign (
            view.components.length ? { content: content, components: view.components } : { content: content },
            { allowedMentions: { parse: [] } }));   // [v2.61] авторы -- ссылками, без пингов
        // [v2.61] Первую самоправку видно в логе (дальше -- молча, иначе было бы 60 строк в час).
        if (w.first) { w.first = false; console.log ('[' + (d()) + '] [music] сообщение /queue обновил сам (стр. ' + w.page + ')'); }
        w.text = content;
        if (empty) m.qMsg = null;         // финальный вид показали -- больше не правим
    }
    catch (e)
    {
        const code = String ((e && (e.code || (e.rawError && e.rawError.code))) || '');
        if (code !== '10008')             // 10008 -- сообщение удалили, это не ошибка
            console.error ('[music] сам не смог обновить сообщение /queue: ' + oneLine ((e && e.message) || e));
        m.qMsg = null;
    }
}

if (QUEUE_LIVE_MS)
    setInterval (() =>
    {
        const now = Date.now ();
        for (const g of Object.keys ($music))
        {
            const w = $music[g] && $music[g].qMsg;
            if (!w || (now - w.at) < QUEUE_LIVE_MS) continue;
            w.at = now;
            queueLiveTick (g).catch (() => {});
        }
    }, QUEUE_LIVE_STEP).unref ();

// Старт после перезапуска/падения: вернуть ПРИСУТСТВИЕ бота в канале, а также очередь,
// текущий трек и позицию.
// [v2.24] Порядок именно такой: состояние «сижу в канале» не зависит от очереди
// (/join без музыки, /stop, доигравшая очередь) и должно переживать перезапуск.
// Если в канале есть живой слушатель -- сразу играем; если пока никого -- заходим и
// ЖДЁМ (музыка не играет в пустоту), а очередь начнётся, как только человек появится
// (см. ветку в checkListeners).
async function resumeMusic (server)
{
    try
    {
        const guild = client.guilds.cache.get (server);
        if (!guild) return;
        const m = musicOf (server);
        // --- 1) ПРИСУТСТВИЕ: где бот сидел до перезапуска ---
        const voice = await readVoiceState (server);
        let vch = null;
        if (voice && voice.channelId && !voice.left)
        {
            vch = guild.channels.cache.get (voice.channelId) ||
                await guild.channels.fetch (voice.channelId).catch (() => null);
            if (vch && (typeof vch.isVoiceBased !== 'function' || !vch.isVoiceBased ())) vch = null;
            if (!vch) writeVoiceState (server, null, false); // канал удалили -- помнить нечего
        }
        if (vch)
        {
            joinVoice (server, vch, guild, 'вернулся туда, где сидел до перезапуска');
            // [v2.34] Слушателей на старте считаем БЕЗ ДОГАДОК (humansInChannelChecked):
            // от этого ответа зависит, играть или молчать, а чужой бот, чей member не
            // приложен к голосовому состоянию, раньше считался ЖИВЫМ слушателем.
            const _h = await humansInChannelChecked (server, vch.id);
            if (m.connection)
                console.log ('[' + (d()) + '] [music] возвращаюсь в «' + vch.name +
                    '» -- бот сидел там до перезапуска' +
                    (_h ? '' : ' (живых слушателей нет)'));
        }
        // --- 2а) ИСТОРИЯ ДОБАВЛЕНИЙ [v2.54] ---
        // Читаем ДО очереди и не выходим раньше времени: история живёт своей жизнью
        // (очередь могла доиграть или быть стёрта /stop, а добавления помним).
        await historyLoad (server);
        if (Array.isArray (m.history) && m.history.length)
            console.log ('[' + (d()) + '] [music] история добавлений: ' + m.history.length + ' ' +
                plural (m.history.length, 'пачка', 'пачки', 'пачек') + ' с прошлого запуска -- /history');
        // --- 2) ОЧЕРЕДЬ с прошлого запуска ---
        let saved = await db (server, 'musicState', 'queue');
        if (!saved) return;
        const tracks = (saved.tracks || []).filter (t => t && t.url).map (jsonToTrack);
        const current = saved.current ? jsonToTrack (saved.current) : null;
        if (!current && !tracks.length) return;
        m.savedChannelId = vch ? vch.id : (saved.channelId || null);
        m.textChannelId = saved.textChannelId || m.textChannelId;
        // [v2.57] Сообщение /queue, которое ведёт самообновление, тоже возвращаем: иначе
        // после перезапуска оно замирало бы на состоянии до рестарта (а перезапускаем мы
        // часто). Текст в базе не держим -- первая же проверка обновит его сама.
        m.qMsg = queueWatchRestore (saved.qMsg);
        // [v2.12.2] ждущий трек возвращается НА СВОЁ место из очереди (curIdx), а не
        // всегда в начало: если DJ переставил его через /move, порядок сохраняется
        const at = Math.min (Math.max (0, Math.round (saved.curIdx || 0)), tracks.length);
        m.tracks = current ? [...tracks.slice (0, at), current, ...tracks.slice (at)] : tracks;
        // [v2.54] очередь на месте -- самое время один раз перенести её пачки в историю
        // (если настоящей истории ещё нет: первое обновление на этой версии)
        await historySeedFromQueue (server);
        m.seekTrack = current;   // этому треку playNext попробует сдвиг на elapsed
        m.seekSec = Math.max (0, Math.round (saved.elapsed || 0));
        // уже вернулись в канал (присутствие выше) -- значит точно не «выходили по /leave»
        m.leftByUser = vch ? false : !!saved.left;
        m.pending = true;
        // [v2.32] Треки без автора (из старых баз) -- обычный DJ их не трогает: говорим
        // об этом при старте и даём готовую команду, иначе непонятно, почему такой трек
        // нельзя ни убрать, ни подвинуть.
        const _noAuth = (current && !current.byId ? 1 : 0) + tracks.filter (t => !t.byId).length;
        if (_noAuth)
            console.log ('[' + (d()) + '] [music] в очереди ' + _noAuth + ' ' +
                plural (_noAuth, 'трек', 'трека', 'треков') + ' без автора (добавлены до v2.31): обычный DJ их не уберёт и не подвинет -- только админы и модеры.\n' +
                '     Проставить автора сразу всем:  node . fixauthors <его id> [имя]   (сначала можно — --dry)');
        // живо ли место: и трек, и место в треке, и очередь целиком остаются в памяти
        let ch = m.savedChannelId
            ? (guild.channels.cache.get (m.savedChannelId) ||
               await guild.channels.fetch (m.savedChannelId).catch (() => null))
            : null;
        if (ch && (typeof ch.isVoiceBased !== 'function' || !ch.isVoiceBased ())) ch = null;
        if (!ch) m.savedChannelId = null;
        const where = (current ? (current.title || 'трек') +
            (current.isLive ? ' (эфир)' : (m.seekSec ? ' (с ' + fmtDur (m.seekSec) + ')' : '')) :
            'очередь без текущего') +
            (tracks.length ? ' + ещё ' + tracks.length + ' в очереди' : '');
        if (m.leftByUser)
        {
            console.log ('[' + (d()) + '] [music] очередь с прошлого раза на месте (выходили по /leave) -- ' + where + '; продолжу по /join');
            return;
        }
        if (!ch)
        {
            console.log ('[' + (d()) + '] [music] канала из прошлого запуска нет -- очередь ждёт /join: ' + where);
            return;
        }
        // [v2.34] НЕ ИГРАТЬ В ПУСТУЮ КОМНАТУ. Раньше здесь стояла быстрая проверка по
        // кэшу (humansInChannel), и на старте она могла ошибиться в обе стороны: чужой
        // бот без member считался слушателем (и yt-dlp запускался в тишину), а
        // недогруженные состояния -- людьми. Теперь спрашиваем по-настоящему; не
        // ответил Discord -- считаем, что человек есть (лучше заиграть, чем промолчать).
        if (!await humansInChannelChecked (server, ch.id))
        {
            // В канал мы уже зашли (присутствие выше) -- сидим и молчим, пока кто-то не
            // войдёт: очередь и МЕСТО В ТРЕКЕ остаются как были (m.seekTrack/m.seekSec).
            console.log ('[' + (d()) + '] [music] зашёл в «' + ch.name + '» и МОЛЧУ: живых слушателей нет, ' +
                'играть не для кого -- очередь и место помню (' + where + '); начну, как только кто-то войдёт ' +
                '(или /join, когда надо)');
            scheduleVoiceStatus (server, true); // статус/присутствие отражают «жду слушателя»
            schedulePresence (true);
            saveMusicState (server); // запись остаётся с той же позицией (elapsed из seekSec)
            return;
        }
        startRestored (server, ch, guild);
    }
    catch (e) { console.error ('[music] не смог возобновить очередь: ' + oneLine (e.message)); }
}

// Начать играть «отложенную» (сохранённую) очередь в указанном канале:
// [v2.34] ГЛАВНОЕ ПРАВИЛО ЗДЕСЬ: НЕ ИГРАТЬ В ПУСТУЮ КОМНАТУ. Проверка слушателей
// стоит ПОСЛЕДНЕЙ ЛИНИЕЙ обороны -- прямо перед playNext(), а не только у вызывающих.
// Иначе любой будущий вызов этой функции (или новый путь восстановления) снова
// заставит бота запустить yt-dlp в тишину и только потом поставить паузу.
// Если играть некому -- заходим в канал, молчим и ждём человека: очередь и позиция
// остаются как были в памяти и в базе.
function startRestored (server, ch, guild)
{
    const m = musicOf (server);
    const current = m.seekTrack || null;
    const seek = m.seekSec || 0;
    const rest = restCount (m);
    const where = (current ? (current.title || 'трек') +
        (current.isLive ? ' (эфир)' : (seek ? ' (с ' + fmtDur (seek) + ')' : '')) : 'очередь без текущего') +
        (rest ? ' + ещё ' + rest + ' в очереди' : '');
    if (!joinVoice (server, ch, guild) || !m.connection) return;
    m.savedChannelId = ch.id;
    if (!humansInChannel (server, ch.id))
    {
        // Остаёмся в канале, но НЕ играем -- тот же режим ожидания, что и после старта:
        m.pending = true;
        m.leftByUser = false;
        console.log ('[' + (d()) + '] [music] в «' + ch.name + '» никого -- играть не для кого: ' +
            'стою и жду слушателя (помню: ' + where + '), начну с того же места');
        scheduleVoiceStatus (server, true);
        schedulePresence (true);
        saveMusicState (server);
        return;
    }
    m.pending = false;
    m.leftByUser = false;
    console.log ('[' + (d()) + '] [music] возобновляю очередь в «' + ch.name + '»: ' + where);
    schedulePresence (true);
    playNext (server);
    scheduleDeadScan (server); // [v2.41] очередь вернулась -- посмотрим, живы ли треки впереди
}

// [v2.28] Сообщение ЛЮДЯМ про музыку (не в журнал): уходит в тот канал, откуда бота
// позвали (/play или /join запоминает его в m.textChannelId). Если канала нет или он
// недоступен -- просто молчим: событие и так есть в логе. Никогда не бросает -- это
// уведомление, а не работа.
function musicNotice (guildId, text)
{
    const m = $music[guildId];
    if (!m || !m.textChannelId || !text) return;
    const ch = client.channels.cache.get (m.textChannelId);
    if (!ch || typeof ch.send !== 'function') return;
    ch.send (text).catch (() => {});
}

// [v2.39] КОМУ ГОВОРИТЬ О ПРОБЛЕМЕ С ТРЕКОМ. Раньше любое «этот трек не заиграл/его
// больше нет» уходило в ОДИН канал -- тот, откуда шла последняя команда (m.textChannelId),
// и это мог быть чужой канал, где автор трека вообще не появится. Проблема же касается
// того, кто трек поставил. Поэтому у каждого трека помним текстовый канал, откуда его
// добавили (track.addIn, ставится в /play), и пишем туда: автор вернётся в свою комнату
// и сразу увидит, что его трек удалён и почему -- а не будет думать, что забыл его
// добавить. Канала больше нет (удалён, бот не видит) -- падаем на прежний путь.
function trackNotice (guildId, track, text)
{
    const m = $music[guildId];
    if (!m || !text) return;
    const _id = track && track.addIn ? String (track.addIn) : '';
    const ch = _id ? client.channels.cache.get (_id) : null;
    if (ch && typeof ch.send === 'function') { ch.send (text).catch (() => {}); return; }
    musicNotice (guildId, text);
}

// ============================================================================
// [v2.41] ЗАРАНЕЕ ПРОЧЁСЫВАЕМ ОЧЕРЕДЬ И ПРЕДУПРЕЖДАЕМ О ПРОБЛЕМАХ [v2.43].
// Раньше бот узнавал «видео больше нет» только когда трек подходил к предзагрузке:
// человек ждал свою песню, чтобы услышать, что её не будет. Теперь бот смотрит вперёд
// сам, но НИЧЕГО НЕ УБИРАЕТ по своей проверке: ответ зависит от нашего IP и прокси
// (регион, VPN) и меняется на ходу -- трек только помечается «под вопросом» (⚠ в /queue),
// а уходит из очереди ровно по факту (не запустился при воспроизведении). Автору бот
// говорит в ТОТ канал, откуда он трек добавил.
//
// ПОЧЕМУ ЭТО НЕ ГРОЗИТ ОГРАНИЧЕНИЯМИ YOUTUBE (главный вопрос владельца):
//   * сначала ДЕШЁВЫЙ публичный oEmbed (один крошечный запрос, без скачивания, без плеера);
//     yt-dlp запускается ТОЛЬКО если oEmbed отказал, то есть чтобы ПОДТВЕРДИТЬ приговор --
//     и делает ровно то же, что и перед обычным проигрыванием трека;
//   * за один проход смотрим не больше `queue_check_depth` треков (по умолчанию 20)
//     от начала очереди и с паузой `queue_check_gap_ms` (по умолчанию 5 с) -- это меньше,
//     чем один запуск yt-dlp на каждый сыгранный трек, который бот делает и так;
//   * один и тот же адрес за сессию проверяется один раз ($deadChecked);
//   * прямые эфиры не проверяются вообще (у них «конца» нет);
//   * сетевая ошибка, «подтвердите, что вы не робот», возрастное ограничение -- НЕ приговор:
//     трек остаётся в очереди и может быть проверен позже.
// ============================================================================
const $deadChecked = new Map ();        // адрес трека -> { state: 'alive'|'dead'|'unknown', at }
const DEAD_UNKNOWN_RETRY = 30 * 60 * 1000; // «не поняли» -- переспросим не раньше чем через полчаса
const DEAD_RESCAN_MS = 3 * 60 * 1000;       // [v2.43] период тихого прохода (см. setInterval ниже)
const DEAD_PROBE_TIMEOUT = 8000;
const $deadScan = {};                   // guildId -> true, пока идёт проход

function deadStateOf (url)
{
    const v = url ? $deadChecked.get (url) : null;
    if (!v) return null;
    if (v.state === 'unknown' && Date.now () - v.at > DEAD_UNKNOWN_RETRY) return null;
    return v.state;
}
function deadRemember (url, state)
{
    if (!url) return;
    if ($deadChecked.size > 5000) $deadChecked.clear (); // сессия длинная -- память не растим
    $deadChecked.set (url, { state, at: Date.now () });
}

// АДРЕС ПРОКСИ ДЛЯ НАШЕГО ЗАПРОСА. В URL вида `socks5://` SOCKS-агент Node резолвит имя
// САМ (так устроен socks-proxy-agent v6), а на машине, где youtube.com не резолвится
// локально -- обычная история, когда весь YouTube ходят через VPN, -- запрос вообще не
// уйдёт. `socks5h://` резолвит имя НА СТОРОНЕ прокси, ровно как делает yt-dlp со своим
// `--proxy`. Поэтому для своей проверки мы поднимаем схему до *h (сам конфиг не трогаем:
// он же уходит в yt-dlp, которому своё).
function proxyForAgent (proxyUrl)
{
    const s = String (proxyUrl || '').trim ();
    if (/^socks4:\/\//i.test (s)) return s.replace (/^socks4:\/\//i, 'socks4a://');
    if (/^socks5:\/\//i.test (s)) return s.replace (/^socks5:\/\//i, 'socks5h://');
    if (/^socks:\/\//i.test (s)) return s.replace (/^socks:\/\//i, 'socks5h://');
    return s;
}

// oEmbed: маленький публичный запрос. 'ok' -- видео есть, 'gone' -- удалено/закрыто,
// 'unknown' -- не смогли узнать (403/429/5xx), 'neterr' -- до YouTube вообще не дошли
// (DNS, сокет): это не про видео, и по такому ответу ничего не убираем.
// Проверяем ТОЛЬКО адреса самого YouTube: у чужого адреса (или «голого» id из старой
// базы) ответ ничего не значит, и убирать по нему трек нельзя ни в каком случае.
const YT_URL_RE = /^https?:\/\/(?:www\.|m\.|music\.)?youtube\.com\/(?:watch|shorts|live|embed)|^https?:\/\/youtu\.be\//i;
async function oembedProbe (url)
{
    if (!YT_URL_RE.test (String (url || ''))) return 'unknown';
    // [v2.52] Прокси берём и когда он помечен «мёртвым», если локальный DNS его
    // не видит: на такой машине DIRECT не работает вообще, а oEmbed-проверка без
    // маршрута отвечает 'neterr' -- то есть очередь просто перестаёт проверяться.
    // (Считаем ЗАРАНЕЕ: внутри new Promise уже нельзя ждать.)
    // [v2.60] Берём первый НЕ «икнувший» прокси (а если локальный DNS мёртв -- хоть
    // какой-то): раньше тут был один общий флаг, и один обрыв глушил проверку целиком.
    const proxyAddr = await proxyForFetch ();
    return new Promise (resolve =>
    {
        let httpsMod;
        try { httpsMod = require ('https'); } catch { return resolve ('neterr'); }
        let agent = null;
        if (proxyAddr)
            try
            {
                const M = require ('socks-proxy-agent'); // рядом с discord.js -- берём, если есть
                const A = M.SocksProxyAgent || M;
                agent = new A (proxyForAgent (proxyAddr));
            }
            catch { agent = null; } // модуля рядом нет -- идём напрямую, проверить это не мешает
        let done = false;
        const fin = v => { if (done) return; done = true; resolve (v); };
        let req;
        try
        {
            req = httpsMod.get ('https://www.youtube.com/oembed?format=json&url=' + encodeURIComponent (url),
                { agent, timeout: DEAD_PROBE_TIMEOUT },
                res =>
                {
                    res.resume (); // тело не нужно: важен только код ответа
                    if (res.statusCode === 200) return fin ('ok');
                    // 400 (нет такого видео), 401 (закрытое), 404 (удалено) -- это приговор,
                    // который всё равно подтвердит yt-dlp. А 403 -- часто «встраивание
                    // запрещено», и такое видео прекрасно играется: это НЕ смерть.
                    if (res.statusCode === 400 || res.statusCode === 401 || res.statusCode === 404) return fin ('gone');
                    fin ('unknown');
                });
        }
        catch { return fin ('neterr'); }
        req.on ('timeout', () => { try { req.destroy (); } catch {} fin ('neterr'); });
        req.on ('error', () => fin ('neterr'));
    });
}

// Один раз за сессию: если до YouTube не достучаться ВООБЩЕ, сказать об этом прямо --
// иначе выглядело бы, будто проверка работает, а просто ничего не находит.
let oembedFails = 0, oembedOkEver = 0, oembedHintTold = false;
function oembedNote (verdict)
{
    if (verdict === 'ok' || verdict === 'gone') { oembedOkEver++; oembedFails = 0; return; }
    if (verdict !== 'neterr') return;
    if (++oembedFails < 5 || oembedOkEver || oembedHintTold) return;
    oembedHintTold = true;
    console.error ('[' + (d()) + '] [music] проверка очереди: не могу достучаться до YouTube (DNS/сеть) -- ' +
        'мёртвые видео, как и раньше, узнаются только при подходе к эфиру. ' +
        'Проверь MUSIC.proxy (запрос идёт через socks5h) или выключи MUSIC.queue_check вовсе');
}

// Приговор выносит yt-dlp -- тот же инструмент, что играет музыку. Значит «мёртвый» трек --
// ровно тот, который бот и в эфире не открыл бы; видео «нельзя встроить» останется в очереди.
// strict -- для первых треков очереди: там мало oEmbed, потому что он отвечает «есть» и про
// видео, которое этому IP не отдаётся (регион, блокировка) -- а оно не сыграет, и человек
// узнал бы об этом только в момент перехода. Поэтому передний край очереди (STRICT_DEPTH
// треков) спрашивают у самого yt-dlp -- один раз на трек, как перед проигрыванием.
async function deadProbe (url, strict = false)
{
    const oe = await oembedProbe (url);
    oembedNote (oe);
    if (oe === 'ok' && !strict) return 'alive';
    if (oe !== 'ok' && oe !== 'gone') return 'unknown'; // 403/429/5xx или вообще не дошли -- не трогаем
    ytDlpQuiet++;
    try
    {
        await ytDlpRun (url, { simulate: true, quiet: true, noWarnings: true, noPlaylist: true });
        return 'alive'; // oEmbed отказал, а играется -- значит дело во встраивании
    }
    catch (e) { return isGoneError (e) ? 'dead' : 'unknown'; }
    finally { ytDlpQuiet--; }
}

// Одним сообщением на канал: если в очереди нашлось сразу несколько подозрительных -- это спам,
// а не событие.
function deadWarnAdd (told, guildId, track)
{
    const m = $music[guildId];
    const want = track && track.addIn ? String (track.addIn) : '';
    const ch = want ? client.channels.cache.get (want) : null;
    const id = (ch && typeof ch.send === 'function') ? want
        : (m && m.textChannelId ? String (m.textChannelId) : '');
    if (!id) return;
    if (!told.has (id)) told.set (id, []);
    told.get (id).push (track.title || 'трек');
}
// [v2.43] Это ПРЕДУПРЕЖДЕНИЕ, а не приговор: трек остаётся в очереди, и в тексте это
// сказано прямо -- иначе человек пойдёт ставить заново то, что и так на месте.
function deadWarnSend (told)
{
    for (const [id, titles] of told)
    {
        const ch = client.channels.cache.get (id);
        if (!ch || typeof ch.send !== 'function') continue;
        ch.send ('⚠️ **Возможно, это видео недоступно:** ' +
            titles.slice (0, 8).map (t => '**' + oneLine (t, 60) + '**').join (', ') +
            (titles.length > 8 ? ' и ещё ' + (titles.length - 8) : '') +
            '. Проверка идёт заранее и через мой прокси -- бывает, что видео просто не\n' +
            'отдаётся сейчас (регион, VPN). **Из очереди не убираю:** проверю, когда дойдёт\n' +
            'очередь, и если не сыграет -- скажу причину и уберу. Ставлять заново не надо.').catch (() => {});
    }
}

function scheduleDeadScan (guildId, delay = 8000)
{
    if (!MUSIC_QUEUE_CHECK || !QUEUE_CHECK_DEPTH) return;
    const m = $music[guildId];
    if (!m || m.deadScanTimer) return; // уже запланировано
    m.deadScanAt = Date.now () + delay; // [v2.43] для строки в /queue: когда будет проход
    m.deadScanTimer = setTimeout (() => { m.deadScanTimer = null; deadScan (guildId).catch (() => {}); }, delay);
    if (m.deadScanTimer && m.deadScanTimer.unref) m.deadScanTimer.unref (); // проверка не держит процесс
}

// [v2.43] СБОР ИТОГА ДЛЯ /queue. Проверка заранее больше ничего не убирает, поэтому счёт
// «мёртвых убрано» -- это про реальные случаи: трек доехал до эфира и НЕ ЗАПУСТИЛСЯ.
// Сюда же пишем, когда прошёл последний проход.
function deadCheckNote (guildId, fields)
{
    const m = $music[guildId];
    if (!m) return;
    const c = m.check || (m.check = { at: 0, checked: 0, dropped: 0 });
    for (const k in fields) c[k] = fields[k];
}
function deadDropNote (guildId)
{
    const m = $music[guildId];
    if (!m) return;
    const c = m.check || (m.check = { at: 0, checked: 0, dropped: 0 });
    c.dropped = (c.dropped || 0) + 1;
}

async function deadScan (guildId)
{
    if (!MUSIC_QUEUE_CHECK || !QUEUE_CHECK_DEPTH || $deadScan[guildId]) return;
    $deadScan[guildId] = true;
    const told = new Map ();
    let checked = 0, warned = 0;
    try
    {
        for (;;)
        {
            const m = $music[guildId];
            if (!m || !m.tracks || !m.tracks.length) break;
            if (checked >= QUEUE_CHECK_DEPTH) break;
            // Ближайший непроверенный трек -- от начала очереди и дальше (что ближе к эфиру,
            // то и важнее). Уже проверенное пропускаем: так глубина получается «не больше N
            // ЗАПРОСОВ за проход», а не «не дальше N-го трека» -- и длинный плейлист
            // разбирается целиком, просто за несколько проходов.
            let target = null, targetAt = -1;
            for (let i = 0; i < m.tracks.length; i++)
            {
                const t = m.tracks[i];
                if (!t || t.isLive || t.gone) continue;
                const _u = t.url || t.streamUrl;
                if (!_u || deadStateOf (_u)) continue;
                target = t; targetAt = i; break;
            }
            if (!target) break;
            const url = target.url || target.streamUrl;
            const verdict = await deadProbe (url, targetAt < QUEUE_CHECK_STRICT);
            deadRemember (url, verdict);
            checked++;
            const now = $music[guildId];
            if (!now) break;
            if (verdict === 'dead')
            {
                // [v2.43] НЕ УБИРАЕМ, А ПОМЕЧАЕМ. Именно на предварительной проверке это
                // плавающий ответ: он зависит от нашего IP и прокси (регион, VPN) и от
                // того, как сейчас отвечает YouTube. Владелец меняет прокси -- и трек,
                // «мёртвый» пять минут назад, спокойно играет. Удаляем только по факту:
                // не запустился при воспроизведении -- тогда и уходит из очереди.
                const at = now.tracks.indexOf (target);
                if (at >= 0)
                {
                    target.warn = 'проверка заранее: видео не отдаётся (регион/прокси или удалено)';
                    target.warnAt = Date.now ();
                    warned++;
                    if (!target.warnTold)
                        console.error ('[' + (d()) + '] [music] проверка очереди: похоже, видео недоступно -- ' +
                            (target.title || 'трек') + ' -- оставляю в очереди, проверю при воспроизведении');
                    target.warnTold = true;
                }
                deadWarnAdd (told, guildId, target);
            }
            await new Promise (r => setTimeout (r, QUEUE_CHECK_GAP_MS)); // пауза: не залпом
        }
    }
    finally
    {
        $deadScan[guildId] = false;
        // Одна строка на проход: видно, что проверка жива и что она нашла.
        if (checked)
        {
            console.log ('[' + (d()) + '] [music] проверка очереди: проверено ' + checked + ' ' +
                plural (checked, 'трек', 'трека', 'треков') + ' -- ' +
                (warned ? 'под вопросом: ' + warned + ' (из очереди не убрал)' : 'подозрительных нет'));
            deadCheckNote (guildId, { at: Date.now (), checked: checked });
        }
        deadWarnSend (told);
    }
}

// Повторный тихий проход: подхватывает то, что в прошлый раз не поняли (сеть, «не робот»).
// Если проверять нечего, он выходит сразу (все адреса уже в $deadChecked) и ничего не стоит.
setInterval (() =>
{
    for (const id of Object.keys ($music)) scheduleDeadScan (id, 1000);
}, DEAD_RESCAN_MS).unref ();

// [v2.43] СКОЛЬКО ТРЕКОВ ЕЩЁ НЕ ПРОВЕРЯЛОСЬ в этой сессии -- для строки в /queue
// («осталось проверить N»). Считаем по тому же правилу, что и сам проход: у трека есть
// адрес и он не эфир; уже проверенное (в т.ч. «не поняли») сюда не попадает до тех пор,
// пока пометка не устареет (DEAD_UNKNOWN_RETRY).
function queueUncheckedLeft (m)
{
    if (!m || !m.tracks) return 0;
    let left = 0;
    for (const t of m.tracks)
    {
        if (!t || t.isLive) continue;
        const u = t.url || t.streamUrl;
        if (!u || deadStateOf (u)) continue;
        left++;
    }
    return left;
}

// [v2.28] РЕЖИМ «НЕ ЖДАТЬ ОТСУТСТВУЮЩИХ АВТОРОВ» (MUSIC.skip_absent_author).
// Ситуация: бот один в канале и молчит (пауза: своя «нет слушателей» или человек
// поставил /pause), а дальше в очереди есть треки тех, кто СЛУШАЕТ прямо сейчас в
// другом канале. Ждать некому -- поэтому треки отсутствующих авторов (вместе с
// недоеденным текущим) переставляются в КОНЕЦ очереди (ничего не теряется: вернётся
// автор -- они снова дойдут по очереди), а бот переезжает к тому, кто есть, и играет.
// Возвращает true, если переехали и заиграли. Порядок внутри переставленных сохранён.
function skipAbsentAuthors (guildId, curChId)
{
    const m = $music[guildId];
    if (!m || !m.connection) return false;
    if (!MUSIC_SKIP_ABSENT) return false;
    const cand = [];
    if (m.current) cand.push (m.current);
    for (const t of (m.tracks || [])) cand.push (t);
    if (cand.length < 2) return false;
    let at = -1, ch = null;
    for (let i = 0; i < cand.length && i < 500; i++)
    {
        const aCh = authorVoiceId (guildId, cand[i]);
        if (!aCh || aCh === curChId) continue;
        const c = client.channels.cache.get (aCh);
        if (c) { at = i; ch = c; break; }
    }
    // at === 0 -- автор недоеденного трека тут: это обычный переезд (ниже), не пропуск.
    // at < 0 -- в голосовых никого из авторов: играть не для кого, остаёмся как есть.
    if (at <= 0 || !ch) return false;
    const guildMove = client.guilds.cache.get (guildId);
    if (!guildMove) return false;
    const withCur = !!m.current;
    const cut = withCur ? (at - 1) : at;          // сколько треков очереди уходит в конец
    const moved = cand.slice (0, at);             // недоеденный текущий + треки до нужного
    const target = cand[at];
    const whoName = target.byName || u (target.byId);
    try
    {
        joinVoice (guildId, ch, guildMove, 'авторов пропущенных треков нет в голосовом -- ' +
            whoName + ' слушает здесь');
    }
    catch (e)
    {
        console.error ('[music] пропуск отсутствующих авторов: переехать не вышло: ' + oneLine (e.message));
        return false;
    }
    m.tracks = m.tracks.slice (cut).concat (moved); // переставленные -- в конец, в своём порядке
    m.current = null;
    m.seekTrack = null;
    m.seekSec = 0;
    m.playedMs = 0;
    m.playingSince = null;
    m.pending = false;
    m.pausedByNobody = false;
    dropPreload (m);
    m.savedChannelId = ch.id;
    saveMusicState (guildId);
    try { m.player.stop (true); } catch {} // Idle -> playNext: сразу заиграет трек, которого ждут
    scheduleVoiceStatus (guildId, true);
    schedulePresence (true);
    const names = moved.slice (0, 3).map (t => t.title || 'трек').join (', ');
    console.log ('[' + (d()) + '] [music] ' + moved.length + ' ' + plural (moved.length, 'трек', 'трека', 'треков') +
        ' отсутствующих авторов (' + names + (moved.length > 3 ? ' и др.' : '') +
        ') -- переставил в конец очереди и перешёл в «' + ch.name + '»: ' + whoName + ' ждёт своё');
    musicNotice (guildId, '⏭ ' + moved.length + ' ' + plural (moved.length, 'трек', 'трека', 'треков') +
        ' от тех, кого нет в голосовом, -- ждать некому: поставил их в конец очереди и играю **' +
        (target.title || 'трек') + '** в «' + ch.name + '» (добавил ' + whoName + ').');
    return true;
}

// ============================================================================
// [v2.12] ЖИВЫЕ СЛУШАТЕЛИ: музыка не играет в пустоту и не теряет задуманное.
//   * никого в канале -> пауза (позиция помнится и сохраняется);
//   * слушатель вернулся (>0) -> продолжаем с того же места;
//   * очередь ждёт слушателя (после перезапуска) -> сами заходим в тот же канал,
//     когда там кто-то появился (кроме случая /leave -- тогда ждём /join).
// ============================================================================
function checkListeners (server, _noFollow = false)
{
    const m = $music[server];
    if (!m) return;
    if (m.connection)
    {
        const chId = m.connection.joinConfig.channelId;
        const people = humansInChannel (server, chId);
        const ch = client.channels.cache.get (chId);
        const where = ch ? '«' + ch.name + '»' : chId;
        // важно: трогаем только РЕАЛЬНО играющий трек -- если человек сам поставил /pause,
        // уход и возврат слушателей его паузу не отменяет
        const playing = m.player.state.status === AudioPlayerStatus.Playing;
        if (!people && m.current && playing && !m.pausedByNobody)
        {
            m.pausedByNobody = true;
            m.playedMs = playedMsOf (m);
            m.playingSince = null;
            try { m.player.pause (); } catch (e) { /* плеер мог быть пуст -- не страшно */ }
            console.log ('[' + (d()) + '] [music] в ' + where + ' никого -- пауза (продолжу, когда вернётся слушатель)');
            saveMusicState (server);
            scheduleVoiceStatus (server, true);
            schedulePresence (true);
            // [v2.27] Не ждём следующего события в голосовых: раз комната опустела,
            // сразу смотрим, не нужно ли уехать к автору (ветка ниже). Без этого бот
            // стоял бы один до чьего-то следующего захода/выхода.
            if (!_noFollow) return checkListeners (server, false);
        }
        else if (people > 0 && m.pausedByNobody)
        {
            m.pausedByNobody = false;
            m.playingSince = Date.now ();
            try { m.player.unpause (); } catch (e) { /* аналогично */ }
            console.log ('[' + (d()) + '] [music] слушатель вернулся в ' + where + ' -- продолжаю');
            saveMusicState (server);
            scheduleVoiceStatus (server, true);
            schedulePresence (true);
        }
        else if (!people && !playing && !_noFollow && (m.current || m.tracks.length))
        {
            // [v2.18] Бот один и молчит, а автор музыки сидит в другом голосовом канале --
            // едем к нему: кто поставил трек, тот его и слушает.
            // [v2.27] Смотрим ВСЮ очередь вперёд, а не только текущий и следующий трек:
            // на длинном чужом плейлисте автор ближайшего нужного трека может быть и
            // третьим, и десятым -- раньше бот оставался в пустой комнате и очередь
            // стояла (см. pickAuthorChannel). Приоритет -- у автора НЕДОИГРАННОГО трека,
            // потом -- у автора ближайшего следующего.
            // [v2.27] Теперь это срабатывает на ЛЮБОЙ паузе, а не только на «нет
            // слушателей»: если человек сам поставил /pause и комната опустела, бот тоже
            // не должен стоять один там, где его никто не слышит. Паузу ЧЕЛОВЕКА при
            // переезде не снимаем (продолжит он сам), а нашу (pausedByNobody) снимает
            // ветка выше -- приехали туда, где слушатель есть.
            // Логика паузы/продолжения тут НЕ дублируется: после переезда checkListeners
            // вызывается заново и сам снимает паузу обычным путём (ветка выше), а от
            // бесконечной беготни между двумя авторами защищает _noFollow (второй
            // проход уже никого не догоняет).
            // [v2.28] Сначала -- режим «не ждать отсутствующих авторов»: если дальше по
            // очереди есть те, кто СЛУШАЕТ (а не просто добавил), их треки переставляются
            // вперёд, и мы играем именно им (подробности -- skipAbsentAuthors).
            if (skipAbsentAuthors (server, chId)) return checkListeners (server, true);
            const guildMove = client.guilds.cache.get (server);
            const found = pickAuthorChannel (server, chId);
            if (found && guildMove)
            {
                try
                {
                    joinVoice (server, found.ch, guildMove, 'в прошлой комнате никого, а автор трека ' +
                        (found.track.byName || u (found.track.byId)) + ' слушает здесь');
                    m.savedChannelId = found.ch.id;
                    // [v2.28] И сразу играем: раз приехали туда, где есть слушатель, пауза
                    // больше не нужна -- в том числе поставленная ЧЕЛОВЕКОМ (/pause):
                    // человек пришёл слушать музыку, а не тишину. Наша «нет слушателей»
                    // снимается веткой выше при повторном вызове, а вот человеческая
                    // осталась бы -- поэтому снимаем её здесь явно.
                    if (m.player.state.status === AudioPlayerStatus.Paused && !m.pausedByNobody)
                    {
                        m.playingSince = Date.now ();
                        try { m.player.unpause (); } catch { /* плеер мог быть пуст */ }
                        console.log ('[' + (d()) + '] [music] приехал туда, где есть слушатель -- снимаю паузу и продолжаю');
                        saveMusicState (server);
                        scheduleVoiceStatus (server, true);
                        schedulePresence (true);
                    }
                    return checkListeners (server, true);
                }
                catch (e)
                {
                    console.error ('[music] к автору трека не переехал: ' + oneLine (e.message));
                }
            }
        }
        // [v2.24] Бот уже в канале (вернулся после перезапуска), но очередь ждала
        // слушателя: человек зашёл -- начинаем с того же места, где остановились.
        // Это НЕ продолжение цепочки выше, а отдельная проверка.
        // [v2.34] ...и не только когда есть ЖДУЩИЙ трек: очередь могла сохраниться
        // вообще без «текущего» (бот сохранил состояние между треками и упал) -- тогда
        // m.seekTrack пуст, а играть всё равно есть что (m.tracks[0]). Раньше такая
        // очередь ждала вечно: комната полна, а бот молчит.
        if (people > 0 && m.pending && !m.current && (m.seekTrack || m.tracks.length))
        {
            const g = client.guilds.cache.get (server);
            const chHere = client.channels.cache.get (chId);
            if (g && chHere)
            {
                console.log ('[' + (d()) + '] [music] слушатель зашёл в ' + where + ' -- начинаю сохранённую очередь');
                startRestored (server, chHere, g);
            }
        }
        return;
    }
    // бота в канале нет, но есть ждущая очередь: заходим сами, если там появился человек
    if (!m.pending || m.leftByUser || !m.savedChannelId) return;
    const guild = client.guilds.cache.get (server);
    const ch = guild && guild.channels.cache.get (m.savedChannelId);
    if (!guild || !ch || !humansInChannel (server, ch.id)) return;
    startRestored (server, ch, guild);
}

function jsonToTrack (t)
{
    return { url: t.url, streamUrl: t.url, title: t.title || 'Без названия', duration: t.duration || 0,
             author: t.author || '', isLive: !!t.isLive, thumbnail: '', seek: t.seek || 0,
             byId: t.byId || null, byName: t.byName || '', addAt: Number (t.addAt) || 0,
             addIn: t.addIn || null }; // [v2.39] куда писать, если с треком что-то не так
}

// ============================================================================
// [v2.8] ПРОФИЛЬНЫЙ СТАТУС: «что бот делает» — видно везде, даже вне голосового.
//   слушает трек / смотрит канал, где сидит / свободен (ждёт команду).
// Discord лимитирует обновления presence, поэтому здесь та же схема, что у статуса
// канала: дебаунс + текст берётся В МОМЕНТ записи (на экране всегда актуальное).
// ============================================================================
const PRESENCE_MIN_GAP = 5000; // мс между обновлениями (лимит Discord на presence)
let $presenceTimer = null;
let $presenceLast = 0;
let $presenceDone = null; // что уже выставлено на экран (чтобы не дёргать API зря)

function presenceNow ()
{
    // если серверов несколько -- показываем самое интересное: трек важнее ожидания:
    let playing = null, waiting = null;
    for (let g in $music)
    {
        const m = $music[g];
        if (!m.connection) continue;
        const chId = m.connection.joinConfig.channelId;
        const ch = client.channels.cache.get (chId);
        const where = ch ? '«' + ch.name + '»' : 'голосовом канале';
        // хвост: что ещё ждёт и сколько людей в комнате (обе части -- только если есть)
        const people = humansInChannel (g, chId);
        const tail = (m.tracks.length ? ' · в очереди ' + m.tracks.length : '') +
            (people ? ' · в канале ' + people : '');
        if (m.current)
        {
            // [v2.11] у прямого эфира своя иконка -- 🔴 вместо 🎶 (длительности у него нет):
            // [v2.12] пауза «нет слушателей» -- 😴, чтобы по профилю было видно причину
            const icon = m.pausedByNobody ? '😴 '
                : (m.player.state.status === AudioPlayerStatus.Paused ? '⏸ '
                    : (m.current.isLive ? '🔴 ' : '🎶 '));
            const suffix = ' — ' + where + tail;
            // 128 символов -- лимит поля активности: режем НАЗВАНИЕ, а не хвост с очередью
            playing = icon + clipText (m.current.title || 'трек', 128 - icon.length - suffix.length) + suffix;
        }
        else if (!waiting)
            // [v2.34] Очередь ждёт слушателя (pending) -- это НЕ «музыка идёт»: бот зашёл
            // и молчит (в том числе после перезапуска в пустой канал). Помечаем прямо.
            waiting = (m.pending ? '⏸ ' + where + ' — жду слушателя' : '🎧 ' + where) + tail;
    }
    if (playing) return { type: ActivityType.Listening, name: playing };
    if (waiting) return { type: ActivityType.Watching, name: waiting };
    return { type: ActivityType.Playing, name: '/help · /play · /join' }; // свободен
}

function writePresence ()
{
    if (!client.user) return; // до ready менять нечего
    const want = presenceNow ();
    want.name = String (want.name).slice (0, 128); // лимит поля активности
    if ($presenceDone && $presenceDone.type === want.type && $presenceDone.name === want.name) return;
    $presenceDone = want;
    $presenceLast = Date.now ();
    try
    {
        client.user.setActivity ({ name: want.name, type: want.type });
    }
    catch (e)
    {
        console.error ('[' + (d()) + '] [presence] статус не выставился: ' + e.message);
        $presenceDone = null; // попробуем при следующем событии
    }
}

function schedulePresence (immediate = false)
{
    if ($presenceTimer) return; // уже запланировано -- текст возьмётся свежий в момент записи
    const wait = immediate ? Math.max (PRESENCE_MIN_GAP - (Date.now () - $presenceLast), 0) : PRESENCE_MIN_GAP;
    $presenceTimer = setTimeout (() => { $presenceTimer = null; writePresence (); }, wait);
}

// Подключение к голосовому каналу.
// [v2.10] Вынесено из connectTo: этим же путём пользуется возобновление музыки после
// перезапуска (там нет ни interaction, ни голосового канала участника -- есть id из базы).
// [v2.18] reason -- зачем переехали: попадает в строку лога («перешёл в «X» -- автор трека ...»).
// [v2.24] Настоящая работа -- в joinVoiceNow, а здесь обёртка: после каждого удачного
// захода/переезда присутствие бота уходит в базу (см. saveVoiceState).
function joinVoice (guildId, voiceChannel, guild, reason = '')
{
    const m = joinVoiceNow (guildId, voiceChannel, guild, reason);
    if (m && m.connection) saveVoiceState (guildId);
    return m;
}

function joinVoiceNow (guildId, voiceChannel, guild, reason = '')
{
    const m = musicOf (guildId);
    if (!voiceChannel) return m;
    m.justJoinedAt = Date.now (); // позвали -- к автору трека сразу не уезжаем (см. followTrackAuthor)
    if (!m.connection)
    {
        m.connection = joinVoiceChannel
        (
            {
                channelId: voiceChannel.id,
                guildId: guildId,
                adapterCreator: guild.voiceAdapterCreator,
                selfDeaf: false,
            }
        );
        console.log ('[' + (d()) + '] [music] подключился к «' + voiceChannel.name + '»'); // [v2.4] активное событие в лог
        m.since = Date.now (); // [v2.7] от этого считаем «бот тут N мин» в статусе
        // [v2.12] новый заход отменяет «уходим»/«ждём»: очередь снова играет
        m.leaving = false;
        m.pending = false;
        m.leftByUser = false;
        m.selfLeftAt = 0; // [v2.30] зашли заново -- старую отметку о выходе забываем
        m.savedChannelId = voiceChannel.id;
        // [v2.12] обработчики плеера -- ОДИН раз на плеер (раньше вешались при каждом
        // новом подключении, а теперь состояние живёт дольше соединения)
        if (!m.playerWired)
        {
            m.playerWired = true;
            m.player.on (AudioPlayerStatus.Idle, () =>
            {
                // [v2.35] Причина смерти потока (если yt-dlp её сказал) -- ДО затирания
                // ручки: по ней ниже отличаем «видео больше нет» от обычного обрыва.
                const _deadErr = (m.streamHandle && m.streamHandle.proc) ? m.streamHandle.proc.lastErr : null;
                // [v2.14] Трек (любой: доигравший, пропущенный /skip, /stop, /leave)
                // больше не звучит -- закрываем его поток. Иначе yt-dlp вместе с
                // ffmpeg оставались жить в памяти до конца работы бота.
                killStream (m.streamHandle);
                m.streamHandle = null;
                if (m.leaving) return; // [v2.9] это Idle от нашего же выхода, а не конец трека
                // [v2.30] СМЕРТЬ ПОТОКА ВЫГЛЯДИТ КАК КОНЕЦ ТРЕКА -- И ТРЕК МОЛЧА ПРОПАДАЛ.
                // Когда yt-dlp/ffmpeg умирают на середине (или возобновление «с места»
                // отдаёт пустой фрагмент), 'error' у потока не приходит: приходит Idle,
                // и очередь просто ехала дальше -- а человек терял свой трек (нашёл
                // живой прогон: возобновлённый сет умер через 7 секунд и пропустился).
                // Ошибки потока ловил только wireStreamErrors, а этот путь был пуст.
                // Теперь трек, который ФИЗИЧЕСКИ не мог кончиться, возвращается в очередь
                // и играет снова (бюджет повторов -- тот же, что у обрыва потока).
                const playing = m.current;
                const at = playing ? Math.round (playedMsOf (m) / 1000) : 0;
                const asked = !!m.skipRequested; // /skip и /jump -- осознанный уход вперёд
                m.skipRequested = false;
                // [v2.35] ВИДЕО БОЛЬШЕ НЕТ -- ЭТО НЕ ОБРЫВ: продолжать нечего, повтор не
                // поможет. Убираем сразу и говорим людям (раньше падало в лог голым
                // 'Video unavailable', а трек молча пропадал из очереди).
                if (playing && !asked && isGoneError (_deadErr))
                {
                    console.error ('[' + (d()) + '] [music] видео больше нет на YouTube (' + (playing.title || 'трек') +
                        ') -- убираю из очереди: ' + ytDlpErr (_deadErr, 120));
                    deadDropNote (guildId); // [v2.43] реальная причина убрать трек -- он не сыграл
                    trackNotice (guildId, playing, '🗑 **' + (playing.title || 'Трек') + '** -- видео больше нет на YouTube, убираю из очереди.');
                    m.current = null;
                    m.playedMs = 0;
                    m.playingSince = null;
                    m.streamRetries = 0;
                    playNext (guildId);
                    return;
                }
                if (playing && !asked && streamEndedEarly (playing, at, m.startedAtSec))
                {
                    const attempt = (m.streamRetries || 0) + 1;
                    if (attempt <= MUSIC_STREAM_RETRIES)
                    {
                        // Возобновили с места -- и почти сразу замолчало? Значит сдвиг
                        // этому источнику противопоказан: играем тот же трек С НАЧАЛА,
                        // лишь бы не потерять его совсем (как обещано владельцу).
                        const fromStart = !!(m.startedFromSeek && at < (m.startedAtSec || 0) + 15);
                        const seekTo = fromStart ? 0 : at;
                        m.streamRetries = attempt;
                        m.playedMs = seekTo * 1000;
                        m.playingSince = null;
                        m.current = null;
                        m.tracks.unshift (playing);
                        m.seekTrack = playing;
                        m.seekSec = seekTo;
                        console.error ('[' + (d()) + '] [music] поток оборвался (' +
                            (at ? 'на ' + fmtDur (at) : 'в самом начале') + ') -- трек не бросаю: играю его ' +
                            (fromStart ? 'с начала (продолжение с места не вышло)' : 'с этой же секунды') +
                            ', попытка ' + attempt + '/' + MUSIC_STREAM_RETRIES);
                        saveMusicState (guildId);
                        playNext (guildId); // плеер уже Idle -- сразу к тому же треку
                        return;
                    }
                    console.error ('[' + (d()) + '] [music] поток обрывается снова (' + attempt +
                        ' раз) -- пропускаю: ' + (playing.title || 'трек'));
                }
                // трек кончился -- следующий:
                m.current = null;
                m.playedMs = 0;
                m.playingSince = null;
                m.streamRetries = 0;
                playNext (guildId);
            });
            m.player.on ('error', e => console.error ('[music] ошибка плеера: ' + oneLine (e.message)));
        }
        m.connection.subscribe (m.player);
        m.connection.on (VoiceConnectionStatus.Disconnected, async () =>
        {
            try
            {
                await entersState (m.connection, VoiceConnectionStatus.Signalling, 5_000);
            }
            catch
            {
                // канал закрылся / связь не вернулась -- уходим из канала, но очередь
                // НЕ теряем ([v2.12] unexpected: вернёмся сами, когда в канале появится слушатель)
                destroyMusic (guildId, { unexpected: true });
            }
        });
        scheduleVoiceStatus (guildId, true); // [v2.7] показать статус сразу
        schedulePresence (true);             // [v2.8] «смотрит канал»
        return m;
    }
    // пересоединение в другой канал («вызвали в другую комнату»):
    if (m.connection.joinConfig.channelId !== voiceChannel.id)
    {
        const oldChId = m.connection.joinConfig.channelId;
        m.connection.rejoin ({ channelId: voiceChannel.id });
        m.savedChannelId = voiceChannel.id;
        // [v2.7] активное событие в лог: переезд раньше нигде не писался
        console.log ('[' + (d()) + '] [music] перешёл в «' + voiceChannel.name + '»' + (reason ? ' -- ' + reason : ''));
        // [v2.7] статус живёт в канале: из старого снимаем, в новом пишем заново
        clearVoiceStatus (oldChId);
        scheduleVoiceStatus (guildId, true);
        schedulePresence (true); // [v2.8] название канала в статусе тоже сменилось
    }
    return m;
}

// Подключение к каналу вызывающего (слэш-команды):
function connectTo (interaction)
{
    return joinVoice (interaction.guildId, interaction.member.voice.channel, interaction.guild);
}

// ============================================================================
// [v2.32] ВХОД И ВЫХОД ОДНОЙ ДОРОГОЙ: и для слэш-команд, и для кнопок под /queue.
// /join («Вход») и /leave («Выход») раньше жили только в обработчике слэша, а кнопки
// были бы их второй копией -- две копии одной логики разъезжаются (уже проходили).
// ============================================================================

// «Вход»: зайти в канал того, кто позвал, и остаться там. Вся защита от перехвата --
// здесь, поэтому кнопка и команда ведут себя одинаково.
async function joinMusicChannel (interaction)
{
    const guildId = interaction.guildId;
    const m = musicOf (guildId);
    const voiceChannel = interaction.member && interaction.member.voice ? interaction.member.voice.channel : null;
    if (!voiceChannel)
        return interaction.reply ({ content: '🔊 Сначала зайди в голосовой канал!', flags: MessageFlags.Ephemeral });
    const here = !!m.connection && m.connection.joinConfig.channelId === voiceChannel.id;
    // [v2.18] ЗАЩИТА ОТ ПЕРЕХВАТА. Бот играет для АВТОРА трека: тот, кто его
    // добавил, слушает его в своей комнате. Значит /join от другого DJ увёл бы
    // бота прямо посреди прослушивания -- отказываем (тот же смысл, что «кто
    // первый, тот и прав» у /play). Уйти можно только по-честному: /skip, /stop,
    // когда автор сам уйдёт или когда дойдёт до трека другого автора.
    // Если автор ушёл (или его и не было), а бот играет кому-то в другой комнате --
    // /join разрешён, но в ответе и в логе будет сказано, что слушатели остаются.
    const myChId = m.connection ? m.connection.joinConfig.channelId : null;
    let stoleNote = '';
    if (myChId && myChId !== voiceChannel.id && m.current && !m.leaving)
    {
        const whoCall = interaction.member ? uuu (interaction.member) : interaction.user.username;
        const mineCh0 = client.channels.cache.get (myChId);
        const mineName0 = mineCh0 ? '«' + mineCh0.name + '»' : 'другом канале';
        if (authorVoiceId (guildId, m.current) === myChId)
        {
            const title = m.current.title || 'трек';
            const authorName = m.current.byName || u (m.current.byId);
            console.log ('[' + (d()) + '] [music] (кто: ' + whoCall + ') /join отклонён: играю для автора трека ' +
                authorName + ' в ' + mineName0);
            return interaction.reply
            ({
                content: '🎧 Не перееду: я играю **' + title + '** в ' + mineName0 +
                    ' для автора трека (' + authorName + ').\n' +
                    'Увести можно, когда он уйдёт, или командами `/skip` / `/stop` ✌️',
                flags: MessageFlags.Ephemeral,
            });
        }
        if (humansInChannel (guildId, myChId) > 0)
        {
            stoleNote = '🎧 В ' + mineName0 + ' оставались слушатели -- теперь они без музыки';
            console.log ('[' + (d()) + '] [music] (кто: ' + whoCall + ') /join увёл бота из ' + mineName0 +
                ' (автора трека там нет, но слушатели оставались)');
        }
    }
    connectTo (interaction);
    // [v2.7] куда писать уведомления (например «трек не воспроизвёлся»), если
    // /join был первым вызовом, а /play никто не делал:
    m.textChannelId = interaction.channelId;
    scheduleDeadScan (guildId); // [v2.41] собрались играть -- проверим очередь заранее
    // [v2.12] у бота может быть сохранённая очередь (после /leave, обрыва или
    // перезапуска) -- продолжаем её С МЕСТА, а не с чистого листа
    let resume = '';
    if (!m.current && m.tracks.length)
    {
        const next = m.tracks[0];
        const at = (m.seekTrack === next && m.seekSec) ? (next.isLive ? '' : ' с ' + fmtDur (m.seekSec)) : '';
        playNext (guildId);
        resume = ' Продолжаю очередь: **' + (next.title || 'трек') + '**' + at +
            (m.tracks.length ? ' (далее ещё ' + m.tracks.length + ')' : '');
    }
    // Из слэш-команды ответ видят все (это событие в канале), а из кнопки -- только
    // нажавший: иначе каждое нажатие «Войти» добавляло бы в чат новое сообщение.
    const fromButton = typeof interaction.isButton === 'function' && interaction.isButton ();
    return interaction.reply
    ({
        content: (here
            ? '🎧 Я уже тут: **' + voiceChannel.name + '**. Выйти -- `/leave`.'
            : '🎧 Зашёл в **' + voiceChannel.name + '** и остаюсь. Выйти -- `/leave`.') +
            (stoleNote ? '\n' + stoleNote : '') +
            resume,
        ...(fromButton ? { flags: MessageFlags.Ephemeral } : {}),
    });
}

// ============================================================================
// [v2.32] «ВЫХОД» (ОТ /leave) ГЛАЗАМИ АВТОРА -- МЯГКИЙ, А НЕ ГРУБЫЙ.
// Раньше /leave сразу выводил бота из канала, и чужая музыка обрывалась на середине:
// один DJ ушёл -- слушают тишину. Теперь смысл тот, что и задумывался: человек просто
// ОТКЛАДЫВАЕТ СВОИ ТРЕКИ (как /pause, только до его возвращения), а бот продолжает
// играть для остальных -- и даже переезжает к следующему автору, если тот в другом
// канале (переезд делает сам playNext: см. followTrackAuthor).
// Место в отложенном треке НЕ теряется: оно уезжает вместе с ним (track.seek) и
// восстанавливается, когда до него снова дойдёт (и перезапуск это переживает).
// Крайний случай: кроме его треков играть нечего -- тогда это обычный выход из канала
// (очередь и место остаются в базе, продолжит по /join|«Вход»).
// ============================================================================
function leaveMusicVoice (guildId, actorId, who)
{
    const m = musicOf (guildId);
    if (!m.connection) return { ok: false, text: '🤷 Я и так не в голосовом канале.' };
    const mine = t => !!t && isBy (t, actorId);
    const mineNow = !!(m.current && mine (m.current));
    const mineQ = m.tracks.filter (mine).length;
    const othersLeft = m.tracks.some (t => !mine (t)) || (!!m.current && !mine (m.current));
    // Откладывать нечего (у него вообще нет треков) ИЛИ, кроме его записей, играть
    // нечего -- это честный выход из канала, как раньше.
    if ((!mineNow && !mineQ) || !othersLeft)
    {
        destroyMusic (guildId); // очередь и место при этом НЕ теряются
        const rest = m.tracks.length;
        return {
            ok: true,
            text: '👋 Вышел из голосового канала.' +
                (rest
                    ? ' Очередь помню: ' + rest + ' ' + plural (rest, 'трек', 'трека', 'треков') +
                      (m.seekTrack ? ' (начиная с **' + (m.seekTrack.title || 'трек') + '**' +
                          (m.seekSec && !m.seekTrack.isLive ? ' с ' + fmtDur (m.seekSec) : '') + ')' : '') +
                      ' -- продолжу по «Вход» (`/join`).'
                    : ''),
        };
    }
    // --- мягкий выход: его треки -- в конец очереди, играющий -- с сохранением места ---
    const pos = m.current ? Math.max (0, Math.round (playedMsOf (m) / 1000)) : 0;
    const moved = [], rest = [];
    for (const t of m.tracks) (mine (t) ? moved : rest).push (t);
    if (m.current && mine (m.current))
    {
        const t = m.current;
        if (pos > 0 && !t.isLive) t.seek = pos; // место едет вместе с треком
        moved.unshift (t);
    }
    if (m.seekTrack && mine (m.seekTrack))
    {
        if (!m.seekTrack.seek) m.seekTrack.seek = Math.max (0, Math.round (m.seekSec || 0));
        m.seekTrack = null;
        m.seekSec = 0;
    }
    m.tracks = rest.concat (moved);
    m.current = null;
    m.playedMs = 0;
    m.playingSince = null;
    m.pausedByNobody = false;
    dropPreload (m);
    saveMusicState (guildId);
    try { m.player.stop (true); } catch (e) { /* плеер мог быть пуст -- не страшно */ }
    scheduleVoiceStatus (guildId, true);
    schedulePresence (true);
    const next = m.tracks[0];
    const posTxt = pos ? ' (продолжу с ' + fmtDur (pos) + ')' : '';
    console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'отложил свои треки (' + moved.length + ')' +
        (pos ? ' вместе с местом в треке ' + fmtDur (pos) : '') +
        ' -- они уехали в конец очереди' + (next ? '; играю дальше: ' + (next.title || 'трек') : ''));
    return {
        ok: true,
        text: '⏸ Отложил твои треки (' + moved.length + ' ' + plural (moved.length, 'трек', 'трека', 'треков') +
            ')' + posTxt + ' -- они в конце очереди, уберутся сами, когда доиграют.' +
            (next ? ' Играю дальше: **' + (next.title || 'трек') + '**' : '') +
            '\n_Это не выход бота: чтобы он ушёл из канала -- `⏹ Очистка/Выход` (или `/stop`),' +
            ' а чтобы вернуть свои треки назад -- `⬆ Поднять` в меню автора._',
    };
}

// Выход из канала. [v2.12] Очередь при этом НЕ стирается: забывает её только /stop
// (forget: true) . По /leave бот запоминает и очередь, и место в треке и продолжит,
// когда его позовут /join (или попросят /play); при обрыве связи -- попробует сам.
function destroyMusic (guildId, opts = {})
{
    const m = $music[guildId];
    if (!m) return;
    // [v2.30] Выход инициировали МЫ (это /stop, /leave, конец очереди или обработчик
    // обрыва), а не админ, выкинувший бота из канала. Без этой отметки следующее
    // событие voiceStateUpdate принимало наш собственный выход за «бота выкинули» и
    // писало 'очередь помню' даже сразу после /stop, который очередь как раз стёр.
    m.selfLeftAt = Date.now ();
    // [v2.7] активное событие в лог: «вышел» раньше нигде не писалось,
    // а по логу должно быть видно и заход, и выход:
    const chId = (m.connection && m.connection.joinConfig ? m.connection.joinConfig.channelId : null) ||
        m.savedChannelId || null;
    const ch = chId ? client.channels.cache.get (chId) : null;
    // [v2.9] player.stop() синхронно шлёт Idle, а его обработчик запускает следующий трек.
    // На выходе это означало лишний yt-dlp: ставим флаг и фиксируем позицию ДО stop().
    const at = Math.round (playedMsOf (m) / 1000);
    m.leaving = true;
    m.playedMs = at * 1000;
    m.playingSince = null;
    dropPreload (m); // [v2.9] убираем за собой: заготовка следующего трека тоже не нужна
    // [v2.14] Глушим играющий поток явно: если плеер уже в Idle, stop() не сработает
    // и без этой строки процессы yt-dlp/ffmpeg остались бы висеть.
    killStream (m.streamHandle);
    m.streamHandle = null;
    try { m.player.stop (true); } catch {}
    try { m.connection.destroy (); } catch {}
    m.connection = null;
    if (opts.forget) // /stop -- очередь больше не нужна
    {
        m.tracks = [];
        m.current = null;
        m.seekTrack = null;
        m.seekSec = 0;
        m.playedMs = 0;
        m.pending = false;
        m.pausedByNobody = false;
        m.playedToSomeone = false;
        clearMusicState (guildId);
    }
    else // /leave или обрыв: очередь, текущий трек и место -- в базу
    {
        if (m.current)
        {
            m.tracks.unshift (m.current); // «текущий» встаёт в начало очереди
            m.seekTrack = m.current;      // ...и playNext продолжит его с этой позиции
            m.seekSec = at;
        }
        m.current = null;
        m.pending = true;
        m.pausedByNobody = false;
        m.leftByUser = !opts.unexpected; // /leave -- сами не возвращаемся; обрыв -- вернёмся
        saveMusicState (guildId);
    }
    // [v2.24] Присутствие: при обрыве связи (или когда бота выкинули из канала) тот же
    // канал остаётся в записи -- при следующем запуске бот вернётся туда сам. А вот
    // /leave и /stop -- это явный выход: канал забываем совсем.
    if (opts.unexpected && !opts.forget) writeVoiceState (guildId, chId, false);
    else writeVoiceState (guildId, null, false);
    // [v2.7] снимаем статус: иначе в канале останется старая строка
    clearVoiceStatus (chId);
    if ($voiceStatus[guildId] && $voiceStatus[guildId].timer)
        clearTimeout ($voiceStatus[guildId].timer);
    delete $voiceStatus[guildId];
    schedulePresence (true); // [v2.8] вышел -- статус снова «свободен»
    if (chId)
        console.log ('[' + (d()) + '] [music] вышел из «' + (ch ? ch.name : chId) + '»' +
            (opts.forget
                ? ' (очередь очищена)'
                : ' (очередь сохранена' + (opts.unexpected ? ', обрыв связи' : '') + ': ' +
                  (m.seekTrack ? (m.seekTrack.title || 'трек') + ' ждёт, ' : '') +
                  restCount (m) + ' далее)'));
}

// Форматирование длительности. isLive -- ПРЯМОЙ ЭФИР: у него длительности нет
// и быть не может, поэтому показываем 🔴 LIVE. Если же длительность просто
// неизвестна (yt-dlp не отдал число), это НЕ эфир -- показываем '--:--'
// (раньше такое превращалось в «🔴 LIVE» и путало обычный трек с трансляцией).
function fmtDur (sec, isLive = false)
{
    if (isLive) return '🔴 LIVE';
    if (!sec || sec <= 0) return '--:--';
    let h = sec / 3600 | 0, m = sec % 3600 / 60 | 0, s = sec % 60 | 0;
    return (h ? h + ':' + pad(m) : pad(m)) + ':' + pad(s);
}

// «Что играет» одной строкой: «🎶 Название — 03:35» / «🔴 Название» (эфир, у него
// иконка уже сама всё говорит) / «⏸ Название — 03:35» (пауза).
function nowPlayingLine (t, paused = false)
{
    if (!t) return null;
    return (paused ? '⏸ ' : (t.isLive ? '🔴 ' : '🎶 ')) + (t.title || 'трек') +
        (t.isLive ? '' : ' — ' + fmtDur (t.duration));
}

// Определение: ссылка или текстовый поиск:
function isUrl (s)
{
    return /^https?:\/\//i.test (s);
}

// Слэш-команды:
const musicCommands =
[
    // [v2.6] /help -- та же инструкция, что в стартовой ЛС, видна только вызвавшему
    // (доступна всем, без DJ и без голосового канала):
    new SlashCommandBuilder ()
        .setName ('help')
        .setDescription ('Инструкция: как пользоваться ботом'),
    new SlashCommandBuilder ()
        .setName ('play')
        .setDescription ('Добавить в очередь: ссылка (YouTube/плейлист/эфир) или поиск')
        .addStringOption (o =>
            o.setName ('запрос')
             .setDescription ('Ссылка или название трека')
             .setRequired (true)),
    // [v2.7] /join -- просто зайти в канал и сидеть (музыка не нужна):
    new SlashCommandBuilder ()
        .setName ('join')
        .setDescription ('Зайти в твой голосовой канал и остаться там (даже без музыки)'),
    new SlashCommandBuilder ()
        .setName ('stop')
        .setDescription ('Остановить музыку и очистить очередь'),
    new SlashCommandBuilder ()
        .setName ('skip')
        .setDescription ('Пропустить текущий трек -- своего (у админов и модеров -- любого)'),
    // [v2.12] управление очередью (DJ): убрать трек, очистить очередь, прыгнуть к номеру
    new SlashCommandBuilder ()
        .setName ('remove')
        .setDescription ('Убрать трек из очереди по номеру')
        .addIntegerOption (o =>
            o.setName ('number')
             .setDescription ('Номер трека в очереди (см. /queue)')
             .setMinValue (1)
             .setRequired (true)),
    new SlashCommandBuilder ()
        .setName ('move')
        .setDescription ('Переставить трек в очереди на другое место')
        .addIntegerOption (o =>
            o.setName ('number')
             .setDescription ('Какой трек двигать (номер из /queue)')
             .setMinValue (1)
             .setRequired (true))
        .addIntegerOption (o =>
            o.setName ('to')
             .setDescription ('На какое место поставить (номер из /queue)')
             .setMinValue (1)
             .setRequired (true)),
    // [v2.26] /clear теперь глушит и играющий трек (раньше он «доигрывал» и получалось
    // ничейно), поэтому и описание говорит ровно это.
    new SlashCommandBuilder ()
        .setName ('clear')
        .setDescription ('Очистить очередь и остановить музыку (выйти, но помнить -- /leave)')
        .addUserOption (o =>
            o.setName ('author')
             .setDescription ('Убрать ТОЛЬКО треки этого человека (без него -- вся очередь)')),
    // [v2.27] /push -- поднять треки одного автора наверх очереди (только админы/модеры:
    // обычному DJ это дало бы возможность переставлять чужое и превратило бы очередь в
    // бардак). Без аргумента -- свои треки (удобно тестировать, не ища свой ник).
    new SlashCommandBuilder ()
        .setName ('push')
        .setDescription ('Поднять треки автора наверх очереди (DJ -- свои, админы/модеры -- любые)')
        .addUserOption (o =>
            o.setName ('author')
             .setDescription ('Чьи треки поднять (без него -- твои; чужого -- только админы/модеры)')),
    new SlashCommandBuilder ()
        .setName ('jump')
        .setDescription ('Перейти сразу к треку (DJ -- по своим, админы/модеры -- любым)')
        .addIntegerOption (o =>
            o.setName ('number')
             .setDescription ('Номер трека в очереди (см. /queue)')
             .setMinValue (1)
             .setRequired (true))
        // [v2.56] ДВА ВАРИАНТА ПЕРЕХОДА. По умолчанию -- «срочный»: ничего не теряется,
        // прерванный трек [v2.63] встаёт СРАЗУ ЗА целью (заиграет следующим, с того же
        // места), а остальная очередь не двигается. Второй -- «обрезать до трека»:
        // всё до цели убирается насовсем (это и есть «чистка», только одним движением).
        .addStringOption (o =>
            o.setName ('mode')
            .setDescription ('Что делать с тем, что стояло до него (без ответа -- спрошу кнопками)')
            .addChoices (
                { name: 'Срочный переход -- прерванный трек заиграет следующим', value: 'urgent' },
                { name: 'Обрезать до трека -- всё до него убрать насовсем', value: 'cut' })),
    // [v2.32] /seek -- перейти к другому месту ВНУТРИ текущего трека (у DJ были
    // только «следующий» и «прыжок по очереди», а перемотать было нечем).
    new SlashCommandBuilder ()
        .setName ('seek')
        .setDescription ('Перейти к другому месту в текущем треке -- своего (время: 1:30, 83 или 0:05)')
        .addStringOption (o =>
            o.setName ('time')
             .setDescription ('Куда перейти: 90, 1:30 или 1:02:03 (0 -- с начала)')
             .setRequired (true)),
    new SlashCommandBuilder ()
        .setName ('pause')
        .setDescription ('Пауза'),
    new SlashCommandBuilder ()
        .setName ('resume')
        .setDescription ('Продолжить воспроизведение'),
    // [v2.14] /bans -- кто сейчас в наказании: имя, точный срок, причина (только staff).
    // Ответ виден только вызвавшему (ephemeral), вызов фиксируется в логе как и все команды.
    new SlashCommandBuilder ()
        .setName ('bans')
        .setDescription ('Активные баны и таймауты: кто, до какого времени и за что (админы/модеры)'),
    // [v2.15] /unban -- снять наказание вручную (админы/модеры). Ответ виден только
    // вызвавшему; снятие попадает и в журнал, и в историю (/bans).
    new SlashCommandBuilder ()
        .setName ('unban')
        .setDescription ('Снять таймаут или бан с человека (админы/модеры)')
        .addUserOption (o =>
            o.setName ('user')
             .setDescription ('С кого снять наказание')
             .setRequired (true))
        .addStringOption (o =>
            o.setName ('reason')
             .setDescription ('Причина снятия (уйдёт в журнал и в аудит Discord)')
             .setMaxLength (400)), // [v2.24] в журнале аудита Discord -- до 512 символов
    // [v2.17] /rolecheck -- что бот помнит о человеке: роли, наказания и что именно
    // он вернёт при следующем входе (админы/модеры). Работает и для того, кто не
    // на сервере: данные лежат в базе по id.
    // [v2.18] /announce и /dm -- замена текстовым командам, ради которых раньше был нужен
    // интент Message Content: слэш-команды не требуют привилегированных интентов.
    new SlashCommandBuilder ()
        .setName ('announce')
        .setDescription ('Опубликовать объявление от имени бота (админы/модеры)')
        .addStringOption (o =>
            o.setName ('text')
             .setDescription ('Текст объявления')
             .setMaxLength (2000) // [v2.24] лимит сообщения Discord -- пусть форма сама не даст превысить
             .setRequired (true))
        .addAttachmentOption (o =>
            o.setName ('file')
             .setDescription ('Вложение к объявлению (картинка, файл)'))
        .addChannelOption (o =>
            o.setName ('channel')
             .setDescription ('Куда опубликовать (по умолчанию -- в этот канал)')),
    new SlashCommandBuilder ()
        .setName ('dm')
        .setDescription ('Отправить человеку личное сообщение от имени бота (только админы)')
        .addUserOption (o =>
            o.setName ('user')
             .setDescription ('Кому')
             .setRequired (true))
        .addStringOption (o =>
            o.setName ('text')
             .setDescription ('Текст сообщения (можно без текста, если есть файл)')
             .setMaxLength (2000)) // [v2.24] лимит сообщения Discord
        .addAttachmentOption (o =>
            o.setName ('file')
             .setDescription ('Вложение (картинка, файл)')),
    // [v2.18] /welcome -- замена текстовой `panda welcome` (та требовала интента
    // Message Content): присылает в ЛС ровно то приветствие, которое видят новички.
    new SlashCommandBuilder ()
        .setName ('welcome')
        .setDescription ('Проверить приветствие: бот пришлёт в ЛС то, что видят новички')
        .addUserOption (o =>
            o.setName ('user')
             .setDescription ('Кому прислать проверку (без него -- себе; другому -- админ/модер)')),
    // [v2.18] /forget -- удаление всего, что бот помнит о человеке (роли, история
    // наказаний). Нужен и по делу, и как ответ в форме интентов на вопрос «как
    // запросить удаление данных о своих действиях».
    new SlashCommandBuilder ()
        .setName ('forget')
        .setDescription ('Удалить сохранённые данные о человеке: роли и история наказаний (staff)')
        .addUserOption (o =>
            o.setName ('user')
             .setDescription ('Чьи данные удалить')
             .setRequired (true)),
    // [v2.18] Правый клик по сообщению -> «Переслать в общий»: то же, что делает мост
    // из пандалогии, но БЕЗ интента Message Content (Discord отдаёт выбранное сообщение
    // целиком, вместе с текстом и вложениями). Работает и как основная замена мосту,
    // если Discord отзовёт интент 9 октября 2026.
    new ContextMenuCommandBuilder ()
        .setName ('Переслать в общий')
        .setType (ApplicationCommandType.Message),
    new SlashCommandBuilder ()
        .setName ('rolecheck')
        .setDescription ('Что бот помнит о человеке: роли, наказания и что вернёт при входе (staff)')
        .addUserOption (o =>
            o.setName ('user')
             .setDescription ('Кого проверить (можно любого, не только участника сервера)')
             .setRequired (true)),
    // [v2.22] /mydata -- «что бот помнит обо мне»: о себе может каждый, о другом -- staff.
    // Это и прозрачность для людей, и понятный ответ на вопрос «как человек видит и
    // удаляет свои данные» (в форме интентов такой вопрос есть).
    new SlashCommandBuilder ()
        .setName ('mydata')
        .setDescription ('Что бот помнит лично о тебе (роли, наказания, очередь) и как это удалить')
        .addUserOption (o =>
            o.setName ('user')
             .setDescription ('О ком посмотреть (только админ/модер; без него -- о себе)')),
    // [v2.22] /rekey -- смена ключа шифрования базы. Только владелец бота (id в OWNER):
    // операция идёт по ВСЕМ данным сразу, а новый ключ печатается в консоль.
    // В списке команд видят только админы (иначе она мозолила бы глаза всем).
    new SlashCommandBuilder ()
        .setName ('rekey')
        .setDescription ('Сменить ключ шифрования базы (только владелец бота)')
        .setDefaultMemberPermissions (PermissionsBitField.Flags.Administrator),
    new SlashCommandBuilder ()
        .setName ('queue')
        .setDescription ('Показать очередь треков')
        .addIntegerOption (o =>
            o.setName ('from')
             .setDescription ('С какого номера показать (сколько на странице -- ключ queue_page, по умолчанию 15)')
             .setMinValue (1)),
    // [v2.44] /nowplaying -- «что играет ПРЯМО СЕЙЧАС» одной карточкой (для всех, как
    // /queue): трек, позиция и остаток, кто поставил, сколько слушает, что дальше.
    new SlashCommandBuilder ()
        .setName ('nowplaying')
        .setDescription ('Что играет сейчас: трек, позиция, кто поставил и что дальше'),
    // [v2.54] /history -- кто, когда и что ставил (треки, эфиры и целые плейлисты).
    // Смотреть может каждый, как /queue: это информация, а не действие.
    // Сколько пачек помнить -- ключ MUSIC.history_len (по умолчанию 25).
    new SlashCommandBuilder ()
        .setName ('history')
        .setDescription ('История добавлений: кто, когда и что поставил (треки, эфиры, плейлисты)'),
    new SlashCommandBuilder ()
        .setName ('leave')
        .setDescription ('Отложить свои треки и играть чужое; из канала выхожу, если играть нечего'),
].map (c => c.toJSON ());

// Регистрация команд на всех разрешённых серверах (guild-команды -- мгновенно):
async function registerMusicCommands ()
{
    const rest = new REST ({ version: '10' }).setToken (TOKEN);
    for (let server in SERVERS)
    {
        if (!SERVERS[server].allow) continue;
        try
        {
            await rest.put
            (
                Routes.applicationGuildCommands (ID, server),
                { body: musicCommands }
            );
            console.log ('[' + (d()) + '] [music] команды зарегистрированы (слэш + «Переслать в общий» на сообщении) @ ' + SERVERS[server].name);
        }
        catch (e)
        {
            console.error ('[music] ошибка регистрации команд @ ' + server + ': ' + e.message);
        }
    }
}

// Обработка слэш-команд:
client.on ('interactionCreate', async (interaction) =>
{
    // [v2.14] Кнопки и меню под ответом /queue:
    //   ◀/▶ -- листание (номер страницы зашит в customId, состояние между нажатиями
    //           не нужно, содержимое берётся из ЖИВОЙ очереди);
    //   ⏭ / 🧹 / 🗑 -- частые действия (любой DJ, а не только тот, кто открыл очередь).
    // [v2.36] ОКНО ВВОДА НОМЕРА («#️⃣ На позицию…»): кнопками «⬆ Выше» сороковой трек в
    // начало не перетащить, а тут сразу видно, что вводить.
    if (typeof interaction.isModalSubmit === 'function' && interaction.isModalSubmit ())
    {
        const guildId = interaction.guildId;
        if (!(guildId in SERVERS)) return;
        // [v2.44] «⏱ На таймкод…» -- перемотка ВНУТРИ текущего трека тем же путём, что
        // /seek (никакой второй логики). Здесь -- роль DJ (окно приходит не через гейт
        // кнопок, так что проверяем сами), а [v2.50] на ЧУЖОЙ трек откажет уже
        // seekMusic -- там же, где это делают кнопки ±30 с и слэш-команда.
        if (/^q:skt:(\d+)$/.test (interaction.customId || ''))
        {
            const page0 = parseInt (/^q:skt:(\d+)$/.exec (interaction.customId)[1], 10) || 1;
            if (!isDJ (interaction))
            {
                const role_dj = SERVERS[guildId].role_dj || '';
                return interaction.reply
                (
                    {
                        content: '🚫 Музыка только для ' + (role_dj ? '<@&' + role_dj + '>' : 'DJ'),
                        flags: MessageFlags.Ephemeral,
                    }
                );
            }
            const m0 = musicOf (guildId);
            const raw0 = String (interaction.fields.getTextInputValue ('time') || '').trim ();
            const who0 = interaction.member ? uuu (interaction.member) : interaction.user.username;
            const to0 = parseSeekTime (raw0);
            if (to0 === null)
                return interaction.reply
                (
                    {
                        content: '🤔 Не понял время: `' + raw0.slice (0, 20) + '`.\n' +
                            'Напиши, куда перемотать: `90` (секунды), `1:30` (минуты) или `1:02:03`.',
                        flags: MessageFlags.Ephemeral,
                    }
                );
            const res0 = seekMusic (guildId, to0, who0,
                { actorId: interaction.user.id, actorName: who0, staff: isStaffInteraction (interaction) });
            if (!res0.ok)
                return interaction.reply ({ content: res0.text, flags: MessageFlags.Ephemeral });
            // [v2.35] Сообщение очереди перерисовываем ЧУТЬ ПОЗЖЕ: сразу после перемотки
            // плеер ещё перезапускается, и в строке «Сейчас» стоял бы прочерк.
            const ctx0 = { actorId: interaction.user.id, actorName: who0, staff: isStaffInteraction (interaction) };
            setTimeout (() =>
            {
                const view0 = queueView (m0, page0, 0, ctx0);
                if (interaction.message && typeof interaction.message.edit === 'function')
                    interaction.message.edit ({ content: view0.content, components: view0.components, allowedMentions: { parse: [] } }).catch (() => {});
            }, 1500);
            return interaction.reply ({ content: res0.text, flags: MessageFlags.Ephemeral });
        }
        // [v2.66] Окно ввода номера для «⤴ Перепрыгнуть» (q:jumpm) убрано: теперь у кнопки
        // СПИСОК треков (jumpPickerRows -> q:jsel), номер набирать не нужно. Ветка удалена
        // целиком, чтобы не осталось недостижимого кода.
        const mMpos = /^q:mpos:(\d+)$/.exec (interaction.customId || '');
        if (!mMpos) return;
        const m = musicOf (guildId);
        const n = parseInt (mMpos[1], 10) || 0;
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        const staff2 = isStaffInteraction (interaction);
        const to = parseInt (String (interaction.fields.getTextInputValue ('pos') || '').replace (/\D+/g, ''), 10);
        if (!Number.isInteger (to) || to < 1 || to > m.tracks.length)
            return interaction.reply ({ content: '🤔 В очереди ' + m.tracks.length + ' треков -- номер от 1 до ' + m.tracks.length + '.', flags: MessageFlags.Ephemeral });
        const res = queueMove (guildId, n, to, who, { staff: staff2, actorId: interaction.user.id });
        if (!res.ok)
            return interaction.reply ({ content: res.text, flags: MessageFlags.Ephemeral });
        console.log ('[' + (d()) + '] [music] ' + whoText (who) + 'поставил №' + n + ' на позицию №' + to + ' (окно ввода)');
        // Сообщение очереди в канале обновляем -- в нём уже другие номера.
        // [v2.38] И оставляем трек выбранным (как «⬆ Выше / ⬇ Ниже»): в режиме
        // перестановки видны только кнопки переноса, и так его можно двигать дальше,
        // не выбирая заново; «✖ Вернуться» вернёт обычные кнопки очереди.
        const view2 = queueView (m, queuePageOf (m, res.to), res.to,
            { actorId: interaction.user.id, actorName: who, staff: staff2 });
        if (interaction.message && typeof interaction.message.edit === 'function')
            await interaction.message.edit ({ content: view2.content, components: view2.components, allowedMentions: { parse: [] } }).catch (() => {});
        return interaction.reply ({ content: res.text, flags: MessageFlags.Ephemeral });
    }
    if (interaction.isButton () || interaction.isStringSelectMenu ())
    {
        const cid = interaction.customId || '';
        const guildId = interaction.guildId;
        if (!(guildId in SERVERS)) return;
        const m = musicOf (guildId);
        // Страница, на которой сейчас это сообщение: она зашита в customId меню и
        // «✖ Готово» (между нажатиями состояние не держим). Нет её -- считаем первой.
        const mOwn = /^(?:q:rm|q:mv|q:mx):(\d+)$/.exec (cid);
        const page = mOwn ? (parseInt (mOwn[1], 10) || 1) : 1;
        // [v2.31] Права и подпись вызывающего нужны и списку (какие треки и авторы
        // попадают в меню), и самим действиям -- собираем один раз.
        const staff = isStaffInteraction (interaction);
        const ctx =
        {
            actorId: interaction.user.id,
            actorName: interaction.member ? uuu (interaction.member) : interaction.user.username,
            staff: staff,
        };
        const replyView = async (at = page, moveSel = 0) =>
        {
            const view = queueView (m, at, moveSel, ctx);
            await interaction.update ({ content: view.content, components: view.components, allowedMentions: { parse: [] } });
            // [v2.57] ...и запоминаем, ЧТО именно сейчас показано и на какой странице:
            // иначе самообновление вернуло бы сообщение на первую страницу, а в режиме
            // переноса -- перерисовало бы меню прямо под руками (moveSel != 0 -- стоп).
            queueWatch (m, interaction.message, ctx, at, view.content, moveSel);
        };
        // --- листание: в customId -- кнопка и ЦЕЛЕВАЯ страница; чужие нажатия не
        // трогают чужое сообщение. Старый вид («q:p:12», без имени кнопки) тоже
        // понимаем: такие кнопки ещё висят в старых сообщениях с очередью. ---
        // [v2.55] ...и «q:rf:страница» -- «🔄 Обновить»: та же страница, собранная
        // заново из живой очереди. Отдельная ветка ей не нужна: права и правила у неё
        // ровно те же, что у листания (сообщение перерисовывает тот, кто его открыл).
        const mPage = /^q:(rf|[pn])(?::(?:first|prev|next|last))?:(\d+)$/.exec (cid);
        if (mPage)
        {
            const opener = interaction.message && interaction.message.interaction && interaction.message.interaction.user
                ? interaction.message.interaction.user.id
                : null;
            if (opener && opener !== interaction.user.id)
                return interaction.reply
                (
                    { content: '📜 Эту очередь открыл другой человек -- вызови `/queue` сам.', flags: MessageFlags.Ephemeral }
                );
            return replyView (parseInt (mPage[2], 10) || 1);
        }
        // [v2.61] ПОДТВЕРЖДЕНИЕ /jump: вариант не указали в команде -- спрашиваем кнопками.
        // Ветка стоит ДО общего гейта «только DJ»: staff без роли DJ тоже должен смочь,
        // а права проверяет jumpGuard (staff -- любые, DJ -- только свои).
        const mJp = /^q:jp:(x|u|c)(?::(\d+))?$/.exec (cid);
        if (mJp)
        {
            if (mJp[1] === 'x')
                return interaction.update ({ content: '✖ Прыжок отменён -- очередь на месте.', components: [] });
            const res = jumpMusic (guildId, parseInt (mJp[2], 10) || 0, mJp[1] === 'c',
                { actorId: interaction.user.id, staff: staff });
            return interaction.update ({ content: (res.ok ? '' : '⚠️ ') + res.text, components: [] });
        }
        // --- действия: как и слэш-команды, только для админов/модеров и роли DJ ---
        // [v2.44] mt/mb/mp -- «⏫ В начало», «⏬ В конец», «#️⃣ На позицию…». Их в списке
        // не было, и нажатие молча уходило в return: Discord показывал «взаимодействие
        // не удалось», а перенос кнопками не работал (при этом /move работал -- это и
        // сбивало с толку). Теперь все три пути перестановки разрешены одинаково.
        if (!/^q:(skip|join|leave|clear|stop|da|dau|dax|dx|cq|rm|mv|mt|mb|mp|mu|md|mx|s|sk|tr|rx|jmp|jsel)(:|$)/.test (cid)) return;
        if (!isDJ (interaction))
        {
            const role_dj = SERVERS[guildId].role_dj || '';
            return interaction.reply
            (
                {
                    content: '🚫 Музыка только для ' + (role_dj ? '<@&' + role_dj + '>' : 'DJ'),
                    flags: MessageFlags.Ephemeral,
                }
            );
        }
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        // [v2.62] «⤴ Перепрыгнуть» -- [v2.66] не окно с номером, а СПИСОК ТРЕКОВ:
        // выбрал -- спрашиваем вариант (срочный переход / обрезка) теми же кнопками,
        // что и у /jump. Список личный: DJ видит только свои треки, staff -- все.
        if (cid === 'q:jmp')
        {
            if (!m.tracks.length)
                return interaction.reply ({ content: '🈳 В очереди нет треков -- перепрыгивать некуда.', flags: MessageFlags.Ephemeral });
            const rows = jumpPickerRows (m, ctx.actorId, staff);
            if (!rows)
                return interaction.reply
                ({
                    content: '🈳 Своих треков в очереди нет -- перепрыгивать некуда.\n' +
                        '_Чужой трек они могут пропустить только админы и модеры._',
                    flags: MessageFlags.Ephemeral,
                });
            return interaction.reply
            ({
                content: '⤴ **Перепрыгнуть к треку** -- выбери из списка (номера как в `/queue`):',
                components: rows,
                flags: MessageFlags.Ephemeral,
            });
        }
        // [v2.66] Выбор трека из списка «Перепрыгнуть» -- показываем подтверждение варианта.
        if (cid === 'q:jsel')
        {
            const nSel = parseInt (String ((interaction.values || [])[0] || ''), 10) || 0;
            if (!(nSel >= 1 && nSel <= m.tracks.length))
                return interaction.update ({ content: '🤔 Такого трека в очереди уже нет -- вызови `/queue` заново.', components: [] });
            const c = jumpConfirm (nSel);
            return interaction.update ({ content: c.text, components: c.rows });
        }
        // [v2.17] «⬆ Выше» / «⬇ Ниже» -- перестановка того трека, что выбран в меню
        // [v2.36] «⏫ В начало» / «⏬ В конец» и «#️⃣ На позицию…» (окно ввода):
        // та же queueMove -- права и ответы те же, что у «⬆ Выше/⬇ Ниже» и /move.
        const mTopBot = /^q:m([tb]):(\d+)$/.exec (cid);
        if (mTopBot)
        {
            const n = parseInt (mTopBot[2], 10) || 0;
            const res = queueMove (guildId, n, mTopBot[1] === 't' ? 1 : m.tracks.length, who, ctx);
            if (!res.ok)
                return interaction.reply ({ content: res.text, flags: MessageFlags.Ephemeral });
            const at = queuePageOf (m, res.to);
            await replyView (at, res.to);
            return interaction.followUp ({ content: res.text, flags: MessageFlags.Ephemeral });
        }
        // [v2.44] «⏱ На таймкод…» -- окно ввода времени для ТЕКУЩЕГО трека (та же
        // перемотка, что у /seek и у «◀ 30 с / 30 с ▶»). Страница очереди зашита в
        // customId: после перемотки сообщение перерисуется на той же странице.
        const mTcodeAsk = /^q:sk:(\d+)$/.exec (cid);
        if (mTcodeAsk)
        {
            if (!m.current)
                return interaction.reply ({ content: '🤷 Сейчас ничего не играет -- перематывать нечего.', flags: MessageFlags.Ephemeral });
            if (m.current.isLive)
                return interaction.reply ({ content: '🔴 Это прямой эфир -- позиции у него нет (`/seek 0` -- перейти к живому краю).', flags: MessageFlags.Ephemeral });
            // [v2.46] ЧТО ВИДНО В ОКНЕ (владелец: «не выводит всю длину -- не понять, куда
            // можно перемотать», а потом: «формат подсказывать не надо»):
            //   * ЗАГОЛОВОК -- какой это трек (видно, что перематываешь не то, что думал);
            //   * ПОДПИСЬ ПОЛЯ -- только максимум: «из 1:03:20»; больше в ней ничего нет;
            //   * В ПОЛЕ -- уже стоит текущее место: по нему формат виден сам собой, а
            //     человеку остаётся править пару цифр;
            //   * ПОДСКАЗКА поля (видна, если поле очистить) -- на всякий случай форматы
            //     и текст ошибки при неверном вводе.
            // ЛИМИТЫ DISCORD: заголовок и подпись -- по 45 символов, подсказка поля -- 100.
            // Прежняя подпись («Куда перемотать: 1:30 или 90 (сейчас 1:09:36)») была ровно
            // 45 знаков: на длинном месте (вроде 20:30:00) окно отбивалось бы целиком, а
            // длине трека места не оставалось вообще.
            const at = Math.max (0, Math.round (playedMsOf (m) / 1000));
            const tcodeDur = Number (m.current.duration) > 0 ? Number (m.current.duration) : 0;
            const tcodeTitle = 'Перемотать: ' + clipText (String (m.current.title || 'трек'), 30);
            return interaction.showModal
            (
                new ModalBuilder ().setCustomId ('q:skt:' + mTcodeAsk[1])
                    .setTitle (tcodeTitle.slice (0, 45))
                    .addComponents
                    (
                        new ActionRowBuilder ().addComponents
                        (
                            new TextInputBuilder ()
                                .setCustomId ('time')
                                .setLabel ((tcodeDur ? 'Куда перемотать (из ' + fmtDur (tcodeDur) + ')'
                                                     : 'Куда перемотать (сейчас ' + fmtDur (at) + ')').slice (0, 45))
                                .setPlaceholder (('сейчас ' + fmtDur (at) + '; можно 90, 1:30 или 1:02:03').slice (0, 100))
                                .setStyle (TextInputStyle.Short)
                                .setRequired (true).setMaxLength (8)
                                .setValue (fmtDur (at))
                        )
                    )
            );
        }
        const mPosAsk = /^q:mp:(\d+)$/.exec (cid);
        if (mPosAsk)
            return interaction.showModal
            (
                new ModalBuilder ().setCustomId ('q:mpos:' + mPosAsk[1])
                    .setTitle ('Переставить трек №' + mPosAsk[1])
                    .addComponents
                    (
                        new ActionRowBuilder ().addComponents
                        (
                            new TextInputBuilder ()
                                .setCustomId ('pos')
                                .setLabel ('На какое место (1-' + m.tracks.length + ')') 
                                .setStyle (TextInputStyle.Short)
                                .setRequired (true).setMaxLength (4).setValue (mPosAsk[1])
                        )
                    )
            );
        // «🎚 Двигать трек». Логика общая с /move (queueMove).
        const mStep = /^q:m([ud]):(\d+)$/.exec (cid);
        if (mStep)
        {
            const n = parseInt (mStep[2], 10) || 0;
            const res = queueMove (guildId, n, mStep[1] === 'u' ? n - 1 : n + 1, who, ctx);
            if (!res.ok)
                return interaction.reply ({ content: res.text, flags: MessageFlags.Ephemeral });
            // Показываем ту страницу, где трек оказался, и оставляем его выбранным --
            // так его можно двигать дальше, не выбирая заново.
            const at = queuePageOf (m, res.to);
            await replyView (at, res.to);
            return interaction.followUp ({ content: res.text, flags: MessageFlags.Ephemeral });
        }
        // Выбор трека для перестановки и «✖ Готово» -- состояние только в сообщении:
        if (/^q:mx(:|$)/.test (cid)) return replyView (page, 0);
        if (/^q:mv(:|$)/.test (cid))
        {
            const sel = parseInt ((interaction.values || [])[0], 10) || 0;
            if (!sel)
                return interaction.reply ({ content: '🤔 Не понял, какой трек двигать.', flags: MessageFlags.Ephemeral });
            return replyView (page, sel);
        }
        // [v2.31] Обновление сообщения очереди в канале (чтобы список не остался старым).
        // Меню пересобираем по правам того, КТО ОТКРЫЛ это сообщение: иначе чужое нажатие
        // пересобирало бы список под нажавшего, и владелец видел бы чужое меню (действия
        // всё равно перепроверяются при нажатии, но так честнее и понятнее).
        const refreshQueueMsg = async (srcId) =>
        {
            if (!srcId || srcId === '0' || !interaction.channel ||
                typeof interaction.channel.messages.fetch !== 'function') return;
            const src = await interaction.channel.messages.fetch (srcId).catch (() => null);
            if (src && src.editable)
            {
                const openerId = (src.interaction && src.interaction.user) ? src.interaction.user.id : ctx.actorId;
                const opener = (interaction.guild && interaction.guild.members)
                    ? interaction.guild.members.cache.get (openerId) : null;
                const oCtx = (openerId === ctx.actorId) ? ctx :
                {
                    actorId: openerId,
                    actorName: opener ? uuu (opener) : openerId,
                    staff: isStaffInteraction ({ guildId: interaction.guildId, member: opener }),
                };
                const view = queueView (m, 1, 0, oCtx);
                await src.edit ({ content: view.content, components: view.components, allowedMentions: { parse: [] } }).catch (() => {});
            }
        };
        // [v2.31] Подтверждение чистки -- общее для кнопок «🧹 Очистить» и «⏹ Стоп»:
        // видно, ЧТО именно уйдёт, а staff выбирает «только свои» или «всю очередь».
        // В customId несём id сообщения очереди (или 0, если пришли командой).
        const msgId = interaction.message ? interaction.message.id : '0';
        // [v2.35] ПЕРЕМОТКА ±30 с -- тем же путём, что /seek (своей логики нет, поэтому
        // поведение не может разъехаться): трек возвращается в начало очереди с
        // отметкой секунды и открывается заново. У прямого эфира позиции нет -- кнопки
        // для него погашены в самом сообщении.
        const mSeek = /^q:s:([mp])$/.exec (cid);
        if (mSeek)
        {
            const res = queueSeekBy (guildId, mSeek[1] === 'm' ? -30 : 30, who, ctx);
            // Сообщение очереди обновляем ЧУТЬ ПОЗЖЕ: плеер перезапускается тем же
            // событием, и сразу после перемотки в строке «Сейчас» был бы прочерк.
            if (res.ok) setTimeout (() => { refreshQueueMsg (msgId).catch (() => {}); }, 1500);
            return interaction.reply ({ content: res.text, flags: MessageFlags.Ephemeral });
        }
        // [v2.35] Выбрали трек в едином списке (q:tr) -- показываем его действия:
        // «🗑 Убрать / ⬆ Выше / ⬇ Ниже / ✖ Готово» (раньше было два списка с одними и
        // теми же номерами: один убирал сразу, второй начинал перестановку).
        const mTr = /^q:tr:(\d+)$/.exec (cid);
        if (mTr)
        {
            const sel = parseInt ((interaction.values || [])[0], 10) || 0;
            if (!sel)
                return interaction.reply ({ content: '🤔 Не понял, какой трек выбран.', flags: MessageFlags.Ephemeral });
            return replyView (parseInt (mTr[1], 10) || 1, sel);
        }
        // [v2.35] «🗑 Убрать» у выбранного трека (та же функция, что /remove).
        const mRx = /^q:rx:(\d+):(\d+)$/.exec (cid);
        if (mRx)
        {
            const res = queueRemove (guildId, parseInt (mRx[1], 10) || 0, who, ctx);
            if (!res.ok)
                return interaction.reply ({ content: res.text, flags: MessageFlags.Ephemeral });
            await replyView (parseInt (mRx[2], 10) || 1);
            return interaction.followUp ({ content: res.text, flags: MessageFlags.Ephemeral });
        }
        // [v2.32] Кнопки ВХОД и ВЫХОД -- те же функции, что у /join и /leave.
        // «Выйти» -- мягкий выход: свои треки в конец (место сохраняется), чужая
        // музыка играет дальше; бот уходит из канала только когда играть нечего.
        // [v2.36] «Перейти к тебе?» -- кнопки под ответом /play (когда бот играл в другом
        // канале, где слушают). Нажать может только тот, кто вызвал /play: остальным
        // эта кнопка попадётся на глаза в чате, но переезд делает автор.
        if (/^q:mvn(:|$)/.test (cid))
            return interaction.update
            ({
                content: interaction.message.content.replace (/\n❔[^\n]*$/, '') + '\n✖ Остаюсь там, где играл.',
                components: [],
            });
        const mMvh = /^q:mvh:(\d+):(\d+)$/.exec (cid);
        if (mMvh)
        {
            if (interaction.user.id !== ctx.actorId)
                return interaction.reply ({ content: '🚫 Это предложение было не тебе — `/play` вызывал другой человек.', flags: MessageFlags.Ephemeral });
            const chId = mMvh[2];
            const ch = client.channels.cache.get (chId) || await client.channels.fetch (chId).catch (() => null);
            if (!ch)
                return interaction.reply ({ content: '🤔 Канала уже нет — никуда не переезжаю.', flags: MessageFlags.Ephemeral });
            const nowVoice = interaction.member && interaction.member.voice ? interaction.member.voice.channelId : null;
            if (nowVoice !== chId)
                return interaction.reply ({ content: '🤔 Ты уже не в «' + ch.name + '» — никуда не переезжаю.', flags: MessageFlags.Ephemeral });
            try { joinVoice (guildId, ch, interaction.guild, 'по просьбе ' + ctx.actorName); }
            catch (e)
            {
                console.error ('[music] переезд по просьбе не удался: ' + oneLine (e.message));
                return interaction.reply ({ content: '⚠️ Не смог переехать: ' + oneLine (e.message), flags: MessageFlags.Ephemeral });
            }
            m.savedChannelId = ch.id;
            console.log ('[' + (d()) + '] [music] ' + ctx.actorName + ': переехал в «' + ch.name + '» по просьбе (из /play)');
            return interaction.update
            ({
                content: interaction.message.content.replace (/\n❔[^\n]*$/, '') + '\n🚚 Переехал в «' + ch.name + '».',
                components: [],
            });
        }
        if (cid === 'q:join') return joinMusicChannel (interaction);
        if (cid === 'q:leave')
        {
            const res = leaveMusicVoice (guildId, ctx.actorId, who);
            await refreshQueueMsg (msgId);
            return interaction.reply ({ content: res.ok ? res.text : '⚠️ ' + res.text, flags: MessageFlags.Ephemeral });
        }
        const askClear = leave =>
        {
            const c = queueClearConfirm (m, ctx.actorId, staff, { leave: leave, msgId: msgId });
            return interaction.reply ({ content: c.text, components: c.rows, flags: MessageFlags.Ephemeral });
        };
        const mCq = /^q:cq:(own|all|x)(?::(\d*))?$/.exec (cid);
        if (mCq)
        {
            if (mCq[1] === 'x')
                return interaction.update ({ content: '✖ Отменено -- очередь на месте.', components: [] });
            if (mCq[1] === 'all' && !staff)
                return interaction.reply
                ({ content: '🚫 Всю очередь убирают админы и модеры -- обычный DJ распоряжается только своими записями.', flags: MessageFlags.Ephemeral });
            const res = queueClear (guildId, who, { scope: mCq[1], actorId: ctx.actorId });
            await refreshQueueMsg (mCq[2]);
            return interaction.update ({ content: res.ok ? res.text : '⚠️ ' + res.text, components: [] });
        }
        // [v2.32] МЕНЮ АВТОРА: выбрали автора -- показываем, ЧТО с ним можно сделать
        // (⬆ поднять наверх / 🗑 убрать), и спрашиваем подтверждение. Массовые действия
        // без подтверждения нельзя, а если прав нет -- говорим ПРИЧИНУ, а не молчим.
        if (cid === 'q:da')
        {
            // '0' в меню -- это «без автора» (пустое value Discord не принимает):
            const raw = String ((interaction.values || [])[0] === undefined ? '' : (interaction.values || [])[0]);
            const target = (raw === '0') ? '' : raw;
            const hit = t => !!t && byIdOf (t) === target;
            const found = queueAuthorList (m, ctx.actorId, true).find (o => o.id === target);
            // Автор мог исчезнуть из очереди между показом меню и нажатием -- тогда
            // говорим упоминанием, а не чужим именем из играющего трека.
            const name = found ? found.name : (target ? u (target) : 'без автора');
            const can = staff || (!!target && target === ctx.actorId);
            const n = m.tracks.filter (hit).length;
            const playing = hit (m.current) ? (m.current.title || 'трек') : '';
            const waiting = (!playing && hit (m.seekTrack)) ? (m.seekTrack.title || 'трек') : '';
            const all = n + (playing ? 1 : 0) + (waiting ? 1 : 0);
            if (!all)
                return interaction.reply
                ({
                    content: (target === ctx.actorId ? '🈳 Своих треков в очереди нет -- ничего не сделать.'
                             : '🈳 У ' + (target ? '**' + name + '**' : 'треков без автора') + ' ничего в очереди нет.') +
                        (target === ctx.actorId && m.tracks.length
                            ? '\nВ очереди ' + m.tracks.length + ' ' +
                              plural (m.tracks.length, 'чужой трек', 'чужих трека', 'чужих треков') + '.'
                            : ''),
                    flags: MessageFlags.Ephemeral,
                });
            if (!can)
                return interaction.reply
                ({
                    content: '🚫 **' + name + '** -- чужие треки: поднимать и убирать их могут только админы и модеры.\n' +
                        '_Свои треки можно и самому -- выбери в списке себя: каждый распоряжается своим._' +
                        (target === '' ? '\n_Треки без автора тоже чужие: проставить автора -- `node . fixauthors <id>`._' : ''),
                    flags: MessageFlags.Ephemeral,
                });
            return interaction.reply
            ({
                content: '👤 **' + name + '** -- ' + all + ' ' + plural (all, 'трек', 'трека', 'треков') + ':\n' +
                    (n ? '• в очереди: ' + n + '\n' : '') +
                    (playing ? '• играющий: **' + playing + '**\n' : '') +
                    (waiting ? '• ждущий: **' + waiting + '**\n' : '') +
                    '_⬆ Поднять -- встанут в начало очереди (в своём порядке); 🗑 Удалить -- уйдут совсем ' +
                    '(играющий прервётся). Пока трек не доиграл, лучше сначала «⬆ Поднять»._',
                components:
                [
                    new ActionRowBuilder ().addComponents
                    (
                        new ButtonBuilder ()
                            .setCustomId ('q:dau:' + (target || '0') + ':' + msgId)
                            .setLabel ('⬆ Поднять наверх (' + n + ')').setStyle (ButtonStyle.Primary).setDisabled (!n),
                        new ButtonBuilder ()
                            .setCustomId ('q:dax:' + (target || '0') + ':' + msgId)
                            .setLabel ('🗑 Удалить (' + all + ')').setStyle (ButtonStyle.Danger),
                        new ButtonBuilder ()
                            .setCustomId ('q:dx').setLabel ('✖ Отмена').setStyle (ButtonStyle.Secondary)
                    ),
                ],
                flags: MessageFlags.Ephemeral,
            });
        }
        // Подтверждено: поднять треки выбранного автора наверх очереди.
        const mDau = /^q:dau:([^:]*):(\d*)$/.exec (cid);
        if (mDau)
        {
            const target = (mDau[1] === '0') ? '' : mDau[1];
            if (!staff && (!target || target !== ctx.actorId))
                return interaction.reply
                ({ content: '🚫 Поднимать чужие треки могут только админы и модеры.', flags: MessageFlags.Ephemeral });
            const res = queuePush (guildId, target, who);
            await refreshQueueMsg (mDau[2]);
            return interaction.update ({ content: res.ok ? res.text : '⚠️ ' + res.text, components: [] });
        }
        // Подтверждено: убираем треки выбранного автора.
        const mDax = /^q:dax:([^:]*):(\d*)$/.exec (cid);
        if (mDax)
        {
            const target = (mDax[1] === '0') ? '' : mDax[1];
            if (!staff && target !== ctx.actorId)
                return interaction.reply
                ({ content: '🚫 Удалять треки других могут только админы и модеры.', flags: MessageFlags.Ephemeral });
            const res = queueClearAuthor (guildId, target, who);
            await refreshQueueMsg (mDax[2]);
            return interaction.update ({ content: res.ok ? res.text : '⚠️ ' + res.text, components: [] });
        }
        if (cid === 'q:dx') return interaction.update ({ content: '✖ Отменено -- очередь на месте.', components: [] });
        // [v2.31] «🧹 Очистить» и «⏹ Стоп» -- сначала подтверждение (что именно уйдёт).
        if (cid === 'q:clear') return askClear (false);
        if (cid === 'q:stop') return askClear (true);
        let res;
        if (cid === 'q:skip') res = queueSkip (guildId, who, ctx);   // [v2.53] права: чужой трек не пропускаем
        else res = queueRemove (guildId, parseInt ((interaction.values || [])[0], 10), who, ctx);
        // Сообщение очереди обновляем для ВСЕХ (видно результат) и коротко
        // подтверждаем нажавшему -- ответ виден только ему.
        await replyView (page);
        return interaction.followUp ({ content: res.text, flags: MessageFlags.Ephemeral });
    }
    // [v2.18] КОМАНДА-КОНТЕКСТНОЕ МЕНЮ на сообщении (правый клик -> Приложения ->
    // «Переслать в общий»). Интент Message Content ей НЕ нужен: Discord отдаёт
    // выбранное сообщение целиком -- и текст, и вложения. Это замена мосту из
    // пандалогии на случай, если интент отзовут 9 октября 2026.
    // Оригинал удаляем только в канале-источнике (как это делал мост): если staff
    // переслал сообщение откуда-то ещё, мы его не трогаем -- чужое сообщение удалять
    // по одному клику нельзя.
    if (typeof interaction.isMessageContextMenuCommand === 'function' && interaction.isMessageContextMenuCommand ())
    {
        if (!isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 Команда только для админов и модеров.', flags: MessageFlags.Ephemeral });
        const server = interaction.guildId;
        const s = SERVERS[server];
        const to = s && s.pipe_channel_target;
        const msg = interaction.targetMessage;
        if (!to)
            return interaction.reply ({ content: '⚠️ У этого сервера в config.json не задан `pipe_channel_target` -- пересылать некуда.', flags: MessageFlags.Ephemeral });
        if (!msg)
            return interaction.reply ({ content: '⚠️ Не вижу сообщение -- попробуй ещё раз.', flags: MessageFlags.Ephemeral });
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        const relay = await relayPipe (to, msg);
        if (relay.empty)
            return interaction.editReply ('🤔 В сообщении нет ни текста, ни вложений -- пересылать нечего.\n' +
                '_(если это была картинка -- значит Discord не отдал её вместе с сообщением)_');
        if (!relay.ok)
            return interaction.editReply (relay.notFound
                ? '⚠️ Канал <#' + to + '> недоступен -- не могу туда написать.'
                : '⚠️ Не смог переслать: `' + oneLine (relay.error, 150) + '`');
        const fromSource = s.pipe_channel_source && msg.channel && msg.channel.id === s.pipe_channel_source;
        if (fromSource)
            await msg.delete ().catch (e => console.error ('[' + (d()) + '] [pipe] не смог удалить оригинал: ' + e.message));
        console.log ('[' + (d()) + '] [pipe] (кто: ' + who + ') переслал сообщение ' +
            (msg.author ? msg.author.username : '?') + ' -> ' + (relay.channel.name ? '#' + relay.channel.name : to) +
            (relay.files ? ' + вложение' : '') + (relay.text ? ': ' + oneLine (relay.text, 120) : '') +
            (fromSource ? ' (оригинал удалён)' : ' (оригинал оставлен)'));
        return interaction.editReply ('📣 Переслал в <#' + to + '>.' + (fromSource
            ? ' Оригинал в этом канале удалён.'
            : ' Оригинал оставил на месте -- удали его сам, если не нужен.'));
    }
    if (!interaction.isChatInputCommand ()) return;
    const name = interaction.commandName;
    // [v2.4] активное действие -- в лог: кто и что вызвал
    console.log
    (
        '[' + (d()) + '] [cmd] /' + name +
        ((interaction.options.data || []).length
            ? ' ' + interaction.options.data.map (o => o.name + '=' + String (o.value === undefined ? '' : o.value).slice (0, 120)).join (' ')
            : '') +
        ' -- ' + (interaction.member ? uuu (interaction.member) : (interaction.user ? interaction.user.username : '?')) +
        (interaction.channel && interaction.channel.name ? ' @ #' + interaction.channel.name : '')
    );
    // [v2.6] /help -- всем и всегда: без DJ-роли и без голосового канала, ephemeral.
    if (name === 'help')
    {
        // [v2.32] Инструкция может не влезть в одно сообщение (лимит 6000 символов на
        // все embed'ы вместе): тогда она уходит несколькими ответами, а не отбивается.
        const groups = helpMessages (interaction.guildId);
        await interaction.reply ({ embeds: groups[0], flags: MessageFlags.Ephemeral });
        for (const embeds of groups.slice (1))
            await interaction.followUp ({ embeds, flags: MessageFlags.Ephemeral });
        return;
    }
    // [v2.14] /bans -- до всего остального (это не музыка, а модерация): ответ
    // виден только вызвавшему, права -- админ/модер.
    if (name === 'bans')
    {
        if (!isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 Команда только для админов и модеров.', flags: MessageFlags.Ephemeral });
        // Список банов спрашиваем у Discord -- ответ приходит не мгновенно:
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const o = await bansOverview (interaction.guildId);
        console.log ('[' + (d()) + '] [ban] /bans: активных ' + o.rows.length +
            ', банов ' + o.rows.filter (r => r.isBan).length);
        // [v2.24] Причины наказаний бывают длинными, а записей -- десятки: показываем
        // столько, сколько влезает в лимит (сначала 20, потом меньше), но ответ уходит ВСЕГДА.
        let report = bansReportText (o, 20);
        for (const max of [12, 8, 5, 3, 2, 1])
        {
            if (report.length <= MSG_TEXT_LIMIT) break;
            report = bansReportText (o, max);
        }
        return interaction.editReply ({ content: fitMsgText (report) });
    }
    // [v2.15] /unban -- снять наказание вручную (только staff). Снимаем ровно то, что
    // реально есть: бан в Discord, запись таймаута в базе и отложенный таймер (иначе
    // он позже сработает и напишет в лог «unbanned» уже после ручного снятия).
    // Кто снял и почему -- в журнал и в историю (/bans).
    if (name === 'unban')
    {
        if (!isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 Команда только для админов и модеров.', flags: MessageFlags.Ephemeral });
        const server = interaction.guildId;
        const guild = client.guilds.cache.get (server);
        const target = interaction.options.getUser ('user', true);
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        const why = (interaction.options.getString ('reason') || '').trim ();
        // [v2.24] Причина уходит в журнал аудита Discord, а там лимит 512 символов:
        // длинная причина отклоняла бы снятие бана целиком.
        const reason = ('Снято вручную (' + who + ')' + (why ? ': ' + why : '')).slice (0, 512);
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        // Что именно было: срок из базы, таймер из памяти и настоящий бан из Discord.
        const until = await db (server, 'membersBanTimeout', target.id).catch (() => null);
        const hasRecord = (until !== null && until !== undefined);
        let hadBan = false, banErr = '';
        try { await guild.bans.fetch (target.id); hadBan = true; }
        catch (e) { if (!/Unknown Ban|10026/i.test (e.message)) banErr = oneLine (e.message); }
        if (!hadBan && !hasRecord && !banTimerFor (server, target.id))
            return interaction.editReply
            (
                'ℹ️ У **' + target.username + '** нет ни таймаута, ни бана -- снимать нечего.' +
                (banErr ? '\n_Бан не проверился: `' + banErr + '`._' : '')
            );
        // [!!!] Сначала СНИМАЕМ бан и только потом чистим запись и таймер (как в
        // sweepExpiredBans): если снять не удалось по-настоящему (нет прав, сеть),
        // запись остаётся -- иначе бот «забудет» о человеке, который всё ещё в бане.
        if (hadBan)
        {
            try { await guild.members.unban (target.id, reason); }
            catch (e) { return interaction.editReply ('⚠️ Не смог снять бан с **' + target.username + '**: `' + oneLine (e.message) + '`'); }
        }
        banTimerClear (server, target.id);
        if (hasRecord)
            await db (server, 'membersBanTimeout', target.id, null).catch (() => {});
        banHistoryAdd (server, target.id, 'unban');
        // Что было снято (одной фразой; таймер без записи -- тоже повод отчитаться):
        const what = hadBan ? ('бан' + (hasRecord ? ' и таймаут' : ''))
                            : (hasRecord ? 'таймаут' : 'таймер разбана');
        const till = until ? ', срок был до `' + d (until, true) + '`' : '';
        console.log ('[' + (d()) + '] [ban] ' + who + ' снял наказание с ' + target.username +
            ' (' + what + till + (why ? ', причина: ' + oneLine (why, 120) : '') + ')');
        logTo (SERVERS[server].log_channel).send
        (
            {
                embeds:
                [
                    {
                        author:
                        {
                            name: uu (target),
                            icon_url: target.displayAvatarURL ({extension: 'png', forceStatic: false, size: 1024}),
                        },
                        color: 0x00FF00, // 'GREEN'
                        description: '**' + uu (target) + '** снято наказание: ' + what + till + ' 🕊️\n' +
                            'Снял: **' + who + '**' + (why ? '\nПричина: `' + clipText (oneLine (why, 300), 300) + '`' : ''),
                        footer:
                        {
                            text: SERVERS[server].name,
                        },
                        timestamp: dt(),
                    },
                ]
            }
        );
        return interaction.editReply
        (
            '✅ С **' + target.username + '** снято: ' + what + till + '.' +
            '\nВ журнале отмечено (кто и когда).'
        );
    }
    // [v2.18] /announce -- публикация от имени бота (staff). Заменяет мост из пандалогии,
    // который требовал интент Message Content (без него текст и вложения приходят пустыми).
    // Публикуем в указанный канал (по умолчанию -- в тот, где вызвали), без удаления чего-либо.
    if (name === 'announce')
    {
        if (!isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 Команда только для админов и модеров.', flags: MessageFlags.Ephemeral });
        const text = (interaction.options.getString ('text') || '').trim ();
        const file = interaction.options.getAttachment ('file');
        const target = interaction.options.getChannel ('channel') || interaction.channel;
        if (!text && !file)
            return interaction.reply ({ content: '🤔 Пустое объявление: нужен текст или вложение.', flags: MessageFlags.Ephemeral });
        // [v2.24] Discord не примет текст длиннее 2000 символов: лучше сказать это сразу
        // и внятно, чем получить «Не смог опубликовать: Invalid Form Body».
        if (text.length > MSG_TEXT_LIMIT)
            return interaction.reply ({ content: '❌ Текст объявления -- ' + text.length + ' символов, а Discord принимает до ' +
                MSG_TEXT_LIMIT + '. Сократи или разбей на части.', flags: MessageFlags.Ephemeral });
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        try
        {
            const ch = client.channels.cache.get (target.id) || await client.channels.fetch (target.id);
            if (!ch || typeof ch.send !== 'function')
                return interaction.editReply ('⚠️ Канал <#' + target.id + '> недоступен -- не могу туда написать.');
            await ch.send
            ({
                content: text || undefined,
                files: file ? [{ attachment: file.url, name: file.name || 'файл' }] : [],
            });
            console.log ('[' + (d()) + '] [pipe] (кто: ' + who + ') объявление -> ' + (ch.name ? '#' + ch.name : target.id) +
                (file ? ' + вложение' : '') + (text ? ': ' + oneLine (text, 120) : ''));
            return interaction.editReply ('📣 Опубликовано ' + (target.id === interaction.channelId
                ? 'в этом канале'
                : 'в <#' + target.id + '>') + '.');
        }
        catch (e)
        {
            console.error ('[pipe] объявление не ушло: ' + oneLine (e.message));
            return interaction.editReply ('⚠️ Не смог опубликовать: `' + oneLine (e.message, 150) + '`');
        }
    }
    // [v2.18] /dm -- личное сообщение от имени бота (только админы, как и `panda dm`).
    // Тоже без интента Message Content: текст приходит в самой слэш-команде.
    if (name === 'dm')
    {
        if (!isAdminInteraction (interaction))
            return interaction.reply ({ content: '🚫 Команда только для админов.', flags: MessageFlags.Ephemeral });
        const target = interaction.options.getUser ('user', true);
        const text = (interaction.options.getString ('text') || '').trim ();
        const file = interaction.options.getAttachment ('file');
        if (!text && !file)
            return interaction.reply ({ content: '🤔 Что отправить? Нужен текст или вложение.', flags: MessageFlags.Ephemeral });
        // [v2.24] То же, что у /announce: 2000 символов -- лимит самого Discord.
        if (text.length > MSG_TEXT_LIMIT)
            return interaction.reply ({ content: '❌ Текст ЛС -- ' + text.length + ' символов, а Discord принимает до ' +
                MSG_TEXT_LIMIT + '. Сократи или разбей на части.', flags: MessageFlags.Ephemeral });
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        try
        {
            const user = await client.users.fetch (target.id);
            if (!user || typeof user.send !== 'function')
                return interaction.editReply ('⚠️ Пользователь ' + u (target.id) + ' недоступен.');
            await user.send
            ({
                content: text || undefined,
                files: file ? [{ attachment: file.url, name: file.name || 'файл' }] : [],
            });
            console.log ('[' + (d()) + '] [dm] (кто: ' + who + ') ЛС -> ' + uu (target) +
                (file ? ' + вложение' : '') + (text ? ': ' + oneLine (text, 120) : ''));
            return interaction.editReply ('✉️ Отправил ЛС: ' + u (target.id));
        }
        catch (e)
        {
            console.error ('[dm] ЛС -> ' + uu (target) + ' не ушло: ' + oneLine (e.message));
            return interaction.editReply ('⚠️ ЛС не ушло: `' + oneLine (e.message, 150) + '`.\n' +
                '_(частая причина -- у него закрыта личка)_');
        }
    }
    // [v2.17] /rolecheck -- отчёт о человеке (только staff, ответ виден вызвавшему).
    // Работает с ЛЮБЫМ человеком, в том числе не состоящим на сервере.
    if (name === 'rolecheck')
    {
        if (!isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 Команда только для админов и модеров.', flags: MessageFlags.Ephemeral });
        const target = interaction.options.getUser ('user', true);
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const text = await rolecheckReport (interaction.guildId, target);
        console.log ('[' + (d()) + '] [roles] /rolecheck: ' + target.username + ' -- отчёт выдан');
        return interaction.editReply ({ content: clipText (text, 1900) });
    }
    // [v2.18] /welcome -- проверка приветствия (ответ виден только вызвавшему).
    if (name === 'welcome')
    {
        const target = interaction.options.getUser ('user') || interaction.user;
        if (target.id !== interaction.user.id && !isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 Другому -- только админ или модер.', flags: MessageFlags.Ephemeral });
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const user = await client.users.fetch (target.id).catch (() => null);
        if (!user || typeof user.send !== 'function')
            return interaction.editReply ('⚠️ Пользователь ' + u (target.id) + ' недоступен.');
        const res = await welcomeCheckSend (interaction.guildId, user,
            interaction.member ? uuu (interaction.member) : interaction.user.username);
        return interaction.editReply (res.ok
            ? ('✅ Приветствие отправлено в ЛС: ' + u (target.id))
            : ('⚠️ ' + res.why));
    }
    // [v2.18] /forget -- удалить то, что бот помнит о человеке (роли + история
    // наказаний). Активное наказание НЕ трогаем: оно снимается /unban.
    if (name === 'forget')
    {
        if (!isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 Команда только для админов и модеров.', flags: MessageFlags.Ephemeral });
        const target = interaction.options.getUser ('user', true);
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const server = interaction.guildId;
        const had = [];
        try
        {
            const roles = await db (server, 'memberRoles', target.id);
            if (roles)
            {
                await db (server, 'memberRoles', target.id, null);
                had.push ('роли (' + ((roles.roles || []).length) + ')');
            }
            const hist = await db (server, 'banHistory', target.id);
            if (hist)
            {
                await db (server, 'banHistory', target.id, null);
                had.push ('история наказаний (' + ((hist.events || []).length) + ' ' +
                    plural ((hist.events || []).length, 'событие', 'события', 'событий') + ')');
            }
            // [v2.25] Очередь музыки тоже хранит данные о человеке (byId/byName, /mydata
            // считает эти треки его данными), а раньше /forget их не трогал -- то есть
            // удалялось меньше, чем бот помнит. Убираем его треки из очереди (тем же
            // путём, что `/clear author`).
            // [v2.26] И убираем их ЦЕЛИКОМ: если играет (или ждёт) ЕГО трек -- он снимается
            // и прерывается. «Ничейного» трека быть не должно: раньше в этом случае у него
            // просто стиралось авторство, и он продолжал играть как чей-то безымянный.
            {
                const m = musicOf (server);
                const same = t => t && String (t.byId || '') === String (target.id);
                const goneQ = (m.tracks || []).filter (same).length;
                const playing = same (m.current) ? (m.current.title || 'трек') : '';
                const waiting = !playing && same (m.seekTrack) ? (m.seekTrack.title || 'трек') : '';
                if (goneQ || playing || waiting)
                {
                    m.tracks = m.tracks.filter (t => !same (t));
                    if (waiting) { m.seekTrack = null; m.seekSec = 0; }
                    if (playing)
                    {
                        m.current = null;
                        m.playedMs = 0;
                        m.playingSince = null;
                        m.player.stop (true); // Idle-хэндлер запустит следующий (если есть)
                    }
                    dropPreload (m);
                    startPreload (server);
                    saveMusicState (server);
                    scheduleVoiceStatus (server, true);
                    schedulePresence (true);
                    had.push ('очередь музыки (' + goneQ + ' ' + plural (goneQ, 'трек', 'трека', 'треков') +
                        (playing ? ' + его играющий трек' : (waiting ? ' + его ждущий трек' : '')) + ')');
                }
            }
        }
        catch (e)
        {
            console.error ('[forget] не смог удалить данные ' + target.id + ': ' + oneLine (e.message));
            return interaction.editReply ('⚠️ Не смог удалить: `' + oneLine (e.message, 150) + '`');
        }
        const until = await db (server, 'membersBanTimeout', target.id).catch (() => null);
        const active = (until && until > Date.now ())
            ? ' Активное наказание НЕ тронуто -- снять его можно `/unban`.' : '';
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        console.log ('[' + (d()) + '] [forget] (кто: ' + who + ') удалил данные ' + target.username +
            ' \`' + target.id + '\`: ' + (had.length ? had.join (', ') : 'нечего было удалять'));
        return interaction.editReply ('🧽 Данные ' + u (target.id) + ' удалены: ' +
            (had.length ? had.join (', ') : 'нечего было удалять') + '.' + active);
    }
    // [v2.22] /mydata -- человек видит, что бот о нём помнит. О себе -- любой, о другом -- staff.
    if (name === 'mydata')
    {
        const opt0 = interaction.options.getUser ('user');
        const target = opt0 || interaction.user;
        const self = String (target.id) === String (interaction.user.id);
        if (!self && !isStaffInteraction (interaction))
            return interaction.reply ({ content: '🚫 О другом человеке -- только админ или модер.\n' +
                'О себе -- всегда: просто `/mydata`.', flags: MessageFlags.Ephemeral });
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const user = self ? interaction.user : (await client.users.fetch (target.id).catch (() => target));
        let text = '';
        try { text = await myDataReport (interaction.guildId, user, self); }
        catch (e) { return interaction.editReply ('⚠️ Не смог собрать отчёт: `' + oneLine (e.message, 150) + '`'); }
        console.log ('[' + (d()) + '] [data] (кто: ' +
            (interaction.member ? uuu (interaction.member) : interaction.user.username) +
            ') посмотрел, что бот помнит о ' + user.username + (self ? ' (о себе)' : '') + ' -- отчёт выдан');
        return interaction.editReply ({ content: clipText (text, 1900) });
    }
    // [v2.22] /rekey -- смена ключа шифрования базы: ТОЛЬКО владелец бота (id в OWNER).
    if (name === 'rekey')
    {
        if (!isBotOwner (interaction.user.id))
            return interaction.reply ({ content: '🚫 Команда только для владельца бота (id в ключе `OWNER` конфига)' +
                (OWNER_HOSTER ? '' : '; сейчас `OWNER` не заполнен -- команда недоступна никому') + '.',
                flags: MessageFlags.Ephemeral });
        await interaction.deferReply ({ flags: MessageFlags.Ephemeral });
        const who = interaction.member ? uuu (interaction.member) : interaction.user.username;
        const oldKeys = DB_KEYS.slice ();
        console.log ('[' + (d()) + '] [db] (кто: ' + who + ') /rekey: перешифровываю базу новым ключом');
        const newKey = crypto.randomBytes (32);
        const res = await dbRekey (newKey);
        const sum = 'перешифровано ' + (res.enc + res.plain) + ' ' +
            plural (res.enc + res.plain, 'запись', 'записи', 'записей') +
            ' (открытыми до этого были: ' + res.plain + ')' +
            (res.bad ? ', пропущено нечитаемых: ' + res.bad : '') + ', неймспейсов: ' + res.ns;
        if (res.abort)
        {
            // Новый ключ основным НЕ делаем: часть записей уже под ним -- держим его запасным
            DB_KEYS.length = 0;
            for (const k of oldKeys) DB_KEYS.push (k);
            if (!DB_KEYS.some (k => k.equals (newKey))) DB_KEYS.push (newKey);
            const saved = dbKeysSaveToConfig (oldKeys[0] || null, [newKey]);
            console.log ('[' + (d()) + '] [db] /rekey ПРЕРВАН (' + res.why + '): ' + sum +
                '; основной ключ -- прежний, новый записан запасным (' +
                (saved ? 'config.json обновлён' : 'config.json НЕ обновлён -- впиши вручную') + ')');
            return interaction.editReply ('⚠️ Перешифровка прервана: `' + oneLine (res.why, 120) + '`.\n' + sum +
                '\nНовый ключ **не** стал основным: в `config.json` остался прежний `db_key`, а новый лежит в `db_key_prev` -- данные читаются' +
                (saved ? ' и переживут перезапуск' : '; в конфиг записать не удалось, возьми ключ из консоли бота') +
                '.\nПовтори `/rekey`, когда будет время.');
        }
        DB_KEYS.length = 0;
        DB_KEYS.push (newKey);
        if (oldKeys[0]) DB_KEYS.push (oldKeys[0]);// старый -- только на этот сеанс
        const saved2 = dbKeysSaveToConfig (newKey, []);
        // Ключ печатаем ТОЛЬКО в консоль: в Discord он ушёл бы на серверы Discord.
        console.log ('\n' + '='.repeat (62));
        console.log (' [db] НОВЫЙ КЛЮЧ ШИФРОВАНИЯ БАЗЫ (ключ db_key): ' + newKey.toString ('hex'));
        console.log (' [db] ' + (saved2 ? 'уже вписан в config.json' : 'ВПИСАТЬ В config.json НЕ УДАЛОСЬ -- сделай вручную'));
        console.log (' [db] сохрани его отдельно: без этого ключа записи базы не читаются.');
        console.log ('='.repeat (62) + '\n');
        console.log ('[' + (d()) + '] [db] (кто: ' + who + ') /rekey готов: ' + sum);
        return interaction.editReply ('🔐 База перешифрована новым ключом.\n' + sum +
            '\nНовый ключ ' + (saved2 ? 'уже вписан в `config.json` (`db_key`), старый убран'
                : '**вписать в `config.json` не удалось** -- возьми его из консоли бота') +
            '; ключ также напечатан **в консоли бота** (в Discord не отправляю: оттуда он ушёл бы на серверы Discord).' +
            '\nСохрани его отдельно от config.json -- без него записи базы не читаются. Перезапуск не нужен.');
    }
    // [v2.32] seek -- в том же списке, что музыка (проверка прав ниже общая)
    if (!['play','join','stop','skip','pause','resume','seek','queue','nowplaying','history','leave','remove','clear','jump','move','push'].includes (name)) return;
    const guildId = interaction.guildId;
    const m = musicOf (guildId);

    try
    {
        // DJ-проверка (смотреть /queue, /nowplaying и /history может каждый):
        if (name !== 'queue' && name !== 'nowplaying' && name !== 'history' && !isDJ (interaction))
        {
            let role_dj = SERVERS[guildId].role_dj || '';
            return interaction.reply ({ content: '🚫 Музыка только для ' + (role_dj ? '<@&' + role_dj + '>' : 'DJ'), flags: MessageFlags.Ephemeral });
        }

        // [v2.7] /join -- «посидеть с ботом»: заходит в канал вызывающего и ОСТАЁТСЯ там.
        // Уходит только по /leave или когда его позвали в другую комнату (тогда connectTo
        // делает rejoin). Проверяем «уже здесь?» ДО connectTo -- иначе ответ соврёт.
        if (name === 'join')
            return joinMusicChannel (interaction); // [v2.32] логика одна с кнопкой «▶ Войти»

        if (name === 'play')
        {
            const callerVoice = interaction.member && interaction.member.voice ? interaction.member.voice.channel : null;
            await interaction.deferReply ();
            let query = interaction.options.getString ('запрос');

            let tracks;
            try
            {
                tracks = isUrl (query) ? await playlistInfo (query) : [await trackInfo ('ytsearch1:' + query)];
            }
            catch (e)
            {
                return interaction.editReply ('❌ Не нашёл: `' + e.message.slice (0, 150) + '`');
            }
            if (!tracks.length)
                return interaction.editReply ('❌ Пустой результат.');
            // [v2.14] Кто добавил треки: видно в /queue, а по этому же полю работает
            // `/clear author:@кто` (убрать из очереди треки одного человека).
            // [v2.35] И КОГДА: одна метка на весь заход /play -- это «пачка» в истории
            // добавлений («20:02 Фантазёр -- 2 трека»), по ней в /queue видно свежие
            // вставки в чужом длинном плейлисте. Объект у всех треков пачки один -- метка
            // поэтому общая и не разъезжается.
            const addedAt = Date.now ();
            for (const t of tracks)
            {
                t.byId = interaction.user.id;
                t.byName = interaction.user.username;
                t.addAt = addedAt;
                t.addIn = interaction.channelId; // [v2.39] куда писать, если с треком что-то не так
            }

            // [v2.12] Куда играть. Правила:
            //   * бот уже играет живым слушателям в другом канале -- НЕ перехватываем
            //     («кто первый, тот и прав»): DJ просто пополняет очередь;
            //   * бот сидит один (слушателей нет) -- переезжает к тому, кто позвал;
            //   * бот никуда не подключён -- заходит к вызывающему, если он в канале,
            //     иначе очередь просто копится (заиграет по /join). Т.е. DJ может
            //     собирать плейлист бота, вообще не находясь в голосовом канале.
            const mine = m.connection ? m.connection.joinConfig.channelId : null;
            const mineCh = mine ? client.channels.cache.get (mine) : null;
            const mineName = mineCh ? '«' + mineCh.name + '»' : 'другом канале';
            const minePeople = mine ? humansInChannel (guildId, mine) : 0;
            let note = '';
            // [v2.36] СПРАШИВАЕМ, ПЕРЕЕЗЖАТЬ ЛИ. Раньше здесь был просто отказ («играю
            // в … -- там и продолжу»), и автор треков ничего не мог решить. Теперь он
            // сам выбирает: перейти к нему (там его треки) или оставить бота там, где
            // слушают. Без ответа ничего не меняется -- остаётся как было.
            let askMoveRow = null;
            if (m.connection && callerVoice && callerVoice.id !== mine && minePeople > 0)
            {
                note = '\n🎧 Играю в ' + mineName + ' (' + minePeople + ' -- слушают) -- там и продолжу.' +
                    '\n❔ Перейти к тебе в «' + callerVoice.name + '»?';
                askMoveRow = new ActionRowBuilder ().addComponents
                (
                    new ButtonBuilder ()
                        .setCustomId ('q:mvh:' + guildId + ':' + callerVoice.id).setLabel ('🚚 Перейти')
                        .setStyle (ButtonStyle.Success),
                    new ButtonBuilder ()
                        .setCustomId ('q:mvn').setLabel (('✖ Остаться в ' + mineName).slice (0, 78))
                        .setStyle (ButtonStyle.Secondary)
                );
            }
            else if (callerVoice && (!m.connection || callerVoice.id !== mine))
            {
                const wasElsewhere = !!mine && mine !== callerVoice.id;
                connectTo (interaction); // заходит к вызывающему (или переезжает, если сидел один)
                if (wasElsewhere) note = '\n🚚 Переехал в «' + callerVoice.name + '».';
            }

            m.textChannelId = interaction.channelId; // куда писать уведомления
            const shouldStart = !!m.connection && !m.current; // подключены и ничего не играет
            // [v2.36] Новая пачка встаёт В КОНЕЦ БЛОКА ЭТОГО АВТОРА (или в конец очереди,
            // если его треков там ещё нет) -- треки разных авторов не чередуются.
            const _insAt = authorBlockInsertAt (m.tracks, interaction.user.id);
            const _blockBefore = _insAt < m.tracks.length;
            m.tracks.splice (_insAt, 0, ...tracks);
            scheduleVoiceStatus (guildId); // [v2.7] очередь изменилась -- обновим статус канала
            schedulePresence ();           // [v2.8] «ещё N в очереди»
            scheduleDeadScan (guildId);    // [v2.41] свежая пачка -- сразу проверим, что в ней играется
            if (!shouldStart) startPreload (guildId); // [v2.9] уже играет что-то -- готовим следующий
            saveMusicState (guildId);             // [v2.10] очередь -- на диск
            // [v2.54] ...и НАВСЕГДА в историю добавлений (одна запись на один /play):
            // кто, когда и что поставил -- трек, эфир или плейлист. В /queue этой строки
            // больше нет (просьба владельца), и историю не трогают /stop и /clear.
            historyAdd (guildId,
            {
                at: addedAt,
                byId: interaction.user.id,
                byName: interaction.user.username,
                inCh: interaction.channelId,
                n: tracks.length,
                live: tracks.filter (t => t.isLive).length,
                titles: tracks.map (t => t.title || t.url || ''),
                // [v2.56] Что человек написал в /play (ссылку, адрес плейлиста или
                // запрос -- из /history это можно вставить заново), адреса самих треков
                // и их ключи -- для «судьбы пачки» (что ещё в очереди, что доиграно).
                q: query,
                urls: tracks.map (t => t.url || ''),
                ids: tracks.map (t => ytKey (t.url)),
            }).catch (e => console.error ('[music] история добавлений: ' + oneLine ((e && e.message) || e)));
            await interaction.editReply
            (
                '🎶 Добавлено: **' + (tracks[0].title || query) + '**' +
                (tracks.length > 1 ? ' + ещё ' + (tracks.length - 1) + ' треков' : '') +
                '\nИсточник: `' + tracks[0].author + '` | Длина: `' + fmtDur (tracks[0].duration, tracks[0].isLive) + '`' +
                note +
                (m.connection ? (shouldStart ? '\n▶️ Запускаю...' : '') :
                    '\n⏳ Я не в канале -- заиграю, когда позовёшь `/join`.') +
                (_blockBefore ? '\n📚 Пачка встала в конец твоего блока в очереди (№' + _insAt + ').' : ''),
                { components: askMoveRow ? [askMoveRow] : [] }
            );
            if (shouldStart)
                playNext (guildId);
        }
        else if (name === 'stop')
        {
            // [v2.12] /stop -- стирает очередь совсем (бот её и запускал -- люди знают,
            // что не будет). /leave и обрывы -- только пауза/память.
            // [v2.28] И это ЕДИНСТВЕННОЕ отличие /stop от /clear: /stop ещё и уходит из
            // канала (раньше обе команды делали ровно одно и то же -- непонятно было, какую
            // звать). /clear -- «очистить и остаться», /stop -- «очистить и выйти».
            // [v2.31] Сначала подтверждение -- как и у кнопок под /queue. Обычный DJ
            // распоряжается только своими записями, админы/модеры выбирают: свои или вся.
            const c = queueClearConfirm (m, interaction.user.id, isStaffInteraction (interaction),
                { leave: true, msgId: '0' });
            return interaction.reply ({ content: c.text, components: c.rows, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'remove')
        {
            // [v2.12] убрать один трек из очереди по номеру (каждый видит номера в /queue).
            // [v2.15] Логика -- общая с меню «🗑 Убрать трек» под /queue (queueRemove).
            // [v2.31] DJ -- только свой трек, staff -- любой.
            const res = queueRemove (guildId, interaction.options.getInteger ('number'),
                interaction.member ? uuu (interaction.member) : interaction.user.username,
                { staff: isStaffInteraction (interaction), actorId: interaction.user.id });
            return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'move')
        {
            // [v2.12.2] перестановка внутри очереди. Номера -- те же, что в /queue
            // (текущий трек в них не входит: он показан отдельной строкой «Сейчас»).
            // [v2.17] Логика -- общая с кнопками «⬆/⬇» под /queue (queueMove).
            // [v2.31] Двигать можно только свой трек (staff -- любой).
            const res = queueMove (guildId,
                interaction.options.getInteger ('number'),
                interaction.options.getInteger ('to'),
                interaction.member ? uuu (interaction.member) : interaction.user.username,
                { staff: isStaffInteraction (interaction), actorId: interaction.user.id });
            return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'push')
        {
            // [v2.27] Поднять треки одного автора наверх очереди -- ТОЛЬКО админы/модеры
            // (обычному DJ это позволило бы переставлять чужие треки и превращать очередь
            // в бардак). Без аргумента -- свои: удобно слушать/тестировать свой плейлист.
            // [v2.32] Обычный DJ может поднять СВОИ треки (это распоряжение только своим),
            // а чужие -- админы и модеры. Раньше /push была совсем закрыта для DJ, и
            // поднять свой длинный плейлист можно было только админом.
            const staff = isStaffInteraction (interaction);
            const pick = interaction.options.getUser ('author');
            const targetId = pick ? pick.id : interaction.user.id;
            if (!staff && String (targetId) !== String (interaction.user.id))
                return interaction.reply
                ({
                    content: '🚫 Поднимать чужие треки могут только админы и модеры.\n' +
                        '_Свои -- можно: `/push` без аргумента, или кнопка меню автора под `/queue`._',
                    flags: MessageFlags.Ephemeral,
                });
            const res = queuePush (guildId, targetId,
                interaction.member ? uuu (interaction.member) : interaction.user.username);
            return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'clear')
        {
            // [v2.14] /clear author:@кто -- убрать из очереди только ЕГО треки
            // (длинный плейлист часто собирают несколько DJ, а убрать надо одного).
            // [v2.26] И его треки уходят ЦЕЛИКОМ: если играет его трек -- он прерывается
            // сразу, а не доигрывается «ничейным»; ждущий (после /leave/обрыва) -- тоже.
            const who = interaction.options.getUser ('author');
            const staffClear = isStaffInteraction (interaction);
            if (who)
            {
                // [v2.31] Своё правило и здесь: обычный DJ убирает ТОЛЬКО себя. Чужой
                // плейлист -- не его дело, иначе одним вызовом легко «обнулить» чужой сет.
                if (!staffClear && String (who.id) !== String (interaction.user.id))
                    return interaction.reply
                    ({
                        content: '🚫 Убрать треки другого человека могут только админы и модеры.\n' +
                            '_Свои -- можно: `/clear author:@себя` или меню «🗑 Удалить треки автора» под `/queue`._',
                        flags: MessageFlags.Ephemeral,
                    });
                const res = queueClearAuthor (guildId, who.id,
                    interaction.member ? uuu (interaction.member) : interaction.user.username);
                return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
            }
            // [v2.15] Очистка очереди -- общая логика с кнопками под /queue.
            // [v2.28] Сначала подтверждение: случайный /clear посреди сета одним нажатием
            // глушил музыку. Пустую очередь подтверждать незачем.
            // [v2.31] В подтверждении видно, ЧТО уйдёт, и DJ может убрать только своё.
            if (!m.tracks.length && !m.current && !m.seekTrack)
                return interaction.reply ({ content: '🈳 Очередь и так пуста -- чистить нечего.', flags: MessageFlags.Ephemeral });
            const c = queueClearConfirm (m, interaction.user.id, staffClear, { leave: false, msgId: '0' });
            return interaction.reply ({ content: c.text, components: c.rows, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'jump')
        {
            // [v2.12] сразу к треку под номером (с v2.36 -- ПЕРЕХОД без выброса: см. ниже)
            const n = interaction.options.getInteger ('number');
            if (!m.tracks.length || n < 1 || n > m.tracks.length)
                return interaction.reply
                (
                    {
                        content: m.tracks.length
                            ? '🤔 В очереди ' + m.tracks.length + ' треков -- номер от 1 до ' + m.tracks.length + '.'
                            : '🈳 В очереди нет треков (играет только текущий).',
                        flags: MessageFlags.Ephemeral,
                    }
                );
            // [v2.36] ПРЫЖОК -- ЭТО ПЕРЕХОД, А НЕ ЧИСТКА. Раньше он молча выбрасывал
            // ВСЁ до N-го трека (и в хелпе так и было написано), хотя нужен был просто
            // переход к нужному треку: «а выбрасывать или нет -- сами решат». Теперь
            // выбранный трек играет сразу, а то, что было до него (вместе с прерванным
            // играющим и ЕГО МЕСТОМ В ТРЕКЕ), уезжает в конец очереди -- ничего не
            // теряется: убрать лишнее можно /remove, /clear, /clear author.
            // [v2.62] ПРАВА: staff -- любые треки; обычный DJ -- только по своим (за этим
            // следит jumpGuard внутри jumpMusic, поэтому слэш и кнопки не разъедутся).
            const ctxJ = { actorId: interaction.user.id, staff: isStaffInteraction (interaction) };
            // [v2.61] ВАРИАНТ МОЖНО ВЫБРАТЬ В САМОЙ КОМАНДЕ, а если не выбрал -- СПРАШИВАЕМ
            // кнопками (владелец: «а второй вариант вообще не спросило»). Логика одна --
            // jumpMusic, поэтому слэш-команда и кнопки не разъедутся.
            const mode = interaction.options.getString ('mode');
            if (!mode)
            {
                const c = jumpConfirm (n);
                return interaction.reply ({ content: c.text, components: c.rows, flags: MessageFlags.Ephemeral });
            }
            const res = jumpMusic (guildId, n, mode === 'cut', ctxJ);
            return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'skip')
        {
            // [v2.15] Общая логика с кнопкой «⏭ Пропустить» под /queue.
            // [v2.53] И то же правило: чужой трек пропускают только его автор и staff
            // (проверка внутри queueSkip, чтобы кнопка и команда не разъехались).
            const res = queueSkip (guildId,
                interaction.member ? uuu (interaction.member) : interaction.user.username,
                { actorId: interaction.user.id, staff: isStaffInteraction (interaction) });
            return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'seek')
        {
            // [v2.32] Права -- те же, что у музыки (DJ/админ/модер): это управление
            // воспроизведением, а не очередь. Кто угодно со стороны команду не видит.
            // [v2.50] И сам трек должен быть СВОЙ: чужой перематывает только его автор
            // и staff -- правило то же, что у перестановки и удаления (проверяет
            // seekMusic, чтобы слэш, кнопки ±30 с и окно таймкода не разъехались).
            const raw = interaction.options.getString ('time');
            const sec = parseSeekTime (raw);
            if (sec === null)
                return interaction.reply
                ({
                    content: '🤔 Не понял время: `' + String (raw).slice (0, 20) + '`.\n' +
                        '_Примеры: `90`, `1:30`, `1:02:03`, `0:05` (всего -- до 6 часов). Начать с начала -- `0`._',
                    flags: MessageFlags.Ephemeral,
                });
            const res = seekMusic (guildId, sec,
                interaction.member ? uuu (interaction.member) : interaction.user.username,
                { actorId: interaction.user.id, staff: isStaffInteraction (interaction) });
            return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
        }
        else if (name === 'pause')
        {
            m.player.pause ();
            m.playedMs = playedMsOf (m); // [v2.10] пауза не идёт в зачёт позиции
            m.playingSince = null;
            saveMusicState (guildId);
            scheduleVoiceStatus (guildId, true); // [v2.7] статус: ⏸
            schedulePresence (true);             // [v2.8] статус: ⏸ трек
            // [v2.27] Если бот стоит ОДИН, пауза - момент пересмотреть, где он
            // нужнее: автор недоеденного трека или автор ближайшего следующего может
            // сидеть в другом канале уже сейчас, и нового события в голосовых не будет.
            // Есть живые слушатели - checkListeners ничего не тронет.
            checkListeners (guildId);
            return interaction.reply ('⏸ Пауза.');
        }
        else if (name === 'resume')
        {
            m.player.unpause ();
            m.playingSince = Date.now (); // [v2.10] продолжили считать позицию
            saveMusicState (guildId);
            scheduleVoiceStatus (guildId, true);
            schedulePresence (true);
            return interaction.reply ('▶️ Продолжаем.');
        }
        else if (name === 'nowplaying')
        {
            // [v2.44] Короткая карточка вместо целой очереди: что звучит, откуда,
            // сколько слушает и что будет дальше. Доступна всем (без DJ).
            return interaction.reply (nowPlayingText (m, guildId));
        }
        else if (name === 'history')
        {
            // [v2.54] Кто, когда и что ставил -- треки, эфиры и целые плейлисты.
            // История живёт ОТДЕЛЬНО от очереди (musicState/history) и переживает и
            // доигранное, и /stop, и перезапуск (см. historyLoad/historyAdd).
            await historyLoad (guildId);   // с прошлого запуска могло остаться в базе
            return interaction.reply (historyText (guildId));
        }
        else if (name === 'queue')
        {
            // [v2.14] Страница очереди собирается в queueView: номера (те же, что в
            // /remove,/move,/jump), автор каждого трека, позиция внутри текущего,
            // ОБЩИЙ остаток по времени и кнопки листания у длинных очередей.
            const total = m.tracks.length;
            if (!m.current && !total)
                return interaction.reply ('🈳 Очередь пуста.');
            // [v2.31] Права и подпись вызывающего -- от них зависят меню под очередью
            // (какие треки и авторы в них попадают): DJ видит только свои записи.
            const ctxQ =
            {
                actorId: interaction.user.id,
                actorName: interaction.member ? uuu (interaction.member) : interaction.user.username,
                staff: isStaffInteraction (interaction),
            };
            const fromQ = interaction.options.getInteger ('from') || 1;
            const view = queueView (m, fromQ, 0, ctxQ);
            // [v2.57] withResponse нужен ради id самого сообщения: без него ответ
            // вернёт только InteractionResponse (там id -- от взаимодействия, а не от
            // сообщения), а нам надо помнить ИМЕННО сообщение, чтобы потом его править.
            const sent = await interaction.reply
            (
                Object.assign
                (
                    view.components.length
                        ? { content: view.content, components: view.components }
                        : { content: view.content },
                    { withResponse: true, allowedMentions: { parse: [] } }
                )
            );
            const sentMsg = (sent && sent.resource && sent.resource.message) || null;
            // Сообщение не пришло (Discord не отдал его в ответе) -- живого вести нечего,
            // и прежнее тоже забываем: иначе самообновление продолжало бы править старое.
            if (sentMsg) queueWatch (m, sentMsg, ctxQ, fromQ, view.content, 0);
            else m.qMsg = null;
        }
        else if (name === 'leave')
        {
            // [v2.32] «Выход» -- мягкий: свои треки откладываются, чужая музыка играет
            // дальше (см. leaveMusicVoice). Грубый выход -- только когда играть нечего.
            const res = leaveMusicVoice (guildId, interaction.user.id,
                interaction.member ? uuu (interaction.member) : interaction.user.username);
            return interaction.reply (res.ok ? res.text : { content: res.text, flags: MessageFlags.Ephemeral });
        }
    }
    catch (e)
    {
        console.error ('[music] ошибка обработки команды: ' + e.message);
        if (interaction.deferred || interaction.replied)
            interaction.editReply ('❌ Ошибка: ' + e.message.slice (0, 150)).catch (() => {});
        else
            interaction.reply ({ content: '❌ Ошибка: ' + e.message.slice (0, 150), flags: MessageFlags.Ephemeral }).catch (() => {});
    }
});

// Регистрируем команды после готовности клиента:
client.once ('clientReady', () => registerMusicCommands ());

// [v2.23] Один раз при старте: настройки, которые молча ничего не делают (пары ключей
// и «ни на что не влияет»). Если всё настроено правильно -- ниже ни одной строки.
for (const _cfgIssue of configSanityIssues ())
    console.log ('[' + (d()) + '] [config] ' + _cfgIssue);

// [v2.29] И там же -- не отстал ли боевой config.json от config.example.json (подсказки
// и новые ключи). Тоже молчит, когда расхождения нет.
for (const _cfgDrift of configDriftIssues ())
    console.log ('[' + (d()) + '] [config] ' + _cfgDrift);
